controlled_review.site(p_event_id uuid).source:
declare target public.controlled_stock_events; total bigint; matched bigint;
 sites uuid[]; wrong_product boolean;
begin
 select * into strict target from public.controlled_stock_events where id=p_event_id;
 if target.event_kind not in('receive_inventory','adjust_inventory','record_native_dispense_return_v2:retract_disposal') then
  raise exception 'Unsupported secondary-review historical event kind' using errcode='23514';
 end if;
 select count(*),count(c.id),array_agg(distinct c.controlling_site_id),
  coalesce(bool_or(c.product_id is distinct from target.product_id),false)
 into total,matched,sites,wrong_product
 from public.controlled_stock_container_transitions t
 left join public.controlled_stock_containers c on c.id=t.container_id
 where t.event_id=target.id;
 if total=0 or matched<>total or wrong_product or cardinality(sites)<>1 or sites[1] is null then
  raise exception 'Exactly one retained controlling site is required' using errcode='23514';
 end if;
 return sites[1];
end

controlled_review.validate_history().source:
declare operation_row record; definition_row controlled_review.definitions;
begin
 perform controlled_review.required();
 for definition_row in select * from controlled_review.definitions loop
  if definition_row.id='00000000-0000-0000-0000-000000000000'::uuid or definition_row.version<=0
   or definition_row.capability not in('review','read') or definition_row.event_kind not in('receive_inventory','adjust_inventory','record_native_dispense_return_v2:retract_disposal')
   or array_ndims(definition_row.roles) is distinct from 1 or array_lower(definition_row.roles,1) is distinct from 1 or cardinality(definition_row.roles)not between 1 and 20
   or exists(select 1 from unnest(definition_row.roles)r where r is null or r!~'^[A-Z][A-Z_]{0,39}$')
   or (select count(distinct r)from unnest(definition_row.roles)r)<>cardinality(definition_row.roles)
   or not exists(select 1 from public.catalog_products where id=definition_row.product_id)
   or not exists(select 1 from public.controlled_stock_sites where id=definition_row.site_id) then
   raise exception 'Historical synthetic review definition is invalid' using errcode='23514';
  end if;
 end loop;
 if exists(select 1 from controlled_review.definitions group by product_id,site_id,event_kind,capability
  having min(version)<>1 or max(version)<>count(*) or count(distinct version)<>count(*)) then
  raise exception 'Historical definition stream versions are incomplete' using errcode='23514';
 end if;
 if exists(select 1 from controlled_review.decisions d left join controlled_review.preparations p using(operation_id) where p.operation_id is null)
  or exists(select 1 from controlled_review.cancellations c left join controlled_review.preparations p using(operation_id) where p.operation_id is null)
  or exists(select event_id from controlled_review.decisions group by event_id having count(*)<>1) then
  raise exception 'Orphan or duplicate historical review terminal' using errcode='23514';
 end if;
 for operation_row in select operation_id from controlled_review.preparations order by operation_id loop
  perform controlled_review.validate_operation(operation_row.operation_id);
 end loop;
end

controlled_review.validate_operation(p_o.source:
declare p controlled_review.preparations; d controlled_review.decisions; c controlled_review.cancellations;
 f controlled_review.definitions; e public.controlled_stock_events; expected_request jsonb;
begin
 select * into strict p from controlled_review.preparations where operation_id=p_operation_id;
 select * into strict f from controlled_review.definitions where id=p.definition_id;
 select * into strict e from public.controlled_stock_events where id=p.event_id;
 perform public.controlled_stock_validate_event(e.id);
 expected_request:=jsonb_build_object('actor_id',p.actor_id,'operation_id',p.operation_id,'event_id',p.event_id,
  'definition_id',p.definition_id,'decision',p.decision,'reason',p.reason);
 perform public.controlled_stock_text(to_jsonb(p.reason),4000,true);
 if not e.secondary_review_required or e.actor_id=p.actor_id or f.capability<>'review' or not f.enabled
  or f.product_id<>e.product_id or f.site_id<>controlled_review.site(e.id) or f.event_kind<>e.event_kind
  or not exists(select 1 from public.profiles where id=p.actor_id)
  or p.operation_id='00000000-0000-0000-0000-000000000000'::uuid
  or p.session_id='00000000-0000-0000-0000-000000000000'::uuid
  or p.decision not in('approve','reject') or char_length(p.reason)not between 1 and 4000
  or p.meaning_version<>1 or p.meaning_text<>'Independent record review; no claim of personal physical observation.'
  or p.canonical_request is distinct from expected_request or octet_length(p.canonical_request::text)>131072
  or p.request_hash is distinct from public.controlled_stock_hash(expected_request)
  or p.target is distinct from controlled_review.target(e.id) or p.target_hash is distinct from public.controlled_stock_hash(p.target)
  or p.packet is distinct from controlled_review.packet(jsonb_build_object('event_id',e.id,'definition_id',f.id))
  or p.packet_hash is distinct from public.controlled_stock_hash(p.packet)
  or not isfinite(p.prepared_boot) or not isfinite(p.created_at) or not isfinite(p.expires_at)
  or p.expires_at<>p.created_at+interval '15 minutes' then
  raise exception 'Historical preparation binding is invalid' using errcode='23514';
 end if;
 select * into d from controlled_review.decisions where operation_id=p.operation_id;
 select * into c from controlled_review.cancellations where operation_id=p.operation_id;
 if d.operation_id is not null and c.operation_id is not null then
  raise exception 'Review operation cannot have both decision and cancellation' using errcode='23514';
 end if;
 if c.operation_id is not null and(c.actor_id<>p.actor_id or not isfinite(c.recorded_at)or c.recorded_at<p.created_at
  or c.session_id='00000000-0000-0000-0000-000000000000'::uuid) then
  raise exception 'Historical cancellation binding is invalid' using errcode='23514';
 end if;
 if d.operation_id is not null and(d.event_id<>p.event_id or d.actor_id<>p.actor_id or d.definition_id<>p.definition_id
  or d.target_hash<>p.target_hash or d.request_hash<>p.request_hash or d.packet_hash<>p.packet_hash
  or d.decision<>p.decision or d.reason<>p.reason or d.meaning_text<>p.meaning_text or d.meaning_version<>p.meaning_version
  or d.session_id='00000000-0000-0000-0000-000000000000'::uuid or char_length(d.actor_name)not between 1 and 200
  or not isfinite(d.recorded_at)or d.recorded_at<p.created_at or d.recorded_at>=p.expires_at
  or d.receipt is distinct from controlled_review.receipt(jsonb_build_object('preparation',to_jsonb(p),'decision',to_jsonb(d)))) then
  raise exception 'Historical final decision and exact receipt binding is invalid' using errcode='23514';
 end if;
end

public.cancel_controlled_secondary_revie.source:
declare req jsonb:=controlled_review.request(p_request); state jsonb;
 actor uuid:=(req->>'actor_id')::uuid;
begin
 perform controlled_review.operation_gate(jsonb_build_object('request',req,'action','cancel'));
 state:=controlled_review.operation_state(req);
 if state->>'state' in('saved','cancelled','missing') then return state; end if;
 perform public.controlled_stock_actor(actor);
 insert into controlled_review.cancellations(operation_id,actor_id,session_id)
 values((req->>'operation_id')::uuid,actor,public.next_visit_review_session());
 return controlled_review.operation_state(req);
end

public.execute_controlled_secondary_revi.source:
declare req jsonb:=controlled_review.request(p_request); state jsonb; p controlled_review.preparations;
 actor uuid:=(req->>'actor_id')::uuid;
begin
 perform controlled_review.operation_gate(jsonb_build_object('request',req,'action','execute'));
 state:=controlled_review.operation_state(req);
 if state->>'state'='saved' then return state; end if;
 if state->>'state'<>'prepared' then
  raise exception 'Committed unexpired uncancelled preparation required' using errcode='PT409';
 end if;
 select * into strict p from controlled_review.preparations where operation_id=(req->>'operation_id')::uuid;
 if exists(select 1 from controlled_review.decisions where event_id=p.event_id) then
  raise exception 'Review target already has a final decision' using errcode='23505';
 end if;
 perform controlled_review.require_prior_commit(p.operation_id);
 perform controlled_review.validate_operation(p.operation_id);
 perform public.controlled_stock_validate_event(p.event_id);
 perform controlled_review.execution_definition(req);
 perform public.controlled_stock_actor(actor);
 if p.expires_at<=clock_timestamp() then
  raise exception 'Preparation expired while waiting; review again with a new UUID' using errcode='PT409';
 end if;
 insert into controlled_review.decisions(operation_id,event_id,actor_id,session_id,definition_id,
  target_hash,request_hash,packet_hash,decision,reason,meaning_text,meaning_version)
 values(p.operation_id,p.event_id,actor,public.next_visit_review_session(),p.definition_id,
  p.target_hash,p.request_hash,p.packet_hash,p.decision,p.reason,p.meaning_text,p.meaning_version);
 return controlled_review.operation_state(req);
end

public.list_controlled_secondary_reviews.source:
declare actor uuid; product uuid; site_id uuid; kind text; filter text; page_size integer:=25;
 read_definition jsonb; binding jsonb; cursor_value jsonb; after_sequence bigint:=0;
 items jsonb:='[]'; item jsonb;
 e record; more boolean:=false; next_cursor jsonb:=null; last_sequence bigint; scanned integer:=0;
begin
 if jsonb_typeof(p_request) is distinct from 'object' or octet_length(p_request::text)>131072
 or not(p_request ?& array['actor_id','product_id','site_id','event_kind'])
 or exists(select 1 from jsonb_object_keys(p_request) k where k<>all(array[
  'actor_id','product_id','site_id','event_kind','status','page_size','cursor'])) then
  raise exception 'Exact bounded review queue fields required' using errcode='23514';
 end if;
 actor:=public.controlled_stock_uuid(p_request->'actor_id');
 product:=public.controlled_stock_uuid(p_request->'product_id');
 site_id:=public.controlled_stock_uuid(p_request->'site_id');
 kind:=public.controlled_stock_text(p_request->'event_kind',100);
 filter:=p_request->>'status';
 if p_request ? 'status' and (jsonb_typeof(p_request->'status') is distinct from 'string'
  or filter not in('pending','approved','rejected','blocked-unconfigured')) then
  raise exception 'Known review queue status required' using errcode='23514';
 end if;
 if p_request ? 'page_size' then
  if jsonb_typeof(p_request->'page_size') is distinct from 'number' or p_request->>'page_size' !~ '^[1-9][0-9]{0,2}$' then
   raise exception 'Review page size must be 1 through 100' using errcode='23514';
  end if;
  page_size:=(p_request->>'page_size')::integer;
  if page_size>100 then raise exception 'Review page size must be 1 through 100' using errcode='23514'; end if;
 end if;
 perform controlled_review.entry(p_request);
 read_definition:=controlled_review.current_definition(jsonb_build_object('product_id',product,'site_id',site_id,
  'event_kind',kind,'capability','read'));
 if read_definition is null or not exists(select 1 from public.user_roles r where r.user_id=actor
  and r.role::text in(select jsonb_array_elements_text(read_definition->'roles'))) then
  raise exception 'Current explicit review read scope required' using errcode='42501';
 end if;
 binding:=jsonb_build_object('product_id',product,'site_id',site_id,'event_kind',kind,'status',filter,
  'read_definition_id',read_definition->'id','read_definition_version',read_definition->'version');
 if p_request ? 'cursor' then
  cursor_value:=p_request->'cursor';
  perform public.controlled_stock_keys(cursor_value,array['scope','sequence']);
  if cursor_value->'scope' is distinct from binding or jsonb_typeof(cursor_value->'sequence') is distinct from 'string'
   or cursor_value->>'sequence' !~ '^[1-9][0-9]{0,18}$' then
   raise exception 'Review cursor scope or version changed' using errcode='23514';
  end if;
  begin after_sequence:=(cursor_value->>'sequence')::bigint;
  exception when numeric_value_out_of_range then raise exception 'Invalid review cursor sequence' using errcode='23514'; end;
 end if;
 for e in select id,sequence from public.controlled_stock_events
  where product_id=product and event_kind=kind and secondary_review_required
  and sequence>after_sequence order by sequence,id limit 101 loop
  -- Bound work as well as output. Cursor advances over excluded candidates;
  -- an empty page can have a continuation under a sparse site/status filter.
  if jsonb_array_length(items)=page_size or scanned=100 then more:=true; exit; end if;
  scanned:=scanned+1; last_sequence:=e.sequence;
  item:=controlled_review.event_summary(jsonb_build_object('actor_id',actor,'event_id',e.id));
  if item is null or item->>'site_id'<>site_id::text or (filter is not null and item->>'status'<>filter) then continue; end if;
  items:=items||jsonb_build_array((item-'decision')||jsonb_build_object('decision',case
   when item->'decision'='null'::jsonb then null else jsonb_build_object(
    'decision',item->'decision'->'decision','actor_name',item->'decision'->'actor_name',
    'recorded_at',item->'decision'->'recorded_at') end));
 end loop;
 -- The parent's UNIQUE(product_id,sequence) is the complete continuation key.
 -- Do not disclose an excluded target UUID in a last-inspected cursor.
 if more then next_cursor:=jsonb_build_object('scope',binding,'sequence',last_sequence::text); end if;
 -- Re-evaluate scope after the traversal before returning any rows.
 if controlled_review.current_definition(jsonb_build_object('product_id',product,'site_id',site_id,
  'event_kind',kind,'capability','read')) is distinct from read_definition or not exists(
  select 1 from public.user_roles r where r.user_id=actor
  and r.role::text in(select jsonb_array_elements_text(read_definition->'roles'))) then
  raise exception 'Review read scope changed' using errcode='42501';
 end if;
 perform public.controlled_stock_actor(actor);
 return jsonb_build_object('items',items,'next_cursor',next_cursor,'traversal','live_read_committed_keyset',
  'due_at',null,'deadline_state','not_configured');
end

public.prepare_controlled_secondary_revi.source:
declare req jsonb:=controlled_review.request(p_request); state jsonb; target jsonb; packet jsonb;
 actor uuid:=(req->>'actor_id')::uuid; op uuid:=(req->>'operation_id')::uuid;
begin
 perform controlled_review.operation_gate(jsonb_build_object('request',req,'action','prepare'));
 state:=controlled_review.operation_state(req);
 if state->>'state'<>'missing' then return state; end if;
 if exists(select 1 from controlled_review.decisions where event_id=(req->>'event_id')::uuid) then
  raise exception 'Review target already has a final decision' using errcode='23505';
 end if;
 perform controlled_review.execution_definition(req);
 perform public.controlled_stock_validate_event((req->>'event_id')::uuid);
 target:=controlled_review.target((req->>'event_id')::uuid);
 packet:=controlled_review.packet(jsonb_build_object('event_id',req->>'event_id','definition_id',req->>'definition_id'));
 perform controlled_review.execution_definition(req);
 perform public.controlled_stock_actor(actor);
 insert into controlled_review.preparations(operation_id,event_id,actor_id,session_id,definition_id,
  target,target_hash,canonical_request,request_hash,packet,packet_hash,decision,reason,meaning_text,meaning_version)
 values(op,(req->>'event_id')::uuid,actor,public.next_visit_review_session(),(req->>'definition_id')::uuid,
  target,public.controlled_stock_hash(target),req,public.controlled_stock_hash(req),packet,public.controlled_stock_hash(packet),
  req->>'decision',req->>'reason','Independent record review; no claim of personal physical observation.',1);
 return controlled_review.operation_state(req);
end

public.read_controlled_secondary_review(.source:
declare req jsonb:=controlled_review.request(p_request);
begin
 perform controlled_review.operation_gate(jsonb_build_object('request',req,'action','read'));
 return controlled_review.operation_state(req);
end

public.read_controlled_secondary_review_.source:
declare result jsonb; actor uuid; definition jsonb;
begin
 perform public.controlled_stock_keys(p_request,array['actor_id','event_id']);
 actor:=public.controlled_stock_uuid(p_request->'actor_id');
 perform public.controlled_stock_uuid(p_request->'event_id');
 perform controlled_review.entry(p_request);
 result:=controlled_review.event_summary(p_request);
 if result is null then raise exception 'Configured readable review target required' using errcode='42501'; end if;
 definition:=controlled_review.current_definition(jsonb_build_object('product_id',result#>'{target,product_id}',
  'site_id',result->'site_id','event_kind',result->'event_kind','capability','read'));
 if definition->'id' is distinct from result->'read_definition_id'
  or definition->'version' is distinct from result->'read_definition_version'
  or not exists(select 1 from public.user_roles r where r.user_id=actor
   and r.role::text in(select jsonb_array_elements_text(definition->'roles'))) then
  raise exception 'Review read scope changed' using errcode='42501';
 end if;
 perform public.controlled_stock_actor(actor);
 return result;
end

controlled_review_v3.adapter_add(p_state.source:
declare
 state jsonb:=p_state; identity text; prior jsonb; item jsonb; rank integer; old_rank integer;
 roles text[]:=array['reviewed_target','correction_target','case_report','ordinary_source','original_intake','original_pickup','amendment_predecessor','original_dispense','resolution_correction','opening_basis','retained_context'];
 expected_key jsonb; count_rows integer;
begin
 if jsonb_typeof(state) is distinct from 'object' or jsonb_typeof(state->'rows') is distinct from 'object'
 or jsonb_typeof(p_key) is distinct from 'object' or jsonb_typeof(p_row) is distinct from 'object'
 or p_relation is null or p_role is null or not(p_role=any(roles)) then
  raise exception 'adapter_source_integrity' using errcode='23514';
 end if;
 if octet_length(state::text)>1048576 or octet_length(p_row::text)>1048576 then
  raise exception 'evidence_limit_exceeded' using errcode='54000';
 end if;
 expected_key:=case p_relation
 when 'public.stock_movement_sources' then jsonb_build_object('movement_id',p_row->'movement_id')
 when 'public.stock_custody_sources' then jsonb_build_object('event_id',p_row->'event_id')
 when 'public.stock_pickup_sources' then jsonb_build_object('event_id',p_row->'event_id')
 when 'public.stock_discrepancy_sources' then jsonb_build_object('event_id',p_row->'event_id')
 when 'public.stock_correction_sources' then jsonb_build_object('event_id',p_row->'event_id')
 when 'public.controlled_stock_opening_movements' then jsonb_build_object('opening_id',p_row->'opening_id','movement_id',p_row->'movement_id')
 else jsonb_build_object('id',p_row->'id') end;
 if p_key is distinct from expected_key or exists(select 1 from jsonb_each(p_key) x where jsonb_typeof(x.value)<>'string')
 or p_relation<>all(array[
 'public.controlled_stock_events','public.controlled_stock_actions','public.controlled_stock_preparations',
 'public.controlled_stock_policy_versions','public.controlled_stock_openings','public.controlled_stock_source_links',
 'public.controlled_stock_event_lines','public.controlled_stock_container_transitions','public.controlled_stock_cells',
 'public.controlled_stock_containers','public.inventory_movements','public.stock_movement_sources','public.inventory_lots',
 'public.patient_treatments','public.billing_invoice_items','public.treatment_alert_reviews','public.anesthesia_drug_administrations',
 'public.native_dispenses','public.native_fulfillment_operations','public.native_dispense_allocations','public.native_pickups',
 'public.stock_pickup_sources','public.native_return_events','public.native_return_operations','public.stock_custody_sources',
 'public.native_return_stock_links','public.native_return_compensation_links','public.native_return_discrepancy_events',
 'public.native_return_discrepancy_operations','public.stock_discrepancy_sources','public.native_return_discrepancy_correction_links',
 'public.native_dispense_correction_events','public.native_dispense_correction_operations','public.stock_correction_sources',
 'public.controlled_stock_opening_movements']) then
  raise exception 'adapter_source_integrity' using errcode='23514';
 end if;
 identity:=jsonb_build_array(p_relation,p_key)::text;
 prior:=state->'rows'->identity;
 rank:=array_position(roles,p_role);
 item:=jsonb_build_object('relation',p_relation,'key',p_key,'row',p_row,'row_hash',public.controlled_stock_hash(p_row),'role',p_role);
 if prior is not null then
  if prior->'row' is distinct from p_row or prior->>'row_hash' is distinct from item->>'row_hash' then
   raise exception 'adapter_source_role_conflict' using errcode='23514';
  end if;
  old_rank:=array_position(roles,prior->>'role');
  if old_rank is null then raise exception 'adapter_source_role_conflict' using errcode='23514';end if;
  if old_rank<=rank then return state;end if;
 else
  select count(*) into count_rows from jsonb_object_keys(state->'rows');
  if count_rows>=512 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
  if p_relation=any(array['public.native_dispenses','public.native_pickups','public.native_return_events',
   'public.native_return_discrepancy_events','public.native_dispense_correction_events']) then
   if jsonb_array_length(state->'documents')>=100 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
   state:=jsonb_set(state,'{documents}',(state->'documents')||jsonb_build_array(identity));
  end if;
  if p_relation='public.native_dispense_allocations' then
   if jsonb_array_length(state->'allocations')>=100 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
   state:=jsonb_set(state,'{allocations}',(state->'allocations')||jsonb_build_array(p_row->'id'));
  end if;
 end if;
 state:=jsonb_set(state,array['rows',identity],item);
 if octet_length(state::text)>1048576 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
 return state;
end

controlled_review_v3.adapter_clinical(p_.source:
declare state jsonb:=p_state; e public.controlled_stock_events; p public.controlled_stock_preparations;
 m public.inventory_movements; t public.patient_treatments; i public.billing_invoice_items;
 a public.treatment_alert_reviews; link public.anesthesia_drug_administrations; n integer;
begin
 select * into e from public.controlled_stock_events where id=p_event_id;
 select * into p from public.controlled_stock_preparations where id=p_event_id;
 if e.id is null or e.writer<>all(array['receive_inventory','adjust_inventory','record_patient_treatment','record_anesthesia_drug_administration']) then
  raise exception 'unsupported_event_kind' using errcode='22023';end if;
 select count(*) into n from(select movement_id from public.stock_movement_sources where writer=e.writer and source_id=e.id limit 2)q;
 if n<>1 or not exists(select 1 from public.stock_movement_sources where writer=e.writer and source_id=e.id and movement_id=e.id) then
  raise exception 'adapter_source_integrity' using errcode='23514';end if;
 state:=controlled_review_v3.adapter_movement(state,e.id,e.writer,e.id,e.actor_id,'reviewed_target',true);
 select * into m from public.inventory_movements where id=e.id;
 if e.writer='receive_inventory' then
  if m.kind<>'receive' or m.quantity<=0 then raise exception 'adapter_source_integrity' using errcode='23514';end if;
 elsif e.writer='adjust_inventory' then
  if m.kind<>'adjust' then raise exception 'adapter_source_integrity' using errcode='23514';end if;
 else
  select * into t from public.patient_treatments where id=e.id;
  select * into i from public.billing_invoice_items where id=e.id;
  select * into a from public.treatment_alert_reviews where treatment_id=e.id;
  if t.id is null or i.id is null or a.id is null or t.historical or t.product_id<>e.product_id or t.lot_id<>m.lot_id
  or t.created_by<>e.actor_id or i.created_by<>e.actor_id or a.reviewed_by<>e.actor_id
  or t.invoice_id<>i.invoice_id or t.pet_id is distinct from i.pet_id or t.pet_id<>a.pet_id or i.product_id<>e.product_id
  or m.quantity<>-t.quantity or i.quantity<>t.quantity or m.kind<>'dispense'
  or t.administered_at is distinct from e.observed_at
  or t.administered_at is distinct from(p.canonical_arguments#>>'{request,administered_at}')::timestamptz
  or a.source_hash is distinct from public.controlled_stock_hash(a.snapshot)
  or a.source_hash is distinct from t.request#>>'{alert_review,source_hash}' then
   raise exception 'adapter_source_integrity' using errcode='23514';end if;
  state:=controlled_review_v3.adapter_add(state,'public.patient_treatments',jsonb_build_object('id',t.id),to_jsonb(t),'reviewed_target');
  state:=controlled_review_v3.adapter_add(state,'public.billing_invoice_items',jsonb_build_object('id',i.id),to_jsonb(i),'reviewed_target');
  state:=controlled_review_v3.adapter_add(state,'public.treatment_alert_reviews',jsonb_build_object('id',a.id),to_jsonb(a),'reviewed_target');
  if e.writer='record_anesthesia_drug_administration' then
   select * into link from public.anesthesia_drug_administrations where id=e.id;
   if link.id is null or link.created_by<>e.actor_id or link.pet_id<>t.pet_id
   or link.record_id::text is distinct from p.canonical_arguments->>'record_id'
   or link.pet_id::text is distinct from p.canonical_arguments->>'pet_id'
   or link.request is distinct from((p.canonical_arguments->'request')||jsonb_build_object('pet_id',link.pet_id,'source','Anesthesia record '||link.record_id::text))
   or link.request is distinct from t.request then
    raise exception 'adapter_source_integrity' using errcode='23514';end if;
   state:=controlled_review_v3.adapter_add(state,'public.anesthesia_drug_administrations',jsonb_build_object('id',link.id),to_jsonb(link),'reviewed_target');
  end if;
 end if;
 return state;
end

controlled_review_v3.adapter_context(p_s.source:
declare state jsonb:=p_state; e public.controlled_stock_events; target jsonb; source jsonb;
 row_value jsonb; operation jsonb; provenance jsonb; managed jsonb; did uuid; selected_id uuid; role_name text;
 selected_ids uuid[]; predecessor uuid; original_source uuid; selected_case_id uuid; selected_correction_id uuid;
 correction public.native_return_events; link public.native_return_discrepancy_correction_links;
 n integer:=0; count_links integer; last_id text:='';
begin
 select * into e from public.controlled_stock_events where id=p_event_id;
 if e.id is null then raise exception 'adapter_parent_integrity' using errcode='23514';end if;
 if e.writer='append_native_dispense_correction' then
  select to_jsonb(r) into target from public.native_dispense_correction_events r where r.id=e.id;
  if target is null then raise exception 'adapter_source_integrity' using errcode='23514';end if;
  did:=(target->>'dispense_id')::uuid;
  predecessor:=(target#>>'{document,amends_event_id}')::uuid;
  selected_ids:=array[e.id];
  if predecessor is not null then
   select to_jsonb(r) into source from public.native_dispense_correction_events r where r.id=predecessor;
   if source is null or predecessor=e.id or source->>'dispense_id' is distinct from did::text
   or source->>'kind' is distinct from target->>'kind' or(source->>'sequence')::integer>=(target->>'sequence')::integer then
    raise exception 'adapter_source_integrity' using errcode='23514';end if;
   selected_ids:=selected_ids||predecessor;
  end if;
  foreach selected_id in array selected_ids loop
   role_name:=case when selected_id=e.id then 'reviewed_target' else 'amendment_predecessor' end;
   select to_jsonb(r) into row_value from public.native_dispense_correction_events r where r.id=selected_id;
   select to_jsonb(r) into operation from public.native_dispense_correction_operations r where r.id=selected_id;
   select to_jsonb(r) into provenance from public.stock_correction_sources r where r.event_id=selected_id;
   managed:=controlled_review_v3.managed_source_event(jsonb_build_object('source_kind','correction','source_id',selected_id,'product_id',e.product_id));
   if operation is null or operation->>'actor_id' is distinct from row_value->>'actor_id'
   or operation->'result' is distinct from row_value->'document'
   or row_value->>'record_hash' is distinct from public.native_fulfillment_hash((row_value->'document')-'record_hash')
   or(provenance is null and managed is not null)
   or(provenance is not null and provenance->>'actor_id' is distinct from row_value->>'actor_id') then
    raise exception 'adapter_source_integrity' using errcode='23514';end if;
   -- Membership is validated above; these context-only roles declare no parent/physical edge.
   state:=controlled_review_v3.adapter_add(state,'public.native_dispense_correction_events',jsonb_build_object('id',selected_id),row_value,role_name);
   state:=controlled_review_v3.adapter_add(state,'public.native_dispense_correction_operations',jsonb_build_object('id',selected_id),operation,role_name);
   if provenance is not null then state:=controlled_review_v3.adapter_add(state,'public.stock_correction_sources',jsonb_build_object('event_id',selected_id),provenance,role_name);end if;
  end loop;
  state:=controlled_review_v3.adapter_dispense(state,did,e.product_id,'original_dispense',1);
  if target->>'kind'='pickup_amendment' then
   selected_id:=(target#>>'{document,pickup_amendment,original_pickup_id}')::uuid;
   if selected_id is null or not exists(select 1 from public.native_pickups where id=selected_id and dispense_id=did) then
    raise exception 'adapter_source_integrity' using errcode='23514';end if;
   state:=controlled_review_v3.adapter_pickup(state,selected_id,e.product_id,'original_pickup',1);
  end if;
 elsif e.writer='record_native_return_discrepancy' then
  select to_jsonb(r) into target from public.native_return_discrepancy_events r where r.id=e.id;
  if target is null then raise exception 'adapter_source_integrity' using errcode='23514';end if;
  did:=(target->>'dispense_id')::uuid;selected_case_id:=(target->>'case_id')::uuid;
  original_source:=(target#>>'{document,source,event_id}')::uuid;
  select to_jsonb(r) into source from public.native_return_events r where r.id=original_source;
  if source is null or source->>'dispense_id' is distinct from did::text
  or source->>'record_hash' is distinct from target#>>'{document,source,record_hash}'
  or source->>'action'<>all(array['intake','dispose','restock']) then
   raise exception 'adapter_source_integrity' using errcode='23514';end if;
  selected_ids:=array[e.id];if selected_case_id<>e.id then selected_ids:=selected_ids||selected_case_id;end if;
  foreach selected_id in array selected_ids loop
   role_name:=case when selected_id=e.id then 'reviewed_target' else 'case_report' end;
   select to_jsonb(r) into row_value from public.native_return_discrepancy_events r where r.id=selected_id;
   select to_jsonb(r) into operation from public.native_return_discrepancy_operations r where r.id=selected_id;
   select to_jsonb(r) into provenance from public.stock_discrepancy_sources r where r.event_id=selected_id;
   if row_value is null or operation is null or row_value->>'dispense_id' is distinct from did::text
   or operation->>'actor_id' is distinct from row_value->>'actor_id' or operation->'result' is distinct from row_value->'document'
   or row_value->>'record_hash' is distinct from public.native_fulfillment_hash((row_value->'document')-'record_hash')
   or row_value#>'{document,source}' is distinct from target#>'{document,source}'
   or row_value#>'{document,allocations}' is distinct from target#>'{document,allocations}'
   or(selected_id<>e.id and(row_value->>'action'<>'report' or(row_value->>'sequence')::integer>=(target->>'sequence')::integer)) then
    raise exception 'adapter_source_integrity' using errcode='23514';end if;
   managed:=controlled_review_v3.managed_source_event(jsonb_build_object('source_kind','discrepancy','source_id',selected_id,'product_id',e.product_id));
   if(provenance is null and managed is not null) or(provenance is not null and provenance->>'actor_id' is distinct from row_value->>'actor_id') then
    raise exception 'adapter_source_integrity' using errcode='23514';end if;
   -- Membership is validated above; these context-only roles declare no parent/physical edge.
   state:=controlled_review_v3.adapter_add(state,'public.native_return_discrepancy_events',jsonb_build_object('id',selected_id),row_value,role_name);
   state:=controlled_review_v3.adapter_add(state,'public.native_return_discrepancy_operations',jsonb_build_object('id',selected_id),operation,role_name);
   if provenance is not null then state:=controlled_review_v3.adapter_add(state,'public.stock_discrepancy_sources',jsonb_build_object('event_id',selected_id),provenance,role_name);end if;
  end loop;
  state:=controlled_review_v3.adapter_return(state,original_source,e.product_id,'ordinary_source',1);
  if jsonb_typeof(target#>'{document,correction_ids}') is distinct from 'array' then
   raise exception 'adapter_source_integrity' using errcode='23514';end if;
  if jsonb_array_length(target#>'{document,correction_ids}')>100 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
  if target->>'action'='resolve_corrected' then
   if jsonb_array_length(target#>'{document,correction_ids}')=0 then raise exception 'adapter_source_integrity' using errcode='23514';end if;
   for row_value in select value from jsonb_array_elements(target#>'{document,correction_ids}') loop
    if jsonb_typeof(row_value)<>'string' or row_value#>>'{}'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    or (row_value#>>'{}') collate "C"<=last_id collate "C" then raise exception 'adapter_source_integrity' using errcode='23514';end if;
    last_id:=row_value#>>'{}';selected_correction_id:=last_id::uuid;
    select * into correction from public.native_return_events where id=selected_correction_id;
    select * into link from public.native_return_discrepancy_correction_links l where l.correction_id=selected_correction_id;
    if correction.id is null or link.id is null or link.case_id<>selected_case_id or link.resolution_id<>e.id
    or correction.dispense_id<>did or correction.document->>'version'<>'2'
    or correction.action<>all(array['retract_intake','retract_disposal','retract_restock'])
    or correction.document#>'{correction_target}' is distinct from target#>'{document,source}'
    or correction.document->>'discrepancy_id' is distinct from selected_case_id::text then
     raise exception 'adapter_source_integrity' using errcode='23514';end if;
    n:=n+1;
    state:=controlled_review_v3.adapter_add(state,'public.native_return_discrepancy_correction_links',jsonb_build_object('id',link.id),to_jsonb(link),'reviewed_target');
    state:=controlled_review_v3.adapter_return(state,correction.id,e.product_id,'resolution_correction',1);
   end loop;
  elsif target#>'{document,correction_ids}'<>'[]'::jsonb then raise exception 'adapter_source_integrity' using errcode='23514';end if;
  select count(*) into count_links from(select id from public.native_return_discrepancy_correction_links where resolution_id=e.id limit 101) q;
  if count_links>100 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
  if count_links<>n then raise exception 'adapter_source_integrity' using errcode='23514';end if;
 else raise exception 'unsupported_event_kind' using errcode='22023';end if;
 return state;
end

controlled_review_v3.adapter_dispense(p_.source:
declare state jsonb:=p_state; d public.native_dispenses; op public.native_fulfillment_operations;
 item public.billing_invoice_items; a record; m public.inventory_movements; managed jsonb;
 n integer:=0; source_count integer; total numeric:=0; unit text;
begin
 if p_role is null or p_role<>all(array['reviewed_target','original_dispense']) then
  raise exception 'adapter_source_role_conflict' using errcode='23514';end if;
 if p_depth is null or p_depth<0 or p_depth>4 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
 select * into d from public.native_dispenses where id=p_dispense_id;
 select * into op from public.native_fulfillment_operations where id=p_dispense_id;
 select * into item from public.billing_invoice_items where id=d.invoice_item_id;
 select stock_unit into unit from public.controlled_stock_policy_versions where id=(select policy_version_id from public.controlled_stock_events where id=(state->>'target_event_id')::uuid);
 if d.id is null or op.id is null or item.id is null or op.operation<>'dispense' or op.actor_id<>d.actor_id
 or op.result->'dispense' is distinct from d.document or item.product_id<>p_product_id or item.quantity<>d.quantity
 or item.created_by<>d.actor_id or item.invoice_id<>d.invoice_id or item.pet_id is distinct from d.pet_id
 or d.document->>'unit' is distinct from unit or state->>'product_id' is distinct from p_product_id::text then
  raise exception 'adapter_source_integrity' using errcode='23514';end if;
 managed:=controlled_review_v3.managed_source_event(jsonb_build_object('source_kind','dispense','source_id',d.id,'product_id',p_product_id));
 if managed is not null then state:=controlled_review_v3.adapter_parent(state,(managed->>'event_id')::uuid,p_role);end if;
 state:=controlled_review_v3.adapter_add(state,'public.native_dispenses',jsonb_build_object('id',d.id),to_jsonb(d),p_role);
 state:=controlled_review_v3.adapter_add(state,'public.native_fulfillment_operations',jsonb_build_object('id',op.id),to_jsonb(op),p_role);
 state:=controlled_review_v3.adapter_add(state,'public.billing_invoice_items',jsonb_build_object('id',item.id),to_jsonb(item),p_role);
 for a in select * from public.native_dispense_allocations where dispense_id=d.id order by lot_id limit 101 loop
  n:=n+1;if n>100 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
  select * into m from public.inventory_movements where id=a.movement_id;
  if m.id is null or m.lot_id<>a.lot_id or m.quantity<>-a.quantity or m.kind<>'dispense' then
   raise exception 'adapter_source_integrity' using errcode='23514';end if;
  total:=total+a.quantity;
  state:=controlled_review_v3.adapter_add(state,'public.native_dispense_allocations',jsonb_build_object('id',a.id),to_jsonb(a),p_role);
  state:=controlled_review_v3.adapter_movement(state,a.movement_id,'record_native_dispense',d.id,d.actor_id,p_role,managed is not null);
 end loop;
 if n=0 or total<>d.quantity then raise exception 'adapter_source_integrity' using errcode='23514';end if;
 select count(*) into source_count from(select movement_id from public.stock_movement_sources where writer='record_native_dispense' and source_id=d.id limit 101) q;
 if source_count>100 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
 if source_count not in(0,n) or(managed is not null and source_count<>n)
 or exists(select 1 from public.stock_movement_sources s where writer='record_native_dispense' and source_id=d.id
  and not exists(select 1 from public.native_dispense_allocations allocation_row where allocation_row.dispense_id=d.id and allocation_row.movement_id=s.movement_id)) then
  raise exception 'adapter_source_integrity' using errcode='23514';end if;
 return state;
end

controlled_review_v3.adapter_event_site(.source:
declare e public.controlled_stock_events; site uuid; unit text; r record; n integer:=0;
begin
 select * into e from public.controlled_stock_events where id=p_event_id;
 if e.id is null then raise exception 'adapter_parent_integrity' using errcode='23514';end if;
 select stock_unit into unit from public.controlled_stock_policy_versions where id=e.policy_version_id;
 for r in select c.controlling_site_id,c.product_id,c.stock_unit from public.controlled_stock_container_transitions t
  join public.controlled_stock_containers c on c.id=t.container_id where t.event_id=e.id order by t.container_id limit 513 loop
  n:=n+1;
  if n>512 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
  if r.product_id<>e.product_id or r.stock_unit is distinct from unit or(site is not null and site<>r.controlling_site_id) then
   raise exception 'adapter_source_integrity' using errcode='23514';end if;
  site:=r.controlling_site_id;
 end loop;
 if e.basis in('physical_record','correction_assertion') and(site is null or not exists(select 1 from public.controlled_stock_event_lines where event_id=e.id)) then
  raise exception 'adapter_source_integrity' using errcode='23514';end if;
 return jsonb_build_object('site_id',site);
end

controlled_review_v3.adapter_movement(p_.source:
declare state jsonb:=p_state; m public.inventory_movements; l public.inventory_lots;
 s public.stock_movement_sources; boundary public.controlled_stock_opening_movements;
begin
 select * into m from public.inventory_movements where id=p_movement_id;
 select * into l from public.inventory_lots where id=m.lot_id;
 select * into s from public.stock_movement_sources where movement_id=m.id;
 if m.id is null or l.id is null or l.product_id::text is distinct from state->>'product_id'
 or m.created_by is distinct from p_actor_id or p_managed is null then
  raise exception 'adapter_source_integrity' using errcode='23514';end if;
 if s.movement_id is not null then
  if s.writer is distinct from p_source_writer or s.source_id is distinct from p_source_id or s.actor_id is distinct from p_actor_id then
   raise exception 'adapter_source_integrity' using errcode='23514';end if;
  perform public.stock_source_validate_movement(m.id);
  state:=controlled_review_v3.adapter_add(state,'public.stock_movement_sources',jsonb_build_object('movement_id',s.movement_id),to_jsonb(s),p_role);
 elsif p_managed then raise exception 'adapter_source_integrity' using errcode='23514';end if;
 select * into boundary from public.controlled_stock_opening_movements where movement_id=m.id;
 if p_managed then
  if boundary.movement_id is not null or not exists(select 1 from public.controlled_stock_source_links where movement_id=m.id and event_id=p_source_id) then
   raise exception 'adapter_source_integrity' using errcode='23514';end if;
 else
  if boundary.movement_id is null or boundary.opening_id::text is distinct from state->>'opening_id'
  or boundary.source_snapshot is distinct from to_jsonb(m) or boundary.lot_id<>m.lot_id or boundary.quantity<>m.quantity
  or exists(select 1 from public.controlled_stock_source_links where movement_id=m.id) then
   raise exception 'adapter_source_integrity' using errcode='23514';end if;
  state:=controlled_review_v3.adapter_add(state,'public.controlled_stock_opening_movements',
   jsonb_build_object('opening_id',boundary.opening_id,'movement_id',boundary.movement_id),to_jsonb(boundary),'opening_basis');
 end if;
 state:=controlled_review_v3.adapter_add(state,'public.inventory_movements',jsonb_build_object('id',m.id),to_jsonb(m),p_role);
 state:=controlled_review_v3.adapter_add(state,'public.inventory_lots',jsonb_build_object('id',l.id),to_jsonb(l),p_role);
 return state;
end

controlled_review_v3.adapter_opening_sit.source:
declare
 state jsonb:=p_state; target_event public.controlled_stock_events;
 target_correction public.native_dispense_correction_events; original_dispense public.native_dispenses;
 retained_opening public.controlled_stock_openings; selected_cell public.controlled_stock_cells;
 selected_container public.controlled_stock_containers; original_allocation record;
 entry jsonb; entry_candidate jsonb; projected jsonb; boundary_allocation jsonb;
 allocation_map jsonb:='{}'; prepared_sums jsonb:='{}'; retained_node jsonb;
 opening_container_map jsonb:='{}'; opening_container_ids jsonb;
 positive_sites jsonb:='{}'; zero_sites jsonb:='{}'; site_key text; retained_site uuid; selected_site uuid;
 opening_unit text; target_unit text; selected_pickup uuid;
 return_version integer; correction_version integer; discrepancy_version integer;
 entry_count integer:=0; allocation_count integer:=0; cell_count integer:=0;
 fully_prepared boolean:=true; reason text; expected_prepared numeric; actual_prepared numeric;
begin
 if p_dispense_id is null or p_product_id is null or jsonb_typeof(state) is distinct from 'object'
 or jsonb_typeof(state->'rows') is distinct from 'object' then
  raise exception 'adapter_source_integrity' using errcode='23514';end if;
 if octet_length(state::text)>1048576 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
 select * into target_event from public.controlled_stock_events
 where id=public.controlled_stock_uuid(state->'target_event_id');
 select * into target_correction from public.native_dispense_correction_events where id=target_event.id;
 select * into original_dispense from public.native_dispenses where id=p_dispense_id;
 if target_event.id is null or target_event.writer is distinct from 'append_native_dispense_correction'
 or target_event.event_kind<>all(array['append_native_dispense_correction:clinical_annotation','append_native_dispense_correction:operational_annotation'])
 or target_event.product_id is distinct from p_product_id or state->>'product_id' is distinct from p_product_id::text
 or target_event.opening_id::text is distinct from state->>'opening_id'
 or target_correction.id is null or original_dispense.id is null
 or target_correction.dispense_id is distinct from p_dispense_id
 or target_correction.kind is distinct from split_part(target_event.event_kind,':',2)
 or target_correction.authorization_id is distinct from original_dispense.authorization_id
 or target_correction.pet_id is distinct from original_dispense.pet_id
 or target_correction.actor_id is distinct from target_event.actor_id then
  raise exception 'adapter_source_integrity' using errcode='23514';end if;
 select * into retained_opening from public.controlled_stock_openings where id=target_event.opening_id;
 select stock_unit into opening_unit from public.controlled_stock_policy_versions
 where id=retained_opening.policy_version_id and product_id=p_product_id;
 select stock_unit into target_unit from public.controlled_stock_policy_versions
 where id=target_event.policy_version_id and product_id=p_product_id;
 if retained_opening.id is null or retained_opening.product_id is distinct from p_product_id
 or opening_unit is null or target_unit is distinct from opening_unit then
  raise exception 'adapter_source_integrity' using errcode='23514';end if;
 if octet_length(retained_opening.native_custody_boundary::text)>1048576
 or jsonb_array_length(retained_opening.native_custody_boundary)>200 then
  raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
 -- The immutable parent keeps all its reciprocal, prefix and later-link checks.
 perform public.controlled_stock_validate_opening(retained_opening.id);
 if controlled_review_v3.managed_source_event(jsonb_build_object(
  'source_kind','dispense','source_id',p_dispense_id,'product_id',p_product_id)) is not null then
  raise exception 'adapter_source_integrity' using errcode='23514';end if;
 -- This validates complete original allocations/provenance even for direct private
 -- helper calls; re-adding the existing rows obeys the unchanged role precedence.
 state:=controlled_review_v3.adapter_dispense(state,p_dispense_id,p_product_id,'original_dispense',1);
 for entry_candidate in select value from jsonb_array_elements(retained_opening.native_custody_boundary) loop
  if entry_candidate->>'dispense_id'=p_dispense_id::text then
   entry_count:=entry_count+1;entry:=entry_candidate;
  end if;
 end loop;
 if entry_count<>1 then raise exception 'adapter_source_integrity' using errcode='23514';end if;
 return_version:=public.controlled_stock_opening_selector(entry->'return_head');
 correction_version:=public.controlled_stock_opening_selector(entry->'correction_head');
 discrepancy_version:=public.controlled_stock_opening_selector(entry->'discrepancy_head');
 if entry->'pickup'<>'null'::jsonb then selected_pickup:=public.controlled_stock_uuid(entry#>'{pickup,id}');end if;
 projected:=public.controlled_stock_opening_native_entry(retained_opening.id,p_dispense_id,
  return_version,correction_version,discrepancy_version,selected_pickup);
 if entry is distinct from projected or target_correction.sequence<=correction_version
 or public.controlled_stock_opening_later_source(retained_opening.id,'correction',target_event.id) is distinct from target_event.id then
  raise exception 'adapter_source_integrity' using errcode='23514';end if;
 if jsonb_array_length(entry->'allocations')>100 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
 fully_prepared:=return_version=0 and discrepancy_version=0 and selected_pickup is null
  and not exists(select 1 from public.native_dispense_correction_events prefix_correction
   where prefix_correction.dispense_id=p_dispense_id and prefix_correction.sequence<=correction_version
   and prefix_correction.kind<>all(array['clinical_annotation','operational_annotation']));
 for original_allocation in select * from public.native_dispense_allocations
 where dispense_id=p_dispense_id order by id limit 101 loop
  allocation_count:=allocation_count+1;
  if allocation_count>100 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
  select value into boundary_allocation from jsonb_array_elements(entry->'allocations')
   where value->>'allocation_id'=original_allocation.id::text;
  if boundary_allocation is null or boundary_allocation->>'lot_id' is distinct from original_allocation.lot_id::text
  or original_allocation.quantity<=0
  or (boundary_allocation->>'dispensed_quantity')::numeric is distinct from original_allocation.quantity then
   raise exception 'adapter_source_integrity' using errcode='23514';end if;
  expected_prepared:=(boundary_allocation->>'prepared_quantity')::numeric;
  if expected_prepared is null or expected_prepared<0 then raise exception 'adapter_source_integrity' using errcode='23514';end if;
  if expected_prepared<>original_allocation.quantity or boundary_allocation->'held'<>'[]'::jsonb then fully_prepared:=false;end if;
  allocation_map:=allocation_map||jsonb_build_object(original_allocation.id::text,boundary_allocation);
 end loop;
 if allocation_count=0 or allocation_count<>jsonb_array_length(entry->'allocations') then
  raise exception 'adapter_source_integrity' using errcode='23514';end if;
 -- Preserve assertion/managed cross-set agreement even when O is unsupported.
 for retained_node in select value from jsonb_each(state->'rows') loop
  if retained_node->>'relation'='public.controlled_stock_containers' then
   selected_site:=(retained_node#>>'{row,controlling_site_id}')::uuid;
   if selected_site is null or(retained_site is not null and retained_site<>selected_site) then
    raise exception 'adapter_source_integrity' using errcode='23514';end if;
   retained_site:=selected_site;
  end if;
 end loop;
 for selected_cell in select * from public.controlled_stock_cells
 where opening_id=retained_opening.id and dispense_id=p_dispense_id and channel='prepared'
 order by id limit 513 loop
  cell_count:=cell_count+1;if cell_count>512 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
  boundary_allocation:=allocation_map->selected_cell.allocation_id::text;
  select * into selected_container from public.controlled_stock_containers where id=selected_cell.container_id;
  if boundary_allocation is null or selected_cell.lot_id::text is distinct from boundary_allocation->>'lot_id'
  or selected_cell.intake_id is not null or selected_cell.created_event_id is not null or selected_cell.opening_quantity<0
  or selected_container.id is null or selected_container.opening_id is distinct from retained_opening.id
  or selected_container.product_id is distinct from p_product_id or selected_container.stock_unit is distinct from opening_unit
  or selected_container.kind is distinct from 'prepared' or selected_container.stock_lot_id is not null
  or selected_container.created_event_id is not null or selected_container.controlling_site_id is null then
   raise exception 'adapter_source_integrity' using errcode='23514';end if;
  selected_site:=selected_container.controlling_site_id;
  if retained_site is not null and selected_site<>retained_site then
   raise exception 'adapter_source_integrity' using errcode='23514';end if;
  state:=controlled_review_v3.adapter_add(state,'public.controlled_stock_cells',jsonb_build_object('id',selected_cell.id),to_jsonb(selected_cell),'opening_basis');
  state:=controlled_review_v3.adapter_add(state,'public.controlled_stock_containers',jsonb_build_object('id',selected_container.id),to_jsonb(selected_container),'opening_basis');
  -- Private same-phase canonical membership, never a role/authorization flag.
  opening_container_map:=opening_container_map||jsonb_build_object(selected_container.id::text,true);
  actual_prepared:=coalesce((prepared_sums->>selected_cell.allocation_id::text)::numeric,0)+selected_cell.opening_quantity;
  prepared_sums:=prepared_sums||jsonb_build_object(selected_cell.allocation_id::text,actual_prepared);
  if selected_cell.opening_quantity>0 then positive_sites:=positive_sites||jsonb_build_object(selected_site::text,true);
  else zero_sites:=zero_sites||jsonb_build_object(selected_site::text,true);end if;
 end loop;
 for boundary_allocation in select value from jsonb_each(allocation_map) loop
  actual_prepared:=coalesce((prepared_sums->>(boundary_allocation->>'allocation_id'))::numeric,0);
  if actual_prepared is distinct from (boundary_allocation->>'prepared_quantity')::numeric then
   raise exception 'adapter_source_integrity' using errcode='23514';end if;
 end loop;
 if positive_sites<>'{}'::jsonb then
  for site_key in select jsonb_object_keys(zero_sites) loop
   if not(positive_sites?site_key) then raise exception 'adapter_source_integrity' using errcode='23514';end if;
  end loop;
 end if;
 selected_site:=null;
 if not fully_prepared or positive_sites='{}'::jsonb then reason:='opening_package_incomplete';
 elsif(select count(*) from jsonb_object_keys(positive_sites))<>1 then reason:='opening_package_multisite';
 else select jsonb_object_keys(positive_sites)::uuid into selected_site;end if;
 select coalesce(jsonb_agg(selected_ids.key order by selected_ids.key collate "C"),'[]'::jsonb)into opening_container_ids
 from jsonb_object_keys(opening_container_map)as selected_ids(key);
 return jsonb_build_object('state',state,'site_id',selected_site,'reason',reason,'opening_container_ids',opening_container_ids);
end

controlled_review_v3.adapter_parent(p_st.source:
declare state jsonb:=p_state; e public.controlled_stock_events; r record; row_value jsonb;
begin
 if p_role is null or p_role<>all(array['reviewed_target','correction_target','ordinary_source','original_dispense','original_pickup']) then
  raise exception 'adapter_source_role_conflict' using errcode='23514';end if;
 select * into e from public.controlled_stock_events where id=p_event_id;
 if e.id is null or e.product_id::text is distinct from state->>'product_id'
 or e.opening_id::text is distinct from state->>'opening_id' then
  raise exception 'adapter_parent_integrity' using errcode='23514';end if;
 perform public.controlled_stock_validate_event(e.id);
 state:=controlled_review_v3.adapter_add(state,'public.controlled_stock_events',jsonb_build_object('id',e.id),to_jsonb(e),p_role);
 select to_jsonb(a) into row_value from public.controlled_stock_actions a where a.id=e.id;
 state:=controlled_review_v3.adapter_add(state,'public.controlled_stock_actions',jsonb_build_object('id',e.id),row_value,p_role);
 select to_jsonb(a) into row_value from public.controlled_stock_preparations a where a.id=e.id;
 state:=controlled_review_v3.adapter_add(state,'public.controlled_stock_preparations',jsonb_build_object('id',e.id),row_value,p_role);
 select to_jsonb(a) into row_value from public.controlled_stock_policy_versions a where a.id=e.policy_version_id;
 state:=controlled_review_v3.adapter_add(state,'public.controlled_stock_policy_versions',jsonb_build_object('id',e.policy_version_id),row_value,p_role);
 select to_jsonb(a) into row_value from public.controlled_stock_openings a where a.id=e.opening_id;
 state:=controlled_review_v3.adapter_add(state,'public.controlled_stock_openings',jsonb_build_object('id',e.opening_id),row_value,p_role);
 for r in select * from public.controlled_stock_source_links where event_id=e.id order by id limit 513 loop
  state:=controlled_review_v3.adapter_add(state,'public.controlled_stock_source_links',jsonb_build_object('id',r.id),to_jsonb(r),p_role);
 end loop;
 for r in select * from public.controlled_stock_event_lines where event_id=e.id order by cell_id,source_link_id limit 513 loop
  state:=controlled_review_v3.adapter_add(state,'public.controlled_stock_event_lines',jsonb_build_object('id',r.id),to_jsonb(r),p_role);
  select to_jsonb(c) into row_value from public.controlled_stock_cells c where c.id=r.cell_id;
  state:=controlled_review_v3.adapter_add(state,'public.controlled_stock_cells',jsonb_build_object('id',r.cell_id),row_value,p_role);
  select to_jsonb(c) into row_value from public.controlled_stock_containers c where c.id=(row_value->>'container_id')::uuid;
  state:=controlled_review_v3.adapter_add(state,'public.controlled_stock_containers',jsonb_build_object('id',row_value->'id'),row_value,p_role);
 end loop;
 for r in select * from public.controlled_stock_container_transitions where event_id=e.id order by container_id limit 513 loop
  state:=controlled_review_v3.adapter_add(state,'public.controlled_stock_container_transitions',jsonb_build_object('id',r.id),to_jsonb(r),p_role);
  select to_jsonb(c) into row_value from public.controlled_stock_containers c where c.id=r.container_id;
  state:=controlled_review_v3.adapter_add(state,'public.controlled_stock_containers',jsonb_build_object('id',r.container_id),row_value,p_role);
 end loop;
 return state;
end

controlled_review_v3.adapter_pickup(p_st.source:
declare state jsonb:=p_state; p public.native_pickups; op public.native_fulfillment_operations;
 provenance public.stock_pickup_sources; managed jsonb;
begin
 if p_role is null or p_role<>all(array['reviewed_target','original_pickup']) then
  raise exception 'adapter_source_role_conflict' using errcode='23514';end if;
 if p_depth is null or p_depth<0 or p_depth>4 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
 select * into p from public.native_pickups where id=p_pickup_id;
 select * into op from public.native_fulfillment_operations where id=p_pickup_id;
 select * into provenance from public.stock_pickup_sources where event_id=p_pickup_id;
 if p.id is null or op.id is null or op.operation<>'pickup' or op.actor_id<>p.actor_id or op.result is distinct from p.document then
  raise exception 'adapter_source_integrity' using errcode='23514';end if;
 managed:=controlled_review_v3.managed_source_event(jsonb_build_object('source_kind','pickup','source_id',p.id,'product_id',p_product_id));
 if managed is not null then state:=controlled_review_v3.adapter_parent(state,(managed->>'event_id')::uuid,p_role);end if;
 if provenance.event_id is null and managed is not null then raise exception 'adapter_source_integrity' using errcode='23514';end if;
 if provenance.event_id is not null then
  if provenance.actor_id<>p.actor_id then raise exception 'adapter_source_integrity' using errcode='23514';end if;
  state:=controlled_review_v3.adapter_add(state,'public.stock_pickup_sources',jsonb_build_object('event_id',p.id),to_jsonb(provenance),p_role);
 end if;
 state:=controlled_review_v3.adapter_add(state,'public.native_pickups',jsonb_build_object('id',p.id),to_jsonb(p),p_role);
 state:=controlled_review_v3.adapter_add(state,'public.native_fulfillment_operations',jsonb_build_object('id',op.id),to_jsonb(op),p_role);
 state:=controlled_review_v3.adapter_dispense(state,p.dispense_id,p_product_id,'original_dispense',p_depth+1);
 return state;
end

controlled_review_v3.adapter_return(p_st.source:
declare state jsonb:=p_state; r public.native_return_events; op public.native_return_operations;
 provenance public.stock_custody_sources; original public.native_return_events;
 stock public.native_return_stock_links; movement public.inventory_movements; a public.native_dispense_allocations;
 x record; managed jsonb; source_writer text; n integer:=0; source_count integer; target_id uuid;
begin
 if p_role is null or p_role<>all(array['reviewed_target','correction_target','ordinary_source','original_intake','resolution_correction']) then
  raise exception 'adapter_source_role_conflict' using errcode='23514';end if;
 if p_depth is null or p_depth<0 or p_depth>4 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
 select * into r from public.native_return_events where id=p_return_id;
 select * into op from public.native_return_operations where id=p_return_id;
 select * into provenance from public.stock_custody_sources where event_id=p_return_id;
 source_writer:=case r.document->>'version' when '1' then 'record_native_dispense_return' when '2' then 'record_native_dispense_return_v2' end;
 if r.id is null or op.id is null or source_writer is null or op.actor_id<>r.actor_id or op.result is distinct from r.document
 or r.document->>'record_hash' is distinct from r.record_hash or public.native_fulfillment_hash(r.document-'record_hash') is distinct from r.record_hash then
  raise exception 'adapter_source_integrity' using errcode='23514';end if;
 managed:=controlled_review_v3.managed_source_event(jsonb_build_object('source_kind','return','source_id',r.id,'product_id',p_product_id));
 -- Only these return roles declare parent/physical reference edges.
 if managed is not null and p_role in('reviewed_target','correction_target','ordinary_source') then
  state:=controlled_review_v3.adapter_parent(state,(managed->>'event_id')::uuid,p_role);end if;
 if provenance.event_id is null and managed is not null then raise exception 'adapter_source_integrity' using errcode='23514';end if;
 if provenance.event_id is not null then
  if provenance.actor_id<>r.actor_id or provenance.writer<>source_writer then raise exception 'adapter_source_integrity' using errcode='23514';end if;
  state:=controlled_review_v3.adapter_add(state,'public.stock_custody_sources',jsonb_build_object('event_id',r.id),to_jsonb(provenance),p_role);
 end if;
 state:=controlled_review_v3.adapter_add(state,'public.native_return_events',jsonb_build_object('id',r.id),to_jsonb(r),p_role);
 state:=controlled_review_v3.adapter_add(state,'public.native_return_operations',jsonb_build_object('id',op.id),to_jsonb(op),p_role);
 state:=controlled_review_v3.adapter_dispense(state,r.dispense_id,p_product_id,'original_dispense',p_depth+1);
 if r.intake_id is not null then
  select * into original from public.native_return_events where id=r.intake_id;
  if original.id is null or original.id=r.id or original.action<>'intake' or original.dispense_id<>r.dispense_id or original.sequence>=r.sequence then
   raise exception 'adapter_source_integrity' using errcode='23514';end if;
  state:=controlled_review_v3.adapter_return(state,original.id,p_product_id,'original_intake',p_depth+1);
 end if;
 if r.action in('retract_intake','retract_disposal','retract_restock') then
  target_id:=(r.document#>>'{correction_target,event_id}')::uuid;
  select * into original from public.native_return_events where id=target_id;
  if original.id is null or original.id=r.id or original.dispense_id<>r.dispense_id or original.sequence>=r.sequence
  or original.record_hash is distinct from r.document#>>'{correction_target,record_hash}'
  or original.action is distinct from(case r.action when 'retract_intake' then 'intake' when 'retract_disposal' then 'dispose' else 'restock' end)
  or controlled_review_v3.managed_source_event(jsonb_build_object('source_kind','return','source_id',target_id,'product_id',p_product_id)) is null then
   raise exception 'adapter_source_integrity' using errcode='23514';end if;
  state:=controlled_review_v3.adapter_return(state,target_id,p_product_id,'correction_target',p_depth+1);
 end if;
 if r.action='restock' then
  for x in select * from public.native_return_stock_links where event_id=r.id order by allocation_id limit 101 loop
   n:=n+1;if n>100 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
   select * into a from public.native_dispense_allocations where id=x.allocation_id;
   select * into movement from public.inventory_movements where id=x.movement_id;
   if a.id is null or movement.id is null or a.dispense_id<>r.dispense_id or a.lot_id<>x.lot_id or movement.lot_id<>x.lot_id or movement.quantity<>x.quantity
   or not exists(select 1 from jsonb_array_elements(r.document->'allocations') d where d->>'allocation_id'=x.allocation_id::text
    and d->>'movement_id'=x.movement_id::text and(d->>'quantity')::numeric=x.quantity and d->>'lot_id'=x.lot_id::text) then
    raise exception 'adapter_source_integrity' using errcode='23514';end if;
   state:=controlled_review_v3.adapter_add(state,'public.native_return_stock_links',jsonb_build_object('id',x.id),to_jsonb(x),p_role);
   state:=controlled_review_v3.adapter_movement(state,x.movement_id,source_writer,r.id,r.actor_id,p_role,managed is not null);
  end loop;
 elsif r.action='retract_restock' then
  for x in select * from public.native_return_compensation_links where event_id=r.id order by allocation_id limit 101 loop
   n:=n+1;if n>100 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
   select * into stock from public.native_return_stock_links where event_id=target_id and allocation_id=x.allocation_id;
   select * into movement from public.inventory_movements where id=x.movement_id;
   if stock.id is null or movement.id is null or x.target_event_id<>target_id or x.original_movement_id<>stock.movement_id or x.lot_id<>stock.lot_id
   or movement.lot_id<>x.lot_id or movement.quantity<>-x.quantity
   or not exists(select 1 from jsonb_array_elements(r.document->'allocations') d where d->>'allocation_id'=x.allocation_id::text
    and d->>'movement_id'=x.movement_id::text and(d->>'quantity')::numeric=x.quantity and d->>'lot_id'=x.lot_id::text) then
    raise exception 'adapter_source_integrity' using errcode='23514';end if;
   state:=controlled_review_v3.adapter_add(state,'public.native_return_compensation_links',jsonb_build_object('id',x.id),to_jsonb(x),p_role);
   state:=controlled_review_v3.adapter_add(state,'public.native_return_stock_links',jsonb_build_object('id',stock.id),to_jsonb(stock),'correction_target');
   -- adapter_return(target) already retained/checked the original positive movement.
   -- Its exact stock link above binds original_movement_id; retain the distinct negative movement now.
   state:=controlled_review_v3.adapter_movement(state,x.movement_id,source_writer,r.id,r.actor_id,p_role,managed is not null);
  end loop;
 end if;
 if r.action in('restock','retract_restock') and(n=0 or n<>jsonb_array_length(r.document->'allocations')) then
  raise exception 'adapter_source_integrity' using errcode='23514';end if;
 select count(*) into source_count from(select movement_id from public.stock_movement_sources s where s.writer=source_writer and s.source_id=r.id limit 101) q;
 if source_count>100 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
 if source_count not in(0,n) or(managed is not null and source_count<>n)
 or exists(select 1 from public.stock_movement_sources s where s.writer=source_writer and s.source_id=r.id
  and not exists(select 1 from public.native_return_stock_links l where r.action='restock' and l.event_id=r.id and l.movement_id=s.movement_id)
  and not exists(select 1 from public.native_return_compensation_links l where r.action='retract_restock' and l.event_id=r.id and l.movement_id=s.movement_id)) then
  raise exception 'adapter_source_integrity' using errcode='23514';end if;
 return state;
end

controlled_review_v3.calendar_candidates.source:
declare zone_name text;v jsonb;t text;local_value timestamp;previous text;result jsonb;
begin
 if jsonb_typeof(p_request)is distinct from 'object' or octet_length(p_request::text)>131072 then
  raise exception 'calendar_invalid_request' using errcode='23514';end if;
 if (select array_agg(k order by k)from jsonb_object_keys(p_request)k)is distinct from array['local_values','zone'] then
  raise exception 'calendar_invalid_request' using errcode='23514';
 end if;
 if jsonb_typeof(p_request->'zone')is distinct from 'string' then
  raise exception 'calendar_invalid_zone' using errcode='23514';end if;
 zone_name:=p_request->>'zone';
 if octet_length(zone_name)not between 1 and 100 or
 (zone_name<>'UTC' and(zone_name!~'^[A-Za-z][A-Za-z0-9_+-]*(/[A-Za-z0-9_+-]+)+$'
 or zone_name like 'posix/%' or zone_name like 'right/%'))
 or not exists(select 1 from pg_timezone_names where name=zone_name)then
  raise exception 'calendar_invalid_zone' using errcode='23514';end if;
 if jsonb_typeof(p_request->'local_values')is distinct from 'array' then
  raise exception 'calendar_invalid_local_values' using errcode='23514';end if;
 if jsonb_array_length(p_request->'local_values')not between 1 and 63 then
  raise exception 'calendar_local_value_limit' using errcode='23514';end if;
 for v in select value from jsonb_array_elements(p_request->'local_values')loop
  if jsonb_typeof(v)is distinct from 'string' then
   raise exception 'calendar_invalid_local_value' using errcode='23514';end if;
  t:=v#>>'{}';
  if t!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}$'
  or(previous is not null and t collate "C"<=previous collate "C")then
   raise exception 'calendar_invalid_local_value' using errcode='23514';end if;
  begin local_value:=t::timestamp;
  exception when invalid_datetime_format or datetime_field_overflow then
   raise exception 'calendar_invalid_local_value' using errcode='23514';end;
  if not isfinite(local_value)or local_value<timestamp '2026-01-01 00:00:00'
  or local_value>timestamp '2101-01-01 00:00:00'
  or to_char(local_value,'YYYY-MM-DD"T"HH24:MI:SS')<>t then
   raise exception 'calendar_invalid_local_value' using errcode='23514';end if;
  previous:=t;
 end loop;
 -- Exactly100801 integral-second offsets per distinct local value, at most
 -- 6,350,463 round-trips. No sampling and no contemporary utc_offset fallback.
 with local_inputs as materialized(
  select value as label,value::timestamp as local_value
  from jsonb_array_elements_text(p_request->'local_values')
 ), matches as materialized(
  select l.label,o.offset_seconds,
   (l.local_value-o.offset_seconds*interval '1 second')at time zone 'UTC' as candidate
  from local_inputs l cross join generate_series(-50400,50400)as o(offset_seconds)
  where (((l.local_value-o.offset_seconds*interval '1 second')at time zone 'UTC')at time zone zone_name)=l.local_value
 ), grouped as(
  select l.label,coalesce((select jsonb_agg(jsonb_build_object(
   'utc',to_char(m.candidate at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
   'offset_seconds',m.offset_seconds)order by m.candidate)
   from matches m where m.label=l.label),'[]'::jsonb)as candidates from local_inputs l
 )select jsonb_agg(jsonb_build_object('local_timestamp',label,'candidates',candidates)order by label collate "C")
 into result from grouped;
 -- Bound every retained candidate, including an unselected side of a fold.
 if exists(select 1 from jsonb_array_elements(result)r cross join lateral jsonb_array_elements(r->'candidates')c
  where(c->>'utc')::timestamptz<timestamptz '2026-01-01 00:00:00Z'
   or(c->>'utc')::timestamptz>=timestamptz '2101-01-01 00:00:00Z')then
  raise exception 'calendar_observation_range' using errcode='23514';end if;
 return result;
end

controlled_review_v3.collect_event_sourc.source:
declare e public.controlled_stock_events; state jsonb; adapter jsonb; refs jsonb; rows jsonb;
 target jsonb; result jsonb; adapter_id text; site uuid; site_basis text; reason text;
 did uuid; family uuid; managed jsonb; source_id uuid; node jsonb; retained_site uuid; node_site uuid;
 opening_projection jsonb; before_opening_containers jsonb:='{}'; opening_scope_ids jsonb; opening_scope_map jsonb:='{}'; opening_seen_map jsonb:='{}'; scope_item jsonb; scope_id uuid; scope_sorted jsonb;
begin
 if p_event_id is null or p_event_id='00000000-0000-0000-0000-000000000000'::uuid then
  raise exception 'invalid_adapter_argument' using errcode='22023';end if;
 perform pg_advisory_xact_lock_shared(90271040,0);
 perform controlled_review_v3.required();
 select * into e from public.controlled_stock_events where id=p_event_id;
 if e.id is null then raise exception 'invalid_adapter_argument' using errcode='22023';end if;
 -- Whole literal dispatch precedes any transition/site inspection.
 case e.event_kind
 when 'receive_inventory','adjust_inventory' then adapter_id:='movement_v1';
 when 'record_patient_treatment' then adapter_id:='treatment_v1';
 when 'record_anesthesia_drug_administration' then adapter_id:='anesthesia_v1';
 when 'record_native_dispense' then adapter_id:='dispense_v1';
 when 'record_native_pickup' then adapter_id:='pickup_v1';
 when 'record_native_dispense_return:intake','record_native_dispense_return:dispose','record_native_dispense_return:restock' then adapter_id:='return_v1';
 when 'record_native_dispense_return_v2:intake','record_native_dispense_return_v2:dispose','record_native_dispense_return_v2:restock' then adapter_id:='return_v2';
 when 'record_native_dispense_return_v2:retract_intake','record_native_dispense_return_v2:retract_disposal','record_native_dispense_return_v2:retract_restock' then adapter_id:='retraction_v1';
 when 'record_native_return_discrepancy:report','record_native_return_discrepancy:note','record_native_return_discrepancy:resolve_corrected','record_native_return_discrepancy:resolve_confirmed_original' then adapter_id:='discrepancy_v1';
 when 'append_native_dispense_correction:clinical_annotation','append_native_dispense_correction:operational_annotation','append_native_dispense_correction:pickup_amendment' then adapter_id:='annotation_v1';
 else raise exception 'unsupported_event_kind' using errcode='22023';end case;
 state:=jsonb_build_object('rows','{}'::jsonb,'documents','[]'::jsonb,'allocations','[]'::jsonb,
  'target_event_id',e.id,'product_id',e.product_id,'opening_id',e.opening_id);
 state:=controlled_review_v3.adapter_parent(state,e.id,'reviewed_target');
 if adapter_id in('movement_v1','treatment_v1','anesthesia_v1') then
  state:=controlled_review_v3.adapter_clinical(state,e.id);
 elsif adapter_id='dispense_v1' then
  did:=e.id;family:=did;state:=controlled_review_v3.adapter_dispense(state,did,e.product_id,'reviewed_target',0);
 elsif adapter_id='pickup_v1' then
  select dispense_id into did from public.native_pickups where id=e.id;
  family:=did;state:=controlled_review_v3.adapter_pickup(state,e.id,e.product_id,'reviewed_target',0);
 elsif adapter_id in('return_v1','return_v2','retraction_v1') then
  state:=controlled_review_v3.adapter_return(state,e.id,e.product_id,'reviewed_target',0);
 else state:=controlled_review_v3.adapter_context(state,e.id);end if;
 if adapter_id='annotation_v1' then
  select dispense_id into did from public.native_dispense_correction_events where id=e.id;
  managed:=controlled_review_v3.managed_source_event(jsonb_build_object('source_kind','dispense','source_id',did,'product_id',e.product_id));
  if managed is null then
   if e.event_kind in('append_native_dispense_correction:clinical_annotation','append_native_dispense_correction:operational_annotation')then
    -- Capture ALL existing container IDs before the fixed canonical helper.
    for node in select value from jsonb_each(state->'rows')loop
     if node->>'relation'='public.controlled_stock_containers'then
      before_opening_containers:=before_opening_containers||jsonb_build_object(public.controlled_stock_uuid(node#>'{key,id}')::text,true);
     end if;
    end loop;
    opening_projection:=controlled_review_v3.adapter_opening_site(state,did,e.product_id);state:=opening_projection->'state';
    site:=(opening_projection->>'site_id')::uuid;reason:=opening_projection->>'reason';site_basis:=case when site is null then 'unproven'else 'opening_custody_site'end;
   else reason:='unmanaged_original_dispense';end if;
  else site:=(controlled_review_v3.adapter_event_site((managed->>'event_id')::uuid)->>'site_id')::uuid;site_basis:='managed_dispense';end if;
 elsif adapter_id='discrepancy_v1' then
  select(document#>>'{source,event_id}')::uuid into source_id from public.native_return_discrepancy_events where id=e.id;
  managed:=controlled_review_v3.managed_source_event(jsonb_build_object('source_kind','return','source_id',source_id,'product_id',e.product_id));
  if managed is null then reason:='unmanaged_original_return';
  else site:=(controlled_review_v3.adapter_event_site((managed->>'event_id')::uuid)->>'site_id')::uuid;site_basis:='managed_return';end if;
 else
  site:=(controlled_review_v3.adapter_event_site(e.id)->>'site_id')::uuid;site_basis:='event_transitions';
 end if;
 -- Available retained managed/source and assertion transitions must agree even
 -- when A1 cannot establish a supported site. This scan never supplies the site.
 -- Only a fresh helper-owned canonical set can scope the unsupported path.
 if opening_projection is not null and managed is null
 and e.event_kind in('append_native_dispense_correction:clinical_annotation','append_native_dispense_correction:operational_annotation')
 and opening_projection->'site_id'='null'::jsonb and site is null
 and opening_projection->>'reason'in('opening_package_incomplete','opening_package_multisite')
 and reason=opening_projection->>'reason'and site_basis='unproven'
 and before_opening_containers='{}'::jsonb then
  perform public.controlled_stock_keys(opening_projection,array['state','site_id','reason','opening_container_ids']);
  opening_scope_ids:=opening_projection->'opening_container_ids';
  if jsonb_typeof(opening_scope_ids)is distinct from 'array'then raise exception 'adapter_source_integrity'using errcode='23514';end if;
  if jsonb_array_length(opening_scope_ids)>512 then raise exception 'adapter_source_integrity'using errcode='23514';end if;
  for scope_item in select value from jsonb_array_elements(opening_scope_ids)loop
   scope_id:=public.controlled_stock_uuid(scope_item);
   if opening_scope_map?scope_id::text then raise exception 'adapter_source_integrity'using errcode='23514';end if;
   opening_scope_map:=opening_scope_map||jsonb_build_object(scope_id::text,true);
  end loop;
  select coalesce(jsonb_agg(scope_keys.key order by scope_keys.key collate "C"),'[]'::jsonb)into scope_sorted
  from jsonb_object_keys(opening_scope_map)as scope_keys(key);
  if opening_scope_ids is distinct from scope_sorted then raise exception 'adapter_source_integrity'using errcode='23514';end if;
 end if;
 for node in select value from jsonb_each(state->'rows') loop
  if node->>'relation'='public.controlled_stock_containers' then
   node_site:=(node#>>'{row,controlling_site_id}')::uuid;
   if opening_scope_ids is not null then
    scope_id:=public.controlled_stock_uuid(node#>'{key,id}');
    if node_site is null or node#>'{row,id}'is distinct from to_jsonb(scope_id)
    or not(opening_scope_map?scope_id::text)or opening_seen_map?scope_id::text then
     raise exception 'adapter_source_integrity'using errcode='23514';end if;
    opening_seen_map:=opening_seen_map||jsonb_build_object(scope_id::text,true);
   else
   if node_site is null or(retained_site is not null and retained_site<>node_site) then
    raise exception 'adapter_source_integrity' using errcode='23514';end if;
   retained_site:=node_site;
   end if;
  end if;
 end loop;
 if opening_scope_ids is not null and opening_seen_map is distinct from opening_scope_map then
  raise exception 'adapter_source_integrity'using errcode='23514';end if;
 if reason is null then
  if site is null or(retained_site is not null and retained_site<>site) then
   raise exception 'adapter_source_integrity' using errcode='23514';end if;
 else site:=null;site_basis:='unproven';end if;
 target:=jsonb_build_object('event_id',e.id,'product_id',e.product_id,'sequence',e.sequence,'record_hash',e.record_hash,
  'original_actor_id',e.actor_id,'policy_version_id',e.policy_version_id,'opening_id',e.opening_id,'engine_revision',e.engine_revision);
 select coalesce(jsonb_agg(value-'row' order by (value->>'relation') collate "C",(value->'key')::text collate "C"),'[]'::jsonb),
  coalesce(jsonb_agg(value-'row_hash'-'role' order by (value->>'relation') collate "C",(value->'key')::text collate "C"),'[]'::jsonb)
 into refs,rows from jsonb_each(state->'rows');
 adapter:=jsonb_build_object('version',1,'event_kind',e.event_kind,'adapter_id',adapter_id,'target',target,
  'site_basis',site_basis,'site_id',site,'source_refs',refs,'native_family_dispense_id',family,
  'provenance_state',case when reason is null then 'supported' else 'unsupported' end,'reason',reason);
 result:=jsonb_build_object('adapter',adapter,'source_rows',rows);
 if octet_length(result::text)>1048576 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
 return result;
end

controlled_review_v3.configuration_recor.source:
declare stored_document jsonb;complete_record jsonb;expected_stream jsonb;version_value integer;
begin
 if jsonb_typeof(p_row)is distinct from 'object'or octet_length(p_row::text)>262144 then
  raise exception 'configuration_record_invalid'using errcode='23514';end if;
 perform public.controlled_stock_keys(p_row,array['id','kind','stream_key','version','predecessor_id','predecessor_hash','enabled','document','record_hash','publication_operation_id','published_at','publisher_actor_id','publisher_session_id','publisher_name','authorization_id','publication_mode','effective_from']);
 stored_document:=p_row->'document';
 if jsonb_typeof(stored_document)is distinct from 'object'or octet_length(stored_document::text)>131072
  or jsonb_typeof(p_row->'stream_key')is distinct from 'object'or octet_length((p_row->'stream_key')::text)>4096 then
  raise exception 'configuration_record_invalid'using errcode='23514';end if;
 -- JSONB equality treats1 and1.0 as equal; check this duplicated scalar first.
 if jsonb_typeof(p_row->'version')is distinct from 'number'or(p_row->>'version')!~'^[1-9][0-9]*$'then
  raise exception 'configuration_record_invalid'using errcode='23514';end if;
 version_value:=(p_row->>'version')::integer;
 if version_value<1 then raise exception 'configuration_record_invalid'using errcode='23514';end if;
 -- Validate D before repeated fields or constructing the complete record.
 perform controlled_review_v3.validate_stored_configuration(stored_document);
 if p_row->'kind'is distinct from stored_document->'kind'
  or p_row->'version'is distinct from stored_document->'version'
  or p_row->'predecessor_id'is distinct from stored_document->'predecessor_id'
  or p_row->'predecessor_hash'is distinct from stored_document->'predecessor_hash'
  or p_row->'enabled'is distinct from stored_document->'enabled'then
  raise exception 'configuration_record_invalid'using errcode='23514';end if;
 expected_stream:=jsonb_build_object('kind',stored_document->'kind','product_id',stored_document#>'{scope,product_id}',
  'site_id',stored_document#>'{scope,site_id}','event_kind',stored_document#>'{scope,event_kind}','capability',stored_document#>'{scope,capability}');
 if p_row->'stream_key'is distinct from expected_stream then raise exception 'configuration_record_invalid'using errcode='23514';end if;
 if stored_document->'kind'='"policy"'::jsonb then
  if p_row->'effective_from'is distinct from stored_document#>'{body,effective_from}'then
   raise exception 'configuration_record_invalid'using errcode='23514';end if;
 elsif p_row->'effective_from'is distinct from 'null'::jsonb then
  raise exception 'configuration_record_invalid'using errcode='23514';end if;
 complete_record:=stored_document||jsonb_build_object('id',p_row->'id','publication_operation_id',p_row->'publication_operation_id',
  'published_at',p_row->'published_at','publisher_actor_id',p_row->'publisher_actor_id','publisher_session_id',p_row->'publisher_session_id',
  'publisher_name',p_row->'publisher_name','authorization_id',p_row->'authorization_id','publication_mode',p_row->'publication_mode','record_hash',p_row->'record_hash');
 if octet_length(complete_record::text)>262144 then raise exception 'configuration_record_invalid'using errcode='23514';end if;
 perform controlled_review_v3.validate_configuration_record(complete_record);
 return complete_record;
exception when check_violation or invalid_text_representation or invalid_datetime_format
 or datetime_field_overflow or numeric_value_out_of_range then
 raise exception 'configuration_record_invalid'using errcode='23514';
end

controlled_review_v3.immutable_guard().source:
begin
 raise exception 'Record-review v3 Gate B private A1 evidence is immutable' using errcode='23514';
end

controlled_review_v3.managed_source_even.source:
declare selected_source_kind text; selected_source_id uuid; product uuid; source_row jsonb; did uuid; expected_writer text;
 opening public.controlled_stock_openings; e public.controlled_stock_events; link public.controlled_stock_source_links;
 movement public.inventory_movements; provenance public.stock_movement_sources; allocation record;
 n integer:=0; linked integer:=0; opened integer:=0; sourced integer:=0; dispense_root_count integer; parent_id uuid; ids jsonb:='[]'; entry jsonb;
 native_source_provenance jsonb; selected_movement record; return_count integer:=0; return_sourced integer:=0; return_root_count integer;
begin
 if octet_length(p_request::text)>131072 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
 if jsonb_typeof(p_request) is distinct from 'object'
 or (select array_agg(k order by k) from jsonb_object_keys(p_request) k) is distinct from array['product_id','source_id','source_kind']::text[]
 or jsonb_typeof(p_request->'source_kind') is distinct from 'string'
 or jsonb_typeof(p_request->'source_id') is distinct from 'string'
 or jsonb_typeof(p_request->'product_id') is distinct from 'string'
 or p_request->>'source_id'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
 or p_request->>'product_id'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
  raise exception 'invalid_adapter_argument' using errcode='22023';end if;
 selected_source_kind:=p_request->>'source_kind';selected_source_id:=(p_request->>'source_id')::uuid;product:=(p_request->>'product_id')::uuid;
 if selected_source_id='00000000-0000-0000-0000-000000000000'::uuid or product='00000000-0000-0000-0000-000000000000'::uuid
 or selected_source_kind<>all(array['movement','return','pickup','discrepancy','correction','dispense']) then
  raise exception 'invalid_adapter_argument' using errcode='22023';end if;
 select * into opening from public.controlled_stock_openings where product_id=product;
 if opening.id is not null then perform public.controlled_stock_validate_opening(opening.id);end if;
 if selected_source_kind='movement' then
  select * into movement from public.inventory_movements where id=selected_source_id;
  if movement.id is null or not exists(select 1 from public.inventory_lots where id=movement.lot_id and product_id=product) then
   raise exception 'adapter_source_integrity' using errcode='23514';end if;
  select * into provenance from public.stock_movement_sources where movement_id=selected_source_id;
  if provenance.movement_id is not null then perform public.stock_source_validate_movement(selected_source_id);end if;
  select * into link from public.controlled_stock_source_links where movement_id=selected_source_id;
 else
  case selected_source_kind
  when 'dispense' then select to_jsonb(s) into source_row from public.native_dispenses s where s.id=selected_source_id;
  when 'return' then select to_jsonb(s) into source_row from public.native_return_events s where s.id=selected_source_id;
  when 'pickup' then select to_jsonb(s) into source_row from public.native_pickups s where s.id=selected_source_id;
  when 'discrepancy' then select to_jsonb(s) into source_row from public.native_return_discrepancy_events s where s.id=selected_source_id;
  when 'correction' then select to_jsonb(s) into source_row from public.native_dispense_correction_events s where s.id=selected_source_id;
  end case;
  if source_row is null then raise exception 'adapter_source_integrity' using errcode='23514';end if;
  did:=case when selected_source_kind='dispense' then selected_source_id else(source_row->>'dispense_id')::uuid end;
  perform public.native_fulfillment_verified_dispense(did);
  perform public.native_reconciliation_verified((source_row->>'authorization_id')::uuid,(source_row->>'pet_id')::uuid,did);
  -- Classification is independently callable: validate present native provenance
  -- even for historical_null, without relying on the collector to visit it later.
  case selected_source_kind
  when 'return' then
   select to_jsonb(s) into native_source_provenance from public.stock_custody_sources s where s.event_id=selected_source_id;
   expected_writer:=case source_row#>>'{document,version}' when '1' then 'record_native_dispense_return' when '2' then 'record_native_dispense_return_v2' end;
  when 'pickup' then select to_jsonb(s) into native_source_provenance from public.stock_pickup_sources s where s.event_id=selected_source_id;
  when 'discrepancy' then select to_jsonb(s) into native_source_provenance from public.stock_discrepancy_sources s where s.event_id=selected_source_id;
  when 'correction' then select to_jsonb(s) into native_source_provenance from public.stock_correction_sources s where s.event_id=selected_source_id;
  else null;end case;
  if native_source_provenance is not null and(
   native_source_provenance->>'actor_id' is distinct from source_row->>'actor_id'
   or(selected_source_kind='return' and native_source_provenance->>'writer' is distinct from expected_writer)) then
   raise exception 'adapter_source_integrity' using errcode='23514';end if;
  if selected_source_kind='return' then
   if expected_writer is null then raise exception 'adapter_source_integrity' using errcode='23514';end if;
   for selected_movement in
    select l.movement_id,l.lot_id,l.quantity from public.native_return_stock_links l
     where source_row->>'action'='restock' and l.event_id=selected_source_id
    union all
    select l.movement_id,l.lot_id,-l.quantity from public.native_return_compensation_links l
     where source_row->>'action'='retract_restock' and l.event_id=selected_source_id
    order by movement_id limit 101 loop
    return_count:=return_count+1;if return_count>100 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
    select * into movement from public.inventory_movements where id=selected_movement.movement_id;
    if movement.id is null or movement.lot_id<>selected_movement.lot_id or movement.quantity<>selected_movement.quantity
    or movement.created_by::text is distinct from source_row->>'actor_id'
    or movement.kind is distinct from(case source_row->>'action' when 'restock' then 'native_return' else 'native_return_compensation' end) then
     raise exception 'adapter_source_integrity' using errcode='23514';end if;
    select * into provenance from public.stock_movement_sources where movement_id=selected_movement.movement_id;
    if provenance.movement_id is not null then
     return_sourced:=return_sourced+1;
     if provenance.source_id<>selected_source_id or provenance.writer<>expected_writer
     or provenance.actor_id::text is distinct from source_row->>'actor_id' then
      raise exception 'adapter_source_integrity' using errcode='23514';end if;
     perform public.stock_source_validate_movement(provenance.movement_id);
    end if;
   end loop;
   if(source_row->>'action' in('restock','retract_restock') and(return_count=0 or return_count<>jsonb_array_length(source_row#>'{document,allocations}')))
   or return_sourced not in(0,return_count) then raise exception 'adapter_source_integrity' using errcode='23514';end if;
   select count(*) into return_root_count from(select s.movement_id from public.stock_movement_sources s
    where s.writer=expected_writer and s.source_id=selected_source_id limit 101)q;
   if return_root_count>100 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
   if return_root_count<>return_sourced or exists(select 1 from public.stock_movement_sources s
    where s.writer=expected_writer and s.source_id=selected_source_id
    and not exists(select 1 from public.native_return_stock_links l where source_row->>'action'='restock' and l.event_id=selected_source_id and l.movement_id=s.movement_id)
    and not exists(select 1 from public.native_return_compensation_links l where source_row->>'action'='retract_restock' and l.event_id=selected_source_id and l.movement_id=s.movement_id)) then
    raise exception 'adapter_source_integrity' using errcode='23514';end if;
  end if;
  for allocation in select a.* from public.native_dispense_allocations a where dispense_id=did order by lot_id limit 101 loop
   n:=n+1;if n>100 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
   if not exists(select 1 from public.inventory_lots where id=allocation.lot_id and product_id=product) then
    raise exception 'adapter_source_integrity' using errcode='23514';end if;
   select * into provenance from public.stock_movement_sources where movement_id=allocation.movement_id;
   if provenance.movement_id is not null then
    sourced:=sourced+1;
    if provenance.writer<>'record_native_dispense' or provenance.source_id<>did
    or provenance.actor_id is distinct from(select actor_id from public.native_dispenses where id=did) then
     raise exception 'adapter_source_integrity' using errcode='23514';end if;
    perform public.stock_source_validate_movement(provenance.movement_id);
   end if;
   if exists(select 1 from public.controlled_stock_opening_movements where movement_id=allocation.movement_id and opening_id=opening.id) then opened:=opened+1;end if;
   if selected_source_kind='dispense' then
    select * into link from public.controlled_stock_source_links where movement_id=allocation.movement_id;
    if link.id is not null then
     linked:=linked+1;
     if parent_id is not null and parent_id<>link.event_id then raise exception 'adapter_source_integrity' using errcode='23514';end if;
     parent_id:=link.event_id;ids:=ids||jsonb_build_array(link.id);
    end if;
   end if;
  end loop;
  if n=0 or sourced not in(0,n) or opened not in(0,n) then raise exception 'adapter_source_integrity' using errcode='23514';end if;
  select count(*) into dispense_root_count from(select s.movement_id from public.stock_movement_sources s
   where s.writer='record_native_dispense' and s.source_id=did limit 101)q;
  if dispense_root_count>100 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
  if dispense_root_count<>sourced or exists(select 1 from public.stock_movement_sources s
   where s.writer='record_native_dispense' and s.source_id=did
   and not exists(select 1 from public.native_dispense_allocations a where a.dispense_id=did and a.movement_id=s.movement_id)) then
   raise exception 'adapter_source_integrity' using errcode='23514';end if;
  if selected_source_kind='dispense' then
   if linked not in(0,n) or(linked>0 and(opened>0 or sourced<>n)) then raise exception 'adapter_source_integrity' using errcode='23514';end if;
  else
   case selected_source_kind
   when 'return' then select * into link from public.controlled_stock_source_links where return_event_id=selected_source_id;
   when 'pickup' then select * into link from public.controlled_stock_source_links where pickup_id=selected_source_id;
   when 'discrepancy' then select * into link from public.controlled_stock_source_links where discrepancy_event_id=selected_source_id;
   when 'correction' then select * into link from public.controlled_stock_source_links where correction_event_id=selected_source_id;
   end case;
  end if;
 end if;
 if selected_source_kind<>'dispense' and link.id is not null then parent_id:=link.event_id;ids:=jsonb_build_array(link.id);end if;
 if parent_id is not null then
  if(selected_source_kind not in('movement','dispense') and native_source_provenance is null)
  or(selected_source_kind='return' and return_sourced<>return_count) then
   raise exception 'adapter_source_integrity' using errcode='23514';end if;
  select * into e from public.controlled_stock_events where id=parent_id;
  if e.id is null or e.product_id<>product or(opening.id is not null and e.opening_id<>opening.id) then
   raise exception 'adapter_source_integrity' using errcode='23514';end if;
  perform public.controlled_stock_validate_event(e.id);
  expected_writer:=case selected_source_kind when 'dispense' then 'record_native_dispense' when 'pickup' then 'record_native_pickup'
   when 'correction' then 'append_native_dispense_correction' when 'discrepancy' then 'record_native_return_discrepancy'
   when 'return' then case source_row#>>'{document,version}' when '1' then 'record_native_dispense_return' when '2' then 'record_native_dispense_return_v2' end
   when 'movement' then provenance.writer end;
  if expected_writer is null or e.writer<>expected_writer or(selected_source_kind<>'movement' and(e.id<>selected_source_id or e.actor_id::text is distinct from source_row->>'actor_id'))
  or(selected_source_kind='movement' and(provenance.movement_id is null or e.id<>provenance.source_id or e.actor_id<>provenance.actor_id
   or not exists(select 1 from jsonb_array_elements(e.source_bundle->'available') x where x->>'id'=selected_source_id::text)))
  or(selected_source_kind not in('movement','dispense') and(e.source_bundle#>>'{native,kind}'<>selected_source_kind or e.source_bundle#>>'{native,id}'<>selected_source_id::text)) then
   raise exception 'adapter_source_integrity' using errcode='23514';end if;
  select jsonb_agg(x order by (x#>>'{}') collate "C") into ids from jsonb_array_elements(ids) x;
  return jsonb_build_object('event_id',e.id,'source_link_ids',ids);
 end if;
 if exists(select 1 from public.controlled_stock_events where id=case when selected_source_kind='movement' then coalesce(provenance.source_id,selected_source_id) else selected_source_id end) then
  raise exception 'adapter_source_integrity' using errcode='23514';end if;
 if opening.id is not null then
  if selected_source_kind='movement' then
   if not exists(select 1 from public.controlled_stock_opening_movements where opening_id=opening.id and movement_id=selected_source_id) then
    raise exception 'adapter_source_integrity' using errcode='23514';end if;
  else
   select x into entry from jsonb_array_elements(opening.native_custody_boundary) x where x->>'dispense_id'=did::text;
   if entry is null or opened<>n
   or(selected_source_kind='return' and(source_row->>'sequence')::integer>(entry#>>'{return_head,version}')::integer)
   or(selected_source_kind='correction' and(source_row->>'sequence')::integer>(entry#>>'{correction_head,version}')::integer)
   or(selected_source_kind='discrepancy' and(source_row->>'sequence')::integer>(entry#>>'{discrepancy_head,version}')::integer)
   or(selected_source_kind='pickup' and entry#>>'{pickup,id}' is distinct from selected_source_id::text) then
    raise exception 'adapter_source_integrity' using errcode='23514';end if;
  end if;
 end if;
 return null;
end

controlled_review_v3.ops_action_context(.source:
declare raw_value text;decoded_value json;value jsonb;
begin
 raw_value:=current_setting('controlled_review_v3.escalation_action_request',true);
 if raw_value is null or octet_length(raw_value)>32768 then raise exception 'review_action_context_invalid'using errcode='23514';end if;
 begin decoded_value:=raw_value::json;exception when invalid_text_representation then raise exception 'review_action_context_invalid'using errcode='23514';end;
 perform controlled_review_v3.protocol_context_unique(decoded_value,0);value:=decoded_value::jsonb;
 perform public.controlled_stock_keys(value,array['request','route']);
 perform controlled_review_v3.ops_action_plan(value->'request',value->'route');
 return value;
end

controlled_review_v3.ops_action_mutation.source:
declare request_value jsonb:=controlled_review_v3.protocol_validate_wire(p_request,'record_controlled_review_escalation_action_v3');actor_value uuid;operation_value uuid;existing_value controlled_review_v3.escalation_actions;
 escalation_value controlled_review_v3.escalations;obligation_value controlled_review_v3.obligations;stream_value jsonb;authority_value jsonb;route_value jsonb;actual_route jsonb;plan_value jsonb;keys_value jsonb;old_context text;
begin
 actor_value:=(request_value->>'actor_id')::uuid;operation_value:=(request_value->>'operation_id')::uuid;
 perform controlled_review_v3.ops_action_preflight();perform controlled_review_v3.read_prelude(actor_value);
 keys_value:=jsonb_build_array(jsonb_build_object('class_id',90271101,'key','review-v3-escalation-operation:'||operation_value::text,'mode','exclusive'));
 perform controlled_review_v3.protocol_acquire_advisory(keys_value,actor_value);
 select *into existing_value from controlled_review_v3.escalation_actions where operation_id=operation_value;
 if found then
  if existing_value.actor_id is distinct from actor_value then raise exception 'operation_not_found'using errcode='PT404';end if;
  if existing_value.request_hash is distinct from public.controlled_stock_hash(request_value)then raise exception 'operation_request_mismatch'using errcode='PT409';end if;
  perform controlled_review_v3.ops_admin_read_tail(actor_value);perform controlled_review_v3.ops_validate_action(to_jsonb(existing_value));perform controlled_review_v3.required();perform controlled_review_v3.protocol_identity(actor_value);
  return jsonb_build_object('version',3,'state','recorded','data',jsonb_build_object('operation_id',operation_value,'receipt',existing_value.receipt));
 end if;
 select *into escalation_value from controlled_review_v3.escalations where id=(request_value->>'escalation_id')::uuid;
 if not found then raise exception 'review_escalation_not_authorized'using errcode='42501';end if;
 select *into strict obligation_value from controlled_review_v3.obligations where event_id=escalation_value.event_id;
 route_value:=jsonb_build_object('event_id',escalation_value.event_id,'product_id',obligation_value.product_id,'native_family_dispense_id',obligation_value.adapter->'native_family_dispense_id','family_row_id',obligation_value.family_dispense_id,'administration_id',null);
 -- All earlier family/event gates precede the administration stream; its actual
 -- record UUID is selected under that stream before the full FK/table tail.
 keys_value:=jsonb_build_array(jsonb_build_object('class_id',90271101,'key','review-v3-escalation-operation:'||operation_value::text,'mode','exclusive'));
 if route_value->'native_family_dispense_id'<>'null'::jsonb then keys_value:=keys_value||jsonb_build_array(jsonb_build_object('class_id',90271102,'key','review-v3-family:'||(route_value->>'native_family_dispense_id'),'mode','exclusive'));end if;
 stream_value:=controlled_review_v3.protocol_stream_key(jsonb_build_object('kind','administration','product_id',route_value->'product_id','site_id',null,'event_kind',null,'capability',null));
 keys_value:=keys_value||jsonb_build_array(jsonb_build_object('class_id',90271103,'key','review-v3-event:'||(route_value->>'event_id'),'mode','exclusive'),jsonb_build_object('class_id',90271104,'key','review-v3-config:'||stream_value::text,'mode','shared'));
 perform controlled_review_v3.protocol_acquire_advisory(keys_value,actor_value);
 begin authority_value:=controlled_review_v3.ops_admin_authority(actor_value,obligation_value.product_id,'manage_escalation');
 exception when insufficient_privilege then perform controlled_review_v3.protocol_identity(actor_value);raise exception 'review_escalation_not_authorized'using errcode='42501';end;
 route_value:=route_value||jsonb_build_object('administration_id',authority_value->'id');plan_value:=controlled_review_v3.ops_action_plan(request_value,route_value);
 perform controlled_review_v3.protocol_acquire_relation_tail('escalation_action',plan_value->'rows',plan_value->'keys',actor_value);perform controlled_review_v3.protocol_acquire_fk_tail('escalation_action',plan_value->'rows',actor_value);
 select *into strict escalation_value from controlled_review_v3.escalations where id=(request_value->>'escalation_id')::uuid;
 select *into strict obligation_value from controlled_review_v3.obligations where event_id=escalation_value.event_id;
 actual_route:=jsonb_build_object('event_id',escalation_value.event_id,'product_id',obligation_value.product_id,'native_family_dispense_id',obligation_value.adapter->'native_family_dispense_id','family_row_id',obligation_value.family_dispense_id,'administration_id',authority_value->'id');
 if actual_route is distinct from route_value then raise exception 'review_action_context_stale'using errcode='23514';end if;
 old_context:=current_setting('controlled_review_v3.escalation_action_request',true);perform set_config('controlled_review_v3.escalation_action_request',jsonb_build_object('request',request_value,'route',route_value)::text,true);
 insert into controlled_review_v3.escalation_actions(operation_id,escalation_id,actor_id,session_id,kind,note,recorded_at,request_hash,receipt)
 values(operation_value,(request_value->>'escalation_id')::uuid,actor_value,null,request_value->>'kind',request_value->>'note',null,null,null)returning *into existing_value;
 perform set_config('controlled_review_v3.escalation_action_request',coalesce(old_context,''),true);
 return jsonb_build_object('version',3,'state','recorded','data',jsonb_build_object('operation_id',operation_value,'receipt',existing_value.receipt));
end

controlled_review_v3.ops_action_plan(p_r.source:
declare request_value jsonb:=controlled_review_v3.protocol_validate_wire(p_request,'record_controlled_review_escalation_action_v3');keys_value jsonb;rows_value jsonb;stream_value jsonb;field text;
begin
 perform public.controlled_stock_keys(p_route,array['event_id','product_id','native_family_dispense_id','family_row_id','administration_id']);
 foreach field in array array['event_id','product_id','administration_id']loop perform public.controlled_stock_uuid(p_route->field);end loop;
 foreach field in array array['native_family_dispense_id','family_row_id']loop if p_route->field<>'null'::jsonb then perform public.controlled_stock_uuid(p_route->field);end if;end loop;
 keys_value:=jsonb_build_array(jsonb_build_object('class_id',90271101,'key','review-v3-escalation-operation:'||(request_value->>'operation_id'),'mode','exclusive'));
 if p_route->'native_family_dispense_id'<>'null'::jsonb then keys_value:=keys_value||jsonb_build_array(jsonb_build_object('class_id',90271102,'key','review-v3-family:'||(p_route->>'native_family_dispense_id'),'mode','exclusive'));end if;
 stream_value:=controlled_review_v3.protocol_stream_key(jsonb_build_object('kind','administration','product_id',p_route->'product_id','site_id',null,'event_kind',null,'capability',null));
 keys_value:=keys_value||jsonb_build_array(jsonb_build_object('class_id',90271103,'key','review-v3-event:'||(p_route->>'event_id'),'mode','exclusive'),
  jsonb_build_object('class_id',90271104,'key','review-v3-config:'||stream_value::text,'mode','shared'));
 rows_value:=jsonb_build_array(jsonb_build_object('relation','controlled_review_v3.escalations','key',jsonb_build_object('id',request_value->'escalation_id'),'local',false),
  jsonb_build_object('relation','controlled_review_v3.obligations','key',jsonb_build_object('event_id',p_route->'event_id'),'local',false),
  jsonb_build_object('relation','public.controlled_stock_events','key',jsonb_build_object('id',p_route->'event_id'),'local',false),
  jsonb_build_object('relation','controlled_review_v3.configuration','key',jsonb_build_object('id',p_route->'administration_id'),'local',false));
 if p_route->'family_row_id'<>'null'::jsonb then rows_value:=rows_value||jsonb_build_array(jsonb_build_object('relation','controlled_review_v3.families','key',jsonb_build_object('dispense_id',p_route->'family_row_id'),'local',false));end if;
 perform controlled_review_v3.protocol_lock_keys(keys_value);
 return jsonb_build_object('keys',keys_value,'rows',controlled_review_v3.protocol_row_targets(rows_value));
end

controlled_review_v3.ops_action_prefligh.source:
declare plan_value jsonb:=controlled_review_v3.protocol_relation_plan('escalation_action','[]'::jsonb);item jsonb;
begin
 for item in select value from jsonb_array_elements(plan_value)loop
  if exists(select 1 from pg_catalog.pg_locks where pid=pg_backend_pid()and locktype='relation'and granted
   and relation=to_regclass(item->>'relation')and mode not in('AccessShareLock','RowShareLock','RowExclusiveLock'))then raise exception 'review_lock_order_invalid'using errcode='23514';end if;
 end loop;
end

controlled_review_v3.ops_action_record(p.source:
declare request_value jsonb;receipt_value jsonb;stamp timestamptz;field text;roles_value jsonb;role_value jsonb;previous text;
begin
 if jsonb_typeof(p_row)is distinct from 'object'or octet_length(p_row::text)>65536 then raise exception 'review_action_record_invalid'using errcode='23514';end if;
 perform public.controlled_stock_keys(p_row,array['operation_id','escalation_id','actor_id','session_id','kind','note','recorded_at','request_hash','receipt']);
 request_value:=controlled_review_v3.protocol_validate_wire(p_row-array['session_id','recorded_at','request_hash','receipt'],'record_controlled_review_escalation_action_v3');
 perform public.controlled_stock_uuid(p_row->'session_id');stamp:=(p_row->>'recorded_at')::timestamptz;perform controlled_review_v3.protocol_utc(stamp);
 if p_row->>'request_hash'is distinct from public.controlled_stock_hash(request_value)then raise exception 'review_action_record_invalid'using errcode='23514';end if;
 receipt_value:=p_row->'receipt';perform public.controlled_stock_keys(receipt_value,array['version','operation_id','escalation_id','actor_id','session_id','actor_name','kind','note','recorded_at','request_hash','escalation_hash','administration_id','administration_hash','configured_roles']);
 if receipt_value->'version'is distinct from '3'::jsonb then raise exception 'review_action_record_invalid'using errcode='23514';end if;
 foreach field in array array['operation_id','escalation_id','actor_id','session_id','kind','note','request_hash']loop
  if receipt_value->field is distinct from p_row->field then raise exception 'review_action_record_invalid'using errcode='23514';end if;
 end loop;
 if receipt_value->>'recorded_at'is distinct from controlled_review_v3.protocol_utc(stamp)then raise exception 'review_action_record_invalid'using errcode='23514';end if;
 perform public.controlled_stock_text(receipt_value->'actor_name',200,false);perform public.controlled_stock_uuid(receipt_value->'administration_id');
 foreach field in array array['escalation_hash','administration_hash']loop
  if jsonb_typeof(receipt_value->field)is distinct from 'string'or(receipt_value->>field)!~'^[0-9a-f]{64}$'then raise exception 'review_action_record_invalid'using errcode='23514';end if;
 end loop;
 roles_value:=receipt_value->'configured_roles';if jsonb_typeof(roles_value)is distinct from 'array'or jsonb_array_length(roles_value)not between 1 and 4 then raise exception 'review_action_record_invalid'using errcode='23514';end if;
 for role_value in select value from jsonb_array_elements(roles_value)loop
  if jsonb_typeof(role_value)is distinct from 'string'or role_value#>>'{}'not in('ADMIN','DVM','STAFF','TECH')or(previous is not null and(role_value#>>'{}')collate "C"<=previous collate "C")then raise exception 'review_action_record_invalid'using errcode='23514';end if;previous:=role_value#>>'{}';
 end loop;
 return p_row||jsonb_build_object('recorded_at',controlled_review_v3.protocol_utc(stamp));
exception when invalid_text_representation or datetime_field_overflow then raise exception 'review_action_record_invalid'using errcode='23514';
end

controlled_review_v3.ops_admin_authority.source:
declare identity_value jsonb;session_value uuid;stream_value jsonb;record_value jsonb;
 active_value boolean;roles_value jsonb;session_valid boolean;member_value jsonb;name_value text;
begin
 if p_capability not in('audit','manage_escalation')or p_capability is null then raise exception 'review_capability_invalid'using errcode='23514';end if;
 identity_value:=controlled_review_v3.protocol_identity(p_actor_id);session_value:=(identity_value->>'session_id')::uuid;
 stream_value:=controlled_review_v3.protocol_stream_key(jsonb_build_object('kind','administration','product_id',p_product_id,'site_id',null,'event_kind',null,'capability',null));
 record_value:=controlled_review_v3.protocol_select_configuration(jsonb_build_object('stream_key',stream_value,'at',controlled_review_v3.protocol_utc(clock_timestamp())));
 if record_value is null then raise exception 'review_administration_not_authorized'using errcode='42501';end if;
 -- One fresh command observes real session, active profile and BOTH the entire
 -- relevant live role set and the requested configured capability together.
 select p.is_active,p.full_name,
  (select coalesce(jsonb_agg(role_name order by role_name collate "C"),'[]'::jsonb)from(
   select distinct r.role::text as role_name from public.user_roles r where r.user_id=p_actor_id and r.role::text in('ADMIN','DVM','STAFF','TECH'))q),
  (auth.uid()=p_actor_id and auth.jwt()->>'role'='authenticated'and exists(select 1 from auth.sessions s
   where s.id=session_value and s.user_id=p_actor_id and(s.not_after is null or s.not_after>clock_timestamp())))
 into active_value,name_value,roles_value,session_valid from public.profiles p where p.id=p_actor_id;
 if not found or active_value is distinct from true or session_valid is distinct from true then raise exception 'review_identity_invalid'using errcode='42501';end if;
 member_value:=controlled_review_v3.protocol_member_conditions(jsonb_build_object('record',record_value,'actor_id',p_actor_id,
  'capability',p_capability,'active',active_value,'live_roles',roles_value));
 if member_value is null then raise exception 'review_administration_not_authorized'using errcode='42501';end if;
 perform public.controlled_stock_text(to_jsonb(name_value),200,false);
 return member_value||jsonb_build_object('session_id',session_value,'actor_name',name_value);
end

controlled_review_v3.ops_admin_preflight.source:
declare relation_value text;
begin
 perform controlled_count_entry_v1.assert_existing_sre_preflight();
 for relation_value in select unnest(array['auth.sessions','controlled_review.cancellations','controlled_review.decisions','controlled_review.definitions','controlled_review.descriptor','controlled_review.preparations','controlled_review_v3.cancellations','controlled_review_v3.configuration','controlled_review_v3.decisions','controlled_review_v3.descriptor','controlled_review_v3.escalation_actions','controlled_review_v3.escalations','controlled_review_v3.families','controlled_review_v3.materializations','controlled_review_v3.obligations','controlled_review_v3.operation_claims','controlled_review_v3.preparations','controlled_review_v3.publications','controlled_review_v3.scan_receipts','pg_catalog.pg_attrdef','pg_catalog.pg_attribute','pg_catalog.pg_class','pg_catalog.pg_constraint','pg_catalog.pg_depend','pg_catalog.pg_index','pg_catalog.pg_language','pg_catalog.pg_locks','pg_catalog.pg_namespace','pg_catalog.pg_policy','pg_catalog.pg_proc','pg_catalog.pg_rewrite','pg_catalog.pg_timezone_names','pg_catalog.pg_trigger','pg_catalog.pg_type','public.catalog_products','public.controlled_stock_engine_manifests','public.controlled_stock_sites','public.profiles','public.user_roles'])loop
  if exists(select 1 from pg_catalog.pg_locks where pid=pg_backend_pid()and locktype='relation'and granted
   and relation=to_regclass(relation_value)and mode not in('AccessShareLock','RowShareLock','RowExclusiveLock','ShareRowExclusiveLock'))then
   raise exception 'review_lock_order_invalid'using errcode='23514';end if;
 end loop;
end

