controlled_review_v3.ops_worker_plan(p_r.source:
declare request_value jsonb:=controlled_review_v3.protocol_validate_wire(p_request,'materialize_one');keys_value jsonb;rows_value jsonb;stream_value jsonb;kind_value text;cap_value text;ids_value jsonb;item jsonb;field_value text;
begin
 perform public.controlled_stock_keys(p_adapter,array['event_id','product_id','event_kind','site_id','native_family_dispense_id']);
 if jsonb_typeof(p_adapter->'event_kind')is distinct from 'string'or p_adapter->>'event_kind'not in('receive_inventory','adjust_inventory','record_patient_treatment','record_anesthesia_drug_administration','record_native_dispense','record_native_pickup','record_native_dispense_return:intake','record_native_dispense_return:dispose','record_native_dispense_return:restock','record_native_dispense_return_v2:intake','record_native_dispense_return_v2:dispose','record_native_dispense_return_v2:restock','record_native_dispense_return_v2:retract_intake','record_native_dispense_return_v2:retract_disposal','record_native_dispense_return_v2:retract_restock','record_native_return_discrepancy:report','record_native_return_discrepancy:note','record_native_return_discrepancy:resolve_corrected','record_native_return_discrepancy:resolve_confirmed_original','append_native_dispense_correction:clinical_annotation','append_native_dispense_correction:operational_annotation','append_native_dispense_correction:pickup_amendment')then raise exception 'review_worker_route_invalid'using errcode='23514';end if;
 foreach field_value in array array['site_id','native_family_dispense_id']loop
  if p_adapter->field_value<>'null'::jsonb then perform public.controlled_stock_uuid(p_adapter->field_value);end if;
 end loop;
 if p_adapter->'event_id'is distinct from request_value->'event_id'or p_adapter->'product_id'is distinct from request_value->'product_id'then raise exception 'review_worker_route_invalid'using errcode='23514';end if;
 keys_value:=jsonb_build_array(jsonb_build_object('class_id',90271101,'key','review-v3-materialization-operation:'||(request_value->>'operation_id'),'mode','exclusive'));
 if p_adapter->'native_family_dispense_id'<>'null'::jsonb then keys_value:=keys_value||jsonb_build_array(jsonb_build_object('class_id',90271102,'key','review-v3-family:'||(p_adapter->>'native_family_dispense_id'),'mode','exclusive'));end if;
 keys_value:=keys_value||jsonb_build_array(jsonb_build_object('class_id',90271103,'key','review-v3-event:'||(request_value->>'event_id'),'mode','exclusive'));
 if p_adapter->'site_id'<>'null'::jsonb then
  foreach kind_value in array array['policy','calendar','routing']loop
   stream_value:=controlled_review_v3.protocol_stream_key(jsonb_build_object('kind',kind_value,'product_id',request_value->'product_id','site_id',p_adapter->'site_id','event_kind',null,'capability',null));
   keys_value:=keys_value||jsonb_build_array(jsonb_build_object('class_id',90271104,'key','review-v3-config:'||stream_value::text,'mode','shared'));
  end loop;
  foreach cap_value in array array['read','review']loop
   stream_value:=controlled_review_v3.protocol_stream_key(jsonb_build_object('kind','eligibility','product_id',request_value->'product_id','site_id',p_adapter->'site_id','event_kind',p_adapter->'event_kind','capability',cap_value));
   keys_value:=keys_value||jsonb_build_array(jsonb_build_object('class_id',90271104,'key','review-v3-config:'||stream_value::text,'mode','shared'));
  end loop;
 end if;
 ids_value:=controlled_review_v3.ops_worker_ids((request_value->>'operation_id')::uuid,(request_value->>'event_id')::uuid);
 for item in select value from jsonb_each(ids_value)loop keys_value:=keys_value||jsonb_build_array(jsonb_build_object('class_id',90271105,'key','review-v3-unique:escalations:'||(item#>>'{}'),'mode','exclusive'));end loop;
 perform controlled_review_v3.protocol_lock_keys(keys_value);return keys_value;
end

