controlled_review_v3.ops_worker_projecti.source:
declare adapter_value jsonb:=p_visible->'adapter';event_value jsonb;family_value jsonb;
 obligation_value jsonb;packet_base jsonb;target_value jsonb;stored_value jsonb;
begin
 perform public.controlled_stock_keys(p_visible,array['state','adapter','source_rows']);
 if p_visible->>'state'not in('complete','collector_limit')or p_visible->>'state'is null then
  raise exception 'review_history_integrity'using errcode='23514';end if;
 if p_visible->>'state'='complete'then
  if jsonb_typeof(p_visible->'source_rows')is distinct from 'array'then raise exception 'review_history_integrity'using errcode='23514';end if;
  select value->'row'into strict event_value from jsonb_array_elements(p_visible->'source_rows')
   where value->>'relation'='public.controlled_stock_events'and value#>'{key,id}'=adapter_value#>'{target,event_id}';
  if adapter_value->>'native_family_dispense_id'is not null then
   family_value:=controlled_review_v3.read_native_family_captured(p_visible-'state',
    (adapter_value->>'native_family_dispense_id')::uuid,(adapter_value#>>'{target,product_id}')::uuid);
  end if;
  if adapter_value->'provenance_state'='"supported"'::jsonb then
   packet_base:=controlled_review_v3.read_scalar_base(p_visible-'state');
  end if;
 else
  perform public.controlled_stock_keys(adapter_value,array['version','event_kind','adapter_id','target','site_basis','site_id','source_refs','native_family_dispense_id','provenance_state','reason']);
  if p_visible->'source_rows'is distinct from 'null'::jsonb or adapter_value->'version'is distinct from '1'::jsonb
   or adapter_value->'site_basis'is distinct from '"unproven"'::jsonb or adapter_value->'site_id'is distinct from 'null'::jsonb
   or adapter_value->'native_family_dispense_id'is distinct from 'null'::jsonb or adapter_value->'source_refs'is distinct from '[]'::jsonb
   or adapter_value->'provenance_state'is distinct from '"unsupported"'::jsonb or adapter_value->'reason'is distinct from '"evidence_limit_exceeded"'::jsonb then
   raise exception 'review_history_integrity'using errcode='23514';end if;
  -- No source traversal/family/site fallback after the cold leaf. The target
  -- was validated outside its catch. Only the immutable parent header is read.
  select jsonb_build_object('id',id,'product_id',product_id,'sequence',sequence,'record_hash',record_hash,
   'actor_id',actor_id,'policy_version_id',policy_version_id,'opening_id',opening_id,'engine_revision',engine_revision,
   'event_kind',event_kind,'basis',basis,'observed_at',observed_at,'recorded_at',recorded_at,
   'secondary_review_required',secondary_review_required)into strict event_value
   from public.controlled_stock_events where id=(adapter_value#>>'{target,event_id}')::uuid;
 end if;
 target_value:=jsonb_build_object('event_id',event_value->'id','product_id',event_value->'product_id','sequence',event_value->'sequence',
  'record_hash',event_value->'record_hash','original_actor_id',event_value->'actor_id','policy_version_id',event_value->'policy_version_id',
  'opening_id',event_value->'opening_id','engine_revision',event_value->'engine_revision');
 if adapter_value->'target'is distinct from target_value or adapter_value->'event_kind'is distinct from event_value->'event_kind'then
  raise exception 'review_history_integrity'using errcode='23514';end if;
 obligation_value:=controlled_review_v3.read_obligation_captured(event_value,adapter_value,family_value);
 stored_value:=controlled_review_v3.protocol_obligation_dto((event_value->>'id')::uuid);
 if stored_value is not null and stored_value is distinct from obligation_value then raise exception 'review_history_integrity'using errcode='23514';end if;
 if obligation_value is null and(exists(select 1 from controlled_review_v3.decisions where event_id=(event_value->>'id')::uuid)
  or exists(select 1 from controlled_review_v3.escalations where event_id=(event_value->>'id')::uuid))then
  raise exception 'review_history_integrity'using errcode='23514';end if;
 if packet_base is null and exists(select 1 from controlled_review_v3.decisions where event_id=(event_value->>'id')::uuid)then
  raise exception 'review_history_integrity'using errcode='23514';end if;
 return jsonb_build_object('source_state',p_visible->'state','target',target_value,'adapter',adapter_value,'event',event_value,
  'obligation',obligation_value,'family',family_value,'packet_base',packet_base);
end

controlled_review_v3.ops_worker_rows_fro.source:
declare rows_value jsonb;event_value uuid:=(p_projection#>>'{target,event_id}')::uuid;
 family_value jsonb:=p_projection->'family';id_value uuid;field_value text;
begin
 rows_value:=jsonb_build_array(jsonb_build_object('relation','public.controlled_stock_events','key',jsonb_build_object('id',event_value),'local',false));
 if p_projection->'obligation'is not null and p_projection->'obligation'<>'null'::jsonb then
  rows_value:=rows_value||jsonb_build_array(jsonb_build_object('relation','controlled_review_v3.obligations','key',jsonb_build_object('event_id',event_value),
   'local',not exists(select 1 from controlled_review_v3.obligations where event_id=event_value)));
 end if;
 if p_projection->'obligation'is not null and p_projection->'obligation'<>'null'::jsonb
  and family_value is not null and family_value<>'null'::jsonb then
  id_value:=(family_value->>'dispense_id')::uuid;
  rows_value:=rows_value||jsonb_build_array(
   jsonb_build_object('relation','public.controlled_stock_events','key',jsonb_build_object('id',id_value),'local',false),
   jsonb_build_object('relation','controlled_review_v3.families','key',jsonb_build_object('dispense_id',id_value),
    'local',not exists(select 1 from controlled_review_v3.families where dispense_id=id_value)));
 end if;
 -- Reserve all retained configuration FK targets. No current configuration is
 -- substituted for a family's original selection or an obligation's anchor.
 foreach field_value in array array['policy_id','calendar_id','routing_id']loop
  for id_value in select distinct id_text::uuid from(
   select p_projection#>>array['obligation','historical',field_value]id_text
   union select family_value#>>array['selection',field_value])refs where id_text is not null loop
   rows_value:=rows_value||jsonb_build_array(jsonb_build_object('relation','controlled_review_v3.configuration',
    'key',jsonb_build_object('id',id_value),'local',false));
  end loop;
 end loop;
 return controlled_review_v3.protocol_row_targets(rows_value);
end

controlled_review_v3.protocol_acquire_ad.source:
declare planned jsonb:=controlled_review_v3.protocol_lock_keys(p_keys);item jsonb;unsigned_key bigint;class_value integer;key_value integer;
begin
 perform controlled_count_entry_v1.assert_complete_product_kernel();
 perform controlled_review_v3.protocol_assert_advisory('[]'::jsonb);
 -- pg_locks cannot distinguish session-owned from transaction-owned locks.
 -- Reentrant xact acquisition adopts the already compatible barrier for this
 -- transaction; a later session unlock cannot release this ownership.
 if exists(select 1 from pg_catalog.pg_locks l where l.pid=pg_catalog.pg_backend_pid()
  and l.database=(select oid from pg_catalog.pg_database where datname=pg_catalog.current_database())
  and l.locktype='advisory'and l.granted and l.classid=90271040::oid and l.objid=0::oid
  and l.objsubid=2 and l.mode='ShareLock')then
  perform pg_advisory_xact_lock_shared(90271040,0);
 else
  -- Complete actual sole-exclusive120 is required, not the lock bit alone.
  perform controlled_stock_workflow_v1.assert_frontier();
  perform pg_advisory_xact_lock(90271040,0);
 end if;
 -- Refuse caller-held strong locks on ANY finite path dependency BEFORE
 -- the first table-reading principal command or missing earlier advisory key.
 -- The raw target's initial ordinary ROW EXCLUSIVE is deliberately compatible.
 if exists(select 1 from pg_locks as held where held.pid=pg_backend_pid()and held.locktype='relation'and held.granted
  and held.mode not in('AccessShareLock','RowShareLock','RowExclusiveLock')
  and not(held.mode='ShareRowExclusiveLock'and held.relation in(
   select c.oid from controlled_count_entry_v1.shared_product_relation_plan_values()p
   join pg_catalog.pg_namespace n on n.nspname=p.schema_name
   join pg_catalog.pg_class c on c.relnamespace=n.oid and c.relname=p.relation_name))
  and held.relation in(select to_regclass(resource.value->>'relation')from
   unnest(array['prepare','decision','prepared_cancel','eventless_cancel','publication','materialize','scan','escalation_action','raw_family','raw_obligation'])as path(name)
   cross join lateral jsonb_array_elements(controlled_review_v3.protocol_path_tables(path.name))as resource(value)))then
  raise exception 'review_lock_order_invalid'using errcode='23514';end if;
 perform controlled_review_v3.protocol_principal(p_actor_id);
 for item in select value from jsonb_array_elements(planned)loop
  class_value:=(item->>'class_id')::integer;key_value:=(item->>'lock_id')::integer;
  unsigned_key:=(key_value::bigint+4294967296)%4294967296;
  if not exists(select 1 from pg_locks where pid=pg_backend_pid()and locktype='advisory'and granted
   and classid=class_value::oid and objid=unsigned_key::oid and objsubid=2
   and(mode='ExclusiveLock'or(mode='ShareLock'and item->>'mode'='shared')))then
   -- Do not upgrade a shared collision, append an earlier key, or introduce an
   -- earlier class behind a later phase. Raw guards must assert the full union.
   if exists(select 1 from pg_locks where pid=pg_backend_pid()and locktype='advisory'and granted and objsubid=2
    and classid between 90271101::oid and 90271106::oid
    and(classid>class_value::oid or(classid=class_value::oid and(
     (objid::bigint>2147483647 and objid::bigint-4294967296>=key_value)
     or(objid::bigint<=2147483647 and objid::bigint>=key_value)))))then
    raise exception 'review_lock_order_invalid'using errcode='23514';end if;
  end if;
  -- Always acquire xact ownership, including a compatible existing session
  -- lock. Raw insert guards must use this adoption helper, never assert alone.
  if item->>'mode'='exclusive'then perform pg_advisory_xact_lock(class_value,key_value);
  else perform pg_advisory_xact_lock_shared(class_value,key_value);end if;
  -- A fresh command after each possibly blocking lock, including reentrant use.
  perform controlled_review_v3.protocol_principal(p_actor_id);
 end loop;
 perform controlled_review_v3.protocol_principal(p_actor_id);
 perform controlled_review_v3.protocol_assert_advisory(p_keys);
end

controlled_review_v3.protocol_acquire_fk.source:
declare rows_value jsonb:=controlled_review_v3.protocol_row_targets(p_rows);item jsonb;key_value uuid;
begin
 perform controlled_review_v3.protocol_assert_relation_tail(p_path,rows_value);
 perform controlled_review_v3.protocol_principal(p_actor_id);
 for item in select value from jsonb_array_elements(rows_value)loop
  if item->'local'='true'::jsonb then continue;end if;
  select(value#>>'{}')::uuid into key_value from jsonb_each(item->'key');
  case item->>'relation'
  when 'controlled_review_v3.configuration'then perform 1 from controlled_review_v3.configuration where id=key_value for key share;
  when 'controlled_review_v3.publications'then perform 1 from controlled_review_v3.publications where operation_id=key_value for key share;
  when 'controlled_review_v3.operation_claims'then perform 1 from controlled_review_v3.operation_claims where operation_id=key_value for key share;
  when 'controlled_review_v3.families'then perform 1 from controlled_review_v3.families where dispense_id=key_value for key share;
  when 'controlled_review_v3.obligations'then perform 1 from controlled_review_v3.obligations where event_id=key_value for key share;
  when 'controlled_review_v3.preparations'then perform 1 from controlled_review_v3.preparations where operation_id=key_value for key share;
  when 'controlled_review_v3.escalations'then perform 1 from controlled_review_v3.escalations where id=key_value for key share;
  when 'public.controlled_stock_events'then perform 1 from public.controlled_stock_events where id=key_value for key share;
  else raise exception 'review_lock_plan_invalid'using errcode='23514';end case;
  if not found then raise exception 'review_history_integrity'using errcode='23514';end if;
  perform controlled_review_v3.protocol_principal(p_actor_id);
 end loop;
 perform controlled_review_v3.protocol_principal(p_actor_id);
end

controlled_review_v3.protocol_acquire_re.source:
declare planned jsonb:=controlled_review_v3.protocol_relation_plan(p_path,p_rows);item jsonb;
begin
 perform controlled_count_entry_v1.assert_complete_product_kernel();
 -- This is not proof that caller keys are the COMPLETE path union. Concrete
 -- facade/raw guard source must derive that exact union before invoking here.
 perform controlled_review_v3.protocol_assert_advisory(p_keys);
 -- No table-reading principal command before the complete nonwaiting preflight.
 for item in select value from jsonb_array_elements(planned)loop
  if exists(select 1 from pg_locks where pid=pg_backend_pid()and locktype='relation'and granted
   and relation=to_regclass(item->>'relation')and mode not in('AccessShareLock','RowShareLock','RowExclusiveLock')
   and not(mode='ShareRowExclusiveLock'and relation in(
    select c.oid from controlled_count_entry_v1.shared_product_relation_plan_values()p
    join pg_catalog.pg_namespace n on n.nspname=p.schema_name
    join pg_catalog.pg_class c on c.relnamespace=n.oid and c.relname=p.relation_name)))then
   raise exception 'review_lock_order_invalid'using errcode='23514';end if;
 end loop;
 -- Preflight the ENTIRE plan before the first new lock: a strong held lock on a
 -- later relation must not let us block on an earlier one before refusing.
 perform controlled_review_v3.protocol_principal(p_actor_id);
 for item in select value from jsonb_array_elements(planned)loop
  case item->>'relation'
 when 'auth.sessions'then
  case item->>'mode'
   when 'ACCESS SHARE'then lock table auth.sessions in access share mode;
   when 'ROW SHARE'then lock table auth.sessions in row share mode;
   when 'ROW EXCLUSIVE'then lock table auth.sessions in row exclusive mode;
   else raise exception 'review_lock_plan_invalid'using errcode='23514';end case;
 when 'controlled_review.cancellations'then
  case item->>'mode'
   when 'ACCESS SHARE'then lock table controlled_review.cancellations in access share mode;
   when 'ROW SHARE'then lock table controlled_review.cancellations in row share mode;
   when 'ROW EXCLUSIVE'then lock table controlled_review.cancellations in row exclusive mode;
   else raise exception 'review_lock_plan_invalid'using errcode='23514';end case;
 when 'controlled_review.decisions'then
  case item->>'mode'
   when 'ACCESS SHARE'then lock table controlled_review.decisions in access share mode;
   when 'ROW SHARE'then lock table controlled_review.decisions in row share mode;
   when 'ROW EXCLUSIVE'then lock table controlled_review.decisions in row exclusive mode;
   else raise exception 'review_lock_plan_invalid'using errcode='23514';end case;
 when 'controlled_review.definitions'then
  case item->>'mode'
   when 'ACCESS SHARE'then lock table controlled_review.definitions in access share mode;
   when 'ROW SHARE'then lock table controlled_review.definitions in row share mode;
   when 'ROW EXCLUSIVE'then lock table controlled_review.definitions in row exclusive mode;
   else raise exception 'review_lock_plan_invalid'using errcode='23514';end case;
 when 'controlled_review.descriptor'then
  case item->>'mode'
   when 'ACCESS SHARE'then lock table controlled_review.descriptor in access share mode;
   when 'ROW SHARE'then lock table controlled_review.descriptor in row share mode;
   when 'ROW EXCLUSIVE'then lock table controlled_review.descriptor in row exclusive mode;
   else raise exception 'review_lock_plan_invalid'using errcode='23514';end case;
