controlled_review_v3.protocol_cancel_mut.source:
declare request_value jsonb:=controlled_review_v3.protocol_operation_request(p_request);actor_value uuid;operation_value uuid;
claim_value controlled_review_v3.operation_claims;preparation_value controlled_review_v3.preparations;cancellation_value controlled_review_v3.cancellations;
claim_exists boolean;preparation_exists boolean;keys_value jsonb;rows_value jsonb;adapter_value jsonb;kind_value text;path_value text;
previous_context text;context_value jsonb;at_value timestamptz;identity_value jsonb;response_value jsonb;
begin
 actor_value:=(request_value->>'actor_id')::uuid;operation_value:=(request_value->>'operation_id')::uuid;
 perform controlled_review_v3.read_practice_preflight();
 perform controlled_review_v3.read_relation_preflight();
 perform controlled_review_v3.ops_admin_preflight();
 perform pg_advisory_xact_lock_shared(90271040,0);perform controlled_review_v3.required();
 perform controlled_review_v3.protocol_identity(actor_value);
 keys_value:=jsonb_build_array(jsonb_build_object('class_id',90271101,'key','review-v3-operation:'||operation_value::text,'mode','exclusive'));
 perform controlled_review_v3.protocol_acquire_advisory(keys_value,actor_value);
 select *into claim_value from controlled_review_v3.operation_claims where operation_id=operation_value;claim_exists:=found;
 if claim_exists and claim_value.actor_id<>actor_value then raise exception 'operation_not_found'using errcode='PT404';end if;
 if exists(select 1 from controlled_review_v3.decisions where operation_id=operation_value)
  or exists(select 1 from controlled_review_v3.cancellations where operation_id=operation_value)then
  return controlled_review_v3.protocol_owned_state(request_value);end if;
 select *into preparation_value from controlled_review_v3.preparations where operation_id=operation_value;preparation_exists:=found;
 if preparation_exists then
  if not claim_exists then raise exception 'review_history_integrity'using errcode='23514';end if;
  perform controlled_review_v3.protocol_retained_preparation(to_jsonb(preparation_value));
  adapter_value:=preparation_value.packet->'adapter';path_value:='prepared_cancel';kind_value:='prepared';
  keys_value:=controlled_review_v3.protocol_review_keys(jsonb_build_object('path','prepared_cancel','operation_id',operation_value,
   'adapter',adapter_value,'escalation_ids','{}'::jsonb));
  perform controlled_review_v3.protocol_acquire_advisory(keys_value,actor_value);
  rows_value:=controlled_review_v3.protocol_review_rows(jsonb_build_object('path','prepared_cancel','operation_id',operation_value,
   'event_id',preparation_value.event_id,'configuration_ids','{}'::jsonb));
 else
  -- A visible bare claim is corrupt committed history; this operation did not
  -- invent a reusable reservation. The normal no-claim path creates both rows.
  if claim_exists then raise exception 'review_history_integrity'using errcode='23514';end if;
  path_value:='eventless_cancel';kind_value:='unprepared';
  rows_value:=controlled_review_v3.protocol_review_rows(jsonb_build_object('path','eventless_cancel','operation_id',operation_value,
   'event_id',null,'configuration_ids','{}'::jsonb));
 end if;
 perform controlled_review_v3.protocol_acquire_relation_tail(path_value,rows_value,keys_value,actor_value);
 perform controlled_review_v3.protocol_acquire_fk_tail(path_value,rows_value,actor_value);
 perform controlled_review_v3.required();identity_value:=controlled_review_v3.protocol_identity(actor_value);
 if not claim_exists then
  context_value:=controlled_review_v3.protocol_claim_context(jsonb_build_object('version',1,'path','eventless_cancel','request',request_value,'route',null,'rows',rows_value));
  previous_context:=current_setting('controlled_review_v3.claim_request',true);
  perform set_config('controlled_review_v3.claim_request',context_value::text,true);
  insert into controlled_review_v3.operation_claims(operation_id,actor_id,claimed_at)values(operation_value,actor_value,null)returning *into claim_value;
 end if;
 identity_value:=controlled_review_v3.protocol_identity(actor_value);at_value:=clock_timestamp();
 insert into controlled_review_v3.cancellations(operation_id,actor_id,session_id,kind,transport_digest,recorded_at)
 values(operation_value,actor_value,null,null,null,null)returning *into cancellation_value;
 if not claim_exists then perform set_config('controlled_review_v3.claim_request',coalesce(previous_context,''),true);end if;
 return jsonb_build_object('version',3,'state','cancelled','data',controlled_review_v3.protocol_cancellation_data(to_jsonb(claim_value),
  case when preparation_exists then to_jsonb(preparation_value)else 'null'::jsonb end,to_jsonb(cancellation_value)));
end

controlled_review_v3.protocol_cancellati.source:
declare recorded_value timestamptz;claim_time timestamptz;
begin
 perform public.controlled_stock_keys(p_claim,array['operation_id','actor_id','claimed_at']);
 perform public.controlled_stock_keys(p_cancellation,array['operation_id','actor_id','session_id','kind','transport_digest','recorded_at']);
 perform public.controlled_stock_uuid(p_claim->'operation_id');perform public.controlled_stock_uuid(p_claim->'actor_id');
 perform public.controlled_stock_uuid(p_cancellation->'session_id');
 if p_claim->'operation_id'is distinct from p_cancellation->'operation_id'or p_claim->'actor_id'is distinct from p_cancellation->'actor_id'
  or p_cancellation->>'kind'not in('prepared','unprepared')or jsonb_typeof(p_cancellation->'kind')is distinct from 'string'
  or jsonb_typeof(p_cancellation->'recorded_at')is distinct from 'string'or jsonb_typeof(p_claim->'claimed_at')is distinct from 'string'then
  raise exception 'review_history_integrity'using errcode='23514';end if;
 recorded_value:=(p_cancellation->>'recorded_at')::timestamptz;claim_time:=(p_claim->>'claimed_at')::timestamptz;
 perform controlled_review_v3.protocol_utc(claim_time);perform controlled_review_v3.protocol_utc(recorded_value);
 if recorded_value<claim_time then raise exception 'review_history_integrity'using errcode='23514';end if;
 if p_cancellation->>'kind'='unprepared'then
  if p_preparation is distinct from 'null'::jsonb or p_cancellation->'transport_digest'is distinct from 'null'::jsonb then
   raise exception 'review_history_integrity'using errcode='23514';end if;
 else
  perform controlled_review_v3.protocol_retained_preparation(p_preparation);
  if p_cancellation->'operation_id'is distinct from p_preparation->'operation_id'or p_cancellation->'actor_id'is distinct from p_preparation->'actor_id'
   or p_cancellation->'transport_digest'is distinct from p_preparation->'transport_digest'
   or recorded_value<(p_preparation->>'created_at')::timestamptz then
   raise exception 'review_history_integrity'using errcode='23514';end if;
 end if;
 return jsonb_build_object('operation_id',p_cancellation->'operation_id','actor_id',p_cancellation->'actor_id',
  'cancellation_kind',p_cancellation->'kind','transport_digest',p_cancellation->'transport_digest',
  'cancelled_at',controlled_review_v3.protocol_utc(recorded_value));
exception when invalid_text_representation or datetime_field_overflow then
 raise exception 'review_history_integrity'using errcode='23514';
end

controlled_review_v3.protocol_capacity_l.source:
declare first_line text;
begin
 if p_message is distinct from 'evidence_limit_exceeded'or p_context is null then return false;end if;
 first_line:=split_part(p_context,E'\n',1);
 -- These nine source-pinned collector helpers are the complete explicit
 -- RAISE54000 closure. An engine-size/internal54000 cannot match this RAISE.
 return first_line~'^PL/pgSQL function controlled_review_v3\.(adapter_add|collect_event_sources|managed_source_event|adapter_event_site|adapter_dispense|adapter_pickup|adapter_return|adapter_opening_site|adapter_context)\([^\n]*\) line [1-9][0-9]* at RAISE$';
end

controlled_review_v3.protocol_claim_cont.source:
declare request_value jsonb;rows_value jsonb;route_value jsonb;target_value jsonb;field text;
begin
 if jsonb_typeof(p_value)is distinct from 'object'or octet_length(p_value::text)>65536 then
  raise exception 'review_claim_context_invalid'using errcode='23514';end if;
 perform public.controlled_stock_keys(p_value,array['version','path','request','route','rows']);
 if jsonb_typeof(p_value->'version')is distinct from 'number'or p_value->>'version'<>'1'
  or jsonb_typeof(p_value->'path')is distinct from 'string'or p_value->>'path'not in('prepare','eventless_cancel')then
  raise exception 'review_claim_context_invalid'using errcode='23514';end if;
 rows_value:=controlled_review_v3.protocol_row_targets(p_value->'rows');
 if rows_value is distinct from p_value->'rows'then raise exception 'review_claim_context_invalid'using errcode='23514';end if;
 if p_value->>'path'='eventless_cancel'then
  request_value:=controlled_review_v3.protocol_operation_request(p_value->'request');
  if p_value->'route'is distinct from 'null'::jsonb then raise exception 'review_claim_context_invalid'using errcode='23514';end if;
 else
  request_value:=controlled_review_v3.protocol_request(p_value->'request');route_value:=p_value->'route';
  perform public.controlled_stock_keys(route_value,array['target','event_kind','site_id','native_family_dispense_id','provenance_state']);
  target_value:=route_value->'target';perform public.controlled_stock_keys(target_value,array['event_id','product_id','sequence','record_hash','original_actor_id','policy_version_id','opening_id','engine_revision']);
  for field in select unnest(array['event_id','product_id','original_actor_id','policy_version_id','opening_id'])loop
   perform public.controlled_stock_uuid(target_value->field);end loop;
  if target_value->'event_id'is distinct from request_value->'event_id'or jsonb_typeof(target_value->'record_hash')is distinct from 'string'
   or target_value->>'record_hash'!~'^[0-9a-f]{64}$'or jsonb_typeof(target_value->'sequence')is distinct from 'number'
   or target_value->>'sequence'!~'^[1-9][0-9]{0,18}$'or(target_value->>'sequence')::numeric>9223372036854775807
   or jsonb_typeof(target_value->'engine_revision')is distinct from 'number'or target_value->>'engine_revision'!~'^[1-9][0-9]{0,9}$'
   or(target_value->>'engine_revision')::numeric>2147483647 or route_value->'provenance_state'is distinct from '"supported"'::jsonb then
   raise exception 'review_claim_context_invalid'using errcode='23514';end if;
  -- Pure finite key derivation validates literal kind/site/family syntax. Its
  -- success does NOT admit the hinted provenance, target, or rows as evidence.
  perform controlled_review_v3.protocol_review_route_keys(jsonb_build_object('path','prepare','operation_id',request_value->'operation_id',
   'route',route_value,'escalation_ids','{}'::jsonb));
 end if;
 return p_value;
end

controlled_review_v3.protocol_collect_vi.source:
declare event_value public.controlled_stock_events;adapter_id_value text;target_value jsonb;collected_value jsonb;
message_value text;context_value text;
begin
 if p_event_id is null or p_event_id='00000000-0000-0000-0000-000000000000'::uuid then
  raise exception 'review_request_invalid'using errcode='23514';end if;
 perform pg_advisory_xact_lock_shared(90271040,0);perform controlled_review_v3.required();
 -- Canonical target validation is deliberately OUTSIDE the catch. Neither
 -- integrity nor parent validation failures become an overflow exception.
 perform public.controlled_stock_validate_event(p_event_id);
 select *into strict event_value from public.controlled_stock_events where id=p_event_id;
 case event_value.event_kind
  when 'receive_inventory','adjust_inventory'then adapter_id_value:='movement_v1';
  when 'record_patient_treatment'then adapter_id_value:='treatment_v1';
  when 'record_anesthesia_drug_administration'then adapter_id_value:='anesthesia_v1';
  when 'record_native_dispense'then adapter_id_value:='dispense_v1';
  when 'record_native_pickup'then adapter_id_value:='pickup_v1';
  when 'record_native_dispense_return:intake','record_native_dispense_return:dispose','record_native_dispense_return:restock'then adapter_id_value:='return_v1';
  when 'record_native_dispense_return_v2:intake','record_native_dispense_return_v2:dispose','record_native_dispense_return_v2:restock'then adapter_id_value:='return_v2';
  when 'record_native_dispense_return_v2:retract_intake','record_native_dispense_return_v2:retract_disposal','record_native_dispense_return_v2:retract_restock'then adapter_id_value:='retraction_v1';
  when 'record_native_return_discrepancy:report','record_native_return_discrepancy:note','record_native_return_discrepancy:resolve_corrected','record_native_return_discrepancy:resolve_confirmed_original'then adapter_id_value:='discrepancy_v1';
  when 'append_native_dispense_correction:clinical_annotation','append_native_dispense_correction:operational_annotation','append_native_dispense_correction:pickup_amendment'then adapter_id_value:='annotation_v1';
  else raise exception 'unsupported_event_kind'using errcode='22023';end case;
 target_value:=jsonb_build_object('event_id',event_value.id,'product_id',event_value.product_id,'sequence',event_value.sequence,
  'record_hash',event_value.record_hash,'original_actor_id',event_value.actor_id,'policy_version_id',event_value.policy_version_id,
  'opening_id',event_value.opening_id,'engine_revision',event_value.engine_revision);
 begin
  collected_value:=controlled_review_v3.collect_event_sources(p_event_id);
 exception when sqlstate '54000'then
  get stacked diagnostics message_value=MESSAGE_TEXT,context_value=PG_EXCEPTION_CONTEXT;
  if not controlled_review_v3.protocol_capacity_leaf(message_value,context_value)then raise;end if;
  -- No queries, traversal, source row or kind-specific site/family fallback
  -- after a budget failure. The null source_rows explicitly means NO packet.
  return jsonb_build_object('state','collector_limit','adapter',jsonb_build_object('version',1,
   'event_kind',event_value.event_kind,'adapter_id',adapter_id_value,'target',target_value,
   'site_basis','unproven','site_id',null,'source_refs','[]'::jsonb,'native_family_dispense_id',null,
   'provenance_state','unsupported','reason','evidence_limit_exceeded'),'source_rows',null);
 end;
 if collected_value#>'{adapter,target}'is distinct from target_value then
  raise exception 'review_history_integrity'using errcode='23514';end if;
 return jsonb_build_object('state','complete','adapter',collected_value->'adapter','source_rows',collected_value->'source_rows');
end

controlled_review_v3.protocol_configurat.source:
declare stored_row controlled_review_v3.configuration;result_value jsonb;
begin
 if p_id is null or p_id='00000000-0000-0000-0000-000000000000'::uuid then
  raise exception 'configuration_record_invalid'using errcode='23514';end if;
 select *into stored_row from controlled_review_v3.configuration where id=p_id;
 if not found then return null;end if;
 result_value:=jsonb_build_object('id',stored_row.id,'kind',stored_row.kind,'stream_key',stored_row.stream_key,
  'version',stored_row.version,'predecessor_id',stored_row.predecessor_id,'predecessor_hash',stored_row.predecessor_hash,
  'enabled',stored_row.enabled,'document',stored_row.document,'record_hash',stored_row.record_hash,
  'publication_operation_id',stored_row.publication_operation_id,
  'published_at',controlled_review_v3.protocol_utc(stored_row.published_at),
  'publisher_actor_id',stored_row.publisher_actor_id,'publisher_session_id',stored_row.publisher_session_id,
  'publisher_name',stored_row.publisher_name,'authorization_id',stored_row.authorization_id,'publication_mode',stored_row.publication_mode,
  'effective_from',case when stored_row.effective_from is null then null else controlled_review_v3.protocol_utc(stored_row.effective_from)end);
 perform controlled_review_v3.configuration_record(result_value);
 return result_value;
end

declare row_value jsonb:=controlled_review_v3.protocol_configuration_dto(p_id);
