begin
 if TG_OP<>'INSERT'or TG_TABLE_SCHEMA<>'controlled_review_v3'or TG_TABLE_NAME not in('families','obligations','preparations')then
  raise exception 'review_insert_invalid'using errcode='23514';end if;
 if session_user='postgres'and current_user='postgres'and TG_TABLE_NAME in('families','obligations')then
  if TG_TABLE_NAME='families'then
   NEW:=jsonb_populate_record(null::controlled_review_v3.families,controlled_review_v3.ops_construct_worker_family(to_jsonb(NEW)));
  else NEW:=jsonb_populate_record(null::controlled_review_v3.obligations,controlled_review_v3.ops_construct_worker_obligation(to_jsonb(NEW)));end if;
  return NEW;
 end if;
 -- Refuse explicit server fields before any construction. Canonical full stored
 -- rows are not accepted/normalized by this NULL-only writer route.
 if TG_TABLE_NAME='preparations'then
  if NEW.session_id is not null or NEW.request_hash is not null or NEW.transport_digest is not null or NEW.target_hash is not null
   or NEW.packet is not null or NEW.packet_hash is not null or NEW.prepared_boot is not null or NEW.prepared_xid is not null
   or NEW.created_at is not null or NEW.expires_at is not null then raise exception 'review_server_field_supplied'using errcode='23514';end if;
  operation_value:=NEW.operation_id;actor_value:=NEW.actor_id;
 else
  -- Only the exact already-validated native context identifies the intended
  -- operation. No ID or provenance from this context is accepted as authority.
  if session_user<>'authenticator'or current_user<>'postgres'or pg_catalog.pg_my_temp_schema()<>0 then
   raise exception 'review_claim_native_route_required'using errcode='42501';end if;
  context_value:=controlled_review_v3.protocol_native_context_value();request_value:=context_value->'request';
  operation_value:=(request_value->>'operation_id')::uuid;actor_value:=(request_value->>'actor_id')::uuid;
  if TG_TABLE_NAME='families'then
   if NEW.target is not null or NEW.target_hash is not null or NEW.site_id is not null or NEW.selection is not null or NEW.binding_hash is not null or NEW.materialized_at is not null then
    raise exception 'review_server_field_supplied'using errcode='23514';end if;
  else
   if NEW.event_sequence is not null or NEW.meaning is not null or NEW.target is not null or NEW.target_hash is not null or NEW.adapter is not null
    or NEW.historical is not null or NEW.binding_hash is not null or NEW.site_id is not null or NEW.due_at is not null
    or NEW.family_dispense_id is not null or NEW.materialized_at is not null then raise exception 'review_server_field_supplied'using errcode='23514';end if;
  end if;
 end if;
 if context_value is null then context_value:=controlled_review_v3.protocol_native_context_value();end if;
 proof_value:=controlled_review_v3.protocol_native_prepare_context(operation_value,actor_value,context_value);request_value:=proof_value->'request';
 if TG_TABLE_NAME='preparations'then
  if NEW.request is distinct from request_value or NEW.operation_id is distinct from(request_value->>'operation_id')::uuid
   or NEW.event_id is distinct from(request_value->>'event_id')::uuid or NEW.actor_id is distinct from(request_value->>'actor_id')::uuid
   or NEW.policy_id is distinct from(request_value->>'policy_id')::uuid or NEW.read_eligibility_id is distinct from(request_value->>'read_eligibility_id')::uuid
   or NEW.review_eligibility_id is distinct from(request_value->>'review_eligibility_id')::uuid or NEW.decision is distinct from request_value->>'decision'
   or NEW.reason is distinct from request_value->>'reason'then raise exception 'operation_request_mismatch'using errcode='PT409';end if;
  if exists(select 1 from controlled_review_v3.decisions where event_id=NEW.event_id)then raise exception 'review_already_terminal'using errcode='PT409';end if;
  identity_value:=controlled_review_v3.protocol_identity(actor_value);
  NEW.prepared_boot:=pg_postmaster_start_time();NEW.prepared_xid:=pg_current_xact_id();at_value:=clock_timestamp();
  packet_value:=controlled_review_v3.protocol_packet_from_collected(jsonb_build_object('actor_id',actor_value,'event_id',NEW.event_id),at_value,proof_value->'collected');
  packet_value:=controlled_review_v3.protocol_signing_packet(request_value,packet_value);
  identity_value:=controlled_review_v3.protocol_identity(actor_value);at_value:=clock_timestamp();
  packet_value:=packet_value||jsonb_build_object('current_authorization',controlled_review_v3.protocol_authorization_route(packet_value->'adapter',actor_value,at_value));
  packet_value:=controlled_review_v3.protocol_signing_packet(request_value,packet_value);
  if not exists(select 1 from controlled_review_v3.obligations where event_id=NEW.event_id)
   or controlled_review_v3.protocol_obligation_dto(NEW.event_id)is distinct from packet_value->'obligation'then
   raise exception 'review_history_integrity'using errcode='23514';end if;
  NEW.session_id:=(identity_value->>'session_id')::uuid;NEW.request_hash:=public.controlled_stock_hash(request_value);
  NEW.transport_digest:=controlled_review_v3.protocol_transport_digest(request_value);NEW.target_hash:=public.controlled_stock_hash(packet_value->'target');
  NEW.packet:=packet_value;NEW.packet_hash:=public.controlled_stock_hash(packet_value);NEW.created_at:=at_value;NEW.expires_at:=at_value+interval '15 minutes';
