  obligation_value:=controlled_review_v3.read_scalar_base(proof_value->'collected')->'obligation';
  if obligation_value->>'family_dispense_id'is null or NEW.dispense_id is distinct from(obligation_value->>'family_dispense_id')::uuid then
   raise exception 'review_history_integrity'using errcode='23514';end if;
  family_value:=controlled_review_v3.read_native_family_captured(proof_value->'collected',NEW.dispense_id,(obligation_value->>'product_id')::uuid);
  if NEW.product_id is distinct from(family_value->>'product_id')::uuid then raise exception 'review_history_integrity'using errcode='23514';end if;
  NEW.target:=family_value->'target';NEW.target_hash:=family_value->>'target_hash';NEW.site_id:=(family_value->>'site_id')::uuid;
  NEW.selection:=family_value->'selection';NEW.binding_hash:=family_value->>'binding_hash';NEW.materialized_at:=clock_timestamp();
 else
  if NEW.event_id is distinct from(request_value->>'event_id')::uuid then raise exception 'review_history_integrity'using errcode='23514';end if;
  obligation_value:=controlled_review_v3.read_scalar_base(proof_value->'collected')->'obligation';
  if obligation_value is null or NEW.product_id is distinct from(obligation_value->>'product_id')::uuid then
   raise exception 'review_history_integrity'using errcode='23514';end if;
  NEW.event_sequence:=(obligation_value->>'event_sequence')::bigint;NEW.meaning:=obligation_value->>'meaning';
  NEW.target:=obligation_value->'target';NEW.target_hash:=obligation_value->>'target_hash';NEW.adapter:=obligation_value->'adapter';
  NEW.historical:=obligation_value->'historical';NEW.binding_hash:=obligation_value->>'binding_hash';NEW.site_id:=(obligation_value->>'site_id')::uuid;
  NEW.due_at:=(obligation_value->>'due_at')::timestamptz;NEW.family_dispense_id:=(obligation_value->>'family_dispense_id')::uuid;NEW.materialized_at:=clock_timestamp();
 end if;
 if pg_catalog.pg_my_temp_schema()<>0 then raise exception 'review_claim_temp_namespace_forbidden'using errcode='42501';end if;
 return NEW;
end

