 perform public.controlled_stock_keys(adapter_value->'target',array['event_id','product_id','sequence','record_hash','original_actor_id','policy_version_id','opening_id','engine_revision']);
 if adapter_value#>'{target,event_id}'is distinct from to_jsonb(event_value)then raise exception 'review_history_integrity'using errcode='23514';end if;
 if adapter_value->'provenance_state'is distinct from '"supported"'::jsonb then
  raise exception 'unsupported_provenance'using errcode='23514';end if;
 perform controlled_review_v3.protocol_utc(p_at);
 authorization_value:=controlled_review_v3.protocol_authorization_route(adapter_value,actor_value,p_at);
 if authorization_value->'read'is not distinct from 'null'::jsonb then raise exception 'review_read_not_authorized'using errcode='42501';end if;
 -- No current permission is inferred from this immutable tuple/base. Each
 -- guard's final current-role/config/clock/signing refresh remains outside too.
 base_value:=controlled_review_v3.read_scalar_base(p_collected);
 if base_value#>'{target,event_id}'is distinct from to_jsonb(event_value)or base_value#>'{event,id}'is distinct from to_jsonb(event_value)
  or base_value->'adapter'is distinct from adapter_value or base_value#>'{event,event_kind}'is distinct from adapter_value->'event_kind'
  or base_value->'target'is distinct from jsonb_build_object('event_id',base_value#>'{event,id}','product_id',base_value#>'{event,product_id}',
   'sequence',base_value#>'{event,sequence}','record_hash',base_value#>'{event,record_hash}','original_actor_id',base_value#>'{event,actor_id}',
   'policy_version_id',base_value#>'{event,policy_version_id}','opening_id',base_value#>'{event,opening_id}','engine_revision',base_value#>'{event,engine_revision}')
  then raise exception 'review_history_integrity'using errcode='23514';end if;
 result_value:=base_value||jsonb_build_object('current_authorization',authorization_value);
 if octet_length(result_value::text)>1048576 then raise exception 'evidence_limit_exceeded'using errcode='23514';end if;
 perform controlled_review_v3.protocol_identity(actor_value);
 return result_value;
end

controlled_review_v3.protocol_page_size(.source:
declare result_value integer;
begin
 if jsonb_typeof(p_value)is distinct from 'number'or(p_value#>>'{}')!~'^[1-9][0-9]{0,2}$'then
  raise exception 'review_page_size_invalid'using errcode='23514';end if;
 result_value:=(p_value#>>'{}')::integer;
 if result_value>100 then raise exception 'review_page_size_invalid'using errcode='23514';end if;
 return result_value;
end

controlled_review_v3.protocol_policy_at(.source:
begin
 if p_product_id is null or p_product_id='00000000-0000-0000-0000-000000000000'::uuid
  or p_anchor is null or not isfinite(p_anchor)then
  raise exception 'review_history_integrity'using errcode='23514';end if;
 -- Configuration starts in2026; older immutable source is still visible, with
 -- explicit historical absence, rather than interpreted under today's policy.
 if p_site_id is null or p_anchor<timestamptz '2026-01-01 00:00:00Z'or p_anchor>=timestamptz '2101-01-01 00:00:00Z'then return null;end if;
 return controlled_review_v3.protocol_select_configuration(jsonb_build_object('stream_key',jsonb_build_object(
  'kind','policy','product_id',p_product_id,'site_id',p_site_id,'event_kind',null,'capability',null),
  'at',controlled_review_v3.protocol_utc(p_anchor)));
end

controlled_review_v3.protocol_policy_ref.source:
declare policy_value jsonb;kind_value text;reference_value jsonb;references_value jsonb:='{}';reference_id uuid;
begin
 policy_value:=controlled_review_v3.validate_configuration_record(p_policy);
 if policy_value->'kind'is distinct from '"policy"'::jsonb then
  raise exception 'review_history_integrity'using errcode='23514';end if;
 foreach kind_value in array array['calendar','routing']loop
  reference_value:=null;
  if policy_value#>array['body',kind_value||'_id']is distinct from 'null'::jsonb then
   reference_id:=public.controlled_stock_uuid(policy_value#>array['body',kind_value||'_id']);
   reference_value:=controlled_review_v3.protocol_configuration_record(reference_id);
   if reference_value is null or reference_value->>'kind'<>kind_value
    or reference_value#>'{scope,product_id}'is distinct from policy_value#>'{scope,product_id}'
    or reference_value#>'{scope,site_id}'is distinct from policy_value#>'{scope,site_id}'
    or reference_value->'enabled'is distinct from 'true'::jsonb
    or controlled_review_v3.protocol_instant(reference_value->'published_at')>controlled_review_v3.protocol_instant(policy_value->'published_at')then
    raise exception 'review_history_integrity'using errcode='23514';end if;
  end if;
  references_value:=references_value||jsonb_build_object(kind_value,reference_value);
 end loop;
 return references_value;
end

controlled_review_v3.protocol_prepare_mu.source:
declare request_value jsonb:=controlled_review_v3.protocol_request(p_request);actor_value uuid;operation_value uuid;event_value uuid;
claim_value controlled_review_v3.operation_claims;preparation_value controlled_review_v3.preparations;claim_exists boolean;
adapter_value jsonb;after_adapter jsonb;collected_value jsonb;after_collected jsonb;keys_value jsonb;rows_value jsonb;route_value jsonb;context_value jsonb;previous_context text;
packet_value jsonb;obligation_value jsonb;family_value jsonb;at_value timestamptz;boot_value timestamptz;xid_value xid8;
begin
 actor_value:=(request_value->>'actor_id')::uuid;operation_value:=(request_value->>'operation_id')::uuid;event_value:=(request_value->>'event_id')::uuid;
 perform controlled_review_v3.read_practice_preflight();
 perform controlled_review_v3.read_relation_preflight();
 perform controlled_review_v3.ops_admin_preflight();
 perform pg_advisory_xact_lock_shared(90271040,0);perform controlled_review_v3.required();
 perform controlled_review_v3.protocol_identity(actor_value);
 perform controlled_review_v3.protocol_acquire_advisory(jsonb_build_array(jsonb_build_object('class_id',90271101,
  'key','review-v3-operation:'||operation_value::text,'mode','exclusive')),actor_value);
 select *into claim_value from controlled_review_v3.operation_claims where operation_id=operation_value;claim_exists:=found;
 if claim_exists then
  if claim_value.actor_id<>actor_value then raise exception 'operation_not_found'using errcode='PT404';end if;
  select *into preparation_value from controlled_review_v3.preparations where operation_id=operation_value;
  if found and preparation_value.request is distinct from request_value then raise exception 'operation_request_mismatch'using errcode='PT409';end if;
  return controlled_review_v3.protocol_owned_state(jsonb_build_object('actor_id',actor_value,'operation_id',operation_value));
 end if;
 collected_value:=controlled_review_v3.collect_event_sources(event_value);adapter_value:=collected_value->'adapter';
 if adapter_value->'provenance_state'is distinct from '"supported"'::jsonb then raise exception 'unsupported_provenance'using errcode='23514';end if;
 if adapter_value#>'{target,original_actor_id}'=request_value->'actor_id'then raise exception 'own_record'using errcode='23514';end if;
 if not exists(select 1 from public.controlled_stock_events where id=event_value and secondary_review_required)then raise exception 'not_required'using errcode='23514';end if;
 keys_value:=controlled_review_v3.protocol_review_keys(jsonb_build_object('path','prepare','operation_id',operation_value,'adapter',adapter_value,'escalation_ids','{}'::jsonb));
 perform controlled_review_v3.protocol_acquire_advisory(keys_value,actor_value);
 after_collected:=controlled_review_v3.collect_event_sources(event_value);after_adapter:=after_collected->'adapter';
 if after_adapter is distinct from adapter_value then raise exception 'review_history_integrity'using errcode='23514';end if;
 if exists(select 1 from controlled_review_v3.decisions where event_id=event_value)then raise exception 'review_already_terminal'using errcode='PT409';end if;
 rows_value:=controlled_review_v3.protocol_review_rows(jsonb_build_object('path','prepare','operation_id',operation_value,'event_id',event_value,
  'configuration_ids',jsonb_build_object('policy',request_value->'policy_id','read',request_value->'read_eligibility_id','review',request_value->'review_eligibility_id')));
 perform controlled_review_v3.protocol_acquire_relation_tail('prepare',rows_value,keys_value,actor_value);
 perform controlled_review_v3.protocol_acquire_fk_tail('prepare',rows_value,actor_value);
 perform controlled_review_v3.read_clinical_dependencies_required();
 perform controlled_review_v3.required();perform controlled_review_v3.protocol_identity(actor_value);
 -- No insert has occurred before the full union above. The context is only a
 -- copied request+untrusted routing/row hint: the guard independently rederives
 -- and proves actual gates. It contains no caller/producer authorization flag.
 route_value:=jsonb_build_object('target',adapter_value->'target','event_kind',adapter_value->'event_kind','site_id',adapter_value->'site_id',
  'native_family_dispense_id',adapter_value->'native_family_dispense_id','provenance_state',adapter_value->'provenance_state');
 context_value:=controlled_review_v3.protocol_claim_context(jsonb_build_object('version',1,'path','prepare','request',request_value,'route',route_value,'rows',rows_value));
 previous_context:=current_setting('controlled_review_v3.claim_request',true);
 perform set_config('controlled_review_v3.claim_request',context_value::text,true);
 insert into controlled_review_v3.operation_claims(operation_id,actor_id,claimed_at)values(operation_value,actor_value,null)returning *into claim_value;
 -- Guard-owned claim time is already retained. Immutable obligations do not
 -- depend on current actor/config projection. Preparation's BEFORE guard owns
 -- its fresh accepted instant, complete P and TTL after these reserved locals.
 obligation_value:=controlled_review_v3.read_scalar_base(after_collected)->'obligation';
 if obligation_value->'family_dispense_id'is distinct from 'null'::jsonb then
  family_value:=controlled_review_v3.read_native_family_captured(after_collected,(obligation_value->>'family_dispense_id')::uuid,(obligation_value->>'product_id')::uuid);
  if not exists(select 1 from controlled_review_v3.families where dispense_id=(family_value->>'dispense_id')::uuid)then
   insert into controlled_review_v3.families(dispense_id,target,target_hash,product_id,site_id,selection,binding_hash,materialized_at)
   values((family_value->>'dispense_id')::uuid,null,null,(family_value->>'product_id')::uuid,null,null,null,null);
  end if;
 end if;
 if not exists(select 1 from controlled_review_v3.obligations where event_id=event_value)then
  insert into controlled_review_v3.obligations(event_id,product_id,event_sequence,meaning,target,target_hash,adapter,historical,binding_hash,site_id,due_at,family_dispense_id,materialized_at)
  values(event_value,(obligation_value->>'product_id')::uuid,null,null,null,null,null,null,null,null,null,null,null);
 end if;
 insert into controlled_review_v3.preparations(operation_id,event_id,actor_id,session_id,request,request_hash,transport_digest,target_hash,packet,packet_hash,
  policy_id,read_eligibility_id,review_eligibility_id,decision,reason,prepared_boot,prepared_xid,created_at,expires_at)
 values(operation_value,event_value,actor_value,null,request_value,null,null,null,null,null,
  (request_value->>'policy_id')::uuid,(request_value->>'read_eligibility_id')::uuid,(request_value->>'review_eligibility_id')::uuid,
  request_value->>'decision',request_value->>'reason',null,null,null,null)
 returning *into preparation_value;
 perform set_config('controlled_review_v3.claim_request',coalesce(previous_context,''),true);
 return jsonb_build_object('version',3,'state','prepared','data',controlled_review_v3.protocol_prepared_data(to_jsonb(preparation_value)));
end

controlled_review_v3.protocol_principal(.source:
begin
 if p_actor_id is not null then return controlled_review_v3.protocol_identity(p_actor_id);end if;
 if session_user<>'postgres'or current_user<>'postgres'or auth.uid()is not null
  or auth.jwt()->>'role'is not null then
  raise exception 'review_private_owner_required'using errcode='42501';end if;
 if current_setting('transaction_isolation')<>'read committed'then
  raise exception 'review_isolation_invalid'using errcode='23514';end if;
 return jsonb_build_object('actor_id',null,'session_id',null);
end

controlled_review_v3.protocol_publicatio.source:
declare actor_value uuid;document_value jsonb;stream_value jsonb;authority_value jsonb;member_value jsonb;capability_value text;
begin
 actor_value:=public.controlled_stock_uuid(p_request->'actor_id');document_value:=p_request->'document';
 perform controlled_review_v3.protocol_identity(actor_value);
 capability_value:=case document_value->>'kind'when 'policy'then 'publish_policy'when 'calendar'then 'publish_calendar'
  when 'routing'then 'publish_routing'when 'eligibility'then 'manage_eligibility'else null end;
 if capability_value is null then raise exception 'review_configuration_not_authorized'using errcode='42501';end if;
 stream_value:=controlled_review_v3.protocol_stream_key(jsonb_build_object('kind','administration','product_id',document_value#>'{scope,product_id}',
  'site_id',null,'event_kind',null,'capability',null));
 authority_value:=controlled_review_v3.protocol_select_configuration(jsonb_build_object('stream_key',stream_value,'at',controlled_review_v3.protocol_utc(p_at)));
 if authority_value is null then raise exception 'review_configuration_not_authorized'using errcode='42501';end if;
 member_value:=controlled_review_v3.protocol_live_member(authority_value,actor_value,capability_value);
 if member_value is null then raise exception 'review_configuration_not_authorized'using errcode='42501';end if;
 return authority_value;
end

declare request_value jsonb:=controlled_review_v3.protocol_publication_wire(p_request);document_value jsonb:=request_value->'document';stream_value jsonb;administration_stream jsonb;keys_value jsonb;reference_kind text;
begin
 stream_value:=controlled_review_v3.protocol_stream_key((document_value->'scope')||jsonb_build_object('kind',document_value->'kind'));
 keys_value:=jsonb_build_array(
  jsonb_build_object('class_id',90271101,'key','review-v3-publication-operation:'||(request_value->>'operation_id'),'mode','exclusive'),
  jsonb_build_object('class_id',90271104,'key','review-v3-config:'||stream_value::text,'mode','exclusive'),
  jsonb_build_object('class_id',90271105,'key','review-v3-unique:configuration:'||(request_value->>'record_id'),'mode','exclusive'));
 if document_value->>'kind'<>'administration'then
  administration_stream:=controlled_review_v3.protocol_stream_key(jsonb_build_object('kind','administration','product_id',document_value#>'{scope,product_id}','site_id',null,'event_kind',null,'capability',null));
  keys_value:=keys_value||jsonb_build_array(jsonb_build_object('class_id',90271104,'key','review-v3-config:'||administration_stream::text,'mode','shared'));
 end if;
 if document_value->>'kind'='policy'then
  for reference_kind in select unnest(array['calendar','routing'])loop
   if document_value#>array['body',reference_kind||'_id']is distinct from 'null'::jsonb then
    stream_value:=controlled_review_v3.protocol_stream_key(jsonb_build_object('kind',reference_kind,'product_id',document_value#>'{scope,product_id}',
     'site_id',document_value#>'{scope,site_id}','event_kind',null,'capability',null));
    keys_value:=keys_value||jsonb_build_array(jsonb_build_object('class_id',90271104,'key','review-v3-config:'||stream_value::text,'mode','shared'));
   end if;
  end loop;
 end if;
 perform controlled_review_v3.protocol_lock_keys(keys_value);return keys_value;
end

declare request_value jsonb;
begin
 if jsonb_typeof(p_value)is distinct from 'object'or octet_length(p_value::text)>262144 then raise exception 'review_publication_context_invalid'using errcode='23514';end if;
 perform public.controlled_stock_keys(p_value,array['version','request','authority_id']);
 if jsonb_typeof(p_value->'version')is distinct from 'number'or p_value->>'version'<>'1'then raise exception 'review_publication_context_invalid'using errcode='23514';end if;
 request_value:=controlled_review_v3.protocol_publication_wire(p_value->'request');
 if request_value#>>'{document,kind}'='administration'then
  if p_value->'authority_id'is distinct from 'null'::jsonb then raise exception 'review_publication_context_invalid'using errcode='23514';end if;
 else perform public.controlled_stock_uuid(p_value->'authority_id');end if;
 return p_value;
end

declare row_value controlled_review_v3.publications;
begin
 select *into row_value from controlled_review_v3.publications where operation_id=p_operation_id;
 if not found then return null;end if;
 return jsonb_build_object('operation_id',row_value.operation_id,'actor_id',row_value.actor_id,'request',row_value.request,
  'request_hash',row_value.request_hash,'record_id',row_value.record_id,'receipt',row_value.receipt,
  'recorded_at',controlled_review_v3.protocol_utc(row_value.recorded_at),'mode',row_value.mode);
end

declare actor_value uuid;document_value jsonb;
begin
 if p_owner is null or jsonb_typeof(p_request)is distinct from 'object'or octet_length(p_request::text)>131072 then
  raise exception 'review_request_invalid'using errcode='23514';end if;
 if p_owner then
  perform controlled_review_v3.protocol_principal(null);
  perform public.controlled_stock_keys(p_request,array['operation_id','record_id','document','reason']);
  perform public.controlled_stock_text(p_request->'reason',4000,true);
 else
  perform public.controlled_stock_keys(p_request,array['actor_id','operation_id','record_id','document']);
  actor_value:=public.controlled_stock_uuid(p_request->'actor_id');perform controlled_review_v3.protocol_identity(actor_value);
 end if;
 perform public.controlled_stock_uuid(p_request->'operation_id');perform public.controlled_stock_uuid(p_request->'record_id');
 document_value:=controlled_review_v3.validate_configuration(p_request->'document');
 if(p_owner and document_value->'kind'is distinct from '"administration"'::jsonb)
  or(not p_owner and document_value->'kind'='"administration"'::jsonb)then
  raise exception 'review_configuration_not_authorized'using errcode='42501';end if;
 return p_request;
end

declare request_value jsonb:=controlled_review_v3.protocol_publication_input(p_request,p_owner);document_value jsonb:=request_value->'document';
stream_value jsonb;administration_stream jsonb;keys_value jsonb;reference_kind text;
begin
 stream_value:=controlled_review_v3.protocol_stream_key((document_value->'scope')||jsonb_build_object('kind',document_value->'kind'));
 keys_value:=jsonb_build_array(
  jsonb_build_object('class_id',90271101,'key','review-v3-publication-operation:'||(request_value->>'operation_id'),'mode','exclusive'),
  jsonb_build_object('class_id',90271104,'key','review-v3-config:'||stream_value::text,'mode','exclusive'),
  jsonb_build_object('class_id',90271105,'key','review-v3-unique:configuration:'||(request_value->>'record_id'),'mode','exclusive'));
 if not p_owner then
  administration_stream:=controlled_review_v3.protocol_stream_key(jsonb_build_object('kind','administration',
   'product_id',document_value#>'{scope,product_id}','site_id',null,'event_kind',null,'capability',null));
  keys_value:=keys_value||jsonb_build_array(jsonb_build_object('class_id',90271104,'key','review-v3-config:'||administration_stream::text,'mode','shared'));
 end if;
 if document_value->>'kind'='policy'then
  for reference_kind in select unnest(array['calendar','routing'])loop
   if document_value#>array['body',reference_kind||'_id']is distinct from 'null'::jsonb then
    stream_value:=controlled_review_v3.protocol_stream_key(jsonb_build_object('kind',reference_kind,'product_id',document_value#>'{scope,product_id}',
     'site_id',document_value#>'{scope,site_id}','event_kind',null,'capability',null));
    keys_value:=keys_value||jsonb_build_array(jsonb_build_object('class_id',90271104,'key','review-v3-config:'||stream_value::text,'mode','shared'));
   end if;
  end loop;
 end if;
 perform controlled_review_v3.protocol_lock_keys(keys_value);return keys_value;
end

declare record_value jsonb:=controlled_review_v3.validate_configuration_record(p_record);row_value jsonb;publication_value jsonb;pair_value jsonb;
begin
 row_value:=controlled_review_v3.protocol_configuration_row_value(record_value);
 publication_value:=jsonb_build_object('operation_id',record_value->'publication_operation_id','actor_id',record_value->'publisher_actor_id',
  'request',p_request,'request_hash',public.controlled_stock_hash(p_request),'record_id',record_value->'id',
  'receipt',controlled_review_v3.protocol_publication_receipt(p_request,record_value),'recorded_at',record_value->'published_at','mode',record_value->'publication_mode');
 pair_value:=jsonb_build_object('configuration',row_value,'publication',publication_value);
 return controlled_review_v3.validate_configuration_pair(pair_value);
end

declare record_value jsonb:=controlled_review_v3.validate_configuration_record(p_record);
begin
 return jsonb_build_object('version',3,'operation_id',record_value->'publication_operation_id','request_hash',public.controlled_stock_hash(p_request),
  'record_id',record_value->'id','record_hash',record_value->'record_hash','publisher_actor_id',record_value->'publisher_actor_id',
  'publisher_session_id',record_value->'publisher_session_id','publisher_name',record_value->'publisher_name',
  'authorization_id',record_value->'authorization_id','publication_mode',record_value->'publication_mode','published_at',record_value->'published_at');
end

declare document_value jsonb;stored_value jsonb;record_value jsonb;effective_value timestamptz;publisher_value uuid;session_value uuid;
begin
 document_value:=controlled_review_v3.validate_configuration(p_request->'document');
 perform controlled_review_v3.protocol_utc(p_at);
 if p_mode='staff_administration'then
  perform public.controlled_stock_keys(p_request,array['actor_id','operation_id','record_id','document']);
  publisher_value:=public.controlled_stock_uuid(p_identity->'actor_id');session_value:=public.controlled_stock_uuid(p_identity->'session_id');
  perform public.controlled_stock_text(to_jsonb(p_name),200,false);perform public.controlled_stock_uuid(to_jsonb(p_authority_id));
  if to_jsonb(publisher_value)is distinct from p_request->'actor_id'or to_jsonb(p_authority_id)is distinct from p_request->'operation_id'then
   raise exception 'review_configuration_not_authorized'using errcode='42501';end if;
 elsif p_mode='staff'then
  perform public.controlled_stock_keys(p_request,array['actor_id','operation_id','record_id','document']);
  publisher_value:=public.controlled_stock_uuid(p_identity->'actor_id');session_value:=public.controlled_stock_uuid(p_identity->'session_id');
  perform public.controlled_stock_text(to_jsonb(p_name),200,false);perform public.controlled_stock_uuid(to_jsonb(p_authority_id));
  if to_jsonb(publisher_value)is distinct from p_request->'actor_id'or document_value->>'kind'='administration'then
   raise exception 'review_configuration_not_authorized'using errcode='42501';end if;
 elsif p_mode in('owner_bootstrap','owner_recovery')then
  perform public.controlled_stock_keys(p_request,array['operation_id','record_id','document','reason']);
  perform public.controlled_stock_text(p_request->'reason',4000,true);
  if p_identity is distinct from 'null'::jsonb or p_name is distinct from 'Database owner (postgres)'or p_authority_id is not null
   or document_value->>'kind'<>'administration'then raise exception 'review_configuration_not_authorized'using errcode='42501';end if;
 else raise exception 'review_configuration_not_authorized'using errcode='42501';end if;
 stored_value:=document_value||jsonb_build_object('calendar_observation',p_calendar_observation);
 if document_value->>'kind'='policy'then
  effective_value:=case document_value#>>'{body,effective_from,mode}'when 'now'then p_at
   else controlled_review_v3.protocol_instant(document_value#>'{body,effective_from,at}')end;
  if effective_value<p_at then raise exception 'review_policy_effective_time_invalid'using errcode='23514';end if;
  stored_value:=jsonb_set(stored_value,'{body,effective_from}',to_jsonb(controlled_review_v3.protocol_utc(effective_value)));
 end if;
 record_value:=stored_value||jsonb_build_object('id',p_request->'record_id','publication_operation_id',p_request->'operation_id',
  'published_at',controlled_review_v3.protocol_utc(p_at),'publisher_actor_id',publisher_value,'publisher_session_id',session_value,
  'publisher_name',p_name,'authorization_id',p_authority_id,'publication_mode',p_mode);
 record_value:=record_value||jsonb_build_object('record_hash',public.controlled_stock_hash(record_value));
 return controlled_review_v3.validate_configuration_record(record_value);
end

declare document_value jsonb:=p_request->'document';rows_value jsonb;field text;id_value uuid;
begin
 -- Called only after operation/config/unique locks and request/principal
 -- validation. No caller-provided authority ID grants a capability.
 rows_value:=jsonb_build_array(
  jsonb_build_object('relation','controlled_review_v3.configuration','key',jsonb_build_object('id',p_request->'record_id'),'local',true),
  jsonb_build_object('relation','controlled_review_v3.publications','key',jsonb_build_object('operation_id',p_request->'operation_id'),'local',true));
 if document_value->'predecessor_id'is distinct from 'null'::jsonb then
  id_value:=public.controlled_stock_uuid(document_value->'predecessor_id');
  rows_value:=rows_value||jsonb_build_array(jsonb_build_object('relation','controlled_review_v3.configuration','key',jsonb_build_object('id',id_value),'local',false));end if;
 if p_authority_id is not null then rows_value:=rows_value||jsonb_build_array(jsonb_build_object('relation','controlled_review_v3.configuration',
  'key',jsonb_build_object('id',p_authority_id),'local',false));end if;
 if document_value->'kind'='"policy"'::jsonb then
  for field in select unnest(array['calendar_id','routing_id'])loop
   if document_value#>array['body',field]is distinct from 'null'::jsonb then
    id_value:=public.controlled_stock_uuid(document_value#>array['body',field]);
    rows_value:=rows_value||jsonb_build_array(jsonb_build_object('relation','controlled_review_v3.configuration','key',jsonb_build_object('id',id_value),'local',false));end if;
  end loop;
 end if;
 return controlled_review_v3.protocol_row_targets(rows_value);
end

declare child json;
begin
 if p_value is null or p_depth is null or p_depth<0 or p_depth>16 then raise exception 'review_publication_context_invalid'using errcode='23514';end if;
 if json_typeof(p_value)='object'then
  if(select count(*)from json_each(p_value))>32 or exists(select 1 from json_each(p_value)group by key collate "C" having count(*)>1)then raise exception 'review_publication_context_invalid'using errcode='23514';end if;
  for child in select value from json_each(p_value)loop perform controlled_review_v3.protocol_publication_unique_json(child,p_depth+1);end loop;
 elsif json_typeof(p_value)='array'then
  if json_array_length(p_value)>100 then raise exception 'review_publication_context_invalid'using errcode='23514';end if;
  for child in select value from json_array_elements(p_value)loop perform controlled_review_v3.protocol_publication_unique_json(child,p_depth+1);end loop;
 end if;
end

declare document_value jsonb;
begin
 if jsonb_typeof(p_request)is distinct from 'object'or octet_length(p_request::text)>131072 then raise exception 'review_request_invalid'using errcode='23514';end if;
 document_value:=controlled_review_v3.validate_configuration(p_request->'document');
 if document_value->>'kind'='administration'and not(p_request?'actor_id')then
  perform public.controlled_stock_keys(p_request,array['operation_id','record_id','document','reason']);perform public.controlled_stock_text(p_request->'reason',4000,true);
 else
  perform public.controlled_stock_keys(p_request,array['actor_id','operation_id','record_id','document']);perform public.controlled_stock_uuid(p_request->'actor_id');end if;
 perform public.controlled_stock_uuid(p_request->'operation_id');perform public.controlled_stock_uuid(p_request->'record_id');return p_request;
end

controlled_review_v3.protocol_publish_mu.source:
declare request_value jsonb;document_value jsonb;actor_value uuid;operation_value uuid;record_id_value uuid;keys_value jsonb;rows_value jsonb;
authority_value jsonb;authority_id uuid;context_value jsonb;previous_context text;record_value jsonb;
publication_value controlled_review_v3.publications;configuration_value controlled_review_v3.configuration;existing_value boolean;
begin
 perform controlled_review_v3.read_practice_preflight();
 perform controlled_review_v3.read_relation_preflight();
 perform controlled_review_v3.ops_admin_preflight();
 perform pg_advisory_xact_lock_shared(90271040,0);
 if pg_catalog.pg_my_temp_schema()<>0 then raise exception 'review_temp_namespace_forbidden'using errcode='42501';end if;
 perform controlled_review_v3.required();
 request_value:=controlled_review_v3.protocol_publication_input(p_request,p_owner);document_value:=request_value->'document';
 actor_value:=case when p_owner then null else(request_value->>'actor_id')::uuid end;
 operation_value:=(request_value->>'operation_id')::uuid;record_id_value:=(request_value->>'record_id')::uuid;
 keys_value:=jsonb_build_array(jsonb_build_object('class_id',90271101,'key','review-v3-publication-operation:'||operation_value::text,'mode','exclusive'));
 perform controlled_review_v3.protocol_acquire_advisory(keys_value,actor_value);
 select *into publication_value from controlled_review_v3.publications where operation_id=operation_value;existing_value:=found;
 if existing_value then
  if publication_value.actor_id is distinct from actor_value then raise exception 'operation_not_found'using errcode='PT404';end if;
  if publication_value.request is distinct from request_value or publication_value.record_id<>record_id_value then
   raise exception 'operation_request_mismatch'using errcode='PT409';end if;
  record_value:=controlled_review_v3.protocol_validate_publication_record(publication_value.record_id);
  -- Exact saved owned replay skips renewed administration capability; active
  -- real identity/session (or strict actual owner) and metadata still apply.
  perform controlled_review_v3.protocol_publication_input(request_value,p_owner);
  return jsonb_build_object('version',3,'state','published','data',jsonb_build_object('operation_id',operation_value,'record',record_value,'receipt',publication_value.receipt));
 end if;
 keys_value:=controlled_review_v3.protocol_publication_candidate_keys(request_value);
 perform controlled_review_v3.protocol_acquire_advisory(keys_value,actor_value);
 if not p_owner then
  authority_value:=controlled_review_v3.protocol_publication_authority(request_value,clock_timestamp());authority_id:=(authority_value->>'id')::uuid;
 end if;
 rows_value:=controlled_review_v3.protocol_publication_rows(request_value,authority_id);
 perform controlled_review_v3.protocol_acquire_relation_tail('publication',rows_value,keys_value,actor_value);
 perform controlled_review_v3.protocol_acquire_fk_tail('publication',rows_value,actor_value);
 context_value:=controlled_review_v3.protocol_publication_context(jsonb_build_object('version',1,'request',request_value,'authority_id',authority_id));
 previous_context:=current_setting('controlled_review_v3.publication_request',true);
 perform set_config('controlled_review_v3.publication_request',context_value::text,true);
 -- Logical original C values are supplied unchanged. Every server-owned field
 -- is explicitly NULL; guard rejects a non-NULL proposal and owns its clock/R.
 insert into controlled_review_v3.configuration(id,kind,stream_key,version,predecessor_id,predecessor_hash,enabled,document,record_hash,
  publication_operation_id,published_at,publisher_actor_id,publisher_session_id,publisher_name,authorization_id,publication_mode,effective_from)
 values(record_id_value,document_value->>'kind',(document_value->'scope')||jsonb_build_object('kind',document_value->'kind'),
  (document_value->>'version')::integer,(document_value->>'predecessor_id')::uuid,document_value->>'predecessor_hash',(document_value->>'enabled')::boolean,
  null,null,operation_value,null,null,null,null,null,null,null)returning *into configuration_value;
 record_value:=controlled_review_v3.protocol_configuration_record(configuration_value.id);
 insert into controlled_review_v3.publications(operation_id,actor_id,request,request_hash,record_id,receipt,recorded_at,mode)
 values(operation_value,actor_value,request_value,null,configuration_value.id,null,null,null)returning *into publication_value;
 perform set_config('controlled_review_v3.publication_request',coalesce(previous_context,''),true);
 -- Both rows are exact reciprocal values. Their deferred guards must succeed
 -- and the outer transaction must COMMIT before a transport reports success.
 record_value:=controlled_review_v3.protocol_validate_publication_record(configuration_value.id);
 return jsonb_build_object('version',3,'state','published','data',jsonb_build_object('operation_id',operation_value,'record',record_value,'receipt',publication_value.receipt));
end

controlled_review_v3.protocol_read_autho.source:
declare actor_value uuid;record_id_value uuid;record_value jsonb;latest_value jsonb;identity_value jsonb;session_value uuid;
 active_value boolean;roles_value jsonb;session_valid boolean;member_value jsonb;fingerprint_value jsonb;
begin
 if jsonb_typeof(p_request)is distinct from 'object'or octet_length(p_request::text)>8192 then
  raise exception 'review_request_invalid'using errcode='23514';end if;
 perform public.controlled_stock_keys(p_request,array['actor_id','read_eligibility_id']);
 actor_value:=public.controlled_stock_uuid(p_request->'actor_id');record_id_value:=public.controlled_stock_uuid(p_request->'read_eligibility_id');
 identity_value:=controlled_review_v3.protocol_identity(actor_value);session_value:=(identity_value->>'session_id')::uuid;
 record_value:=controlled_review_v3.protocol_configuration_record(record_id_value);
 if record_value is null or record_value->'kind'is distinct from '"eligibility"'::jsonb
  or record_value#>>'{scope,capability}'not in('read','exception_read')then
  raise exception 'review_read_not_authorized'using errcode='42501';end if;
 latest_value:=controlled_review_v3.protocol_select_configuration(jsonb_build_object('stream_key',
  (record_value->'scope')||jsonb_build_object('kind','eligibility'),'at',controlled_review_v3.protocol_utc(clock_timestamp())));
 if latest_value->'id'is distinct from record_value->'id'then raise exception 'cursor_stale'using errcode='PT409';end if;
 -- One final fresh command obtains the actual profile state, all relevant LIVE
 -- staff roles and still-valid actual session together. No Auth/profile rowlock.
 select p.is_active,
  (select coalesce(jsonb_agg(role_name order by role_name collate "C"),'[]'::jsonb)from(
   select distinct r.role::text as role_name from public.user_roles r where r.user_id=actor_value and r.role::text in('ADMIN','DVM','STAFF','TECH'))q),
  (auth.uid()=actor_value and auth.jwt()->>'role'='authenticated'and exists(
   select 1 from auth.sessions s where s.id=session_value and s.user_id=actor_value and(s.not_after is null or s.not_after>clock_timestamp())))
 into active_value,roles_value,session_valid from public.profiles p where p.id=actor_value;
 if not found or active_value is distinct from true or session_valid is distinct from true then
  raise exception 'review_identity_invalid'using errcode='42501';end if;
 member_value:=controlled_review_v3.protocol_member_conditions(jsonb_build_object('record',record_value,'actor_id',actor_value,
  'capability',record_value#>'{scope,capability}','active',active_value,'live_roles',roles_value));
 if member_value is null then raise exception 'review_read_not_authorized'using errcode='42501';end if;
 -- Exact prospective preimage, separate from P's immutable configured roles.
 -- A permitted role addition/swap changes this hash even if P remains stable.
 fingerprint_value:=jsonb_build_object('version',3,'actor_id',actor_value,'profile_active',active_value,'live_roles',roles_value,
  'read_eligibility_id',record_value->'id','read_eligibility_hash',record_value->'record_hash');
 return jsonb_build_object('member',member_value,'read_authorization_hash',public.controlled_stock_hash(fingerprint_value));
end

controlled_review_v3.protocol_read_publi.source:
declare raw_value text;decoded_value json;context_value jsonb;
begin
 raw_value:=current_setting('controlled_review_v3.publication_request',true);
 if raw_value is null or raw_value=''or octet_length(raw_value)>262144 then raise exception 'review_publication_context_invalid'using errcode='23514';end if;
 begin decoded_value:=raw_value::json;perform controlled_review_v3.protocol_publication_unique_json(decoded_value,0);context_value:=decoded_value::jsonb;
 exception when invalid_text_representation then raise exception 'review_publication_context_invalid'using errcode='23514';end;
 return controlled_review_v3.protocol_publication_context(context_value);
end

controlled_review_v3.protocol_receipt_fo.source:
declare preparation_value controlled_review_v3.preparations;identity_value jsonb;actor_name_value text;packet_value jsonb;
 historical_value jsonb;deadline_state_value text;due_value timestamptz;result_value jsonb;
begin
 select *into strict preparation_value from controlled_review_v3.preparations where operation_id=p_operation_id;
 identity_value:=controlled_review_v3.protocol_identity(preparation_value.actor_id);
 select full_name into strict actor_name_value from public.profiles where id=preparation_value.actor_id;
 perform public.controlled_stock_text(to_jsonb(actor_name_value),200,false);
 perform controlled_review_v3.protocol_utc(p_recorded_at);
 if p_recorded_at<preparation_value.created_at or p_recorded_at>=preparation_value.expires_at then
  raise exception 'review_preparation_expired'using errcode='PT409';end if;
 packet_value:=preparation_value.packet;historical_value:=packet_value#>'{obligation,historical}';
 due_value:=case when historical_value->'due_at'='null'::jsonb then null
  else controlled_review_v3.protocol_instant(historical_value->'due_at')end;
 deadline_state_value:=case when due_value is null then 'completed_time_unassessable'
  when p_recorded_at<=due_value then 'completed_on_time'else 'completed_late'end;
 result_value:=jsonb_build_object('version',3,'operation_id',p_operation_id,'event_id',preparation_value.event_id,
  'meaning','independent_record_review_v1','meaning_text','Independent record review; no claim of personal physical observation.','meaning_version',1,
  'target',packet_value->'target','target_hash',preparation_value.target_hash,'adapter_id',packet_value#>'{adapter,adapter_id}',
  'site_basis',packet_value#>'{adapter,site_basis}','site_id',packet_value#>'{adapter,site_id}',
  'request_hash',preparation_value.request_hash,'transport_digest',preparation_value.transport_digest,'packet_hash',preparation_value.packet_hash,
  'obligation_binding_hash',packet_value#>'{obligation,binding_hash}','historical',historical_value,
  'policy_id',preparation_value.policy_id,'policy_hash',packet_value#>'{current_authorization,policy,record_hash}',
  'read_eligibility_id',preparation_value.read_eligibility_id,'read_eligibility_hash',packet_value#>'{current_authorization,read,record_hash}',
  'review_eligibility_id',preparation_value.review_eligibility_id,'review_eligibility_hash',packet_value#>'{current_authorization,review,record_hash}',
  'actor_id',preparation_value.actor_id,'session_id',identity_value->'session_id','actor_name',actor_name_value,
  'decision',preparation_value.decision,'reason',preparation_value.reason,'recorded_at',controlled_review_v3.protocol_utc(p_recorded_at),
  'review_state',case when preparation_value.decision='approve'then 'approved'else 'rejected'end,'deadline_state',deadline_state_value);
 perform controlled_review_v3.protocol_saved_commitment(result_value);
 return result_value;
end

controlled_review_v3.protocol_receipt_fr.source:
declare preparation_value jsonb:=controlled_review_v3.protocol_retained_preparation(p_preparation);
packet_value jsonb:=preparation_value->'packet';historical_value jsonb;recorded_value timestamptz;due_value timestamptz;deadline_value text;
begin
 perform public.controlled_stock_keys(p_decision,array['operation_id','event_id','actor_id','session_id','actor_name','decision','reason',
  'request_hash','transport_digest','packet_hash','target_hash','recorded_at','receipt']);
 if exists(select 1 from unnest(array['operation_id','event_id','actor_id','decision','reason','request_hash','transport_digest','packet_hash','target_hash'])as field
  where p_decision->field is distinct from preparation_value->field)then
  raise exception 'review_history_integrity'using errcode='23514';end if;
 perform public.controlled_stock_uuid(p_decision->'session_id');
 perform public.controlled_stock_text(p_decision->'actor_name',200,false);
 if jsonb_typeof(p_decision->'recorded_at')is distinct from 'string'then raise exception 'review_history_integrity'using errcode='23514';end if;
 recorded_value:=(p_decision->>'recorded_at')::timestamptz;
 if recorded_value<(preparation_value->>'created_at')::timestamptz or recorded_value>=(preparation_value->>'expires_at')::timestamptz then
  raise exception 'review_history_integrity'using errcode='23514';end if;
 historical_value:=packet_value#>'{obligation,historical}';
 if jsonb_typeof(historical_value)is distinct from 'object'then raise exception 'review_history_integrity'using errcode='23514';end if;
 due_value:=case when historical_value->'due_at'='null'::jsonb then null else controlled_review_v3.protocol_instant(historical_value->'due_at')end;
 deadline_value:=case when due_value is null then 'completed_time_unassessable'when recorded_value<=due_value then 'completed_on_time'else 'completed_late'end;
 return jsonb_build_object('version',3,'operation_id',preparation_value->'operation_id','event_id',preparation_value->'event_id',
  'meaning','independent_record_review_v1','meaning_text','Independent record review; no claim of personal physical observation.','meaning_version',1,
  'target',packet_value->'target','target_hash',preparation_value->'target_hash','adapter_id',packet_value#>'{adapter,adapter_id}',
  'site_basis',packet_value#>'{adapter,site_basis}','site_id',packet_value#>'{adapter,site_id}',
  'request_hash',preparation_value->'request_hash','transport_digest',preparation_value->'transport_digest','packet_hash',preparation_value->'packet_hash',
  'obligation_binding_hash',packet_value#>'{obligation,binding_hash}','historical',historical_value,
  'policy_id',preparation_value->'policy_id','policy_hash',packet_value#>'{current_authorization,policy,record_hash}',
  'read_eligibility_id',preparation_value->'read_eligibility_id','read_eligibility_hash',packet_value#>'{current_authorization,read,record_hash}',
  'review_eligibility_id',preparation_value->'review_eligibility_id','review_eligibility_hash',packet_value#>'{current_authorization,review,record_hash}',
  'actor_id',p_decision->'actor_id','session_id',p_decision->'session_id','actor_name',p_decision->'actor_name',
  'decision',p_decision->'decision','reason',p_decision->'reason','recorded_at',controlled_review_v3.protocol_utc(recorded_value),
  'review_state',case when p_decision->>'decision'='approve'then 'approved'else 'rejected'end,'deadline_state',deadline_value);
exception when invalid_text_representation or datetime_field_overflow or numeric_value_out_of_range then
 raise exception 'review_history_integrity'using errcode='23514';
end

controlled_review_v3.protocol_recover_sa.source:
declare request_value jsonb:=controlled_review_v3.protocol_operation_request(p_request);
begin
 perform controlled_review_v3.protocol_identity((request_value->>'actor_id')::uuid);
 -- Fail closed before locks or reading operation/clinical state. A final metadata
 -- seal, owned reciprocal history validator, lock-tail union and actual Auth
 -- acceptance are required before an operational recovery facade can exist.
 raise exception 'review_protocol_not_implemented'using errcode='0A000';
end

controlled_review_v3.protocol_rejection_.source:
declare raw_value text;json_value json;value jsonb;
begin
 raw_value:=current_setting('controlled_review_v3.rejection_context',true);
 if raw_value is null or octet_length(raw_value)>1024 then raise exception 'review_rejection_context_invalid'using errcode='23514';end if;
 begin json_value:=raw_value::json;exception when invalid_text_representation then raise exception 'review_rejection_context_invalid'using errcode='23514';end;
 perform controlled_review_v3.protocol_context_unique(json_value,0);
 value:=json_value::jsonb;
 perform public.controlled_stock_keys(value,array['operation_id','actor_id','event_id']);
 perform public.controlled_stock_uuid(value->'operation_id');perform public.controlled_stock_uuid(value->'actor_id');perform public.controlled_stock_uuid(value->'event_id');
 return value;
end

declare receipt_value jsonb;
begin
 receipt_value:=controlled_review_v3.protocol_receipt_from_rows(p_preparation,p_decision);
 if p_decision->'decision'is distinct from '"reject"'::jsonb or receipt_value is distinct from p_decision->'receipt'then raise exception 'review_rejection_evidence_invalid'using errcode='23514';end if;
 return jsonb_build_object('version',1,'reason','rejected','event_id',p_decision->'event_id','target_hash',p_decision->'target_hash',
  'decision_operation_id',p_decision->'operation_id','receipt_hash',public.controlled_stock_hash(receipt_value));
end

declare evidence_value jsonb;stamp timestamptz;row_value jsonb;field text;
begin
 if jsonb_typeof(p_row)is distinct from 'object'or octet_length(p_row::text)>131072 then raise exception 'review_rejection_record_invalid'using errcode='23514';end if;
 perform public.controlled_stock_keys(p_row,array['id','event_id','reason','routing_snapshot','first_detected_at','evidence','record_hash']);
 perform public.controlled_stock_uuid(p_row->'id');perform public.controlled_stock_uuid(p_row->'event_id');
 if p_row->'reason'is distinct from '"rejected"'::jsonb or jsonb_typeof(p_row->'first_detected_at')is distinct from 'string'then raise exception 'review_rejection_record_invalid'using errcode='23514';end if;
 stamp:=(p_row->>'first_detected_at')::timestamptz;perform controlled_review_v3.protocol_utc(stamp);
 evidence_value:=p_row->'evidence';perform public.controlled_stock_keys(evidence_value,array['version','reason','event_id','target_hash','decision_operation_id','receipt_hash']);
 if evidence_value->'version'is distinct from '1'::jsonb or evidence_value->'reason'is distinct from '"rejected"'::jsonb
  or evidence_value->'event_id'is distinct from p_row->'event_id'then raise exception 'review_rejection_record_invalid'using errcode='23514';end if;
 perform public.controlled_stock_uuid(evidence_value->'decision_operation_id');
 foreach field in array array['target_hash','receipt_hash']loop
  if jsonb_typeof(evidence_value->field)is distinct from 'string'or(evidence_value->>field)!~'^[0-9a-f]{64}$'then raise exception 'review_rejection_record_invalid'using errcode='23514';end if;
 end loop;
 perform controlled_review_v3.protocol_validate_rejection_routing(p_row->'routing_snapshot',p_row#>'{routing_snapshot,historical}',stamp);
 row_value:=jsonb_build_object('id',p_row->'id','event_id',p_row->'event_id','reason','rejected','routing_snapshot',p_row->'routing_snapshot',
  'first_detected_at',controlled_review_v3.protocol_utc(stamp),'evidence',evidence_value);
 if jsonb_typeof(p_row->'record_hash')is distinct from 'string'or p_row->>'record_hash'is distinct from public.controlled_stock_hash(row_value)then raise exception 'review_rejection_record_invalid'using errcode='23514';end if;
 return row_value||jsonb_build_object('record_hash',p_row->'record_hash');
exception when invalid_text_representation or datetime_field_overflow then raise exception 'review_rejection_record_invalid'using errcode='23514';
end

declare facts jsonb:='[]';snapshot_value jsonb;at_value timestamptz;status_value text;eligible boolean:=false;member jsonb;
begin
 perform controlled_review_v3.protocol_utc(p_not_before);
 if p_historical is not null and p_historical<>'null'::jsonb then
  -- Validate structural inventory BEFORE querying named UUIDs. The final pure
  -- validator below rechecks every exact roster/role/status/time binding.
  perform public.controlled_stock_keys(p_historical,array['version','id','record_hash','enabled','members']);
  if jsonb_typeof(p_historical->'members')is distinct from 'array'or jsonb_array_length(p_historical->'members')>100 then raise exception 'review_rejection_routing_invalid'using errcode='23514';end if;
  for member in select value from jsonb_array_elements(p_historical->'members')loop
   perform public.controlled_stock_keys(member,array['actor_id','roles']);perform public.controlled_stock_uuid(member->'actor_id');
  end loop;
  -- ONE bounded command observes every named member, including inactive ones.
  -- No row lock, fresh session, wild-card user scan or impersonated JWT.
  with named as(select value->>'actor_id'as actor_id,value->'roles'as roles from jsonb_array_elements(p_historical->'members')),
  observed as(select n.actor_id,n.roles,coalesce(p.id is not null and p.is_active,false)as profile_active,
   coalesce((select jsonb_agg(role_name order by role_name collate "C")from(select distinct r.role::text as role_name from public.user_roles r
    where p.id is not null and r.user_id=n.actor_id::uuid and r.role::text in('ADMIN','DVM','STAFF','TECH'))roles),'[]'::jsonb)as live_roles
   from named n left join public.profiles p on p.id=n.actor_id::uuid)
  select coalesce(jsonb_agg(jsonb_build_object('actor_id',actor_id,'configured_roles',roles,'profile_active',profile_active,'live_roles',live_roles)
   order by actor_id collate "C"),'[]'::jsonb),coalesce(bool_or(profile_active and exists(select 1 from jsonb_array_elements(roles)c(value)
    join jsonb_array_elements(live_roles)l(value)on c.value=l.value)),false)into facts,eligible from observed;
  status_value:=case when p_historical->'enabled'='false'::jsonb then 'disabled_route'when eligible then 'eligible_recipients'else 'no_eligible_recipient'end;
 else status_value:='missing_route';end if;
 at_value:=clock_timestamp();
 snapshot_value:=jsonb_build_object('version',1,'historical',coalesce(p_historical,'null'::jsonb),'assessment',jsonb_build_object('version',1,
  'recorded_at',controlled_review_v3.protocol_utc(at_value),'status',status_value,'member_facts',facts));
 return controlled_review_v3.protocol_validate_rejection_routing(snapshot_value,p_historical,p_not_before);
end

controlled_review_v3.protocol_relation_p.source:
declare base_value jsonb:=controlled_review_v3.protocol_path_tables(p_path);
 rows_value jsonb:=controlled_review_v3.protocol_row_targets(p_rows);item jsonb;result_value jsonb;
begin
 for item in select value from jsonb_array_elements(rows_value)loop
  if not exists(select 1 from jsonb_array_elements(base_value)as b(value)where b.value->'relation'=item->'relation')
   or(item->'local'='true'::jsonb and not exists(select 1 from jsonb_array_elements(base_value)as b(value)
    where b.value->'relation'=item->'relation'and b.value->>'mode'='ROW EXCLUSIVE'))then
   raise exception 'review_lock_plan_invalid'using errcode='23514';end if;
 end loop;
 with modes as(select value->>'relation'as relation_name,case value->>'mode'when 'ROW EXCLUSIVE'then 3 else 1 end as strength
  from jsonb_array_elements(base_value)
 union all select value->>'relation',2 from jsonb_array_elements(rows_value)where value->'local'='false'::jsonb),
 collapsed as(select relation_name,max(strength)as strength from modes group by relation_name)
 select jsonb_agg(jsonb_build_object('relation',relation_name,'mode',case strength when 3 then 'ROW EXCLUSIVE'
  when 2 then 'ROW SHARE'else 'ACCESS SHARE'end)order by relation_name collate "C")into result_value from collapsed;
 return result_value;
end

