 perform public.controlled_stock_uuid(p_row->'session_id');
 perform public.controlled_stock_keys(packet_value,array['version','meaning','meaning_text','meaning_version','target','adapter','event',
  'parent_preparation','original_result','clinical_snapshot','source_rows','event_lines','cells','transitions','containers','obligation','current_authorization']);
 if octet_length(packet_value::text)>1048576 or packet_value->'version'is distinct from '3'::jsonb
  or packet_value->'meaning'is distinct from '"independent_record_review_v1"'::jsonb
  or packet_value->'meaning_text'is distinct from '"Independent record review; no claim of personal physical observation."'::jsonb
  or packet_value->'meaning_version'is distinct from '1'::jsonb
  or packet_value#>'{adapter,provenance_state}'is distinct from '"supported"'::jsonb
  or packet_value#>'{event,secondary_review_required}'is distinct from 'true'::jsonb
  or packet_value#>'{target,event_id}'is distinct from request_value->'event_id'
  or packet_value#>'{target,original_actor_id}'=request_value->'actor_id'
  or packet_value#>'{current_authorization,policy,id}'is distinct from request_value->'policy_id'
  or packet_value#>'{current_authorization,read,id}'is distinct from request_value->'read_eligibility_id'
  or packet_value#>'{current_authorization,review,id}'is distinct from request_value->'review_eligibility_id'then
  raise exception 'review_history_integrity'using errcode='23514';end if;
 if exists(select 1 from unnest(array['operation_id','event_id','actor_id','policy_id','read_eligibility_id','review_eligibility_id','decision','reason'])as field
   where p_row->field is distinct from request_value->field)
  or p_row->>'request_hash'is distinct from public.controlled_stock_hash(request_value)
  or p_row->>'transport_digest'is distinct from controlled_review_v3.protocol_transport_digest(request_value)
  or p_row->>'target_hash'is distinct from public.controlled_stock_hash(packet_value->'target')
  or p_row->>'packet_hash'is distinct from public.controlled_stock_hash(packet_value)then
  raise exception 'review_history_integrity'using errcode='23514';end if;
 -- Raw row timestamptz text is a PostgreSQL projection; derived response text
 -- is normalized separately. Never treat source display spelling as a seal.
 if jsonb_typeof(p_row->'created_at')is distinct from 'string'or jsonb_typeof(p_row->'expires_at')is distinct from 'string'
  or jsonb_typeof(p_row->'prepared_boot')is distinct from 'string'
  or jsonb_typeof(p_row->'prepared_xid')is distinct from 'string'or p_row->>'prepared_xid'!~'^[1-9][0-9]{0,19}$'then
  raise exception 'review_history_integrity'using errcode='23514';end if;
 created_value:=(p_row->>'created_at')::timestamptz;expires_value:=(p_row->>'expires_at')::timestamptz;
 perform controlled_review_v3.protocol_utc(created_value);perform controlled_review_v3.protocol_utc(expires_value);
 if not isfinite((p_row->>'prepared_boot')::timestamptz)or(p_row->>'prepared_boot')::timestamptz>created_value
  or expires_value is distinct from created_value+interval '15 minutes'
  or(p_row->>'prepared_xid')::numeric>18446744073709551615::numeric then
  raise exception 'review_history_integrity'using errcode='23514';end if;
 return p_row;
exception when invalid_text_representation or datetime_field_overflow or numeric_value_out_of_range then
 raise exception 'review_history_integrity'using errcode='23514';
end

