declare path_value text;operation_value uuid;adapter_value jsonb;target_value jsonb;event_value uuid;family_value uuid;
site_value uuid;product_value uuid;kind_value text;keys_value jsonb;stream_value jsonb;item jsonb;capability_value text;field text;
begin
 perform public.controlled_stock_keys(p_request,array['path','operation_id','adapter','escalation_ids']);
 if jsonb_typeof(p_request->'path')is distinct from 'string'or p_request->>'path'not in('prepare','decision','prepared_cancel')then
  raise exception 'review_lock_plan_invalid'using errcode='23514';end if;
 path_value:=p_request->>'path';operation_value:=public.controlled_stock_uuid(p_request->'operation_id');adapter_value:=p_request->'adapter';
 perform public.controlled_stock_keys(adapter_value,array['version','event_kind','adapter_id','target','site_basis','site_id','source_refs','native_family_dispense_id','provenance_state','reason']);
 target_value:=adapter_value->'target';perform public.controlled_stock_keys(target_value,array['event_id','product_id','sequence','record_hash','original_actor_id','policy_version_id','opening_id','engine_revision']);
 event_value:=public.controlled_stock_uuid(target_value->'event_id');product_value:=public.controlled_stock_uuid(target_value->'product_id');
 family_value:=case when adapter_value->'native_family_dispense_id'='null'::jsonb then null else public.controlled_stock_uuid(adapter_value->'native_family_dispense_id')end;
 site_value:=case when adapter_value->'site_id'='null'::jsonb then null else public.controlled_stock_uuid(adapter_value->'site_id')end;
 kind_value:=adapter_value->>'event_kind';
 if site_value is null or adapter_value->'provenance_state'is distinct from '"supported"'::jsonb then
  raise exception 'unsupported_provenance'using errcode='23514';end if;
 keys_value:=jsonb_build_array(jsonb_build_object('class_id',90271101,'key','review-v3-operation:'||operation_value::text,'mode','exclusive'));
 -- Family locking uses the original proven native family ID even if no managed
 -- families row can be created (e.g. supported opening pickup). No second event.
 if family_value is not null then keys_value:=keys_value||jsonb_build_array(jsonb_build_object('class_id',90271102,
  'key','review-v3-family:'||family_value::text,'mode','exclusive'));end if;
 keys_value:=keys_value||jsonb_build_array(jsonb_build_object('class_id',90271103,'key','review-v3-event:'||event_value::text,'mode','exclusive'));
 if path_value<>'prepared_cancel'then
  stream_value:=controlled_review_v3.protocol_stream_key(jsonb_build_object('kind','policy','product_id',product_value,'site_id',site_value,'event_kind',null,'capability',null));
  keys_value:=keys_value||jsonb_build_array(jsonb_build_object('class_id',90271104,'key','review-v3-config:'||stream_value::text,'mode','shared'));
  for capability_value in select unnest(array['read','review'])loop
   stream_value:=controlled_review_v3.protocol_stream_key(jsonb_build_object('kind','eligibility','product_id',product_value,
    'site_id',site_value,'event_kind',kind_value,'capability',capability_value));
   keys_value:=keys_value||jsonb_build_array(jsonb_build_object('class_id',90271104,'key','review-v3-config:'||stream_value::text,'mode','shared'));
  end loop;
 end if;
 if path_value='decision'then
  perform public.controlled_stock_keys(p_request->'escalation_ids',array['rejected','overdue']);
  stream_value:=controlled_review_v3.protocol_stream_key(jsonb_build_object('kind','routing','product_id',product_value,'site_id',site_value,'event_kind',null,'capability',null));
  keys_value:=keys_value||jsonb_build_array(jsonb_build_object('class_id',90271104,'key','review-v3-config:'||stream_value::text,'mode','shared'));
  if p_request#>'{escalation_ids,rejected}'=p_request#>'{escalation_ids,overdue}'then raise exception 'review_lock_plan_invalid'using errcode='23514';end if;
  for field in select unnest(array['rejected','overdue'])loop
   perform public.controlled_stock_uuid(p_request#>array['escalation_ids',field]);
   keys_value:=keys_value||jsonb_build_array(jsonb_build_object('class_id',90271105,'key','review-v3-unique:escalations:'||
    (p_request#>>array['escalation_ids',field]),'mode','exclusive'));
  end loop;
 elsif p_request->'escalation_ids'is distinct from '{}'::jsonb then raise exception 'review_lock_plan_invalid'using errcode='23514';end if;
 -- Validate actual hash collisions/strongest mode/total signed ordering now.
 perform controlled_review_v3.protocol_lock_keys(keys_value);
 return keys_value;
end

