controlled_review_v3.protocol_review_row.source:
declare path_value text;event_kind_value text;operation_value uuid;event_value uuid;family_value uuid;obligation_value controlled_review_v3.obligations;
rows_value jsonb:='[]'::jsonb;field text;id_value uuid;claim_exists boolean;obligation_exists boolean;family_exists boolean;
begin
 perform public.controlled_stock_keys(p_request,array['path','operation_id','event_id','configuration_ids']);
 if jsonb_typeof(p_request->'path')is distinct from 'string'or p_request->>'path'not in('prepare','decision','prepared_cancel','eventless_cancel')then
  raise exception 'review_lock_plan_invalid'using errcode='23514';end if;
 path_value:=p_request->>'path';operation_value:=public.controlled_stock_uuid(p_request->'operation_id');
 if path_value='eventless_cancel'then
  if p_request->'event_id'is distinct from 'null'::jsonb or p_request->'configuration_ids'is distinct from '{}'::jsonb then
   raise exception 'review_lock_plan_invalid'using errcode='23514';end if;
  if exists(select 1 from controlled_review_v3.preparations where operation_id=operation_value)then
   raise exception 'review_lock_plan_stale'using errcode='PT409';end if;
  claim_exists:=exists(select 1 from controlled_review_v3.operation_claims where operation_id=operation_value);
  return controlled_review_v3.protocol_row_targets(jsonb_build_array(jsonb_build_object('relation','controlled_review_v3.operation_claims',
   'key',jsonb_build_object('operation_id',operation_value),'local',not claim_exists)));
 end if;
 event_value:=public.controlled_stock_uuid(p_request->'event_id');
 if path_value='decision'then
  if p_request->'configuration_ids'is distinct from '{}'::jsonb then raise exception 'review_lock_plan_invalid'using errcode='23514';end if;
  return controlled_review_v3.protocol_row_targets(jsonb_build_array(
   jsonb_build_object('relation','controlled_review_v3.obligations','key',jsonb_build_object('event_id',event_value),'local',false),
   jsonb_build_object('relation','controlled_review_v3.preparations','key',jsonb_build_object('operation_id',operation_value),'local',false)));
 end if;
 claim_exists:=exists(select 1 from controlled_review_v3.operation_claims where operation_id=operation_value);
 rows_value:=rows_value||jsonb_build_array(jsonb_build_object('relation','controlled_review_v3.operation_claims','key',jsonb_build_object('operation_id',operation_value),'local',not claim_exists));
 if path_value='prepared_cancel'then
  if not claim_exists or p_request->'configuration_ids'is distinct from '{}'::jsonb then raise exception 'review_history_integrity'using errcode='23514';end if;
  return controlled_review_v3.protocol_row_targets(rows_value);
 end if;
 perform public.controlled_stock_keys(p_request->'configuration_ids',array['policy','read','review']);
 for field in select unnest(array['policy','read','review'])loop
  id_value:=public.controlled_stock_uuid(p_request#>array['configuration_ids',field]);
  rows_value:=rows_value||jsonb_build_array(jsonb_build_object('relation','controlled_review_v3.configuration','key',jsonb_build_object('id',id_value),'local',false));
 end loop;
 select *into obligation_value from controlled_review_v3.obligations where event_id=event_value;
 obligation_exists:=found;
 rows_value:=rows_value||jsonb_build_array(jsonb_build_object('relation','controlled_review_v3.obligations','key',jsonb_build_object('event_id',event_value),'local',not obligation_exists));
 -- Full canonical key union is unconditional, including parent and managed
 -- family even when an obligation already exists. Only initial presence flags
 -- vary; no xmin/subtransaction/epoch ownership inference is used.
  rows_value:=rows_value||jsonb_build_array(jsonb_build_object('relation','public.controlled_stock_events','key',jsonb_build_object('id',event_value),'local',false));
  -- Preview is recomputed only while earlier immutable/family/event gates are
  -- held by the caller. It never assumes adapter family equals managed family.
  select event_kind into strict event_kind_value from public.controlled_stock_events where id=event_value;
  -- Source-exact family branch: obligation_preview only assigns family_id for
  -- native dispense/pickup. Other20 kinds cannot yield a family; do not rebuild
  -- their entire immutable adapter merely to rediscover SQL NULL here.
  if event_kind_value in('record_native_dispense','record_native_pickup')then
   family_value:=(controlled_review_v3.protocol_obligation_preview(event_value)->>'family_dispense_id')::uuid;
  else family_value:=null;end if;
  if family_value is not null then
   family_exists:=exists(select 1 from controlled_review_v3.families where dispense_id=family_value);
   rows_value:=rows_value||jsonb_build_array(jsonb_build_object('relation','controlled_review_v3.families','key',jsonb_build_object('dispense_id',family_value),'local',not family_exists));
  end if;
 return controlled_review_v3.protocol_row_targets(rows_value);
end

controlled_review_v3.protocol_review_sta.source:
declare required_value boolean;adapter_value jsonb;authorization_value jsonb;obligation_value jsonb;historical_value jsonb;
 terminal_value jsonb;as_of_value timestamptz;due_value timestamptz;terminal_time timestamptz;result_value jsonb;
 review_value text;deadline_value text;signing_value text;reason_value text;basis_value text;unavailable_value text;
begin
 if jsonb_typeof(p_request)is distinct from 'object'or octet_length(p_request::text)>1048576 then
  raise exception 'review_history_integrity'using errcode='23514';end if;
 perform public.controlled_stock_keys(p_request,array['secondary_review_required','actor_id','original_actor_id','adapter','current_authorization','current_policy_status','terminal_decision','as_of','obligation']);
 perform public.controlled_stock_uuid(p_request->'actor_id');perform public.controlled_stock_uuid(p_request->'original_actor_id');
 if jsonb_typeof(p_request->'secondary_review_required')is distinct from 'boolean'
  or jsonb_typeof(p_request->'current_policy_status')is distinct from 'string'
  or p_request->>'current_policy_status'not in('missing','disabled','enabled')then
  raise exception 'review_history_integrity'using errcode='23514';end if;
 required_value:=(p_request->>'secondary_review_required')::boolean;adapter_value:=p_request->'adapter';
 authorization_value:=p_request->'current_authorization';terminal_value:=p_request->'terminal_decision';
 obligation_value:=p_request->'obligation';as_of_value:=controlled_review_v3.protocol_instant(p_request->'as_of');
 perform public.controlled_stock_keys(authorization_value,array['policy','read','review']);
 if adapter_value#>'{target,original_actor_id}'is distinct from p_request->'original_actor_id'then
  raise exception 'review_history_integrity'using errcode='23514';end if;
 if not required_value then
  if obligation_value is distinct from 'null'::jsonb or terminal_value is distinct from 'null'::jsonb then
   raise exception 'review_history_integrity'using errcode='23514';end if;
  return jsonb_build_object('review_state','not_required','deadline_state','not_required','deadline_basis','not_required',
   'due_at',null,'unavailable_reason',null,'signing_state','blocked','signing_reason','not_required');
 end if;
 if jsonb_typeof(obligation_value)is distinct from 'object'or obligation_value->'adapter'is distinct from adapter_value
  or jsonb_typeof(obligation_value->'historical')is distinct from 'object'then
  raise exception 'review_history_integrity'using errcode='23514';end if;
 historical_value:=obligation_value->'historical';basis_value:=historical_value->>'deadline_basis';unavailable_value:=historical_value->>'unavailable_reason';
 if basis_value is null or basis_value not in('configured','not_configured','not_assigned','historical_policy_unavailable','calendar_unavailable')
  or obligation_value->'due_at'is distinct from historical_value->'due_at'then
  raise exception 'review_history_integrity'using errcode='23514';end if;
 if historical_value->'due_at'is distinct from 'null'::jsonb then due_value:=controlled_review_v3.protocol_instant(historical_value->'due_at');end if;
 if(basis_value='configured')is distinct from(due_value is not null)or(due_value is not null and unavailable_value is not null)then
  raise exception 'review_history_integrity'using errcode='23514';end if;
 review_value:='awaiting_review';signing_value:='blocked';
 if terminal_value is distinct from 'null'::jsonb then
  perform public.controlled_stock_keys(terminal_value,array['decision','recorded_at']);
  if jsonb_typeof(terminal_value->'decision')is distinct from 'string'or terminal_value->>'decision'not in('approve','reject')then
   raise exception 'review_history_integrity'using errcode='23514';end if;
  terminal_time:=controlled_review_v3.protocol_instant(terminal_value->'recorded_at');
  review_value:=case when terminal_value->>'decision'='approve'then 'approved'else 'rejected'end;
  deadline_value:=case when due_value is null then 'completed_time_unassessable'
   when terminal_time<=due_value then 'completed_on_time'else 'completed_late'end;
  signing_value:='terminal';reason_value:='terminal_outcome';
 else
  deadline_value:=case when due_value is null then basis_value when as_of_value>due_value then 'overdue'else 'not_due'end;
  if adapter_value->'provenance_state'is distinct from '"supported"'::jsonb then reason_value:='unsupported_provenance';
  elsif p_request->'actor_id'=p_request->'original_actor_id'then reason_value:='own_record';
  elsif p_request->>'current_policy_status'='missing'then reason_value:='no_current_policy';
  elsif p_request->>'current_policy_status'='disabled'or authorization_value->'policy'='null'::jsonb then reason_value:='disabled_current_policy';
  elsif authorization_value->'read'='null'::jsonb then reason_value:='no_read_eligibility';
  elsif authorization_value->'review'='null'::jsonb then reason_value:='no_review_eligibility';
  else signing_value:='available';reason_value:='none';end if;
 end if;
 return jsonb_build_object('review_state',review_value,'deadline_state',deadline_value,'deadline_basis',basis_value,
  'due_at',historical_value->'due_at','unavailable_reason',historical_value->'unavailable_reason','signing_state',signing_value,'signing_reason',reason_value);
end

controlled_review_v3.protocol_routing_sn.source:
declare record_value jsonb;
begin
 if p_record is null or p_record='null'::jsonb then return null;end if;
 record_value:=controlled_review_v3.validate_configuration_record(p_record);
 if record_value->'kind'is distinct from '"routing"'::jsonb then
  raise exception 'review_history_integrity'using errcode='23514';end if;
 return jsonb_build_object('version',1,'id',record_value->'id','record_hash',record_value->'record_hash',
  'enabled',record_value->'enabled','members',record_value#>'{body,members}');
end

controlled_review_v3.protocol_row_target.source:
declare item jsonb;result_value jsonb;
begin
 if jsonb_typeof(p_rows)is distinct from 'array'or jsonb_array_length(p_rows)>64
  or octet_length(p_rows::text)>32768 then raise exception 'review_lock_plan_invalid'using errcode='23514';end if;
 for item in select value from jsonb_array_elements(p_rows)loop
  perform public.controlled_stock_keys(item,array['relation','key','local']);
  if jsonb_typeof(item->'relation')is distinct from 'string'or jsonb_typeof(item->'local')is distinct from 'boolean'then
   raise exception 'review_lock_plan_invalid'using errcode='23514';end if;
  case item->>'relation'
  when 'controlled_review_v3.configuration'then perform public.controlled_stock_keys(item->'key',array['id']);perform public.controlled_stock_uuid(item#>'{key,id}');
  when 'controlled_review_v3.publications'then perform public.controlled_stock_keys(item->'key',array['operation_id']);perform public.controlled_stock_uuid(item#>'{key,operation_id}');
  when 'controlled_review_v3.operation_claims'then perform public.controlled_stock_keys(item->'key',array['operation_id']);perform public.controlled_stock_uuid(item#>'{key,operation_id}');
  when 'controlled_review_v3.families'then perform public.controlled_stock_keys(item->'key',array['dispense_id']);perform public.controlled_stock_uuid(item#>'{key,dispense_id}');
  when 'controlled_review_v3.obligations'then perform public.controlled_stock_keys(item->'key',array['event_id']);perform public.controlled_stock_uuid(item#>'{key,event_id}');
  when 'controlled_review_v3.preparations'then perform public.controlled_stock_keys(item->'key',array['operation_id']);perform public.controlled_stock_uuid(item#>'{key,operation_id}');
  when 'controlled_review_v3.escalations'then perform public.controlled_stock_keys(item->'key',array['id']);perform public.controlled_stock_uuid(item#>'{key,id}');
  when 'public.controlled_stock_events'then perform public.controlled_stock_keys(item->'key',array['id']);perform public.controlled_stock_uuid(item#>'{key,id}');
  else raise exception 'review_lock_plan_invalid'using errcode='23514';end case;
 end loop;
 if exists(select 1 from jsonb_array_elements(p_rows)as a(value)join jsonb_array_elements(p_rows)as b(value)
  on a.value->'relation'=b.value->'relation'and a.value->'key'=b.value->'key'
  where a.value->'local'is distinct from b.value->'local')then
  raise exception 'review_lock_plan_invalid'using errcode='23514';end if;
 select coalesce(jsonb_agg(value order by value->>'relation'collate "C",(value->'key')::text collate "C"),'[]'::jsonb)
 into result_value from(select distinct value from jsonb_array_elements(p_rows))as deduplicated;
 return result_value;
end

controlled_review_v3.protocol_saved_comm.source:
declare field_name text;recorded_text text;recorded_value timestamp;
begin
 if jsonb_typeof(p_receipt)is distinct from 'object'or octet_length(p_receipt::text)>131072 then
  raise exception 'review_receipt_invalid'using errcode='23514';end if;
 perform public.controlled_stock_keys(p_receipt,array['version','operation_id','event_id','meaning','meaning_text','meaning_version','target','target_hash','adapter_id','site_basis','site_id','request_hash','transport_digest','packet_hash','obligation_binding_hash','historical','policy_id','policy_hash','read_eligibility_id','read_eligibility_hash','review_eligibility_id','review_eligibility_hash','actor_id','session_id','actor_name','decision','reason','recorded_at','review_state','deadline_state']);
 if jsonb_typeof(p_receipt->'version')is distinct from 'number'or p_receipt->>'version'<>'3'
  or jsonb_typeof(p_receipt->'meaning_version')is distinct from 'number'or p_receipt->>'meaning_version'<>'1'
  or p_receipt->'meaning'is distinct from '"independent_record_review_v1"'::jsonb
  or p_receipt->'meaning_text'is distinct from '"Independent record review; no claim of personal physical observation."'::jsonb then
  raise exception 'review_receipt_invalid'using errcode='23514';end if;
 foreach field_name in array array['operation_id','event_id','site_id','policy_id','read_eligibility_id','review_eligibility_id','actor_id','session_id']loop
  perform public.controlled_stock_uuid(p_receipt->field_name);end loop;
 foreach field_name in array array['target_hash','request_hash','transport_digest','packet_hash','obligation_binding_hash','policy_hash','read_eligibility_hash','review_eligibility_hash']loop
  if jsonb_typeof(p_receipt->field_name)is distinct from 'string'or(p_receipt->>field_name)!~'^[0-9a-f]{64}$'then
   raise exception 'review_receipt_invalid'using errcode='23514';end if;end loop;
 perform public.controlled_stock_text(p_receipt->'actor_name',200,false);
 perform public.controlled_stock_text(p_receipt->'reason',4000,true);
 if jsonb_typeof(p_receipt->'decision')is distinct from 'string'or p_receipt->>'decision'not in('approve','reject')
  or jsonb_typeof(p_receipt->'review_state')is distinct from 'string'
  or p_receipt->>'review_state'is distinct from (case p_receipt->>'decision'when 'approve'then 'approved'else 'rejected'end)
  or jsonb_typeof(p_receipt->'deadline_state')is distinct from 'string'
  or p_receipt->>'deadline_state'not in('completed_on_time','completed_late','completed_time_unassessable')
  or jsonb_typeof(p_receipt->'adapter_id')is distinct from 'string'
  or p_receipt->>'adapter_id'not in('movement_v1','treatment_v1','anesthesia_v1','dispense_v1','pickup_v1','return_v1','return_v2','retraction_v1','discrepancy_v1','annotation_v1')
  or jsonb_typeof(p_receipt->'site_basis')is distinct from 'string'
  or p_receipt->>'site_basis'not in('event_transitions','managed_dispense','managed_pickup','managed_return','opening_custody_site')
  or jsonb_typeof(p_receipt->'target')is distinct from 'object'or jsonb_typeof(p_receipt->'historical')is distinct from 'object'
  or jsonb_typeof(p_receipt->'recorded_at')is distinct from 'string'then
  raise exception 'review_receipt_invalid'using errcode='23514';end if;
 recorded_text:=p_receipt->>'recorded_at';
 if recorded_text!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{6}Z$'then
  raise exception 'review_receipt_invalid'using errcode='23514';end if;
 recorded_value:=left(recorded_text,26)::timestamp;
 if not isfinite(recorded_value)or recorded_value<timestamp '2026-01-01'or recorded_value>=timestamp '2101-01-01'
  or to_char(recorded_value,'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')<>recorded_text then
  raise exception 'review_receipt_invalid'using errcode='23514';end if;
 -- Only a minimal projection. Caller's reciprocal history validator must first
 -- prove this is the exact stored receipt for the owned accepted preparation.
 return jsonb_build_object('version',3,'actor_id',p_receipt->'actor_id','operation_id',p_receipt->'operation_id',
  'transport_digest',p_receipt->'transport_digest','decision',p_receipt->'decision','recorded_at',p_receipt->'recorded_at',
  'receipt_hash',public.controlled_stock_hash(p_receipt));
exception when check_violation or invalid_text_representation or invalid_datetime_format or datetime_field_overflow then
 raise exception 'review_receipt_invalid'using errcode='23514';
end

controlled_review_v3.protocol_select_con.source:
declare stream_value jsonb;at_value timestamptz;selected_id uuid;
begin
 if jsonb_typeof(p_request)is distinct from 'object'or octet_length(p_request::text)>8192 then
  raise exception 'review_selection_invalid'using errcode='23514';end if;
 perform public.controlled_stock_keys(p_request,array['stream_key','at']);
 stream_value:=controlled_review_v3.protocol_stream_key(p_request->'stream_key');
 at_value:=controlled_review_v3.protocol_instant(p_request->'at');
 if stream_value->>'kind'='policy'then
  select id into selected_id from controlled_review_v3.configuration
   where stream_key=stream_value and effective_from<=at_value and published_at<=at_value
   order by effective_from desc,version desc limit 1;
 else
  select id into selected_id from controlled_review_v3.configuration
   where stream_key=stream_value and published_at<=at_value order by version desc limit 1;
 end if;
 if selected_id is null then return null;end if;
 -- No enabled filter: a disabled newest/selected record suppresses prior rows.
 return controlled_review_v3.protocol_configuration_record(selected_id);
end

controlled_review_v3.protocol_signing_pa.source:
declare request_value jsonb:=controlled_review_v3.protocol_request(p_request);authorization_value jsonb;
begin
 authorization_value:=p_packet->'current_authorization';
 if p_packet#>'{adapter,provenance_state}'is distinct from '"supported"'::jsonb then
  raise exception 'unsupported_provenance'using errcode='23514';end if;
 if p_packet#>'{event,secondary_review_required}'is distinct from 'true'::jsonb then
  raise exception 'not_required'using errcode='23514';end if;
 if p_packet#>'{target,original_actor_id}'=request_value->'actor_id'then raise exception 'own_record'using errcode='23514';end if;
 if authorization_value->'policy'is not distinct from 'null'::jsonb then raise exception 'no_current_policy'using errcode='PT409';end if;
 if authorization_value#>'{policy,rule,enabled}'is distinct from 'true'::jsonb then raise exception 'disabled_current_policy'using errcode='PT409';end if;
 if authorization_value->'read'is not distinct from 'null'::jsonb then raise exception 'no_read_eligibility'using errcode='42501';end if;
 if authorization_value->'review'is not distinct from 'null'::jsonb then raise exception 'no_review_eligibility'using errcode='42501';end if;
 if authorization_value#>'{policy,id}'is distinct from request_value->'policy_id'then raise exception 'policy_changed'using errcode='PT409';end if;
 if authorization_value#>'{read,id}'is distinct from request_value->'read_eligibility_id'then raise exception 'read_eligibility_changed'using errcode='PT409';end if;
 if authorization_value#>'{review,id}'is distinct from request_value->'review_eligibility_id'then raise exception 'review_eligibility_changed'using errcode='PT409';end if;
 if p_packet#>'{target,event_id}'is distinct from request_value->'event_id'or p_packet#>'{obligation,event_id}'is distinct from request_value->'event_id'then
  raise exception 'review_history_integrity'using errcode='23514';end if;
 return p_packet;
end

controlled_review_v3.protocol_stream_key.source:
declare kind_value text;capability_value text;
begin
 if jsonb_typeof(p_request)is distinct from 'object'or octet_length(p_request::text)>4096 then
  raise exception 'review_stream_invalid'using errcode='23514';end if;
 perform public.controlled_stock_keys(p_request,array['kind','product_id','site_id','event_kind','capability']);
 perform public.controlled_stock_uuid(p_request->'product_id');
 if jsonb_typeof(p_request->'kind')is distinct from 'string'then
  raise exception 'review_stream_invalid'using errcode='23514';end if;
 kind_value:=p_request->>'kind';
 if kind_value='administration'then
  if p_request->'site_id'is distinct from 'null'::jsonb or p_request->'event_kind'is distinct from 'null'::jsonb
   or p_request->'capability'is distinct from 'null'::jsonb then
   raise exception 'review_stream_invalid'using errcode='23514';end if;
 elsif kind_value in('policy','calendar','routing')then
  perform public.controlled_stock_uuid(p_request->'site_id');
  if p_request->'event_kind'is distinct from 'null'::jsonb or p_request->'capability'is distinct from 'null'::jsonb then
   raise exception 'review_stream_invalid'using errcode='23514';end if;
 elsif kind_value='eligibility'then
  if jsonb_typeof(p_request->'capability')is distinct from 'string'then
   raise exception 'review_stream_invalid'using errcode='23514';end if;
  capability_value:=p_request->>'capability';
  if capability_value='exception_read'then
   if p_request->'site_id'is distinct from 'null'::jsonb or p_request->'event_kind'is distinct from 'null'::jsonb then
    raise exception 'review_stream_invalid'using errcode='23514';end if;
  elsif capability_value in('read','review')then
   perform public.controlled_stock_uuid(p_request->'site_id');
   if jsonb_typeof(p_request->'event_kind')is distinct from 'string'or p_request->>'event_kind'not in(
    'receive_inventory','adjust_inventory','record_patient_treatment','record_anesthesia_drug_administration',
    'record_native_dispense','record_native_pickup','record_native_dispense_return:intake','record_native_dispense_return:dispose','record_native_dispense_return:restock',
    'record_native_dispense_return_v2:intake','record_native_dispense_return_v2:dispose','record_native_dispense_return_v2:restock',
    'record_native_dispense_return_v2:retract_intake','record_native_dispense_return_v2:retract_disposal','record_native_dispense_return_v2:retract_restock',
    'record_native_return_discrepancy:report','record_native_return_discrepancy:note','record_native_return_discrepancy:resolve_corrected','record_native_return_discrepancy:resolve_confirmed_original',
    'append_native_dispense_correction:clinical_annotation','append_native_dispense_correction:operational_annotation','append_native_dispense_correction:pickup_amendment')then
    raise exception 'review_stream_invalid'using errcode='23514';end if;
  else raise exception 'review_stream_invalid'using errcode='23514';end if;
 else raise exception 'review_stream_invalid'using errcode='23514';end if;
 return p_request;
exception when check_violation then
 raise exception 'review_stream_invalid'using errcode='23514';
end

controlled_review_v3.protocol_terminal_l.source:
declare family_value jsonb;product_value uuid;
begin
 if TG_OP<>'INSERT'or TG_TABLE_SCHEMA<>'controlled_review_v3'then raise exception 'review_insert_invalid'using errcode='23514';end if;
 -- These are the alreadyheld dependencies of the mutation tail. This observer
 -- adds no new lock resource, row lock, write, DDL or current permission.
 -- Frozen collectors may reenter the alreadyheld shared practice barrier.
 perform controlled_review_v3.required();
 if TG_TABLE_NAME in('operation_claims','preparations','decisions','cancellations')then
  perform controlled_review_v3.protocol_validate_operation(NEW.operation_id);
 elsif TG_TABLE_NAME='escalations'then
  if NEW.reason='overdue'then
   perform controlled_review_v3.ops_validate_overdue(to_jsonb(NEW));
   if NEW.evidence->'terminal_operation_id'<>'null'::jsonb then perform controlled_review_v3.protocol_validate_operation((NEW.evidence->>'terminal_operation_id')::uuid);end if;
  elsif NEW.reason='rejected'then
   perform controlled_review_v3.protocol_validate_rejection(to_jsonb(NEW));
   perform controlled_review_v3.protocol_validate_operation((NEW.evidence->>'decision_operation_id')::uuid);
  else perform controlled_review_v3.ops_validate_worker_source(to_jsonb(NEW));end if;
 elsif TG_TABLE_NAME='obligations'then
  perform controlled_review_v3.ops_validate_mutation_obligation(NEW.event_id);
  perform controlled_review_v3.protocol_utc(NEW.materialized_at);
 elsif TG_TABLE_NAME='families'then
     family_value:=controlled_review_v3.protocol_family_dto(NEW.dispense_id);
  if family_value is null or family_value is distinct from controlled_review_v3.protocol_family_preview(NEW.dispense_id,NEW.product_id)
   or not exists(select 1 from controlled_review_v3.obligations where family_dispense_id=NEW.dispense_id)then
   raise exception 'review_history_integrity'using errcode='23514';end if;
  perform controlled_review_v3.protocol_utc(NEW.materialized_at);
 else raise exception 'review_lifecycle_table_not_implemented'using errcode='0A000';end if;
 return null;
end

controlled_review_v3.protocol_terminal_p.source:
begin
 if TG_OP<>'INSERT'or TG_TABLE_SCHEMA<>'controlled_review_v3'or TG_TABLE_NAME not in('configuration','publications')then raise exception 'review_insert_invalid'using errcode='23514';end if;
 perform controlled_review_v3.required();
 if exists(select 1 from controlled_review_v3.configuration where id=case when TG_TABLE_NAME='configuration'then(to_jsonb(NEW)->>'id')::uuid else(to_jsonb(NEW)->>'record_id')::uuid end and publication_mode='staff_administration')then
  perform controlled_stock_workflow_v1.review_saved_publication_required(case when TG_TABLE_NAME='configuration'then(to_jsonb(NEW)->>'id')::uuid else(to_jsonb(NEW)->>'record_id')::uuid end);
 end if;
 if TG_TABLE_NAME='configuration'then perform controlled_review_v3.protocol_validate_publication_record(NEW.id);
 else perform controlled_review_v3.protocol_validate_publication_record(NEW.record_id);end if;
 return null;
end

controlled_review_v3.protocol_transport_.source:
declare request_value jsonb:=controlled_review_v3.protocol_request(p_request);field_name text;field_bytes bytea;
 framed bytea:=convert_to(E'lrv-record-review-request-v3\n','UTF8');
begin
 foreach field_name in array array['actor_id','operation_id','event_id','policy_id','read_eligibility_id','review_eligibility_id','decision','reason']loop
  field_bytes:=convert_to(request_value->>field_name,'UTF8');
  framed:=framed||convert_to(octet_length(field_bytes)::text||':','UTF8')||field_bytes;
 end loop;
 return encode(sha256(framed),'hex');
end

controlled_review_v3.protocol_utc(p_valu.source:
begin
 if p_value is null or not isfinite(p_value)or p_value<timestamptz '2026-01-01 00:00:00Z'
  or p_value>=timestamptz '2101-01-01 00:00:00Z'then
  raise exception 'review_timestamp_invalid'using errcode='23514';end if;
 return to_char(p_value at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"');
end

controlled_review_v3.protocol_validate_o.source:
declare expected_value jsonb;actual_value jsonb;family_value jsonb;maintenance_value controlled_review_v3.materializations;
begin
 select *into maintenance_value from controlled_review_v3.materializations where event_id=p_event_id and product_id=(select product_id from controlled_review_v3.obligations where event_id=p_event_id)order by operation_id limit 1;
 if found then perform controlled_review_v3.ops_validate_materialization(to_jsonb(maintenance_value));return;end if;
 expected_value:=controlled_review_v3.protocol_obligation_preview(p_event_id);actual_value:=controlled_review_v3.protocol_obligation_dto(p_event_id);
 if expected_value is null or actual_value is distinct from expected_value then raise exception 'review_history_integrity'using errcode='23514';end if;
 if actual_value->>'family_dispense_id'is not null then
  family_value:=controlled_review_v3.protocol_family_dto((actual_value->>'family_dispense_id')::uuid);
  if family_value is null or family_value is distinct from controlled_review_v3.protocol_family_preview((actual_value->>'family_dispense_id')::uuid,(actual_value->>'product_id')::uuid)then
   raise exception 'review_history_integrity'using errcode='23514';end if;
 end if;
 -- This limited lifecycle candidate has no general worker materialization route.
 -- It refuses an orphan obligation rather than claim full maintenance support.
 if not exists(select 1 from controlled_review_v3.preparations where event_id=p_event_id)then
  raise exception 'review_lifecycle_obligation_unpaired'using errcode='23514';end if;
end

declare claim_value controlled_review_v3.operation_claims;preparation_value controlled_review_v3.preparations;
decision_value controlled_review_v3.decisions;cancellation_value controlled_review_v3.cancellations;
preparation_exists boolean;decision_exists boolean;cancellation_exists boolean;receipt_value jsonb;rejection_value controlled_review_v3.escalations;overdue_value controlled_review_v3.escalations;
begin
 select *into strict claim_value from controlled_review_v3.operation_claims where operation_id=p_operation_id;
 perform public.controlled_stock_uuid(to_jsonb(claim_value.operation_id));perform public.controlled_stock_uuid(to_jsonb(claim_value.actor_id));
 perform controlled_review_v3.protocol_utc(claim_value.claimed_at);
 select *into preparation_value from controlled_review_v3.preparations where operation_id=p_operation_id;preparation_exists:=found;
 select *into decision_value from controlled_review_v3.decisions where operation_id=p_operation_id;decision_exists:=found;
 select *into cancellation_value from controlled_review_v3.cancellations where operation_id=p_operation_id;cancellation_exists:=found;
 if not preparation_exists and not cancellation_exists or decision_exists and cancellation_exists
  or decision_exists and not preparation_exists then raise exception 'review_history_integrity'using errcode='23514';end if;
 if preparation_exists then
  if preparation_value.actor_id<>claim_value.actor_id or preparation_value.created_at<claim_value.claimed_at then
   raise exception 'review_history_integrity'using errcode='23514';end if;
  perform controlled_review_v3.read_clinical_dependencies_required();
  perform controlled_review_v3.read_validate_retained_packet(to_jsonb(preparation_value),controlled_review_v3.read_scalar_base(controlled_review_v3.collect_event_sources(preparation_value.event_id)));
 end if;
 if decision_exists then
  receipt_value:=controlled_review_v3.protocol_receipt_from_rows(to_jsonb(preparation_value),to_jsonb(decision_value));
  if receipt_value is distinct from decision_value.receipt then raise exception 'review_history_integrity'using errcode='23514';end if;
  if receipt_value->>'deadline_state'='completed_late'then
   select *into strict overdue_value from controlled_review_v3.escalations where event_id=decision_value.event_id and reason='overdue';
   perform controlled_review_v3.ops_validate_overdue(to_jsonb(overdue_value));end if;
  if decision_value.decision='reject'then
   select *into strict rejection_value from controlled_review_v3.escalations where event_id=decision_value.event_id and reason='rejected';
   if rejection_value.evidence->>'decision_operation_id'is distinct from decision_value.operation_id::text then raise exception 'review_rejection_history_invalid'using errcode='23514';end if;
   perform controlled_review_v3.protocol_validate_rejection(to_jsonb(rejection_value));
  elsif exists(select 1 from controlled_review_v3.escalations where event_id=decision_value.event_id and reason='rejected')then
   raise exception 'review_rejection_history_invalid'using errcode='23514';end if;
 end if;
 if cancellation_exists then
  perform controlled_review_v3.protocol_cancellation_data(to_jsonb(claim_value),case when preparation_exists then to_jsonb(preparation_value)else 'null'::jsonb end,to_jsonb(cancellation_value));
 end if;
end

controlled_review_v3.protocol_validate_p.source:
declare configuration_value jsonb:=controlled_review_v3.protocol_configuration_dto(p_record_id);publication_value jsonb;pair_value jsonb;
begin
 if configuration_value is null then raise exception 'review_history_integrity'using errcode='23514';end if;
 publication_value:=controlled_review_v3.protocol_publication_dto((configuration_value->>'publication_operation_id')::uuid);
 if publication_value is null then raise exception 'review_history_integrity'using errcode='23514';end if;
 pair_value:=controlled_review_v3.validate_configuration_pair(jsonb_build_object('configuration',configuration_value,'publication',publication_value));
 return controlled_review_v3.configuration_record(pair_value->'configuration');
end

controlled_review_v3.protocol_validate_r.source:
declare row_value jsonb:=controlled_review_v3.protocol_rejection_record(p_row);decision_value controlled_review_v3.decisions;
 preparation_value controlled_review_v3.preparations;obligation_value controlled_review_v3.obligations;expected_ids jsonb;
begin
 select *into strict decision_value from controlled_review_v3.decisions where operation_id=(row_value#>>'{evidence,decision_operation_id}')::uuid;
 select *into strict preparation_value from controlled_review_v3.preparations where operation_id=decision_value.operation_id;
 select *into strict obligation_value from controlled_review_v3.obligations where event_id=decision_value.event_id;
 expected_ids:=controlled_review_v3.protocol_escalation_ids(decision_value.operation_id,decision_value.event_id);
 if row_value->>'id'is distinct from expected_ids->>'rejected'or row_value->>'event_id'is distinct from decision_value.event_id::text
  or(row_value->>'first_detected_at')::timestamptz is distinct from decision_value.recorded_at
  or row_value->'evidence'is distinct from controlled_review_v3.protocol_rejection_evidence(to_jsonb(preparation_value),to_jsonb(decision_value))then raise exception 'review_rejection_history_invalid'using errcode='23514';end if;
 perform controlled_review_v3.protocol_validate_retained_packet(to_jsonb(preparation_value));
 if preparation_value.packet->'obligation'is distinct from controlled_review_v3.protocol_obligation_dto(obligation_value.event_id)then raise exception 'review_rejection_history_invalid'using errcode='23514';end if;
 perform controlled_review_v3.protocol_validate_rejection_routing(row_value->'routing_snapshot',obligation_value.historical->'routing_snapshot',decision_value.recorded_at);
end

declare assessment jsonb;facts jsonb;fact jsonb;members jsonb;member jsonb;configured jsonb;live_value jsonb;role_value jsonb;
 prior_actor text;prior_role text;index_value integer:=0;eligible boolean:=false;status_value text;stamp timestamptz;
begin
 if jsonb_typeof(p_snapshot)is distinct from 'object'or octet_length(p_snapshot::text)>65536 then raise exception 'review_rejection_routing_invalid'using errcode='23514';end if;
 perform public.controlled_stock_keys(p_snapshot,array['version','historical','assessment']);
 if p_snapshot->'version'is distinct from '1'::jsonb or p_snapshot->'historical'is distinct from coalesce(p_historical,'null'::jsonb)then raise exception 'review_rejection_routing_invalid'using errcode='23514';end if;
 assessment:=p_snapshot->'assessment';perform public.controlled_stock_keys(assessment,array['version','recorded_at','status','member_facts']);
 if assessment->'version'is distinct from '1'::jsonb or jsonb_typeof(assessment->'status')is distinct from 'string'then raise exception 'review_rejection_routing_invalid'using errcode='23514';end if;
 stamp:=controlled_review_v3.protocol_instant(assessment->'recorded_at');perform controlled_review_v3.protocol_utc(p_first_detected_at);
 if stamp<p_first_detected_at then raise exception 'review_rejection_routing_invalid'using errcode='23514';end if;
 facts:=assessment->'member_facts';
 if jsonb_typeof(facts)is distinct from 'array'or jsonb_array_length(facts)>100 then raise exception 'review_rejection_routing_invalid'using errcode='23514';end if;
 if p_historical is null or p_historical='null'::jsonb then
  if facts<>'[]'::jsonb or assessment->>'status'<>'missing_route'then raise exception 'review_rejection_routing_invalid'using errcode='23514';end if;
  return p_snapshot;
 end if;
 perform public.controlled_stock_keys(p_historical,array['version','id','record_hash','enabled','members']);
 perform public.controlled_stock_uuid(p_historical->'id');
 if p_historical->'version'is distinct from '1'::jsonb or jsonb_typeof(p_historical->'record_hash')is distinct from 'string'
  or(p_historical->>'record_hash')!~'^[0-9a-f]{64}$'or jsonb_typeof(p_historical->'enabled')is distinct from 'boolean'then raise exception 'review_rejection_routing_invalid'using errcode='23514';end if;
 members:=p_historical->'members';
 if jsonb_typeof(members)is distinct from 'array'or jsonb_array_length(members)>100 or jsonb_array_length(members)<>jsonb_array_length(facts)
  or(p_historical->'enabled'='true'::jsonb and jsonb_array_length(members)=0)then raise exception 'review_rejection_routing_invalid'using errcode='23514';end if;
 for fact in select value from jsonb_array_elements(facts)loop
  member:=members->index_value;index_value:=index_value+1;
  perform public.controlled_stock_keys(member,array['actor_id','roles']);perform public.controlled_stock_uuid(member->'actor_id');
  perform public.controlled_stock_keys(fact,array['actor_id','configured_roles','profile_active','live_roles']);
  if fact->'actor_id'is distinct from member->'actor_id'or fact->'configured_roles'is distinct from member->'roles'
   or jsonb_typeof(fact->'profile_active')is distinct from 'boolean'
   or(prior_actor is not null and (member->>'actor_id')collate "C"<=prior_actor collate "C")then raise exception 'review_rejection_routing_invalid'using errcode='23514';end if;
  prior_actor:=member->>'actor_id';configured:=fact->'configured_roles';live_value:=fact->'live_roles';
  if jsonb_typeof(configured)is distinct from 'array'or jsonb_array_length(configured)not between 1 and 4
   or jsonb_typeof(live_value)is distinct from 'array'or jsonb_array_length(live_value)>4 then raise exception 'review_rejection_routing_invalid'using errcode='23514';end if;
  prior_role:=null;
  for role_value in select value from jsonb_array_elements(configured)loop
   if jsonb_typeof(role_value)is distinct from 'string'or role_value#>>'{}'not in('ADMIN','DVM','STAFF','TECH')
    or(prior_role is not null and(role_value#>>'{}')collate "C"<=prior_role collate "C")then raise exception 'review_rejection_routing_invalid'using errcode='23514';end if;
   prior_role:=role_value#>>'{}';
  end loop;
  prior_role:=null;
  for role_value in select value from jsonb_array_elements(live_value)loop
   if jsonb_typeof(role_value)is distinct from 'string'or role_value#>>'{}'not in('ADMIN','DVM','STAFF','TECH')
    or(prior_role is not null and(role_value#>>'{}')collate "C"<=prior_role collate "C")then raise exception 'review_rejection_routing_invalid'using errcode='23514';end if;
   prior_role:=role_value#>>'{}';
  end loop;
  if fact->'profile_active'='true'::jsonb and exists(select 1 from jsonb_array_elements(configured)c(value)join jsonb_array_elements(live_value)l(value)on c.value=l.value)then eligible:=true;end if;
 end loop;
 status_value:=case when p_historical->'enabled'='false'::jsonb then 'disabled_route'when eligible then 'eligible_recipients'else 'no_eligible_recipient'end;
 if assessment->>'status'is distinct from status_value then raise exception 'review_rejection_routing_invalid'using errcode='23514';end if;
 return p_snapshot;
end

declare row_value jsonb:=controlled_review_v3.protocol_retained_preparation(p_preparation);packet_value jsonb:=row_value->'packet';
base_value jsonb;policy_value jsonb;read_value jsonb;review_value jsonb;authorization_value jsonb;stream_value jsonb;at_value timestamptz;
actor_value uuid;product_value uuid;site_value uuid;kind_value text;member_value jsonb;
begin
 base_value:=controlled_review_v3.protocol_packet_base((row_value->>'event_id')::uuid);
 if packet_value-'current_authorization'is distinct from base_value then raise exception 'review_history_integrity'using errcode='23514';end if;
 actor_value:=(row_value->>'actor_id')::uuid;product_value:=(packet_value#>>'{target,product_id}')::uuid;
 site_value:=(packet_value#>>'{adapter,site_id}')::uuid;kind_value:=packet_value#>>'{adapter,event_kind}';at_value:=(row_value->>'created_at')::timestamptz;
 stream_value:=jsonb_build_object('kind','policy','product_id',product_value,'site_id',site_value,'event_kind',null,'capability',null);
 policy_value:=controlled_review_v3.protocol_select_configuration(jsonb_build_object('stream_key',stream_value,'at',controlled_review_v3.protocol_utc(at_value)));
 stream_value:=stream_value||jsonb_build_object('kind','eligibility','event_kind',kind_value,'capability','read');
 read_value:=controlled_review_v3.protocol_select_configuration(jsonb_build_object('stream_key',stream_value,'at',controlled_review_v3.protocol_utc(at_value)));
 stream_value:=stream_value||jsonb_build_object('capability','review');
 review_value:=controlled_review_v3.protocol_select_configuration(jsonb_build_object('stream_key',stream_value,'at',controlled_review_v3.protocol_utc(at_value)));
 if policy_value is null or read_value is null or review_value is null or policy_value->'id'is distinct from row_value->'policy_id'
  or read_value->'id'is distinct from row_value->'read_eligibility_id'or review_value->'id'is distinct from row_value->'review_eligibility_id'
  or policy_value->'enabled'is distinct from 'true'::jsonb or policy_value#>array['body','rules',kind_value,'enabled']is distinct from 'true'::jsonb then
  raise exception 'review_history_integrity'using errcode='23514';end if;
 authorization_value:=jsonb_build_object('policy',jsonb_build_object('id',policy_value->'id','record_hash',policy_value->'record_hash','rule',policy_value#>array['body','rules',kind_value]),
  'read',controlled_review_v3.protocol_retained_member(read_value,actor_value,product_value,site_value,kind_value,'read'),
  'review',controlled_review_v3.protocol_retained_member(review_value,actor_value,product_value,site_value,kind_value,'review'));
 if authorization_value is distinct from packet_value->'current_authorization'then raise exception 'review_history_integrity'using errcode='23514';end if;
end

controlled_review_v3.protocol_validate_w.source:
declare kind_value text;stream_value jsonb;from_value bigint;through_value bigint;high_value bigint;
begin
 if jsonb_typeof(p_request)is distinct from 'object'or octet_length(p_request::text)>131072 then
  raise exception 'review_request_invalid'using errcode='23514';end if;
 if p_kind='prepare_controlled_record_review_v3'then return controlled_review_v3.protocol_request(p_request);
 elsif p_kind in('read_controlled_record_review_v3','execute_controlled_record_review_v3','cancel_controlled_record_review_v3','read_controlled_review_publication_v3')then
  return controlled_review_v3.protocol_operation_request(p_request);
 elsif p_kind='get_controlled_record_review_event_v3'then
  perform public.controlled_stock_keys(p_request,array['actor_id','event_id']);
  perform public.controlled_stock_uuid(p_request->'event_id');
 elsif p_kind='list_controlled_record_reviews_v3'then
  perform public.controlled_stock_keys(p_request,array['actor_id','product_id','site_id','event_kind','view','page_size','cursor']);
  perform public.controlled_stock_uuid(p_request->'product_id');
  perform controlled_review_v3.protocol_page_size(p_request->'page_size');
  if p_request->'view'='"site"'::jsonb then
   stream_value:=jsonb_build_object('kind','eligibility','product_id',p_request->'product_id','site_id',p_request->'site_id','event_kind',p_request->'event_kind','capability','read');
  elsif p_request->'view'='"exceptions"'::jsonb then
   stream_value:=jsonb_build_object('kind','eligibility','product_id',p_request->'product_id','site_id',p_request->'site_id','event_kind',p_request->'event_kind','capability','exception_read');
  else raise exception 'review_request_invalid'using errcode='23514';end if;
  perform controlled_review_v3.protocol_stream_key(stream_value);
  if p_request->'cursor'is distinct from 'null'::jsonb then perform controlled_review_v3.protocol_cursor(p_request->'cursor',p_request);end if;
 elsif p_kind='publish_controlled_review_configuration_v3'then
  perform public.controlled_stock_keys(p_request,array['actor_id','operation_id','record_id','document']);
  perform public.controlled_stock_uuid(p_request->'operation_id');perform public.controlled_stock_uuid(p_request->'record_id');
  perform controlled_review_v3.validate_configuration(p_request->'document');
  if p_request#>'{document,kind}'='"administration"'::jsonb then raise exception 'review_request_invalid'using errcode='23514';end if;
 elsif p_kind='get_controlled_review_configuration_v3'then
  perform public.controlled_stock_keys(p_request,array['actor_id','product_id','kind','site_id','event_kind','capability','after_version','page_size']);
  stream_value:=p_request-array['actor_id','after_version','page_size'];
  perform controlled_review_v3.protocol_stream_key(stream_value);
  perform controlled_review_v3.protocol_page_size(p_request->'page_size');
  if jsonb_typeof(p_request->'after_version')is distinct from 'number'or(p_request->>'after_version')!~'^(0|[1-9][0-9]{0,9})$'
   or(p_request->>'after_version')::numeric>2147483647 then raise exception 'review_request_invalid'using errcode='23514';end if;
 elsif p_kind='record_controlled_review_escalation_action_v3'then
  perform public.controlled_stock_keys(p_request,array['actor_id','operation_id','escalation_id','kind','note']);
  perform public.controlled_stock_uuid(p_request->'operation_id');perform public.controlled_stock_uuid(p_request->'escalation_id');
  if jsonb_typeof(p_request->'kind')is distinct from 'string'or p_request->>'kind'not in('acknowledge','resolution_note')then
   raise exception 'review_request_invalid'using errcode='23514';end if;
  perform public.controlled_stock_text(p_request->'note',4000,true);
 elsif p_kind='get_controlled_review_backlog_v3'then
  perform public.controlled_stock_keys(p_request,array['actor_id','product_id','after_sequence','page_size']);
  perform public.controlled_stock_uuid(p_request->'product_id');perform controlled_review_v3.protocol_bigint_wire(p_request->'after_sequence');
  perform controlled_review_v3.protocol_page_size(p_request->'page_size');
 elsif p_kind='publish_administration'then
  perform public.controlled_stock_keys(p_request,array['operation_id','record_id','document','reason']);
  perform public.controlled_stock_uuid(p_request->'operation_id');perform public.controlled_stock_uuid(p_request->'record_id');
  perform controlled_review_v3.validate_configuration(p_request->'document');
  if p_request#>'{document,kind}'is distinct from '"administration"'::jsonb then raise exception 'review_request_invalid'using errcode='23514';end if;
  perform public.controlled_stock_text(p_request->'reason',4000,true);
  return p_request;
 elsif p_kind='materialize_one'then
  perform public.controlled_stock_keys(p_request,array['operation_id','product_id','event_id']);
  perform public.controlled_stock_uuid(p_request->'operation_id');perform public.controlled_stock_uuid(p_request->'product_id');
  perform public.controlled_stock_uuid(p_request->'event_id');return p_request;
 elsif p_kind='record_scan'then
  perform public.controlled_stock_keys(p_request,array['operation_id','product_id','from_sequence','through_sequence','high_water']);
  perform public.controlled_stock_uuid(p_request->'operation_id');perform public.controlled_stock_uuid(p_request->'product_id');
  from_value:=controlled_review_v3.protocol_bigint_wire(p_request->'from_sequence');
  through_value:=controlled_review_v3.protocol_bigint_wire(p_request->'through_sequence');
  high_value:=controlled_review_v3.protocol_bigint_wire(p_request->'high_water');
  if from_value>through_value or through_value>high_value then raise exception 'review_request_invalid'using errcode='23514';end if;
  return p_request;
 else raise exception 'review_protocol_not_implemented'using errcode='0A000';end if;
 perform public.controlled_stock_uuid(p_request->'actor_id');
 return p_request;
end

controlled_review_v3.read_adapter_add(p_.source:
declare
 state jsonb:=p_state; identity text; prior jsonb; item jsonb; rank integer; old_rank integer;
 roles text[]:=array['reviewed_target','correction_target','case_report','ordinary_source','original_intake','original_pickup','amendment_predecessor','original_dispense','resolution_correction','opening_basis','retained_context'];
 expected_key jsonb; count_rows integer;
begin
 if jsonb_typeof(state) is distinct from 'object' or jsonb_typeof(state->'rows') is distinct from 'object'
 or jsonb_typeof(p_key) is distinct from 'object' or jsonb_typeof(p_row) is distinct from 'object'
 or p_relation is null or p_role is null or not(p_role=any(roles)) then
  raise exception 'adapter_source_integrity' using errcode='23514';
 end if;
 if octet_length(state::text)>1048576 or octet_length(p_row::text)>1048576 then
  raise exception 'evidence_limit_exceeded' using errcode='54000';
 end if;
 expected_key:=case p_relation
 when 'public.stock_movement_sources' then jsonb_build_object('movement_id',p_row->'movement_id')
 when 'public.stock_custody_sources' then jsonb_build_object('event_id',p_row->'event_id')
 when 'public.stock_pickup_sources' then jsonb_build_object('event_id',p_row->'event_id')
 when 'public.stock_discrepancy_sources' then jsonb_build_object('event_id',p_row->'event_id')
 when 'public.stock_correction_sources' then jsonb_build_object('event_id',p_row->'event_id')
 when 'public.controlled_stock_opening_movements' then jsonb_build_object('opening_id',p_row->'opening_id','movement_id',p_row->'movement_id')
 else jsonb_build_object('id',p_row->'id') end;
 if p_key is distinct from expected_key or exists(select 1 from jsonb_each(p_key) x where jsonb_typeof(x.value)<>'string')
 or p_relation<>all(array[
 'public.controlled_stock_events','public.controlled_stock_actions','public.controlled_stock_preparations',
 'public.controlled_stock_policy_versions','public.controlled_stock_openings','public.controlled_stock_source_links',
 'public.controlled_stock_event_lines','public.controlled_stock_container_transitions','public.controlled_stock_cells',
 'public.controlled_stock_containers','public.inventory_movements','public.stock_movement_sources','public.inventory_lots',
 'public.patient_treatments','public.billing_invoice_items','public.treatment_alert_reviews','public.anesthesia_drug_administrations',
 'public.native_dispenses','public.native_fulfillment_operations','public.native_dispense_allocations','public.native_pickups',
 'public.stock_pickup_sources','public.native_return_events','public.native_return_operations','public.stock_custody_sources',
 'public.native_return_stock_links','public.native_return_compensation_links','public.native_return_discrepancy_events',
 'public.native_return_discrepancy_operations','public.stock_discrepancy_sources','public.native_return_discrepancy_correction_links',
 'public.native_dispense_correction_events','public.native_dispense_correction_operations','public.stock_correction_sources',
 'public.controlled_stock_opening_movements']) then
  raise exception 'adapter_source_integrity' using errcode='23514';
 end if;
 identity:=jsonb_build_array(p_relation,p_key)::text;
 prior:=state->'rows'->identity;
 rank:=array_position(roles,p_role);
 item:=jsonb_build_object('relation',p_relation,'key',p_key,'row',p_row,'row_hash',public.controlled_stock_hash(p_row),'role',p_role);
 if prior is not null then
  if prior->'row' is distinct from p_row or prior->>'row_hash' is distinct from item->>'row_hash' then
   raise exception 'adapter_source_role_conflict' using errcode='23514';
  end if;
  old_rank:=array_position(roles,prior->>'role');
  if old_rank is null then raise exception 'adapter_source_role_conflict' using errcode='23514';end if;
  if old_rank<=rank then return state;end if;
 else
  select count(*) into count_rows from jsonb_object_keys(state->'rows');
  if count_rows>=512 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
  if p_relation=any(array['public.native_dispenses','public.native_pickups','public.native_return_events',
   'public.native_return_discrepancy_events','public.native_dispense_correction_events']) then
   if jsonb_array_length(state->'documents')>=100 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
   state:=jsonb_set(state,'{documents}',(state->'documents')||jsonb_build_array(identity));
  end if;
  if p_relation='public.native_dispense_allocations' then
   if jsonb_array_length(state->'allocations')>=100 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
   state:=jsonb_set(state,'{allocations}',(state->'allocations')||jsonb_build_array(p_row->'id'));
  end if;
 end if;
 state:=jsonb_set(state,array['rows',identity],item);
 if octet_length(state::text)>1048576 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
 return state;
end

controlled_review_v3.read_adapter_annota.source:
declare state jsonb:=p_state; e public.controlled_stock_events; target jsonb; source jsonb;
 row_value jsonb; operation jsonb; provenance jsonb; managed jsonb; did uuid; selected_id uuid; role_name text;
 selected_ids uuid[]; predecessor uuid; original_source uuid; selected_case_id uuid; selected_correction_id uuid;
 correction public.native_return_events; link public.native_return_discrepancy_correction_links;
 n integer:=0; count_links integer; last_id text:='';
begin
 select * into e from public.controlled_stock_events where id=p_event_id;
 if e.id is null then raise exception 'adapter_parent_integrity' using errcode='23514';end if;
 if e.writer='append_native_dispense_correction' then
  select to_jsonb(r) into target from public.native_dispense_correction_events r where r.id=e.id;
  if target is null then raise exception 'adapter_source_integrity' using errcode='23514';end if;
  did:=(target->>'dispense_id')::uuid;
  predecessor:=(target#>>'{document,amends_event_id}')::uuid;
  selected_ids:=array[e.id];
  if predecessor is not null then
   select to_jsonb(r) into source from public.native_dispense_correction_events r where r.id=predecessor;
   if source is null or predecessor=e.id or source->>'dispense_id' is distinct from did::text
   or source->>'kind' is distinct from target->>'kind' or(source->>'sequence')::integer>=(target->>'sequence')::integer then
    raise exception 'adapter_source_integrity' using errcode='23514';end if;
   selected_ids:=selected_ids||predecessor;
  end if;
  foreach selected_id in array selected_ids loop
   role_name:=case when selected_id=e.id then 'reviewed_target' else 'amendment_predecessor' end;
   select to_jsonb(r) into row_value from public.native_dispense_correction_events r where r.id=selected_id;
   select to_jsonb(r) into operation from public.native_dispense_correction_operations r where r.id=selected_id;
   select to_jsonb(r) into provenance from public.stock_correction_sources r where r.event_id=selected_id;
   managed:=controlled_review_v3.read_correction_source_event(selected_id,e.product_id);
   if operation is null or operation->>'actor_id' is distinct from row_value->>'actor_id'
   or operation->'result' is distinct from row_value->'document'
   or row_value->>'record_hash' is distinct from public.native_fulfillment_hash((row_value->'document')-'record_hash')
   or(provenance is null and managed is not null)
   or(provenance is not null and provenance->>'actor_id' is distinct from row_value->>'actor_id') then
    raise exception 'adapter_source_integrity' using errcode='23514';end if;
   -- Membership is validated above; these context-only roles declare no parent/physical edge.
   state:=controlled_review_v3.read_adapter_add(state,'public.native_dispense_correction_events',jsonb_build_object('id',selected_id),row_value,role_name);
   state:=controlled_review_v3.read_adapter_add(state,'public.native_dispense_correction_operations',jsonb_build_object('id',selected_id),operation,role_name);
   if provenance is not null then state:=controlled_review_v3.read_adapter_add(state,'public.stock_correction_sources',jsonb_build_object('event_id',selected_id),provenance,role_name);end if;
  end loop;
  state:=controlled_review_v3.read_adapter_dispense(state,did,e.product_id,'original_dispense',1);
  if target->>'kind'='pickup_amendment' then
   selected_id:=(target#>>'{document,pickup_amendment,original_pickup_id}')::uuid;
   if selected_id is null or not exists(select 1 from public.native_pickups where id=selected_id and dispense_id=did) then
    raise exception 'adapter_source_integrity' using errcode='23514';end if;
   state:=controlled_review_v3.read_adapter_pickup(state,selected_id,e.product_id,'original_pickup',1);
  end if;
 else raise exception 'unsupported_event_kind'using errcode='22023';end if;
 return state;
end

controlled_review_v3.read_adapter_clinic.source:
declare state jsonb:=p_state; e public.controlled_stock_events; p public.controlled_stock_preparations;
 m public.inventory_movements; t public.patient_treatments; i public.billing_invoice_items;
 a public.treatment_alert_reviews; link public.anesthesia_drug_administrations; n integer;
begin
 select * into e from public.controlled_stock_events where id=p_event_id;
 select * into p from public.controlled_stock_preparations where id=p_event_id;
 if e.id is null or e.writer<>all(array['receive_inventory','adjust_inventory','record_patient_treatment','record_anesthesia_drug_administration']) then
  raise exception 'unsupported_event_kind' using errcode='22023';end if;
 select count(*) into n from(select movement_id from public.stock_movement_sources where writer=e.writer and source_id=e.id limit 2)q;
 if n<>1 or not exists(select 1 from public.stock_movement_sources where writer=e.writer and source_id=e.id and movement_id=e.id) then
  raise exception 'adapter_source_integrity' using errcode='23514';end if;
 state:=controlled_review_v3.read_adapter_movement(state,e.id,e.writer,e.id,e.actor_id,'reviewed_target',true);
 select * into m from public.inventory_movements where id=e.id;
 if e.writer='receive_inventory' then
  if m.kind<>'receive' or m.quantity<=0 then raise exception 'adapter_source_integrity' using errcode='23514';end if;
 elsif e.writer='adjust_inventory' then
  if m.kind<>'adjust' then raise exception 'adapter_source_integrity' using errcode='23514';end if;
 else
  select * into t from public.patient_treatments where id=e.id;
  select * into i from public.billing_invoice_items where id=e.id;
  select * into a from public.treatment_alert_reviews where treatment_id=e.id;
  if t.id is null or i.id is null or a.id is null or t.historical or t.product_id<>e.product_id or t.lot_id<>m.lot_id
  or t.created_by<>e.actor_id or i.created_by<>e.actor_id or a.reviewed_by<>e.actor_id
  or t.invoice_id<>i.invoice_id or t.pet_id is distinct from i.pet_id or t.pet_id<>a.pet_id or i.product_id<>e.product_id
  or m.quantity<>-t.quantity or i.quantity<>t.quantity or m.kind<>'dispense'
  or t.administered_at is distinct from e.observed_at
  or t.administered_at is distinct from(p.canonical_arguments#>>'{request,administered_at}')::timestamptz
  or a.source_hash is distinct from public.controlled_stock_hash(a.snapshot)
  or a.source_hash is distinct from t.request#>>'{alert_review,source_hash}' then
   raise exception 'adapter_source_integrity' using errcode='23514';end if;
  state:=controlled_review_v3.read_adapter_add(state,'public.patient_treatments',jsonb_build_object('id',t.id),to_jsonb(t),'reviewed_target');
  state:=controlled_review_v3.read_adapter_add(state,'public.billing_invoice_items',jsonb_build_object('id',i.id),to_jsonb(i),'reviewed_target');
  state:=controlled_review_v3.read_adapter_add(state,'public.treatment_alert_reviews',jsonb_build_object('id',a.id),to_jsonb(a),'reviewed_target');
  if e.writer='record_anesthesia_drug_administration' then
   select * into link from public.anesthesia_drug_administrations where id=e.id;
   if link.id is null or link.created_by<>e.actor_id or link.pet_id<>t.pet_id
   or link.record_id::text is distinct from p.canonical_arguments->>'record_id'
   or link.pet_id::text is distinct from p.canonical_arguments->>'pet_id'
   or link.request is distinct from((p.canonical_arguments->'request')||jsonb_build_object('pet_id',link.pet_id,'source','Anesthesia record '||link.record_id::text))
   or link.request is distinct from t.request then
    raise exception 'adapter_source_integrity' using errcode='23514';end if;
   state:=controlled_review_v3.read_adapter_add(state,'public.anesthesia_drug_administrations',jsonb_build_object('id',link.id),to_jsonb(link),'reviewed_target');
  end if;
 end if;
 return state;
end

controlled_review_v3.read_adapter_discre.source:
declare state jsonb:=p_state; e public.controlled_stock_events; target jsonb; source jsonb;
 row_value jsonb; operation jsonb; provenance jsonb; managed jsonb; did uuid; selected_id uuid; role_name text;
 selected_ids uuid[]; predecessor uuid; original_source uuid; selected_case_id uuid; selected_correction_id uuid;
 correction public.native_return_events; link public.native_return_discrepancy_correction_links;
 n integer:=0; count_links integer; last_id text:='';
begin
 select *into e from public.controlled_stock_events where id=p_event_id;
 if e.id is null or e.writer is distinct from'record_native_return_discrepancy'then raise exception 'adapter_parent_integrity'using errcode='23514';end if;
  select to_jsonb(r) into target from public.native_return_discrepancy_events r where r.id=e.id;
  if target is null then raise exception 'adapter_source_integrity' using errcode='23514';end if;
  did:=(target->>'dispense_id')::uuid;selected_case_id:=(target->>'case_id')::uuid;
  original_source:=(target#>>'{document,source,event_id}')::uuid;
  select to_jsonb(r) into source from public.native_return_events r where r.id=original_source;
  if source is null or source->>'dispense_id' is distinct from did::text
  or source->>'record_hash' is distinct from target#>>'{document,source,record_hash}'
  or source->>'action'<>all(array['intake','dispose','restock']) then
   raise exception 'adapter_source_integrity' using errcode='23514';end if;
  selected_ids:=array[e.id];if selected_case_id<>e.id then selected_ids:=selected_ids||selected_case_id;end if;
  foreach selected_id in array selected_ids loop
   role_name:=case when selected_id=e.id then 'reviewed_target' else 'case_report' end;
   select to_jsonb(r) into row_value from public.native_return_discrepancy_events r where r.id=selected_id;
   select to_jsonb(r) into operation from public.native_return_discrepancy_operations r where r.id=selected_id;
   select to_jsonb(r) into provenance from public.stock_discrepancy_sources r where r.event_id=selected_id;
   if row_value is null or operation is null or row_value->>'dispense_id' is distinct from did::text
   or operation->>'actor_id' is distinct from row_value->>'actor_id' or operation->'result' is distinct from row_value->'document'
   or row_value->>'record_hash' is distinct from public.native_fulfillment_hash((row_value->'document')-'record_hash')
   or row_value#>'{document,source}' is distinct from target#>'{document,source}'
   or row_value#>'{document,allocations}' is distinct from target#>'{document,allocations}'
   or(selected_id<>e.id and(row_value->>'action'<>'report' or(row_value->>'sequence')::integer>=(target->>'sequence')::integer)) then
    raise exception 'adapter_source_integrity' using errcode='23514';end if;
   managed:=controlled_review_v3.read_discrepancy_source_event(selected_id,e.product_id);
   if(provenance is null and managed is not null) or(provenance is not null and provenance->>'actor_id' is distinct from row_value->>'actor_id') then
    raise exception 'adapter_source_integrity' using errcode='23514';end if;
   -- Membership is validated above; these context-only roles declare no parent/physical edge.
   state:=controlled_review_v3.read_adapter_add(state,'public.native_return_discrepancy_events',jsonb_build_object('id',selected_id),row_value,role_name);
   state:=controlled_review_v3.read_adapter_add(state,'public.native_return_discrepancy_operations',jsonb_build_object('id',selected_id),operation,role_name);
   if provenance is not null then state:=controlled_review_v3.read_adapter_add(state,'public.stock_discrepancy_sources',jsonb_build_object('event_id',selected_id),provenance,role_name);end if;
  end loop;
  state:=controlled_review_v3.read_adapter_return_v1(state,original_source,e.product_id,'ordinary_source',1);
  if jsonb_typeof(target#>'{document,correction_ids}') is distinct from 'array' then
   raise exception 'adapter_source_integrity' using errcode='23514';end if;
  if jsonb_array_length(target#>'{document,correction_ids}')>100 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
  if target->>'action'='resolve_corrected' then
   if jsonb_array_length(target#>'{document,correction_ids}')=0 then raise exception 'adapter_source_integrity' using errcode='23514';end if;
   for row_value in select value from jsonb_array_elements(target#>'{document,correction_ids}') loop
    if jsonb_typeof(row_value)<>'string' or row_value#>>'{}'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    or (row_value#>>'{}') collate "C"<=last_id collate "C" then raise exception 'adapter_source_integrity' using errcode='23514';end if;
    last_id:=row_value#>>'{}';selected_correction_id:=last_id::uuid;
    select * into correction from public.native_return_events where id=selected_correction_id;
    select * into link from public.native_return_discrepancy_correction_links l where l.correction_id=selected_correction_id;
    if correction.id is null or link.id is null or link.case_id<>selected_case_id or link.resolution_id<>e.id
    or correction.dispense_id<>did or correction.document->>'version'<>'2'
    or correction.action<>all(array['retract_intake','retract_disposal','retract_restock'])
    or correction.document#>'{correction_target}' is distinct from target#>'{document,source}'
    or correction.document->>'discrepancy_id' is distinct from selected_case_id::text then
     raise exception 'adapter_source_integrity' using errcode='23514';end if;
    n:=n+1;
    state:=controlled_review_v3.read_adapter_add(state,'public.native_return_discrepancy_correction_links',jsonb_build_object('id',link.id),to_jsonb(link),'reviewed_target');
    state:=controlled_review_v3.read_adapter_return_v1(state,correction.id,e.product_id,'resolution_correction',1);
   end loop;
  elsif target#>'{document,correction_ids}'<>'[]'::jsonb then raise exception 'adapter_source_integrity' using errcode='23514';end if;
  select count(*) into count_links from(select id from public.native_return_discrepancy_correction_links where resolution_id=e.id limit 101) q;
  if count_links>100 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
  if count_links<>n then raise exception 'adapter_source_integrity' using errcode='23514';end if;
 return state;
end

controlled_review_v3.read_adapter_dispen.source:
declare state jsonb:=p_state; d public.native_dispenses; op public.native_fulfillment_operations;
 item public.billing_invoice_items; a record; m public.inventory_movements; managed jsonb;
 n integer:=0; source_count integer; total numeric:=0; unit text;
begin
 if p_role is null or p_role<>all(array['reviewed_target','original_dispense']) then
  raise exception 'adapter_source_role_conflict' using errcode='23514';end if;
 if p_depth is null or p_depth<0 or p_depth>4 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
 select * into d from public.native_dispenses where id=p_dispense_id;
 select * into op from public.native_fulfillment_operations where id=p_dispense_id;
 select * into item from public.billing_invoice_items where id=d.invoice_item_id;
 select stock_unit into unit from public.controlled_stock_policy_versions where id=(select policy_version_id from public.controlled_stock_events where id=(state->>'target_event_id')::uuid);
 if d.id is null or op.id is null or item.id is null or op.operation<>'dispense' or op.actor_id<>d.actor_id
 or op.result->'dispense' is distinct from d.document or item.product_id<>p_product_id or item.quantity<>d.quantity
 or item.created_by<>d.actor_id or item.invoice_id<>d.invoice_id or item.pet_id is distinct from d.pet_id
 or d.document->>'unit' is distinct from unit or state->>'product_id' is distinct from p_product_id::text then
  raise exception 'adapter_source_integrity' using errcode='23514';end if;
 managed:=controlled_review_v3.read_native_source_event('dispense',d.id,p_product_id);
 if managed is not null then state:=controlled_review_v3.read_adapter_parent(state,(managed->>'event_id')::uuid,p_role);end if;
 state:=controlled_review_v3.read_adapter_add(state,'public.native_dispenses',jsonb_build_object('id',d.id),to_jsonb(d),p_role);
 state:=controlled_review_v3.read_adapter_add(state,'public.native_fulfillment_operations',jsonb_build_object('id',op.id),to_jsonb(op),p_role);
 state:=controlled_review_v3.read_adapter_add(state,'public.billing_invoice_items',jsonb_build_object('id',item.id),to_jsonb(item),p_role);
 for a in select * from public.native_dispense_allocations where dispense_id=d.id order by lot_id limit 101 loop
  n:=n+1;if n>100 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
  select * into m from public.inventory_movements where id=a.movement_id;
  if m.id is null or m.lot_id<>a.lot_id or m.quantity<>-a.quantity or m.kind<>'dispense' then
   raise exception 'adapter_source_integrity' using errcode='23514';end if;
  total:=total+a.quantity;
  state:=controlled_review_v3.read_adapter_add(state,'public.native_dispense_allocations',jsonb_build_object('id',a.id),to_jsonb(a),p_role);
  state:=controlled_review_v3.read_adapter_movement(state,a.movement_id,'record_native_dispense',d.id,d.actor_id,p_role,managed is not null);
 end loop;
 if n=0 or total<>d.quantity then raise exception 'adapter_source_integrity' using errcode='23514';end if;
 select count(*) into source_count from(select movement_id from public.stock_movement_sources where writer='record_native_dispense' and source_id=d.id limit 101) q;
 if source_count>100 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
 if source_count not in(0,n) or(managed is not null and source_count<>n)
 or exists(select 1 from public.stock_movement_sources s where writer='record_native_dispense' and source_id=d.id
  and not exists(select 1 from public.native_dispense_allocations allocation_row where allocation_row.dispense_id=d.id and allocation_row.movement_id=s.movement_id)) then
  raise exception 'adapter_source_integrity' using errcode='23514';end if;
 return state;
end

controlled_review_v3.read_adapter_moveme.source:
declare state jsonb:=p_state; m public.inventory_movements; l public.inventory_lots;
 s public.stock_movement_sources; boundary public.controlled_stock_opening_movements;
begin
 select * into m from public.inventory_movements where id=p_movement_id;
 select * into l from public.inventory_lots where id=m.lot_id;
 select * into s from public.stock_movement_sources where movement_id=m.id;
 if m.id is null or l.id is null or l.product_id::text is distinct from state->>'product_id'
 or m.created_by is distinct from p_actor_id or p_managed is null then
  raise exception 'adapter_source_integrity' using errcode='23514';end if;
 if s.movement_id is not null then
  if s.writer is distinct from p_source_writer or s.source_id is distinct from p_source_id or s.actor_id is distinct from p_actor_id then
   raise exception 'adapter_source_integrity' using errcode='23514';end if;
  perform controlled_review_v3.read_stock_source(m.id);
  state:=controlled_review_v3.read_adapter_add(state,'public.stock_movement_sources',jsonb_build_object('movement_id',s.movement_id),to_jsonb(s),p_role);
 elsif p_managed then raise exception 'adapter_source_integrity' using errcode='23514';end if;
 select * into boundary from public.controlled_stock_opening_movements where movement_id=m.id;
 if p_managed then
  if boundary.movement_id is not null or not exists(select 1 from public.controlled_stock_source_links where movement_id=m.id and event_id=p_source_id) then
   raise exception 'adapter_source_integrity' using errcode='23514';end if;
 else
  if boundary.movement_id is null or boundary.opening_id::text is distinct from state->>'opening_id'
  or boundary.source_snapshot is distinct from to_jsonb(m) or boundary.lot_id<>m.lot_id or boundary.quantity<>m.quantity
  or exists(select 1 from public.controlled_stock_source_links where movement_id=m.id) then
   raise exception 'adapter_source_integrity' using errcode='23514';end if;
  state:=controlled_review_v3.read_adapter_add(state,'public.controlled_stock_opening_movements',
   jsonb_build_object('opening_id',boundary.opening_id,'movement_id',boundary.movement_id),to_jsonb(boundary),'opening_basis');
 end if;
 state:=controlled_review_v3.read_adapter_add(state,'public.inventory_movements',jsonb_build_object('id',m.id),to_jsonb(m),p_role);
 state:=controlled_review_v3.read_adapter_add(state,'public.inventory_lots',jsonb_build_object('id',l.id),to_jsonb(l),p_role);
 return state;
end

controlled_review_v3.read_adapter_openin.source:
declare
 state jsonb:=p_state; target_event public.controlled_stock_events;
 target_correction public.native_dispense_correction_events; original_dispense public.native_dispenses;
 retained_opening public.controlled_stock_openings; selected_cell public.controlled_stock_cells;
 selected_container public.controlled_stock_containers; original_allocation record;
 entry jsonb; entry_candidate jsonb; projected jsonb; boundary_allocation jsonb;
 allocation_map jsonb:='{}'; prepared_sums jsonb:='{}'; retained_node jsonb;
 opening_container_map jsonb:='{}'; opening_container_ids jsonb;
 positive_sites jsonb:='{}'; zero_sites jsonb:='{}'; site_key text; retained_site uuid; selected_site uuid;
 opening_unit text; target_unit text; selected_pickup uuid;
 return_version integer; correction_version integer; discrepancy_version integer;
 entry_count integer:=0; allocation_count integer:=0; cell_count integer:=0;
 fully_prepared boolean:=true; reason text; expected_prepared numeric; actual_prepared numeric;
begin
 if p_dispense_id is null or p_product_id is null or jsonb_typeof(state) is distinct from 'object'
 or jsonb_typeof(state->'rows') is distinct from 'object' then
  raise exception 'adapter_source_integrity' using errcode='23514';end if;
 if octet_length(state::text)>1048576 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
 select * into target_event from public.controlled_stock_events
 where id=public.controlled_stock_uuid(state->'target_event_id');
 select * into target_correction from public.native_dispense_correction_events where id=target_event.id;
 select * into original_dispense from public.native_dispenses where id=p_dispense_id;
 if target_event.id is null or target_event.writer is distinct from 'append_native_dispense_correction'
 or target_event.event_kind<>all(array['append_native_dispense_correction:clinical_annotation','append_native_dispense_correction:operational_annotation'])
 or target_event.product_id is distinct from p_product_id or state->>'product_id' is distinct from p_product_id::text
 or target_event.opening_id::text is distinct from state->>'opening_id'
 or target_correction.id is null or original_dispense.id is null
 or target_correction.dispense_id is distinct from p_dispense_id
 or target_correction.kind is distinct from split_part(target_event.event_kind,':',2)
 or target_correction.authorization_id is distinct from original_dispense.authorization_id
 or target_correction.pet_id is distinct from original_dispense.pet_id
 or target_correction.actor_id is distinct from target_event.actor_id then
  raise exception 'adapter_source_integrity' using errcode='23514';end if;
 select * into retained_opening from public.controlled_stock_openings where id=target_event.opening_id;
 select stock_unit into opening_unit from public.controlled_stock_policy_versions
 where id=retained_opening.policy_version_id and product_id=p_product_id;
 select stock_unit into target_unit from public.controlled_stock_policy_versions
 where id=target_event.policy_version_id and product_id=p_product_id;
 if retained_opening.id is null or retained_opening.product_id is distinct from p_product_id
 or opening_unit is null or target_unit is distinct from opening_unit then
  raise exception 'adapter_source_integrity' using errcode='23514';end if;
 if octet_length(retained_opening.native_custody_boundary::text)>1048576
 or jsonb_array_length(retained_opening.native_custody_boundary)>200 then
  raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
 -- The immutable parent keeps all its reciprocal, prefix and later-link checks.
 -- H0 independently admitted the immutable opening globally; W preserves it.
 if controlled_review_v3.read_native_source_event('dispense',p_dispense_id,p_product_id) is not null then
  raise exception 'adapter_source_integrity' using errcode='23514';end if;
 -- This validates complete original allocations/provenance even for direct private
 -- helper calls; re-adding the existing rows obeys the unchanged role precedence.
 state:=controlled_review_v3.read_adapter_dispense(state,p_dispense_id,p_product_id,'original_dispense',1);
 for entry_candidate in select value from jsonb_array_elements(retained_opening.native_custody_boundary) loop
  if entry_candidate->>'dispense_id'=p_dispense_id::text then
   entry_count:=entry_count+1;entry:=entry_candidate;
  end if;
 end loop;
 if entry_count<>1 then raise exception 'adapter_source_integrity' using errcode='23514';end if;
 return_version:=public.controlled_stock_opening_selector(entry->'return_head');
 correction_version:=public.controlled_stock_opening_selector(entry->'correction_head');
 discrepancy_version:=public.controlled_stock_opening_selector(entry->'discrepancy_head');
 if entry->'pickup'<>'null'::jsonb then selected_pickup:=public.controlled_stock_uuid(entry#>'{pickup,id}');end if;
 -- Immutable prefix equality and complete later-source registration were
 -- established at H0/each canonical W append. This selected target still must
 -- be strictly later than the retained correction head and have its own exact
 -- managed parent/source link (read_correction_source_event).
 if target_correction.sequence<=correction_version then raise exception 'adapter_source_integrity'using errcode='23514';end if;
 if jsonb_array_length(entry->'allocations')>100 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
 fully_prepared:=return_version=0 and discrepancy_version=0 and selected_pickup is null
  and not exists(select 1 from public.native_dispense_correction_events prefix_correction
   where prefix_correction.dispense_id=p_dispense_id and prefix_correction.sequence<=correction_version
   and prefix_correction.kind<>all(array['clinical_annotation','operational_annotation']));
 for original_allocation in select * from public.native_dispense_allocations
 where dispense_id=p_dispense_id order by id limit 101 loop
  allocation_count:=allocation_count+1;
  if allocation_count>100 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
  select value into boundary_allocation from jsonb_array_elements(entry->'allocations')
   where value->>'allocation_id'=original_allocation.id::text;
  if boundary_allocation is null or boundary_allocation->>'lot_id' is distinct from original_allocation.lot_id::text
  or original_allocation.quantity<=0
  or (boundary_allocation->>'dispensed_quantity')::numeric is distinct from original_allocation.quantity then
   raise exception 'adapter_source_integrity' using errcode='23514';end if;
  expected_prepared:=(boundary_allocation->>'prepared_quantity')::numeric;
  if expected_prepared is null or expected_prepared<0 then raise exception 'adapter_source_integrity' using errcode='23514';end if;
  if expected_prepared<>original_allocation.quantity or boundary_allocation->'held'<>'[]'::jsonb then fully_prepared:=false;end if;
  allocation_map:=allocation_map||jsonb_build_object(original_allocation.id::text,boundary_allocation);
 end loop;
 if allocation_count=0 or allocation_count<>jsonb_array_length(entry->'allocations') then
  raise exception 'adapter_source_integrity' using errcode='23514';end if;
 -- Preserve assertion/managed cross-set agreement even when O is unsupported.
 for retained_node in select value from jsonb_each(state->'rows') loop
  if retained_node->>'relation'='public.controlled_stock_containers' then
   selected_site:=(retained_node#>>'{row,controlling_site_id}')::uuid;
   if selected_site is null or(retained_site is not null and retained_site<>selected_site) then
    raise exception 'adapter_source_integrity' using errcode='23514';end if;
   retained_site:=selected_site;
  end if;
 end loop;
 for selected_cell in select * from public.controlled_stock_cells
 where opening_id=retained_opening.id and dispense_id=p_dispense_id and channel='prepared'
 order by id limit 513 loop
  cell_count:=cell_count+1;if cell_count>512 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
  boundary_allocation:=allocation_map->selected_cell.allocation_id::text;
  select * into selected_container from public.controlled_stock_containers where id=selected_cell.container_id;
  if boundary_allocation is null or selected_cell.lot_id::text is distinct from boundary_allocation->>'lot_id'
  or selected_cell.intake_id is not null or selected_cell.created_event_id is not null or selected_cell.opening_quantity<0
  or selected_container.id is null or selected_container.opening_id is distinct from retained_opening.id
  or selected_container.product_id is distinct from p_product_id or selected_container.stock_unit is distinct from opening_unit
  or selected_container.kind is distinct from 'prepared' or selected_container.stock_lot_id is not null
  or selected_container.created_event_id is not null or selected_container.controlling_site_id is null then
   raise exception 'adapter_source_integrity' using errcode='23514';end if;
  selected_site:=selected_container.controlling_site_id;
  if retained_site is not null and selected_site<>retained_site then
   raise exception 'adapter_source_integrity' using errcode='23514';end if;
  state:=controlled_review_v3.read_adapter_add(state,'public.controlled_stock_cells',jsonb_build_object('id',selected_cell.id),to_jsonb(selected_cell),'opening_basis');
  state:=controlled_review_v3.read_adapter_add(state,'public.controlled_stock_containers',jsonb_build_object('id',selected_container.id),to_jsonb(selected_container),'opening_basis');
  -- Private same-phase canonical membership, never a role/authorization flag.
  opening_container_map:=opening_container_map||jsonb_build_object(selected_container.id::text,true);
  actual_prepared:=coalesce((prepared_sums->>selected_cell.allocation_id::text)::numeric,0)+selected_cell.opening_quantity;
  prepared_sums:=prepared_sums||jsonb_build_object(selected_cell.allocation_id::text,actual_prepared);
  if selected_cell.opening_quantity>0 then positive_sites:=positive_sites||jsonb_build_object(selected_site::text,true);
  else zero_sites:=zero_sites||jsonb_build_object(selected_site::text,true);end if;
 end loop;
 for boundary_allocation in select value from jsonb_each(allocation_map) loop
  actual_prepared:=coalesce((prepared_sums->>(boundary_allocation->>'allocation_id'))::numeric,0);
  if actual_prepared is distinct from (boundary_allocation->>'prepared_quantity')::numeric then
   raise exception 'adapter_source_integrity' using errcode='23514';end if;
 end loop;
 if positive_sites<>'{}'::jsonb then
  for site_key in select jsonb_object_keys(zero_sites) loop
   if not(positive_sites?site_key) then raise exception 'adapter_source_integrity' using errcode='23514';end if;
  end loop;
 end if;
 selected_site:=null;
 if not fully_prepared or positive_sites='{}'::jsonb then reason:='opening_package_incomplete';
 elsif(select count(*) from jsonb_object_keys(positive_sites))<>1 then reason:='opening_package_multisite';
 else select jsonb_object_keys(positive_sites)::uuid into selected_site;end if;
 select coalesce(jsonb_agg(selected_ids.key order by selected_ids.key collate "C"),'[]'::jsonb)into opening_container_ids
 from jsonb_object_keys(opening_container_map)as selected_ids(key);
 return jsonb_build_object('state',state,'site_id',selected_site,'reason',reason,'opening_container_ids',opening_container_ids);
end

controlled_review_v3.read_adapter_parent.source:
declare state jsonb:=p_state; e public.controlled_stock_events; r record; row_value jsonb;
begin
 if p_role is null or p_role<>all(array['reviewed_target','correction_target','ordinary_source','original_dispense','original_pickup']) then
  raise exception 'adapter_source_role_conflict' using errcode='23514';end if;
 select * into e from public.controlled_stock_events where id=p_event_id;
 if e.id is null or e.product_id::text is distinct from state->>'product_id'
 or e.opening_id::text is distinct from state->>'opening_id' then
  raise exception 'adapter_parent_integrity' using errcode='23514';end if;
 perform controlled_review_v3.read_validate_scalar(e.id);
 state:=controlled_review_v3.read_adapter_add(state,'public.controlled_stock_events',jsonb_build_object('id',e.id),to_jsonb(e),p_role);
 select to_jsonb(a) into row_value from public.controlled_stock_actions a where a.id=e.id;
 state:=controlled_review_v3.read_adapter_add(state,'public.controlled_stock_actions',jsonb_build_object('id',e.id),row_value,p_role);
 select to_jsonb(a) into row_value from public.controlled_stock_preparations a where a.id=e.id;
 state:=controlled_review_v3.read_adapter_add(state,'public.controlled_stock_preparations',jsonb_build_object('id',e.id),row_value,p_role);
 select to_jsonb(a) into row_value from public.controlled_stock_policy_versions a where a.id=e.policy_version_id;
 state:=controlled_review_v3.read_adapter_add(state,'public.controlled_stock_policy_versions',jsonb_build_object('id',e.policy_version_id),row_value,p_role);
 select to_jsonb(a) into row_value from public.controlled_stock_openings a where a.id=e.opening_id;
 state:=controlled_review_v3.read_adapter_add(state,'public.controlled_stock_openings',jsonb_build_object('id',e.opening_id),row_value,p_role);
 for r in select * from public.controlled_stock_source_links where event_id=e.id order by id limit 513 loop
  state:=controlled_review_v3.read_adapter_add(state,'public.controlled_stock_source_links',jsonb_build_object('id',r.id),to_jsonb(r),p_role);
 end loop;
 for r in select * from public.controlled_stock_event_lines where event_id=e.id order by cell_id,source_link_id limit 513 loop
  state:=controlled_review_v3.read_adapter_add(state,'public.controlled_stock_event_lines',jsonb_build_object('id',r.id),to_jsonb(r),p_role);
  select to_jsonb(c) into row_value from public.controlled_stock_cells c where c.id=r.cell_id;
  state:=controlled_review_v3.read_adapter_add(state,'public.controlled_stock_cells',jsonb_build_object('id',r.cell_id),row_value,p_role);
  select to_jsonb(c) into row_value from public.controlled_stock_containers c where c.id=(row_value->>'container_id')::uuid;
  state:=controlled_review_v3.read_adapter_add(state,'public.controlled_stock_containers',jsonb_build_object('id',row_value->'id'),row_value,p_role);
 end loop;
 for r in select * from public.controlled_stock_container_transitions where event_id=e.id order by container_id limit 513 loop
  state:=controlled_review_v3.read_adapter_add(state,'public.controlled_stock_container_transitions',jsonb_build_object('id',r.id),to_jsonb(r),p_role);
  select to_jsonb(c) into row_value from public.controlled_stock_containers c where c.id=r.container_id;
  state:=controlled_review_v3.read_adapter_add(state,'public.controlled_stock_containers',jsonb_build_object('id',r.container_id),row_value,p_role);
 end loop;
 return state;
end

controlled_review_v3.read_adapter_pickup.source:
declare state jsonb:=p_state; p public.native_pickups; op public.native_fulfillment_operations;
 provenance public.stock_pickup_sources; managed jsonb;
begin
 if p_role is null or p_role<>all(array['reviewed_target','original_pickup']) then
  raise exception 'adapter_source_role_conflict' using errcode='23514';end if;
 if p_depth is null or p_depth<0 or p_depth>4 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
 select * into p from public.native_pickups where id=p_pickup_id;
 select * into op from public.native_fulfillment_operations where id=p_pickup_id;
 select * into provenance from public.stock_pickup_sources where event_id=p_pickup_id;
 if p.id is null or op.id is null or op.operation<>'pickup' or op.actor_id<>p.actor_id or op.result is distinct from p.document then
  raise exception 'adapter_source_integrity' using errcode='23514';end if;
 managed:=controlled_review_v3.read_native_source_event('pickup',p.id,p_product_id);
 if managed is not null then state:=controlled_review_v3.read_adapter_parent(state,(managed->>'event_id')::uuid,p_role);end if;
 if provenance.event_id is null and managed is not null then raise exception 'adapter_source_integrity' using errcode='23514';end if;
 if provenance.event_id is not null then
  if provenance.actor_id<>p.actor_id then raise exception 'adapter_source_integrity' using errcode='23514';end if;
  state:=controlled_review_v3.read_adapter_add(state,'public.stock_pickup_sources',jsonb_build_object('event_id',p.id),to_jsonb(provenance),p_role);
 end if;
 state:=controlled_review_v3.read_adapter_add(state,'public.native_pickups',jsonb_build_object('id',p.id),to_jsonb(p),p_role);
 state:=controlled_review_v3.read_adapter_add(state,'public.native_fulfillment_operations',jsonb_build_object('id',op.id),to_jsonb(op),p_role);
 state:=controlled_review_v3.read_adapter_dispense(state,p.dispense_id,p_product_id,'original_dispense',p_depth+1);
 return state;
end

controlled_review_v3.read_adapter_return.source:
declare state jsonb:=p_state; r public.native_return_events; op public.native_return_operations;
 provenance public.stock_custody_sources; original public.native_return_events;
 stock public.native_return_stock_links; movement public.inventory_movements; a public.native_dispense_allocations;
 x record; managed jsonb; source_writer text; n integer:=0; source_count integer; target_id uuid;
begin
 if p_role is null or p_role<>all(array['reviewed_target','correction_target','ordinary_source','original_intake','resolution_correction']) then
  raise exception 'adapter_source_role_conflict' using errcode='23514';end if;
 if p_depth is null or p_depth<0 or p_depth>4 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
 select * into r from public.native_return_events where id=p_return_id;
 select * into op from public.native_return_operations where id=p_return_id;
 select * into provenance from public.stock_custody_sources where event_id=p_return_id;
 source_writer:=case r.document->>'version' when '1' then 'record_native_dispense_return' when '2' then 'record_native_dispense_return_v2' end;
 if r.id is not null and(r.document->'version'not in('1'::jsonb,'2'::jsonb)or r.action not in('intake','dispose','restock','retract_intake','retract_disposal','retract_restock'))then raise exception 'read_denied'using errcode='42501';end if;
 if r.id is null or op.id is null or source_writer is null or op.actor_id<>r.actor_id or op.result is distinct from r.document
 or r.document->>'record_hash' is distinct from r.record_hash or public.native_fulfillment_hash(r.document-'record_hash') is distinct from r.record_hash then
  raise exception 'adapter_source_integrity' using errcode='23514';end if;
 managed:=controlled_review_v3.read_return_source_event(r.id,p_product_id);
 -- Only these return roles declare parent/physical reference edges.
 if managed is not null and p_role in('reviewed_target','correction_target','ordinary_source') then
  state:=controlled_review_v3.read_adapter_parent(state,(managed->>'event_id')::uuid,p_role);end if;
 if provenance.event_id is null and managed is not null then raise exception 'adapter_source_integrity' using errcode='23514';end if;
 if provenance.event_id is not null then
  if provenance.actor_id<>r.actor_id or provenance.writer<>source_writer then raise exception 'adapter_source_integrity' using errcode='23514';end if;
  state:=controlled_review_v3.read_adapter_add(state,'public.stock_custody_sources',jsonb_build_object('event_id',r.id),to_jsonb(provenance),p_role);
 end if;
 state:=controlled_review_v3.read_adapter_add(state,'public.native_return_events',jsonb_build_object('id',r.id),to_jsonb(r),p_role);
 state:=controlled_review_v3.read_adapter_add(state,'public.native_return_operations',jsonb_build_object('id',op.id),to_jsonb(op),p_role);
 state:=controlled_review_v3.read_adapter_dispense(state,r.dispense_id,p_product_id,'original_dispense',p_depth+1);
 if r.intake_id is not null then
  select * into original from public.native_return_events where id=r.intake_id;
  if original.id is null or original.id=r.id or original.action<>'intake' or original.dispense_id<>r.dispense_id or original.sequence>=r.sequence then
   raise exception 'adapter_source_integrity' using errcode='23514';end if;
  state:=controlled_review_v3.read_adapter_return_v1(state,original.id,p_product_id,'original_intake',p_depth+1);
 end if;
 if r.action in('retract_intake','retract_disposal','retract_restock') then
  target_id:=(r.document#>>'{correction_target,event_id}')::uuid;
  select * into original from public.native_return_events where id=target_id;
  if original.id is null or original.id=r.id or original.dispense_id<>r.dispense_id or original.sequence>=r.sequence
  or original.record_hash is distinct from r.document#>>'{correction_target,record_hash}'
  or original.action is distinct from(case r.action when 'retract_intake' then 'intake' when 'retract_disposal' then 'dispose' else 'restock' end)
  or controlled_review_v3.read_return_source_event(target_id,p_product_id) is null then
   raise exception 'adapter_source_integrity' using errcode='23514';end if;
  state:=controlled_review_v3.read_adapter_return_v1(state,target_id,p_product_id,'correction_target',p_depth+1);
 end if;
 if r.action='restock' then
  for x in select * from public.native_return_stock_links where event_id=r.id order by allocation_id limit 101 loop
   n:=n+1;if n>100 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
   select * into a from public.native_dispense_allocations where id=x.allocation_id;
   select * into movement from public.inventory_movements where id=x.movement_id;
   if a.id is null or movement.id is null or a.dispense_id<>r.dispense_id or a.lot_id<>x.lot_id or movement.lot_id<>x.lot_id or movement.quantity<>x.quantity
   or not exists(select 1 from jsonb_array_elements(r.document->'allocations') d where d->>'allocation_id'=x.allocation_id::text
    and d->>'movement_id'=x.movement_id::text and(d->>'quantity')::numeric=x.quantity and d->>'lot_id'=x.lot_id::text) then
    raise exception 'adapter_source_integrity' using errcode='23514';end if;
   state:=controlled_review_v3.read_adapter_add(state,'public.native_return_stock_links',jsonb_build_object('id',x.id),to_jsonb(x),p_role);
   state:=controlled_review_v3.read_adapter_movement(state,x.movement_id,source_writer,r.id,r.actor_id,p_role,managed is not null);
  end loop;
 elsif r.action='retract_restock' then
  for x in select * from public.native_return_compensation_links where event_id=r.id order by allocation_id limit 101 loop
   n:=n+1;if n>100 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
   select * into stock from public.native_return_stock_links where event_id=target_id and allocation_id=x.allocation_id;
   select * into movement from public.inventory_movements where id=x.movement_id;
   if stock.id is null or movement.id is null or x.target_event_id<>target_id or x.original_movement_id<>stock.movement_id or x.lot_id<>stock.lot_id
   or movement.lot_id<>x.lot_id or movement.quantity<>-x.quantity
   or not exists(select 1 from jsonb_array_elements(r.document->'allocations') d where d->>'allocation_id'=x.allocation_id::text
    and d->>'movement_id'=x.movement_id::text and(d->>'quantity')::numeric=x.quantity and d->>'lot_id'=x.lot_id::text) then
    raise exception 'adapter_source_integrity' using errcode='23514';end if;
   state:=controlled_review_v3.read_adapter_add(state,'public.native_return_compensation_links',jsonb_build_object('id',x.id),to_jsonb(x),p_role);
   state:=controlled_review_v3.read_adapter_add(state,'public.native_return_stock_links',jsonb_build_object('id',stock.id),to_jsonb(stock),'correction_target');
   -- adapter_return(target) already retained/checked the original positive movement.
   -- Its exact stock link above binds original_movement_id; retain the distinct negative movement now.
   state:=controlled_review_v3.read_adapter_movement(state,x.movement_id,source_writer,r.id,r.actor_id,p_role,managed is not null);
  end loop;
 end if;
 if r.action in('restock','retract_restock') and(n=0 or n<>jsonb_array_length(r.document->'allocations')) then
  raise exception 'adapter_source_integrity' using errcode='23514';end if;
 select count(*) into source_count from(select movement_id from public.stock_movement_sources s where s.writer=source_writer and s.source_id=r.id limit 101) q;
 if source_count>100 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
 if source_count not in(0,n) or(managed is not null and source_count<>n)
 or exists(select 1 from public.stock_movement_sources s where s.writer=source_writer and s.source_id=r.id
  and not exists(select 1 from public.native_return_stock_links l where r.action='restock' and l.event_id=r.id and l.movement_id=s.movement_id)
  and not exists(select 1 from public.native_return_compensation_links l where r.action='retract_restock' and l.event_id=r.id and l.movement_id=s.movement_id)) then
  raise exception 'adapter_source_integrity' using errcode='23514';end if;
 return state;
end

controlled_review_v3.read_adapter_site(p.source:
declare e public.controlled_stock_events; site uuid; unit text; r record; n integer:=0;
begin
 select * into e from public.controlled_stock_events where id=p_event_id;
 if e.id is null then raise exception 'adapter_parent_integrity' using errcode='23514';end if;
 select stock_unit into unit from public.controlled_stock_policy_versions where id=e.policy_version_id;
 for r in select c.controlling_site_id,c.product_id,c.stock_unit from public.controlled_stock_container_transitions t
  join public.controlled_stock_containers c on c.id=t.container_id where t.event_id=e.id order by t.container_id limit 513 loop
  n:=n+1;
  if n>512 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
  if r.product_id<>e.product_id or r.stock_unit is distinct from unit or(site is not null and site<>r.controlling_site_id) then
   raise exception 'adapter_source_integrity' using errcode='23514';end if;
  site:=r.controlling_site_id;
 end loop;
 if e.basis in('physical_record','correction_assertion') and(site is null or not exists(select 1 from public.controlled_stock_event_lines where event_id=e.id)) then
  raise exception 'adapter_source_integrity' using errcode='23514';end if;
 return jsonb_build_object('site_id',site);
end

controlled_review_v3.read_annotation_ope.source:
declare e public.controlled_stock_events;o public.controlled_stock_openings;a record;c record;entry jsonb;item jsonb;allocation_map jsonb:='{}';sums jsonb:='{}';
 sites jsonb:='{}';zero_sites jsonb:='{}';key_value text;site_value uuid;unit_value text;target_unit text;n integer:=0;entry_count integer:=0;cell_count integer:=0;
begin
 select *into e from public.controlled_stock_events where id=p_event_id;
 select *into o from public.controlled_stock_openings where id=e.opening_id and product_id=p_product_id;
 if e.id is null or o.id is null or e.event_kind not in('append_native_dispense_correction:clinical_annotation','append_native_dispense_correction:operational_annotation')
  or jsonb_typeof(o.native_custody_boundary)is distinct from 'array'or jsonb_array_length(o.native_custody_boundary)>200 then return jsonb_build_object('site_id',null);end if;
 for item in select value from jsonb_array_elements(o.native_custody_boundary)loop
  if item->>'dispense_id'=p_dispense_id::text then entry:=item;entry_count:=entry_count+1;end if;
 end loop;
 select stock_unit into unit_value from public.controlled_stock_policy_versions where id=o.policy_version_id and product_id=p_product_id;
 select stock_unit into target_unit from public.controlled_stock_policy_versions where id=e.policy_version_id and product_id=p_product_id;
 if entry_count<>1 or unit_value is null or unit_value is distinct from target_unit
  or public.controlled_stock_opening_selector(entry->'return_head')<>0 or public.controlled_stock_opening_selector(entry->'discrepancy_head')<>0
  or entry->'pickup'is distinct from 'null'::jsonb or jsonb_typeof(entry->'allocations')is distinct from 'array'or jsonb_array_length(entry->'allocations')not between 1 and 100
  or exists(select 1 from public.native_dispense_correction_events prefix where prefix.dispense_id=p_dispense_id
    and prefix.sequence<=public.controlled_stock_opening_selector(entry->'correction_head')and prefix.kind not in('clinical_annotation','operational_annotation'))then return jsonb_build_object('site_id',null);end if;
 for a in select *from public.native_dispense_allocations where dispense_id=p_dispense_id limit 101 loop
  n:=n+1;if n>100 then return jsonb_build_object('site_id',null);end if;
  select value into item from jsonb_array_elements(entry->'allocations')where value->>'allocation_id'=a.id::text;
  if item is null or item->>'lot_id'is distinct from a.lot_id::text or(item->>'dispensed_quantity')::numeric is distinct from a.quantity
   or(item->>'prepared_quantity')::numeric is distinct from a.quantity or a.quantity<=0 or item->'held'is distinct from '[]'::jsonb then return jsonb_build_object('site_id',null);end if;
  allocation_map:=allocation_map||jsonb_build_object(a.id::text,item);
 end loop;
 if n=0 or n<>jsonb_array_length(entry->'allocations')then return jsonb_build_object('site_id',null);end if;
 for c in select cell.*,box.product_id as box_product,box.stock_unit,box.kind as box_kind,box.stock_lot_id,box.opening_id as box_opening,
  box.created_event_id as box_created,box.controlling_site_id from public.controlled_stock_cells cell join public.controlled_stock_containers box on box.id=cell.container_id
  where cell.opening_id=o.id and cell.dispense_id=p_dispense_id and cell.channel='prepared'limit 513 loop
  cell_count:=cell_count+1;if cell_count>512 then return jsonb_build_object('site_id',null);end if;
  item:=allocation_map->c.allocation_id::text;
  if item is null or c.lot_id::text is distinct from item->>'lot_id'or c.intake_id is not null or c.created_event_id is not null or c.opening_quantity<0
   or c.box_opening is distinct from o.id or c.box_product is distinct from p_product_id or c.stock_unit is distinct from unit_value
   or c.box_kind is distinct from 'prepared'or c.stock_lot_id is not null or c.box_created is not null or c.controlling_site_id is null then return jsonb_build_object('site_id',null);end if;
  sums:=sums||jsonb_build_object(c.allocation_id::text,coalesce((sums->>c.allocation_id::text)::numeric,0)+c.opening_quantity);
  if c.opening_quantity>0 then sites:=sites||jsonb_build_object(c.controlling_site_id::text,true);else zero_sites:=zero_sites||jsonb_build_object(c.controlling_site_id::text,true);end if;
 end loop;
 for item in select value from jsonb_each(allocation_map)loop
  if coalesce((sums->>(item->>'allocation_id'))::numeric,0)is distinct from(item->>'prepared_quantity')::numeric then return jsonb_build_object('site_id',null);end if;
 end loop;
 if(select count(*)from jsonb_object_keys(sites))<>1 then return jsonb_build_object('site_id',null);end if;
 for key_value in select jsonb_object_keys(zero_sites)loop if not(sites?key_value)then return jsonb_build_object('site_id',null);end if;end loop;
 select jsonb_object_keys(sites)::uuid into site_value;
 return jsonb_build_object('site_id',site_value);
end

controlled_review_v3.read_authorizations.source:
declare policy_value jsonb:=p_configs->'policy';read_value jsonb;review_value jsonb;policy_projection jsonb;fact jsonb:=p_facts->p_actor_id::text;
begin
 if policy_value is not null and policy_value<>'null'::jsonb and policy_value->'enabled'='true'::jsonb and policy_value#>array['body','rules',p_kind,'enabled']='true'::jsonb then
 policy_projection:=jsonb_build_object('id',policy_value->'id','record_hash',policy_value->'record_hash','rule',policy_value#>array['body','rules',p_kind]);end if;
 if fact is not null then
  if p_configs->'read'<>'null'::jsonb then read_value:=controlled_review_v3.protocol_member_conditions(jsonb_build_object('record',p_configs->'read','actor_id',p_actor_id,'capability','read','active',fact->'active','live_roles',fact->'roles'));end if;
  if p_configs->'review'<>'null'::jsonb then review_value:=controlled_review_v3.protocol_member_conditions(jsonb_build_object('record',p_configs->'review','actor_id',p_actor_id,'capability','review','active',fact->'active','live_roles',fact->'roles'));end if;
 end if;
 return jsonb_build_object('policy',policy_projection,'read',read_value,'review',review_value);
end

controlled_review_v3.read_clinical_depen.source:
