controlled_review_v3.read_collect_scalar.source:
declare e public.controlled_stock_events;s jsonb;refs jsonb;rows_value jsonb;site uuid;adapter_value jsonb;target_value jsonb;row_site uuid;retained_site uuid;return_site uuid;dispense_site uuid;did uuid;managed jsonb;opening_projection jsonb; before_opening_containers jsonb:='{}'; opening_scope_ids jsonb; opening_scope_map jsonb:='{}'; opening_seen_map jsonb:='{}'; scope_item jsonb; scope_id uuid; scope_sorted jsonb;reason_value text;site_basis_value text:='event_transitions';row_value jsonb;
begin
 select *into e from public.controlled_stock_events where id=p_event_id;
 if e.id is null or e.event_kind not in('receive_inventory','adjust_inventory','record_patient_treatment','record_anesthesia_drug_administration','record_native_dispense','record_native_pickup','append_native_dispense_correction:clinical_annotation','append_native_dispense_correction:operational_annotation','append_native_dispense_correction:pickup_amendment','record_native_dispense_return:intake','record_native_dispense_return:dispose','record_native_dispense_return:restock','record_native_dispense_return_v2:intake','record_native_dispense_return_v2:dispose','record_native_dispense_return_v2:restock','record_native_dispense_return_v2:retract_intake','record_native_dispense_return_v2:retract_disposal','record_native_dispense_return_v2:retract_restock','record_native_return_discrepancy:report','record_native_return_discrepancy:note','record_native_return_discrepancy:resolve_corrected','record_native_return_discrepancy:resolve_confirmed_original')then raise exception 'read_denied'using errcode='42501';end if;
 s:=jsonb_build_object('rows','{}'::jsonb,'documents','[]'::jsonb,'allocations','[]'::jsonb,'target_event_id',e.id,'product_id',e.product_id,'opening_id',e.opening_id);
 s:=controlled_review_v3.read_adapter_parent(s,e.id,'reviewed_target');
 if e.event_kind='record_native_dispense'then s:=controlled_review_v3.read_adapter_dispense(s,e.id,e.product_id,'reviewed_target',0);
 elsif e.event_kind='record_native_pickup'then s:=controlled_review_v3.read_adapter_pickup(s,e.id,e.product_id,'reviewed_target',0);
 elsif e.writer in('record_native_dispense_return','record_native_dispense_return_v2')then s:=controlled_review_v3.read_adapter_return_v1(s,e.id,e.product_id,'reviewed_target',0);
 elsif e.writer='record_native_return_discrepancy'then s:=controlled_review_v3.read_adapter_discrepancy(s,e.id);
 elsif e.writer='append_native_dispense_correction'then s:=controlled_review_v3.read_adapter_annotations(s,e.id);
 else s:=controlled_review_v3.read_adapter_clinical(s,e.id);end if;
 if e.writer in('record_native_dispense_return','record_native_dispense_return_v2')then
  select dispense_id into did from public.native_return_events where id=e.id;managed:=controlled_review_v3.read_native_source_event('dispense',did,e.product_id);
  -- The managed D is the immutable scope candidate/cross-check, not the
  -- return event's proof label. Original collect_event_sources derives return
  -- site from the OWN event transitions and labels it event_transitions.
  if managed is not null then
   return_site:=(controlled_review_v3.read_adapter_site(e.id)->>'site_id')::uuid;
   dispense_site:=(controlled_review_v3.read_adapter_site(did)->>'site_id')::uuid;
   if return_site is null or dispense_site is null or return_site is distinct from dispense_site then raise exception 'adapter_source_integrity'using errcode='23514';end if;
   site:=return_site;site_basis_value:='event_transitions';
  else reason_value:='unmanaged_original_dispense';site_basis_value:='unproven';end if;
 elsif e.writer='record_native_return_discrepancy'then
  select(document#>>'{source,event_id}')::uuid into did from public.native_return_discrepancy_events where id=e.id;
  managed:=controlled_review_v3.read_return_source_event(did,e.product_id);
  if managed is not null then site:=(controlled_review_v3.read_adapter_site((managed->>'event_id')::uuid)->>'site_id')::uuid;site_basis_value:='managed_return';
  else reason_value:='unmanaged_original_return';site_basis_value:='unproven';end if;
 elsif e.writer='append_native_dispense_correction'then
  select dispense_id into did from public.native_dispense_correction_events where id=e.id;
  managed:=controlled_review_v3.read_native_source_event('dispense',did,e.product_id);
  if managed is not null then site:=(controlled_review_v3.read_adapter_site(did)->>'site_id')::uuid;site_basis_value:='managed_dispense';
  elsif e.event_kind in('append_native_dispense_correction:clinical_annotation','append_native_dispense_correction:operational_annotation')then
   -- Capture ALL existing container IDs before the fixed canonical helper.
    for row_value in select value from jsonb_each(s->'rows')loop
     if row_value->>'relation'='public.controlled_stock_containers'then
      before_opening_containers:=before_opening_containers||jsonb_build_object(public.controlled_stock_uuid(row_value#>'{key,id}')::text,true);
     end if;
    end loop;
    opening_projection:=controlled_review_v3.read_adapter_opening_site(s,did,e.product_id);s:=opening_projection->'state';
   site:=(opening_projection->>'site_id')::uuid;reason_value:=opening_projection->>'reason';site_basis_value:=case when site is null then 'unproven'else 'opening_custody_site'end;
  else reason_value:='unmanaged_original_dispense';site_basis_value:='unproven';end if;
 else
  site:=(controlled_review_v3.read_adapter_site(e.id)->>'site_id')::uuid;
  if site is null then raise exception 'adapter_source_integrity'using errcode='23514';end if;
 end if;
 -- Only a fresh helper-owned canonical set can scope the unsupported path.
 if opening_projection is not null and managed is null
 and e.event_kind in('append_native_dispense_correction:clinical_annotation','append_native_dispense_correction:operational_annotation')
 and opening_projection->'site_id'='null'::jsonb and site is null
 and opening_projection->>'reason'in('opening_package_incomplete','opening_package_multisite')
 and reason_value=opening_projection->>'reason'and site_basis_value='unproven'
 and before_opening_containers='{}'::jsonb then
  perform public.controlled_stock_keys(opening_projection,array['state','site_id','reason','opening_container_ids']);
  opening_scope_ids:=opening_projection->'opening_container_ids';
  if jsonb_typeof(opening_scope_ids)is distinct from 'array'then raise exception 'adapter_source_integrity'using errcode='23514';end if;
  if jsonb_array_length(opening_scope_ids)>512 then raise exception 'adapter_source_integrity'using errcode='23514';end if;
  for scope_item in select value from jsonb_array_elements(opening_scope_ids)loop
   scope_id:=public.controlled_stock_uuid(scope_item);
   if opening_scope_map?scope_id::text then raise exception 'adapter_source_integrity'using errcode='23514';end if;
   opening_scope_map:=opening_scope_map||jsonb_build_object(scope_id::text,true);
  end loop;
  select coalesce(jsonb_agg(scope_keys.key order by scope_keys.key collate "C"),'[]'::jsonb)into scope_sorted
  from jsonb_object_keys(opening_scope_map)as scope_keys(key);
  if opening_scope_ids is distinct from scope_sorted then raise exception 'adapter_source_integrity'using errcode='23514';end if;
 end if;
 for row_value in select value from jsonb_each(s->'rows')loop
  if row_value->>'relation'='public.controlled_stock_containers'then
   row_site:=(row_value#>>'{row,controlling_site_id}')::uuid;
   if opening_scope_ids is not null then
    scope_id:=public.controlled_stock_uuid(row_value#>'{key,id}');
    if row_site is null or row_value#>'{row,id}'is distinct from to_jsonb(scope_id)
    or not(opening_scope_map?scope_id::text)or opening_seen_map?scope_id::text then
     raise exception 'adapter_source_integrity'using errcode='23514';end if;
    opening_seen_map:=opening_seen_map||jsonb_build_object(scope_id::text,true);
   else
   if row_site is null or(retained_site is not null and row_site<>retained_site)or(site is not null and row_site<>site)then raise exception 'adapter_source_integrity'using errcode='23514';end if;
   retained_site:=row_site;
   end if;
  end if;
 end loop;
 if opening_scope_ids is not null and opening_seen_map is distinct from opening_scope_map then
  raise exception 'adapter_source_integrity'using errcode='23514';end if;
 target_value:=jsonb_build_object('event_id',e.id,'product_id',e.product_id,'sequence',e.sequence,'record_hash',e.record_hash,'original_actor_id',e.actor_id,'policy_version_id',e.policy_version_id,'opening_id',e.opening_id,'engine_revision',e.engine_revision);
 select coalesce(jsonb_agg(value-'row'order by(value->>'relation')collate "C",(value->'key')::text collate "C"),'[]'::jsonb),
 coalesce(jsonb_agg(value-'row_hash'-'role'order by(value->>'relation')collate "C",(value->'key')::text collate "C"),'[]'::jsonb)into refs,rows_value from jsonb_each(s->'rows');
 adapter_value:=jsonb_build_object('version',1,'event_kind',e.event_kind,'adapter_id',case e.event_kind when 'record_patient_treatment'then 'treatment_v1'when 'record_anesthesia_drug_administration'then 'anesthesia_v1'when 'record_native_dispense'then 'dispense_v1'when 'record_native_pickup'then 'pickup_v1'else case when e.writer='record_native_return_discrepancy'then 'discrepancy_v1'when e.writer='append_native_dispense_correction'then 'annotation_v1'when e.writer='record_native_dispense_return'then 'return_v1'when e.event_kind in('record_native_dispense_return_v2:retract_intake','record_native_dispense_return_v2:retract_disposal','record_native_dispense_return_v2:retract_restock')then 'retraction_v1'when e.writer='record_native_dispense_return_v2'then 'return_v2'else 'movement_v1'end end,'target',target_value,'site_basis',site_basis_value,'site_id',site,'source_refs',refs,'native_family_dispense_id',case e.event_kind when 'record_native_dispense'then e.id when 'record_native_pickup'then(select dispense_id from public.native_pickups where id=e.id)else null end,'provenance_state',case when reason_value is null then 'supported'else 'unsupported'end,'reason',reason_value);
 if octet_length(jsonb_build_object('adapter',adapter_value,'source_rows',rows_value)::text)>1048576 then raise exception 'evidence_limit_exceeded'using errcode='54000';end if;
 return jsonb_build_object('adapter',adapter_value,'source_rows',rows_value);
end

controlled_review_v3.read_collect_visibl.source:
declare e public.controlled_stock_events;target_value jsonb;collected_value jsonb;message_value text;context_value text;
begin
 -- All exact local target/source validations OUTSIDE the capacity catch.
 perform controlled_review_v3.read_validate_scalar(p_event_id);
 select *into strict e from public.controlled_stock_events where id=p_event_id;
 target_value:=jsonb_build_object('event_id',e.id,'product_id',e.product_id,'sequence',e.sequence,'record_hash',e.record_hash,'original_actor_id',e.actor_id,'policy_version_id',e.policy_version_id,'opening_id',e.opening_id,'engine_revision',e.engine_revision);
 begin collected_value:=controlled_review_v3.read_collect_scalar(p_event_id);
 exception when sqlstate '54000'then
  get stacked diagnostics message_value=MESSAGE_TEXT,context_value=PG_EXCEPTION_CONTEXT;
  if message_value is distinct from 'evidence_limit_exceeded'or split_part(context_value,E'\n',1)!~'^PL/pgSQL function controlled_review_v3\.(read_adapter_add|read_collect_scalar|read_adapter_site|read_adapter_dispense|read_adapter_pickup|read_adapter_opening_site|read_return_v1_context|read_return_v1_source_event|read_adapter_return_v1|read_return_v2_prefix|read_return_v2_quantity_step|read_return_discrepancy_snapshot|read_return_source_event)\([^\n]*\) line [1-9][0-9]* at RAISE$'then raise;end if;
  return jsonb_build_object('state','collector_limit','event',to_jsonb(e),'adapter',jsonb_build_object('version',1,'event_kind',e.event_kind,'adapter_id',case e.event_kind when 'record_patient_treatment'then 'treatment_v1'when 'record_anesthesia_drug_administration'then 'anesthesia_v1'when 'record_native_dispense'then 'dispense_v1'when 'record_native_pickup'then 'pickup_v1'else case when e.writer='record_native_return_discrepancy'then 'discrepancy_v1'when e.writer='append_native_dispense_correction'then 'annotation_v1'when e.writer='record_native_dispense_return'then 'return_v1'when e.event_kind in('record_native_dispense_return_v2:retract_intake','record_native_dispense_return_v2:retract_disposal','record_native_dispense_return_v2:retract_restock')then 'retraction_v1'when e.writer='record_native_dispense_return_v2'then 'return_v2'else 'movement_v1'end end,'target',target_value,
  'site_basis','unproven','site_id',null,'source_refs','[]'::jsonb,'native_family_dispense_id',null,'provenance_state','unsupported','reason','evidence_limit_exceeded'),'source_rows',null);
 end;
 return jsonb_build_object('state','complete','adapter',collected_value->'adapter','source_rows',collected_value->'source_rows');
end

controlled_review_v3.read_configuration_.source:
declare stored_row controlled_review_v3.configuration;result_value jsonb;
begin
 if p_id is null or p_id='00000000-0000-0000-0000-000000000000'::uuid then
  raise exception 'configuration_record_invalid'using errcode='23514';end if;
 select *into stored_row from controlled_review_v3.configuration where id=p_id;
 if not found then return null;end if;
 result_value:=jsonb_build_object('id',stored_row.id,'kind',stored_row.kind,'stream_key',stored_row.stream_key,
  'version',stored_row.version,'predecessor_id',stored_row.predecessor_id,'predecessor_hash',stored_row.predecessor_hash,
  'enabled',stored_row.enabled,'document',stored_row.document,'record_hash',stored_row.record_hash,
  'publication_operation_id',stored_row.publication_operation_id,
  'published_at',controlled_review_v3.protocol_utc(stored_row.published_at),
  'publisher_actor_id',stored_row.publisher_actor_id,'publisher_session_id',stored_row.publisher_session_id,
  'publisher_name',stored_row.publisher_name,'authorization_id',stored_row.authorization_id,'publication_mode',stored_row.publication_mode,
  'effective_from',case when stored_row.effective_from is null then null else controlled_review_v3.protocol_utc(stored_row.effective_from)end);
 perform controlled_review_v3.configuration_record(result_value);
 return result_value;
end

declare row_value jsonb:=controlled_review_v3.read_configuration_dto(p_id);
begin
 if row_value is null then return null;end if;
 return controlled_review_v3.configuration_record(row_value);
end

