 if d is null or d->>'authorization_id'is distinct from e.authorization_id::text or d->>'pet_id'is distinct from e.pet_id::text then raise exception 'adapter_source_integrity'using errcode='23514';end if;
 authorization_value:=(d->>'authorization_id')::uuid;pet_value:=(d->>'pet_id')::uuid;dispense_value:=(d->>'id')::uuid;
 target:=jsonb_build_object('authorization_id',authorization_value,'pet_id',pet_value,'dispense_id',dispense_value);
 pickup:=public.native_correction_pickup(e.dispense_id);
 head:=jsonb_build_object('event_id',null,'version',0,'record_hash',null);
 if e.prior_event_id is not null then
  select *into previous_row from public.native_dispense_correction_events where id=e.prior_event_id;
  if previous_row.id is null or previous_row.dispense_id is distinct from e.dispense_id or previous_row.authorization_id is distinct from e.authorization_id
   or previous_row.pet_id is distinct from e.pet_id or previous_row.sequence<>e.sequence-1
   or previous_row.record_hash is distinct from public.native_fulfillment_hash(previous_row.document-'record_hash')
   or previous_row.document->>'id'is distinct from previous_row.id::text or previous_row.document->'sequence'is distinct from to_jsonb(previous_row.sequence)
   or previous_row.document->'target'is distinct from target then raise exception 'adapter_source_integrity'using errcode='23514';end if;
  head:=jsonb_build_object('event_id',previous_row.id,'version',previous_row.sequence,'record_hash',previous_row.record_hash);previous_stamp:=previous_row.created_at;
 elsif e.sequence<>1 then raise exception 'adapter_source_integrity'using errcode='23514';end if;
 -- The original canonical writer established global latest/absence and prefix
 -- validity at commit. H0/W preserves it. We still independently bind the exact
 -- retained latest-amendment pointer/value/hash and order to immutable PK rows;
 -- NULL is source absence under that theorem, never a cached validation flag.
 if e.reviewed_context->'latest_pickup_amendment'is distinct from 'null'::jsonb then
  select *into latest_row from public.native_dispense_correction_events where id=(e.reviewed_context#>>'{latest_pickup_amendment,event_id}')::uuid;
  if latest_row.id is null or latest_row.dispense_id is distinct from e.dispense_id or latest_row.kind<>'pickup_amendment'or latest_row.sequence>=e.sequence or latest_row.authorization_id is distinct from e.authorization_id or latest_row.pet_id is distinct from e.pet_id
   or latest_row.document->>'id'is distinct from latest_row.id::text or latest_row.document->'sequence'is distinct from to_jsonb(latest_row.sequence)
   or latest_row.document->'kind'is distinct from '"pickup_amendment"'::jsonb or latest_row.document->'target'is distinct from target
   or latest_row.record_hash is distinct from public.native_fulfillment_hash(latest_row.document-'record_hash')then raise exception 'adapter_source_integrity'using errcode='23514';end if;
  latest:=jsonb_build_object('event_id',latest_row.id,'version',latest_row.sequence,'value',latest_row.document->'pickup_amendment');
 end if;
  v:=e.document;select * into o from public.native_dispense_correction_operations where id=e.id;
  if o.id is null or o.actor_id<>e.actor_id or o.result is distinct from v or o.created_at is distinct from e.created_at
   or o.request_hash is distinct from public.native_fulfillment_hash(jsonb_build_object('version',1,'actor_id',o.actor_id,'operation','append_native_dispense_correction','request',o.request))
   or e.authorization_id<>authorization_value or e.pet_id<>pet_value or e.sequence<>(head->>'version')::integer+1 or e.prior_event_id::text is distinct from head->>'event_id'
   or v->'target' is distinct from target or v->>'id' is distinct from e.id::text or v->'version' is distinct from '1'::jsonb
   or v->'sequence' is distinct from to_jsonb(e.sequence) or v->>'prior_event_id' is distinct from head->>'event_id' or v->>'prior_record_hash' is distinct from head->>'record_hash'
   or v#>>'{actor,id}' is distinct from e.actor_id::text or v->>'kind' is distinct from e.kind or (v->>'created_at')::timestamptz is distinct from e.created_at
   or v->>'authorization_hash' is distinct from d->>'authorization_hash' or v->>'dispense_document_hash' is distinct from public.native_fulfillment_hash(d)
   or v->>'record_hash' is distinct from e.record_hash or e.record_hash is distinct from public.native_fulfillment_hash(v-'record_hash')
   or v->>'reviewed_context_hash' is distinct from public.native_fulfillment_hash(e.reviewed_context)
   or e.reviewed_context->'target' is distinct from target or e.reviewed_context->'head' is distinct from head
   or e.reviewed_context->'latest_pickup_amendment' is distinct from coalesce(latest,'null'::jsonb)
   or e.reviewed_context->>'authorization_hash' is distinct from d->>'authorization_hash'
   or e.reviewed_context->>'dispense_document_hash' is distinct from public.native_fulfillment_hash(d)
   or e.reviewed_context->>'dispense_artifact_hash' is distinct from d->>'artifact_hash'
   or e.reviewed_context->'dispensed_at' is distinct from d->'dispensed_at'
   or (e.reviewed_context->'original_pickup'<>'null'::jsonb and e.reviewed_context->'original_pickup' is distinct from pickup)
   or e.created_at<(d->>'dispensed_at')::timestamptz or (previous_stamp is not null and e.created_at<previous_stamp)
  then raise exception 'Native correction integrity mismatch' using errcode='23514';end if;
  perform public.native_rx_keys(v,array['version','id','target','authorization_hash','dispense_document_hash','sequence','prior_event_id','prior_record_hash','actor','kind','reason','note','amends_event_id','pickup_amendment','reviewed_context_hash','created_at','record_hash']);
  perform public.native_rx_keys(e.reviewed_context,array['version','target','authorization_hash','dispense_document_hash','dispense_artifact_hash','dispensed_at','original_pickup','head','latest_pickup_amendment']);
  perform public.native_rx_keys(v->'actor',array['id','name','authority']);perform public.native_rx_text(v#>'{actor,name}',200);
  if v#>>'{actor,authority}' is distinct from (case when e.kind='clinical_annotation' then 'active_dvm' else 'active_staff' end)
   or (o.request->>'authorization_id')::uuid is distinct from authorization_value or (o.request->>'pet_id')::uuid is distinct from pet_value or (o.request->>'dispense_id')::uuid is distinct from dispense_value
   or o.request-'authorization_id'-'pet_id'-'dispense_id'-'expected_context_hash'-'expected_head'-'attest_review' is distinct from jsonb_build_object('kind',v->'kind','reason',v->'reason','note',v->'note','amends_event_id',v->'amends_event_id','pickup_amendment',v->'pickup_amendment')
   or o.request->'expected_head' is distinct from head or o.request->>'expected_context_hash' is distinct from v->>'reviewed_context_hash' or o.request->'attest_review' is distinct from 'true'::jsonb
