controlled_review_v3.read_discrepancy_ca.source:
declare e public.native_return_discrepancy_events;o public.native_return_discrepancy_operations;
 prefix_value jsonb;prior_snapshot jsonb;combined_snapshot jsonb;rebuilt jsonb;cases_value jsonb:='[]';case_value jsonb;
 selected_case jsonb;held_lots jsonb;open_count integer:=0;matches integer:=0;source_value public.native_return_events;
begin
 select *into e from public.native_return_discrepancy_events where id=p_event_id;
 if e.id is null or e.action not in('report','note','resolve_corrected','resolve_confirmed_original')then raise exception 'adapter_source_integrity'using errcode='23514';end if;
 if octet_length(e.document::text)>1048576 or octet_length(e.reviewed_context::text)>1048576 then raise exception 'evidence_limit_exceeded'using errcode='54000';end if;
 prefix_value:=controlled_review_v3.read_discrepancy_return_prefix(e.id,p_product_id);
 -- Validate the prior snapshot exactly BEFORE changing its case summary. No
 -- bad retained open-count/status/held-lot field is silently repaired.
 prior_snapshot:=controlled_review_v3.read_discrepancy_snapshot(e.reviewed_context->'discrepancies',to_jsonb(e));
 if prior_snapshot->'head'is distinct from e.reviewed_context->'discrepancy_head' or (prior_snapshot#>>'{head,version}')::integer<>e.sequence-1 then raise exception 'adapter_source_integrity'using errcode='23514';end if;
 for case_value in select value from jsonb_array_elements(prior_snapshot->'cases')loop
  if case_value->>'id'=e.case_id::text then
   matches:=matches+1;
   if e.action='report'or case_value->>'status'<>'open'or case_value->'source'is distinct from e.document->'source'or case_value->'allocations'is distinct from e.document->'allocations'then raise exception 'adapter_source_integrity'using errcode='23514';end if;
   case_value:=jsonb_set(case_value,'{decisions}',case_value->'decisions'||jsonb_build_array(e.document));
   if e.action like'resolve_%'then case_value:=jsonb_set(case_value,'{status}',to_jsonb(case e.action when'resolve_corrected'then'resolved_corrected'else'resolved_confirmed_original'end));end if;
  end if;
  cases_value:=cases_value||jsonb_build_array(case_value);
 end loop;
 if e.action='report'then
  if matches<>0 or e.case_id is distinct from e.id then raise exception 'adapter_source_integrity'using errcode='23514';end if;
  cases_value:=cases_value||jsonb_build_array(jsonb_build_object('id',e.id,'source',e.document->'source','allocations',e.document->'allocations','status','open','report',e.document,'decisions','[]'::jsonb));
 elsif matches<>1 then raise exception 'adapter_source_integrity'using errcode='23514';end if;
 select count(*)into open_count from jsonb_array_elements(cases_value)c where c->>'status'='open';
 select coalesce(jsonb_agg(lot_id order by lot_id),'[]'::jsonb)into held_lots from(select distinct a->>'lot_id'as lot_id from jsonb_array_elements(cases_value)c cross join lateral jsonb_array_elements(c->'allocations')a where c->>'status'='open')q;
 combined_snapshot:=jsonb_build_object('version',1,'head',jsonb_build_object('event_id',e.id,'version',e.sequence,'record_hash',e.record_hash),'open_case_count',open_count,'held_lot_ids',held_lots,'cases',cases_value);
 -- PriorB + currentB + disjoint current projections<=B + fixed frame<B.
 -- This internal union4B is immutable and does not relax collector/P1MiB.
 if octet_length(combined_snapshot::text)>4194304 then raise exception 'evidence_limit_exceeded'using errcode='54000';end if;
 rebuilt:=controlled_review_v3.read_discrepancy_snapshot(combined_snapshot,to_jsonb(e));
 if rebuilt is distinct from combined_snapshot then raise exception 'adapter_source_integrity'using errcode='23514';end if;
 select *into o from public.native_return_discrepancy_operations where id=e.id;
 select *into source_value from public.native_return_events where id=(e.document#>>'{source,event_id}')::uuid;
 return jsonb_build_object('event',to_jsonb(e),'operation',to_jsonb(o),'dispense',prefix_value->'dispense','return_prefix',prefix_value->'prior','return_head',prefix_value->'head','prior_discrepancies',prior_snapshot,'selected_discrepancies',rebuilt,'source',to_jsonb(source_value));
end

controlled_review_v3.read_discrepancy_re.source:
declare e public.native_return_discrepancy_events;r public.native_return_events;previous_row public.native_return_events;target_row public.native_return_events;
 captured jsonb;originals jsonb:='[]';c jsonb;item jsonb;line jsonb;original_line jsonb;prior jsonb;quantity_event jsonb;target_event jsonb;
 a public.native_dispense_allocations;lot public.inventory_lots;allocation_map jsonb:='{}';n integer:=0;last_id uuid;identifier uuid;seen jsonb:='{}';head jsonb;last_prefix_sequence integer:=0;
begin
 select *into e from public.native_return_discrepancy_events where id=p_event_id;
 if e.id is null or e.document->'version'is distinct from'1'::jsonb or e.action not in('report','note','resolve_corrected','resolve_confirmed_original')then raise exception 'read_denied'using errcode='42501';end if;
 captured:=controlled_review_v3.read_dispense_capture(e.dispense_id,p_product_id);c:=e.reviewed_context;
 if captured#>>'{dispense,document,id}'is distinct from e.dispense_id::text or captured#>>'{dispense,document,authorization_id}'is distinct from e.authorization_id::text or captured#>>'{dispense,document,pet_id}'is distinct from e.pet_id::text then raise exception 'adapter_source_integrity'using errcode='23514';end if;
 if octet_length(c::text)>1048576 or octet_length(e.document::text)>1048576 then raise exception 'evidence_limit_exceeded'using errcode='54000';end if;
 perform public.native_rx_keys(c,array['version','target','return_head','discrepancy_head','source','replay','discrepancies','intent']);
 if jsonb_typeof(e.document->'allocations')is distinct from'array'or jsonb_array_length(e.document->'allocations')not between 1 and 100 then raise exception 'adapter_source_integrity'using errcode='23514';end if;
 for a in select *from public.native_dispense_allocations where dispense_id=e.dispense_id order by id limit 101 loop
  n:=n+1;if n>100 then raise exception 'adapter_source_integrity'using errcode='23514';end if;
  allocation_map:=allocation_map||jsonb_build_object(a.id::text,to_jsonb(a));originals:=originals||jsonb_build_array(jsonb_build_object('allocation_id',a.id,'lot_id',a.lot_id,'quantity',public.native_fulfillment_decimal(a.quantity)));
 end loop;
 if n=0 then raise exception 'adapter_source_integrity'using errcode='23514';end if;
 head:=c->'return_head';perform public.native_rx_keys(head,array['event_id','version','record_hash']);
 if jsonb_typeof(head->'version')is distinct from'number'or(head->>'version')!~'^[1-9][0-9]{0,9}$'or(head->>'version')::numeric>2147483647 then raise exception 'adapter_source_integrity'using errcode='23514';end if;
 select *into previous_row from public.native_return_events where id=public.native_correction_uuid(head->'event_id');
 if previous_row.id is null or previous_row.dispense_id is distinct from e.dispense_id or previous_row.authorization_id is distinct from e.authorization_id or previous_row.pet_id is distinct from e.pet_id or previous_row.sequence<>(head->>'version')::integer or previous_row.created_at>e.created_at
  or previous_row.record_hash is distinct from head->>'record_hash'or previous_row.document->>'id'is distinct from previous_row.id::text or previous_row.document->'sequence'is distinct from to_jsonb(previous_row.sequence)or previous_row.document->'target'is distinct from e.document->'target'or previous_row.record_hash is distinct from public.native_fulfillment_hash(previous_row.document-'record_hash')then raise exception 'adapter_source_integrity'using errcode='23514';end if;
 prior:=c->'replay';perform public.native_rx_keys(prior,array['allocations','intakes','correction_remaining','historical']);
 if jsonb_typeof(prior->'intakes')is distinct from'array'or jsonb_typeof(prior->'correction_remaining')is distinct from'array'or jsonb_array_length(prior->'intakes')>(head->>'version')::integer or jsonb_array_length(prior->'correction_remaining')>(head->>'version')::integer then raise exception 'adapter_source_integrity'using errcode='23514';end if;
 -- Every retained intake and ordinary-event remainder is independently bound
 -- to its immutable real row. No 'present in snapshot' Boolean is evidence.
 last_prefix_sequence:=0;
 for item in select value from jsonb_array_elements(prior->'intakes')loop
  perform public.native_rx_keys(item,array['id','allocations']);identifier:=public.native_correction_uuid(item->'id');
  if seen?identifier::text then raise exception 'adapter_source_integrity'using errcode='23514';end if;seen:=seen||jsonb_build_object(identifier::text,true);
  select *into r from public.native_return_events where id=identifier;
  if octet_length(r.document::text)>1048576 or octet_length(r.reviewed_context::text)>1048576 then raise exception 'evidence_limit_exceeded'using errcode='54000';end if;
  if r.id is null or r.dispense_id is distinct from e.dispense_id or r.authorization_id is distinct from e.authorization_id or r.pet_id is distinct from e.pet_id or r.sequence>(head->>'version')::integer or r.sequence<=last_prefix_sequence or r.created_at>e.created_at or r.action<>'intake'
   or r.document->>'id'is distinct from r.id::text or r.document->'target'is distinct from e.document->'target'or r.record_hash is distinct from public.native_fulfillment_hash(r.document-'record_hash')
   or jsonb_typeof(item->'allocations')is distinct from'array'or jsonb_typeof(r.document->'allocations')is distinct from'array'or jsonb_array_length(item->'allocations')<>jsonb_array_length(r.document->'allocations')or jsonb_array_length(item->'allocations')not between 1 and 100 then raise exception 'adapter_source_integrity'using errcode='23514';end if;
  last_prefix_sequence:=r.sequence;last_id:=null;
  for line in select value from jsonb_array_elements(item->'allocations')loop
   perform public.native_rx_keys(line,array['allocation_id','lot_id','quantity','held_quantity','disposed_quantity','restocked_quantity']);identifier:=public.native_correction_uuid(line->'allocation_id');
   select value into original_line from jsonb_array_elements(r.document->'allocations')where value->>'allocation_id'=identifier::text;
   if original_line is null or allocation_map->identifier::text is null or(last_id is not null and identifier<=last_id)or line->'lot_id'is distinct from original_line->'lot_id'or line->'lot_id'is distinct from allocation_map#>array[identifier::text,'lot_id']then raise exception 'adapter_source_integrity'using errcode='23514';end if;last_id:=identifier;
   -- Retraction can reduce this retained intake quantity to zero; exact key
   -- membership is required, while equality to original quantity is invented.
   perform controlled_review_v3.read_return_quantity_number(line->'quantity',(original_line->>'quantity')::numeric);
  end loop;
 end loop;
 seen:='{}';last_prefix_sequence:=0;
 for item in select value from jsonb_array_elements(prior->'correction_remaining')loop
  perform public.native_rx_keys(item,array['event_id','allocations']);identifier:=public.native_correction_uuid(item->'event_id');
  if seen?identifier::text then raise exception 'adapter_source_integrity'using errcode='23514';end if;seen:=seen||jsonb_build_object(identifier::text,true);
  select *into r from public.native_return_events where id=identifier;
  if octet_length(r.document::text)>1048576 or octet_length(r.reviewed_context::text)>1048576 then raise exception 'evidence_limit_exceeded'using errcode='54000';end if;
  if r.id is null or r.dispense_id is distinct from e.dispense_id or r.authorization_id is distinct from e.authorization_id or r.pet_id is distinct from e.pet_id or r.sequence>(head->>'version')::integer or r.sequence<=last_prefix_sequence or r.created_at>e.created_at or r.action not in('intake','dispose','restock')
   or r.document->>'id'is distinct from r.id::text or r.document->'target'is distinct from e.document->'target'or r.record_hash is distinct from public.native_fulfillment_hash(r.document-'record_hash')
   or jsonb_typeof(item->'allocations')is distinct from'array'or jsonb_typeof(r.document->'allocations')is distinct from'array'or jsonb_array_length(item->'allocations')<>jsonb_array_length(r.document->'allocations')or jsonb_array_length(item->'allocations')not between 1 and 100 then raise exception 'adapter_source_integrity'using errcode='23514';end if;
  last_prefix_sequence:=r.sequence;last_id:=null;
  for line in select value from jsonb_array_elements(item->'allocations')loop
   perform public.native_rx_keys(line,array['allocation_id','quantity']);identifier:=public.native_correction_uuid(line->'allocation_id');
   select value into original_line from jsonb_array_elements(r.document->'allocations')where value->>'allocation_id'=identifier::text;
   if original_line is null or allocation_map->identifier::text is null or(last_id is not null and identifier<=last_id)then raise exception 'adapter_source_integrity'using errcode='23514';end if;last_id:=identifier;
   perform controlled_review_v3.read_return_quantity_number(line->'quantity',(original_line->>'quantity')::numeric);
  end loop;
 end loop;
 -- No synthetic candidate event is used. Source-exact prefix-only numeric,
 -- allocation and intake/correction conservation checks use actual native head.
 perform controlled_review_v3.read_return_prefix_quantities(originals,prior,(head->>'version')::integer);
