 if jsonb_typeof(p_ids)is distinct from 'array'or jsonb_array_length(p_ids)>201 or octet_length(p_ids::text)>16384 then raise exception 'review_history_integrity'using errcode='23514';end if;
 for id_value in select value from jsonb_array_elements(p_ids)loop perform public.controlled_stock_uuid(id_value);end loop;
 select coalesce(jsonb_object_agg(p.id::text,jsonb_build_object('active',p.is_active,'roles',
  (select coalesce(jsonb_agg(role_value order by role_value collate "C"),'[]'::jsonb)from(select distinct r.role::text role_value from public.user_roles r where r.user_id=p.id and r.role::text in('ADMIN','DVM','STAFF','TECH'))roles_value))),'{}'::jsonb)
 into facts_value from public.profiles p where p.id in(select(value#>>'{}')::uuid from jsonb_array_elements(p_ids));
 return facts_value;
end

controlled_review_v3.read_native_family(.source:
declare managed_value jsonb;event_value public.controlled_stock_events;adapter_value jsonb;policy_value jsonb;references_value jsonb;
 selection_value jsonb;result_value jsonb;reason_value text;stored controlled_review_v3.families;stored_value jsonb;
begin
 managed_value:=controlled_review_v3.read_native_source_event('dispense',p_dispense_id,p_product_id);
 if managed_value is null then
  if exists(select 1 from controlled_review_v3.families where dispense_id=p_dispense_id)then raise exception 'review_history_integrity'using errcode='23514';end if;
  return null;end if;
 select *into strict event_value from public.controlled_stock_events where id=(managed_value->>'event_id')::uuid;
 if event_value.id<>p_dispense_id or event_value.product_id<>p_product_id or event_value.event_kind<>'record_native_dispense'
  or event_value.observed_at is null then raise exception 'review_history_integrity'using errcode='23514';end if;
 adapter_value:=controlled_review_v3.read_collect_scalar(event_value.id)->'adapter';
 policy_value:=controlled_review_v3.read_policy_at(p_product_id,(adapter_value->>'site_id')::uuid,event_value.observed_at);
 references_value:=case when policy_value is null then jsonb_build_object('calendar',null,'routing',null)
  else controlled_review_v3.read_policy_references(policy_value)end;
 reason_value:=case when adapter_value->>'site_id'is null then 'family_site_unproven'
  when policy_value is null then 'no_policy_at_anchor'
  when policy_value->'enabled'is distinct from 'true'::jsonb then 'policy_disabled_at_anchor'else null end;
 selection_value:=jsonb_build_object('version',1,'original_dispense_target',adapter_value->'target',
  'original_dispense_target_hash',public.controlled_stock_hash(adapter_value->'target'),
  'selection_anchor',to_char(event_value.observed_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
  'policy_id',policy_value->'id','policy_hash',policy_value->'record_hash',
