  if octet_length(d::text)>1048576 or octet_length(c::text)>1048576 then raise exception 'evidence_limit_exceeded'using errcode='54000';end if;select * into o from public.native_return_discrepancy_operations where id=e.id;select * into s from public.native_return_events where id=(d#>>'{source,event_id}')::uuid;
