declare result_value numeric;
begin
 -- native sequence is a positive int32; original allocation is numeric14,3.
 -- A gross history total therefore has at most21 integer digits. This is an
 -- intrinsic schema/per-step bound, NOT a growing history-count admission cap.
 if p_value is null or jsonb_typeof(p_value)is distinct from'string'or(p_value#>>'{}')!~'^(0|[1-9][0-9]{0,20})\.[0-9]{3}$'or p_max is null or p_max<0 then raise exception 'adapter_source_integrity'using errcode='23514';end if;
 result_value:=(p_value#>>'{}')::numeric;
 if result_value<0 or result_value>p_max then raise exception 'adapter_source_integrity'using errcode='23514';end if;
 return result_value;
end

