 if jsonb_typeof(e.document->'allocations')is distinct from'array'or jsonb_array_length(e.document->'allocations')not between 1 and 100 then raise exception 'adapter_source_integrity'using errcode='23514';end if;
 if octet_length(c::text)>1048576 or octet_length(e.document::text)>1048576 then raise exception 'evidence_limit_exceeded'using errcode='54000';end if;
 perform public.native_rx_keys(c,array['version','target','authorization_hash','dispense_document_hash','dispensed_at','head','original_pickup','correction_head','allocations','intake','stock_review','policy','intent']);
 if jsonb_typeof(c->'allocations')is distinct from'array'or jsonb_array_length(c->'allocations')not between 1 and 100 then raise exception 'adapter_source_integrity'using errcode='23514';end if;
 for a in select *from public.native_dispense_allocations where dispense_id=e.dispense_id order by id limit 101 loop
  original_count:=original_count+1;if original_count>100 then raise exception 'adapter_source_integrity'using errcode='23514';end if;
  allocation_map:=allocation_map||jsonb_build_object(a.id::text,to_jsonb(a));
 end loop;
 if original_count<>jsonb_array_length(c->'allocations')then raise exception 'adapter_source_integrity'using errcode='23514';end if;
 for x in select value from jsonb_array_elements(c->'allocations')loop
  perform public.native_rx_keys(x,array['allocation_id','lot_id','dispensed_quantity','returned_quantity','remaining_returnable_quantity','held_quantity','disposed_quantity','restocked_quantity','lot_number','expires_on']);
  identifier:=public.native_correction_uuid(x->'allocation_id');item:=allocation_map->identifier::text;
  if item is null or(last_id is not null and identifier<=last_id)or x->>'lot_id'is distinct from item->>'lot_id'then raise exception 'adapter_source_integrity'using errcode='23514';end if;last_id:=identifier;
  select *into lot from public.inventory_lots where id=(item->>'lot_id')::uuid;
  if lot.id is null or lot.product_id is distinct from p_product_id or x->'lot_number'is distinct from to_jsonb(lot.lot_number)or x->'expires_on'is distinct from to_jsonb(lot.expires_on)then raise exception 'adapter_source_integrity'using errcode='23514';end if;
  foreach key_value in array array['dispensed_quantity','returned_quantity','remaining_returnable_quantity','held_quantity','disposed_quantity','restocked_quantity']loop
   if jsonb_typeof(x->key_value)is distinct from'string'or(x->>key_value)!~'^(0|[1-9][0-9]{0,10})\.[0-9]{3}$'then raise exception 'adapter_source_integrity'using errcode='23514';end if;
   number_value:=(x->>key_value)::numeric;if number_value<0 or number_value>(item->>'quantity')::numeric then raise exception 'adapter_source_integrity'using errcode='23514';end if;
  end loop;
  quantity:=(x->>'dispensed_quantity')::numeric;received:=(x->>'returned_quantity')::numeric;remaining:=(x->>'remaining_returnable_quantity')::numeric;held:=(x->>'held_quantity')::numeric;disposed:=(x->>'disposed_quantity')::numeric;restocked:=(x->>'restocked_quantity')::numeric;
  if quantity<>(item->>'quantity')::numeric or remaining<>quantity-received or received<>held+disposed+restocked then raise exception 'adapter_source_integrity'using errcode='23514';end if;
  projected_allocations:=projected_allocations||jsonb_build_array(x-'lot_number'-'expires_on');
 end loop;
 if e.intake_id is null then
  if c->'intake'is distinct from'null'::jsonb then raise exception 'adapter_source_integrity'using errcode='23514';end if;
 else
  select *into root from public.native_return_events where id=e.intake_id;
  if root.id is null or root.dispense_id is distinct from e.dispense_id or root.authorization_id is distinct from e.authorization_id or root.pet_id is distinct from e.pet_id or root.action<>'intake'or root.sequence>=e.sequence or root.created_at>e.created_at
   or root.document->>'id'is distinct from root.id::text or root.document->'target'is distinct from e.document->'target'or root.record_hash is distinct from public.native_fulfillment_hash(root.document-'record_hash')then raise exception 'adapter_source_integrity'using errcode='23514';end if;
  -- V2 roots require the next selected-transition cohort, never an implicit
  -- grant of fullV2 source acceptance through an original_intake context role.
  if root.document->'version'is distinct from'1'::jsonb then raise exception 'read_denied'using errcode='42501';end if;
  perform public.native_rx_keys(c->'intake',array['id','allocations','sequence','custody','package_condition','storage_history']);
  if c#>>'{intake,id}'is distinct from root.id::text or c#>'{intake,sequence}'is distinct from to_jsonb(root.sequence)
   or c#>'{intake,custody}'is distinct from root.document->'custody'or c#>'{intake,package_condition}'is distinct from root.document->'package_condition'or c#>'{intake,storage_history}'is distinct from root.document->'storage_history'
   or jsonb_typeof(c#>'{intake,allocations}')is distinct from'array'or jsonb_array_length(c#>'{intake,allocations}')not between 1 and 100 then raise exception 'adapter_source_integrity'using errcode='23514';end if;
  if jsonb_typeof(root.document->'allocations')is distinct from'array'or jsonb_array_length(root.document->'allocations')not between 1 and 100 then raise exception 'adapter_source_integrity'using errcode='23514';end if;
  -- The original replay retains every intake allocation key even at0 after
  -- retraction. Equal cardinality plus sorted unique membership/lot checks
  -- proves the exact set without inventing unchanged original quantities.
  if jsonb_array_length(c#>'{intake,allocations}')<>jsonb_array_length(root.document->'allocations')then raise exception 'adapter_source_integrity'using errcode='23514';end if;
  last_id:=null;
  for x in select value from jsonb_array_elements(c#>'{intake,allocations}')loop
   perform public.native_rx_keys(x,array['allocation_id','lot_id','quantity','held_quantity','disposed_quantity','restocked_quantity']);identifier:=public.native_correction_uuid(x->'allocation_id');item:=allocation_map->identifier::text;
   select value into y from jsonb_array_elements(root.document->'allocations')where value->>'allocation_id'=identifier::text;
   if item is null or y is null or(last_id is not null and identifier<=last_id)or x->>'lot_id'is distinct from item->>'lot_id'or y->'lot_id'is distinct from x->'lot_id'then raise exception 'adapter_source_integrity'using errcode='23514';end if;last_id:=identifier;
   foreach key_value in array array['quantity','held_quantity','disposed_quantity','restocked_quantity']loop
    if jsonb_typeof(x->key_value)is distinct from'string'or(x->>key_value)!~'^(0|[1-9][0-9]{0,10})\.[0-9]{3}$'then raise exception 'adapter_source_integrity'using errcode='23514';end if;
    number_value:=(x->>key_value)::numeric;if number_value<0 or number_value>(y->>'quantity')::numeric then raise exception 'adapter_source_integrity'using errcode='23514';end if;
   end loop;
   if(x->>'quantity')::numeric<>(x->>'held_quantity')::numeric+(x->>'disposed_quantity')::numeric+(x->>'restocked_quantity')::numeric then raise exception 'adapter_source_integrity'using errcode='23514';end if;
  end loop;
  projected_intakes:=jsonb_build_array((c->'intake')-'sequence'-'custody'-'package_condition'-'storage_history');
 end if;
 prior_projection:=jsonb_build_object('allocations',projected_allocations,'intakes',projected_intakes);
 return jsonb_build_object('dispense',captured,'prior_projection',prior_projection);
end

controlled_review_v3.read_return_v1_sour.source:
declare captured jsonb;e public.native_return_events;native_provenance public.stock_custody_sources;provenance public.stock_movement_sources;
 movement public.inventory_movements;selected_movement record;link public.controlled_stock_source_links;parent public.controlled_stock_events;opening public.controlled_stock_openings;
 did uuid;managed_dispense jsonb;entry jsonb;n integer:=0;sourced integer:=0;root_count integer;expected_writer text:='record_native_dispense_return';
begin
 captured:=controlled_review_v3.read_return_v1_capture(p_event_id,p_product_id);e:=jsonb_populate_record(null::public.native_return_events,captured->'event');did:=e.dispense_id;
 managed_dispense:=controlled_review_v3.read_native_source_event('dispense',did,p_product_id);
 select *into native_provenance from public.stock_custody_sources where event_id=e.id;
 if native_provenance.event_id is not null and(native_provenance.actor_id is distinct from e.actor_id or native_provenance.writer<>expected_writer)then raise exception 'adapter_source_integrity'using errcode='23514';end if;
 for selected_movement in select *from public.native_return_stock_links where e.action='restock'and event_id=e.id order by movement_id limit 101 loop
  n:=n+1;if n>100 then raise exception 'evidence_limit_exceeded'using errcode='54000';end if;
  select *into movement from public.inventory_movements where id=selected_movement.movement_id;
  if movement.id is null or movement.lot_id<>selected_movement.lot_id or movement.quantity<>selected_movement.quantity or movement.created_by is distinct from e.actor_id or movement.kind<>'native_return'then raise exception 'adapter_source_integrity'using errcode='23514';end if;
  select *into provenance from public.stock_movement_sources where movement_id=movement.id;
  if provenance.movement_id is not null then
   sourced:=sourced+1;
   if provenance.source_id<>e.id or provenance.writer<>expected_writer or provenance.actor_id is distinct from e.actor_id then raise exception 'adapter_source_integrity'using errcode='23514';end if;
   perform controlled_review_v3.read_stock_source(provenance.movement_id);
  end if;
 end loop;
 if(e.action='restock'and(n=0 or n<>jsonb_array_length(e.document->'allocations')))or sourced not in(0,n)then raise exception 'adapter_source_integrity'using errcode='23514';end if;
 select count(*)into root_count from(select movement_id from public.stock_movement_sources where writer=expected_writer and source_id=e.id limit 101)q;
 if root_count>100 then raise exception 'evidence_limit_exceeded'using errcode='54000';end if;
 if root_count<>sourced or exists(select 1 from public.stock_movement_sources s where s.writer=expected_writer and s.source_id=e.id and not exists(select 1 from public.native_return_stock_links l where e.action='restock'and l.event_id=e.id and l.movement_id=s.movement_id))then raise exception 'adapter_source_integrity'using errcode='23514';end if;
 select *into opening from public.controlled_stock_openings where product_id=p_product_id;
 select *into link from public.controlled_stock_source_links where return_event_id=e.id;
 if link.id is not null then
  select *into parent from public.controlled_stock_events where id=link.event_id;
  if native_provenance.event_id is null or sourced<>n or parent.id is distinct from e.id or parent.product_id is distinct from p_product_id or parent.writer<>expected_writer or parent.actor_id is distinct from e.actor_id
   or parent.event_kind is distinct from expected_writer||':'||e.action or(opening.id is not null and parent.opening_id is distinct from opening.id)
   or parent.source_bundle#>>'{native,kind}'is distinct from'return'or parent.source_bundle#>>'{native,id}'is distinct from e.id::text then raise exception 'adapter_source_integrity'using errcode='23514';end if;
  perform controlled_review_v3.read_validate_scalar(parent.id);
  return jsonb_build_object('event_id',parent.id,'source_link_ids',jsonb_build_array(link.id));
 end if;
 if exists(select 1 from public.controlled_stock_events where id=e.id)then raise exception 'adapter_source_integrity'using errcode='23514';end if;
 if opening.id is not null then
  if managed_dispense is not null or jsonb_typeof(opening.native_custody_boundary)is distinct from'array'or jsonb_array_length(opening.native_custody_boundary)>200 then raise exception 'adapter_source_integrity'using errcode='23514';end if;
  select value into entry from jsonb_array_elements(opening.native_custody_boundary)where value->>'dispense_id'=did::text;
  if entry is null or e.sequence>public.controlled_stock_opening_selector(entry->'return_head')then raise exception 'adapter_source_integrity'using errcode='23514';end if;
 end if;
 return null;
end

controlled_review_v3.read_return_v2_capt.source:
declare projected jsonb;e public.native_return_events;previous_row public.native_return_events;correction public.native_dispense_correction_events;v jsonb;c jsonb;p_prior jsonb;p_head jsonb;p_dispense jsonb;p_corrections jsonb:='{"events":[]}'::jsonb;o public.native_return_operations;intent jsonb;ds jsonb;i jsonb;x jsonb;l public.native_return_compensation_links;sl public.native_return_stock_links;m public.inventory_movements;source public.native_return_events;root uuid;expected text;begin
 projected:=controlled_review_v3.read_return_v2_prefix(p_event_id,p_product_id);
 select *into e from public.native_return_events where id=p_event_id;v:=e.document;c:=e.reviewed_context;
 p_prior:=projected->'prior';p_head:=projected->'head';p_dispense:=projected#>'{dispense,dispense,document}';
 if e.authorization_id::text is distinct from p_dispense->>'authorization_id'or e.pet_id::text is distinct from p_dispense->>'pet_id'or e.dispense_id::text is distinct from p_dispense->>'id'or e.sequence<>(p_head->>'version')::integer+1 or e.prior_event_id::text is distinct from p_head->>'event_id'or e.created_at<(p_dispense->>'dispensed_at')::timestamptz then raise exception 'adapter_source_integrity'using errcode='23514';end if;
 if c#>>'{correction_head,version}'<>'0'then
  select *into correction from public.native_dispense_correction_events where id=(c#>>'{correction_head,event_id}')::uuid;
  if correction.id is null or correction.dispense_id is distinct from e.dispense_id or correction.authorization_id is distinct from e.authorization_id or correction.pet_id is distinct from e.pet_id or correction.created_at>e.created_at
   or correction.sequence is distinct from(c#>>'{correction_head,version}')::integer or correction.record_hash is distinct from c#>>'{correction_head,record_hash}'or correction.record_hash is distinct from public.native_fulfillment_hash(correction.document-'record_hash')or correction.document->>'id'is distinct from correction.id::text or correction.document->'target'is distinct from v->'target'then raise exception 'adapter_source_integrity'using errcode='23514';end if;
  perform controlled_review_v3.read_correction_capture(correction.id,p_product_id);p_corrections:=jsonb_build_object('events',jsonb_build_array(correction.document));
 end if;
 select * into o from public.native_return_operations where id=e.id;intent:=o.request->'intent';perform public.native_reconciliation_validate_intent(intent);
 perform public.native_rx_keys(v,array['version','id','target','authorization_hash','dispense_document_hash','sequence','prior_event_id','prior_record_hash','actor','action','intake_id','allocations','custody','package_condition','storage_history','reason','note','policy','correction_target','discrepancy_id','physical_attestations','reviewed_context_hash','created_at','record_hash']);
 perform public.native_rx_keys(c,array['version','target','authorization_hash','dispense_document_hash','dispensed_at','head','discrepancy_head','original_pickup','correction_head','allocations','intake','replay','discrepancies','stock_review','policy','intent']);
 ds:=controlled_review_v3.read_return_discrepancy_snapshot(c->'discrepancies',to_jsonb(e));
 if c->'discrepancy_head'is distinct from ds->'head'then raise exception 'adapter_source_integrity'using errcode='23514';end if;i:=public.native_reconciliation_intake(p_prior,e.intake_id);
 if o.id is null or o.actor_id<>e.actor_id or o.result is distinct from v or o.created_at is distinct from e.created_at
  or o.request_hash is distinct from public.native_fulfillment_hash(jsonb_build_object('version',2,'actor_id',e.actor_id,'operation','record_native_dispense_return_v2','request',o.request))
  or e.authorization_id::text is distinct from p_dispense->>'authorization_id' or e.pet_id::text is distinct from p_dispense->>'pet_id'
  or v->'version' is distinct from '2'::jsonb or v->>'id' is distinct from e.id::text or v->>'action' is distinct from e.action or v->>'intake_id' is distinct from e.intake_id::text or v->'sequence' is distinct from to_jsonb(e.sequence)
  or v->'target' is distinct from jsonb_build_object('authorization_id',e.authorization_id,'pet_id',e.pet_id,'dispense_id',e.dispense_id)
  or v->>'record_hash' is distinct from e.record_hash or e.record_hash is distinct from public.native_fulfillment_hash(v-'record_hash') or v->'prior_event_id' is distinct from p_head->'event_id' or v->'prior_record_hash' is distinct from p_head->'record_hash'
  or v#>>'{actor,id}' is distinct from e.actor_id::text or v#>>'{actor,authority}' is distinct from (case when e.action in('intake','dispose') then 'active_staff' else 'active_dvm' end)
  or v->>'authorization_hash' is distinct from p_dispense->>'authorization_hash' or v->>'dispense_document_hash' is distinct from public.native_fulfillment_hash(p_dispense) or (v->>'created_at')::timestamptz is distinct from e.created_at
  or v->>'reviewed_context_hash' is distinct from public.native_fulfillment_hash(c) or o.request->>'expected_context_hash' is distinct from v->>'reviewed_context_hash' or o.request->'expected_head' is distinct from p_head or o.request->'expected_discrepancy_head' is distinct from ds->'head'
  -- Snapshot decoder enumerates every retained discrepancy document, binds
  -- actual PK/domain/chronology and rejects any created_at>selected event.
  or o.request->'attest_review' is distinct from 'true'::jsonb or o.request->'attest_restock' is distinct from to_jsonb(e.action='restock') or o.request->'physical_attestations' is distinct from public.native_reconciliation_attestations(e.action) or v->'physical_attestations' is distinct from o.request->'physical_attestations'
  or c->'version' is distinct from '2'::jsonb or c->'target' is distinct from v->'target' or c->'head' is distinct from p_head or c->'replay' is distinct from p_prior or c->'allocations' is distinct from public.native_reconciliation_balances(p_prior) or c->'intake' is distinct from coalesce(i,'null'::jsonb) or c->'discrepancies' is distinct from ds or c->'intent' is distinct from intent
  or c->'authorization_hash' is distinct from v->'authorization_hash' or c->'dispense_document_hash' is distinct from v->'dispense_document_hash' or c->'dispensed_at' is distinct from p_dispense->'dispensed_at'
  or c->'original_pickup' is distinct from coalesce(public.native_correction_pickup(e.dispense_id),'null'::jsonb)
  or v->'correction_target' is distinct from intent->'correction_target' or v->'discrepancy_id' is distinct from intent->'discrepancy_id' or v->'reason' is distinct from intent->'reason' or v->'note' is distinct from intent->'note' or v->'custody' is distinct from intent->'custody' or v->'package_condition' is distinct from intent->'package_condition' or v->'storage_history' is distinct from intent->'storage_history'
 then raise exception 'Reconciliation event evidence mismatch' using errcode='23514';end if;
 if c#>>'{correction_head,version}'='0' then
  if c->'correction_head' is distinct from jsonb_build_object('event_id',null,'version',0,'record_hash',null) then raise exception 'Dispense clarification head mismatch' using errcode='23514';end if;
 elsif not exists(select 1 from jsonb_array_elements(p_corrections->'events')q where q->>'id'=c#>>'{correction_head,event_id}' and q->'sequence'=c#>'{correction_head,version}' and q->>'record_hash'=c#>>'{correction_head,record_hash}') then raise exception 'Dispense clarification head missing' using errcode='23514';end if;
 if e.action like 'retract_%' then
  select * into source from public.native_return_events where id=(v#>>'{correction_target,event_id}')::uuid;
  expected:=case e.action when 'retract_intake' then 'intake' when 'retract_disposal' then 'dispose' else 'restock' end;root:=case when expected='intake' then source.id else source.intake_id end;
  if source.id is null or source.action<>expected or source.dispense_id<>e.dispense_id or source.sequence>=e.sequence or source.record_hash is distinct from v#>>'{correction_target,record_hash}' or root is distinct from e.intake_id then raise exception 'Reconciliation source mismatch' using errcode='23514';end if;
  if v->'discrepancy_id'<>'null'::jsonb and not exists(select 1 from jsonb_array_elements(ds->'cases')q where q->>'id'=v->>'discrepancy_id' and q->>'status'='open' and q->'source'=v->'correction_target') then raise exception 'Correction discrepancy mismatch' using errcode='23514';end if;
 end if;
 if jsonb_array_length(v->'allocations')<>jsonb_array_length(intent->'allocations') then raise exception 'Reconciliation allocation mismatch' using errcode='23514';end if;
 for x in select value from jsonb_array_elements(v->'allocations') loop
  perform public.native_rx_keys(x,array['allocation_id','lot_id','quantity','movement_id']);
  if not exists(select 1 from jsonb_array_elements(intent->'allocations')q where q->>'allocation_id'=x->>'allocation_id' and public.native_fulfillment_quantity(q->'quantity')=(x->>'quantity')::numeric) then raise exception 'Reconciliation quantity mismatch' using errcode='23514';end if;
  if e.action='retract_restock' then
   select * into l from public.native_return_compensation_links where event_id=e.id and allocation_id=(x->>'allocation_id')::uuid;select * into m from public.inventory_movements where id=l.movement_id;select * into sl from public.native_return_stock_links where event_id=source.id and allocation_id=l.allocation_id;
   if l.id is null or m.id is null or sl.id is null or l.target_event_id<>source.id or l.original_movement_id<>sl.movement_id or l.lot_id<>sl.lot_id or m.kind<>'native_return_compensation' or m.quantity<>-l.quantity or m.lot_id<>l.lot_id or l.quantity<>(x->>'quantity')::numeric or x->>'movement_id' is distinct from m.id::text or x->>'lot_id' is distinct from l.lot_id::text or m.created_by<>e.actor_id or m.created_at is distinct from e.created_at then raise exception 'Reconciliation stock compensation mismatch' using errcode='23514';end if;
  elsif e.action='restock' then
   select * into sl from public.native_return_stock_links where event_id=e.id and allocation_id=(x->>'allocation_id')::uuid;select * into m from public.inventory_movements where id=sl.movement_id;
   if sl.id is null or m.id is null or m.kind<>'native_return' or m.quantity<>sl.quantity or m.lot_id<>sl.lot_id or sl.quantity<>(x->>'quantity')::numeric or x->>'movement_id' is distinct from m.id::text or x->>'lot_id' is distinct from sl.lot_id::text or m.created_by<>e.actor_id or m.created_at is distinct from e.created_at then raise exception 'Reconciliation positive stock mismatch' using errcode='23514';end if;
  elsif x->'movement_id' is distinct from 'null'::jsonb then raise exception 'Nonstock reconciliation cannot move inventory' using errcode='23514';end if;
 end loop;
 if (select count(*) from public.native_return_compensation_links where event_id=e.id)<>(case when e.action='retract_restock' then jsonb_array_length(v->'allocations') else 0 end) or (select count(*) from public.native_return_stock_links where event_id=e.id)<>(case when e.action='restock' then jsonb_array_length(v->'allocations') else 0 end) then raise exception 'Unexpected reconciliation stock links' using errcode='23514';end if;
 if e.action='restock' then
  if v->'policy' is distinct from c->'policy' or v->'policy' is distinct from public.native_return_policy_verified((v#>>'{policy,version}')::integer) or v#>'{policy,enabled}' is distinct from 'true'::jsonb or (v#>>'{policy,reviewed_at}')::timestamptz>e.created_at
   or i->>'custody'<>'clinic_retained' or i->>'package_condition'<>'sealed_intact' or i->>'storage_history'<>'controlled' or c->'original_pickup'<>'null'::jsonb
   or c#>'{stock_review,product,active}' is distinct from 'true'::jsonb or c#>>'{stock_review,product,id}' is distinct from p_dispense#>>'{reviewed_context,product,id}' or c#>>'{stock_review,product,unit}' is distinct from p_dispense->>'unit' or c#>>'{stock_review,practice_date}' is distinct from (e.created_at at time zone 'America/Denver')::date::text
   or exists(select 1 from jsonb_array_elements(v->'allocations')a join public.inventory_lots lot on lot.id=(a->>'lot_id')::uuid where lot.expires_on<(c#>>'{stock_review,practice_date}')::date or ds->'held_lot_ids' ? lot.id::text)
  then raise exception 'Positive restock factual guards mismatch' using errcode='23514';end if;
