void","returns_set":false,"rows":0,"security_definer":false,"source":"\n declare child json;\n begin\n  if p_value is null or p_depth is null or p_depth<0 or p_depth>8 then raise exception ''review_claim_context_invalid''using errcode=''23514'';end if;\n  if json_typeof(p_value)=''object''then\n   if(select count(*)from json_each(p_value))>32 or exists(select 1 from json_each(p_value)group by key collate \"C\" having count(*)>1)then\n    raise exception ''review_claim_context_invalid''using errcode=''23514'';end if;\n   for child in select value from json_each(p_value)loop perform controlled_review_v3.protocol_context_unique(child,p_depth+1);end loop;\n  elsif json_typeof(p_value)=''array''then\n   if json_array_length(p_value)>64 then raise exception ''review_claim_context_invalid''using errcode=''23514'';end if;\n   for child in select value from json_array_elements(p_value)loop perform controlled_review_v3.protocol_context_unique(child,p_depth+1);end loop;\n  end if;\n end\n","sql_body":null,"strict":false,"support":"-","variadic":"-","volatility":"v"},"controlled_review_v3.protocol_cursor(p_cursor jsonb, p_request jsonb)":{"acl":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}],"all_argument_types":null,"argument_modes":null,"argument_names":["p_cursor","p_request"],"configuration":["search_path=pg_catalog, public, pg_temp","TimeZone=UTC"],"cost":100,"default_count":0,"defaults":null,"kind":"f","language":"plpgsql","leakproof":false,"owner":"postgres","parallel":"u","return_type":"jsonb","returns_set":false,"rows":0,"security_definer":false,"source":"\ndeclare after_value bigint;high_value bigint;field_name text;\nbegin\n if jsonb_typeof(p_cursor)is distinct from ''object''or octet_length(p_cursor::text)>8192 then\n  raise exception ''cursor_stale''using errcode=''PT409'';end if;\n perform public.controlled_stock_keys(p_cursor,array[''version'',''actor_id'',''product_id'',''site_id'',''event_kind'',''view'',''after_sequence'',''high_water'',''read_eligibility_id'',''read_authorization_hash'']);\n if jsonb_typeof(p_cursor->''version'')is distinct from ''number''or p_cursor->>''version''<>''3''then\n  raise exception ''cursor_stale''using errcode=''PT409'';end if;\n foreach field_name in array array[''actor_id'',''product_id'',''site_id'',''event_kind'',''view'']loop\n  if p_cursor->field_name is distinct from p_request->field_name then raise exception ''cursor_stale''using errcode=''PT409'';end if;\n end loop;\n perform public.controlled_stock_uuid(p_cursor->''read_eligibility_id'');\n if jsonb_typeof(p_cursor->''read_authorization_hash'')is distinct from ''string''or(p_cursor->>''read_authorization_hash'')!~''^[0-9a-f]{64}$''then\n  raise exception ''cursor_stale''using errcode=''PT409'';end if;\n after_value:=controlled_review_v3.protocol_bigint_wire(p_cursor->''after_sequence'');\n high_value:=controlled_review_v3.protocol_bigint_wire(p_cursor->''high_water'');\n if after_value>high_value then raise exception ''cursor_stale''using errcode=''PT409'';end if;\n -- Current product maximum, read version and LIVE authorization fingerprint\n -- require a fresh authorized queue query, not this value-only validator.\n return p_cursor;\nexception when check_violation or invalid_text_representation or numeric_value_out_of_range then\n raise exception ''cursor_stale''using errcode=''PT409'';\nend\n","sql_body":null,"strict":false,"support":"-","variadic":"-","volatility":"v"},"controlled_review_v3.protocol_deadline(p_calendar jsonb, p_anchor timestamp with time zone)":{"acl":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}],"all_argument_types":null,"argument_modes":null,"argument_names":["p_calendar","p_anchor"],"configuration":["search_path=pg_catalog, public, pg_temp","TimeZone=UTC"],"cost":100,"default_count":0,"defaults":null,"kind":"f","language":"plpgsql","leakproof":false,"owner":"postgres","parallel":"u","return_type":"jsonb","returns_set":false,"rows":0,"security_definer":false,"source":"\ndeclare calendar_value jsonb;anchor_row jsonb;next_row jsonb;result_value jsonb;\nbegin\n calendar_value:=controlled_review_v3.validate_configuration_record(p_calendar);\n if calendar_value->''kind''is distinct from ''\"calendar\"''::jsonb or calendar_value->''enabled''is distinct from ''true''::jsonb\n  or p_anchor is null or not isfinite(p_anchor)then\n  raise exception ''review_deadline_invalid''using errcode=''23514'';end if;\n result_value:=jsonb_build_object(''anchor_local_date'',null,''selected_staffed_date'',null,''due_at'',null,\n  ''deadline_basis'',''calendar_unavailable'',''unavailable_reason'',''anchor_outside_calendar_range'');\n if p_anchor<timestamptz ''2026-01-01 00:00:00Z''or p_anchor>=timestamptz ''2101-01-01 00:00:00Z''then return result_value;end if;\n select value into anchor_row from jsonb_array_elements(calendar_value#>''{body,days}'')\n  where p_anchor>=controlled_review_v3.protocol_instant(value->''start_utc'')and p_anchor<controlled_review_v3.protocol_instant(value->''end_utc'');\n if anchor_row is null then return result_value||jsonb_build_object(''unavailable_reason'',''anchor_outside_coverage'');end if;\n result_value:=result_value||jsonb_build_object(''anchor_local_date'',anchor_row->''date'');\n select value into next_row from jsonb_array_elements(calendar_value#>''{body,days}'')\n  where value->>''date''>anchor_row->>''date''and value->''staffed''=''true''::jsonb order by value->>''date''limit 1;\n if next_row is null then return result_value||jsonb_build_object(''unavailable_reason'',''no_later_staffed_day_in_coverage'');end if;\n return result_value||jsonb_build_object(''selected_staffed_date'',next_row->''date'',''due_at'',next_row->''close_utc'',\n  ''deadline_basis'',''configured'',''unavailable_reason'',null);\nend\n","sql_body":null,"strict":false,"support":"-","variadic":"-","volatility":"v"},"controlled_review_v3.protocol_escalation_ids(p_operation_id uuid, p_event_id uuid)":{"acl":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}],"all_argument_types":null,"argument_modes":null,"argument_names":["p_operation_id","p_event_id"],"configuration":["search_path=pg_catalog, public, pg_temp","TimeZone=UTC"],"cost":100,"default_count":0,"defaults":null,"kind":"f","language":"plpgsql","leakproof":false,"owner":"postgres","parallel":"u","return_type":"jsonb","returns_set":false,"rows":0,"security_definer":false,"source":"\n declare reason_value text;hex_value text;id_value uuid;result_value jsonb:=''{}''::jsonb;\n begin\n  perform public.controlled_stock_uuid(to_jsonb(p_operation_id));perform public.controlled_stock_uuid(to_jsonb(p_event_id));\n  for reason_value in select unnest(array[''rejected'',''overdue''])loop\n   hex_value:=encode(sha256(convert_to(E''lrv-review-escalation-id-v1\\n''||p_operation_id::text||E''\\n''||p_event_id::text||E''\\n''||reason_value,''UTF8'')),''hex'');\n   id_value:=(substring(hex_value from 1 for 8)||''-''||substring(hex_value from 9 for 4)||''-''||substring(hex_value from 13 for 4)||''-''||\n    substring(hex_value from 17 for 4)||''-''||substring(hex_value from 21 for 12))::uuid;\n   perform public.controlled_stock_uuid(to_jsonb(id_value));\n   result_value:=result_value||jsonb_build_object(reason_value,id_value);\n  end loop;\n  if result_value->''rejected''=result_value->''overdue''then raise exception ''review_unique_uuid_collision''using errcode=''23514'';end if;\n  -- A preexisting UUID must later be compared under class105. No retry allocator\n  -- or alternate UUID is chosen at a late phase, even for an unused reserve.\n  return result_value;\n end\n","sql_body":null,"strict":false,"support":"-","variadic":"-","volatility":"v"},"controlled_review_v3.protocol_execute_mutation(p_request jsonb)":{"acl":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}],"all_argument_types":null,"argument_modes":null,"argument_names":["p_request"],"configuration":["search_path=pg_catalog, public, pg_temp","TimeZone=UTC"],"cost":100,"default_count":0,"defaults":null,"kind":"f","language":"plpgsql","leakproof":false,"owner":"postgres","parallel":"u","return_type":"jsonb","returns_set":false,"rows":0,"security_definer":false,"source":"\n declare request_value jsonb:=controlled_review_v3.protocol_operation_request(p_request);actor_value uuid;operation_value uuid;\n preparation_value controlled_review_v3.preparations;state_value jsonb;keys_value jsonb;rows_value jsonb;reserved_ids jsonb;\n saved_value controlled_review_v3.decisions;old_rejection_context text;overdue_value controlled_review_v3.escalations;\n begin\n  actor_value:=(request_value->>''actor_id'')::uuid;operation_value:=(request_value->>''operation_id'')::uuid;\n  -- Owned state takes operation then proven original native-family/event gates;\n  -- own saved/cancelled recovery precedes current roster, same-tx and TTL checks.\n  state_value:=controlled_review_v3.protocol_owned_state(request_value);\n  if state_value->>''state''<>''prepared''then return state_value;end if;\n  select *into strict preparation_value from controlled_review_v3.preparations where operation_id=operation_value;\n  if preparation_value.prepared_boot=pg_postmaster_start_time()and preparation_value.prepared_xid=pg_current_xact_id()then\n   raise exception ''review_preparation_requires_prior_transaction''using errcode=''PT409'';end if;\n  -- Reserve the complete possible rejected+overdue union BEFORE any write,\n  -- including an ordinary approval that ultimately needs neither row.\n  reserved_ids:=controlled_review_v3.protocol_escalation_ids(operation_value,preparation_value.event_id);\n  keys_value:=controlled_review_v3.protocol_review_keys(jsonb_build_object(''path'',''decision'',''operation_id'',operation_value,\n   ''adapter'',preparation_value.packet->''adapter'',''escalation_ids'',reserved_ids));\n  perform controlled_review_v3.protocol_acquire_advisory(keys_value,actor_value);\n  rows_value:=controlled_review_v3.protocol_review_rows(jsonb_build_object(''path'',''decision'',''operation_id'',operation_value,\n   ''event_id'',preparation_value.event_id,''configuration_ids'',''{}''::jsonb));\n  perform controlled_review_v3.protocol_acquire_relation_tail(''decision'',rows_value,keys_value,actor_value);\n  perform controlled_review_v3.protocol_acquire_fk_tail(''decision'',rows_value,actor_value);\n  perform controlled_review_v3.ops_reserved_escalations(operation_value,preparation_value.event_id);\n  perform controlled_review_v3.required();\n  -- Every preceding possible wait is complete. Refresh terminal/cancel/TTL and\n  -- actual current roles/config; no obsolete read snapshot authorizes this write.\n  state_value:=controlled_review_v3.protocol_owned_state(request_value);\n  if state_value->>''state''<>''prepared''then return state_value;end if;\n  -- Final real identity/TTL/current-config/P checks and the single accepted\n  -- recording instant belong to the BEFORE writer. No caller server-field or\n  -- pre-wait packet/timestamp is accepted. Late/rejection construction requires the following\n  -- same-transaction reason insertion and reciprocal deferred validation.\n  insert into controlled_review_v3.decisions(operation_id,event_id,actor_id,session_id,actor_name,decision,reason,request_hash,transport_digest,packet_hash,target_hash,recorded_at,receipt)\n  values(operation_value,preparation_value.event_id,actor_value,null,null,preparation_value.decision,preparation_value.reason,\n   null,null,null,null,null,null)returning *into saved_value;\n  if saved_value.decision=''reject''or saved_value.receipt->>''deadline_state''=''completed_late''then\n   old_rejection_context:=current_setting(''controlled_review_v3.rejection_context'',true);\n   perform set_config(''controlled_review_v3.rejection_context'',jsonb_build_object(''operation_id'',saved_value.operation_id,''actor_id'',saved_value.actor_id,''event_id'',saved_value.event_id)::text,true);\n   if saved_value.d