,''actor_id'',''event_id'']);\n perform public.controlled_stock_uuid(value->''operation_id'');perform public.controlled_stock_uuid(value->''actor_id'');perform public.controlled_stock_uuid(value->''event_id'');\n return value;\nend\n","sql_body":null,"strict":false,"support":"-","variadic":"-","volatility":"v"},"controlled_review_v3.protocol_rejection_evidence(p_preparation jsonb, p_decision jsonb)":{"acl":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}],"all_argument_types":null,"argument_modes":null,"argument_names":["p_preparation","p_decision"],"configuration":["search_path=pg_catalog, public, pg_temp","TimeZone=UTC"],"cost":100,"default_count":0,"defaults":null,"kind":"f","language":"plpgsql","leakproof":false,"owner":"postgres","parallel":"u","return_type":"jsonb","returns_set":false,"rows":0,"security_definer":false,"source":"\ndeclare receipt_value jsonb;\nbegin\n receipt_value:=controlled_review_v3.protocol_receipt_from_rows(p_preparation,p_decision);\n if p_decision->''decision''is distinct from ''\"reject\"''::jsonb or receipt_value is distinct from p_decision->''receipt''then raise exception ''review_rejection_evidence_invalid''using errcode=''23514'';end if;\n return jsonb_build_object(''version'',1,''reason'',''rejected'',''event_id'',p_decision->''event_id'',''target_hash'',p_decision->''target_hash'',\n  ''decision_operation_id'',p_decision->''operation_id'',''receipt_hash'',public.controlled_stock_hash(receipt_value));\nend\n","sql_body":null,"strict":false,"support":"-","variadic":"-","volatility":"v"},"controlled_review_v3.protocol_rejection_record(p_row jsonb)":{"acl":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}],"all_argument_types":null,"argument_modes":null,"argument_names":["p_row"],"configuration":["search_path=pg_catalog, public, pg_temp","TimeZone=UTC"],"cost":100,"default_count":0,"defaults":null,"kind":"f","language":"plpgsql","leakproof":false,"owner":"postgres","parallel":"u","return_type":"jsonb","returns_set":false,"rows":0,"security_definer":false,"source":"\ndeclare evidence_value jsonb;stamp timestamptz;row_value jsonb;field text;\nbegin\n if jsonb_typeof(p_row)is distinct from ''object''or octet_length(p_row::text)>131072 then raise exception ''review_rejection_record_invalid''using errcode=''23514'';end if;\n perform public.controlled_stock_keys(p_row,array[''id'',''event_id'',''reason'',''routing_snapshot'',''first_detected_at'',''evidence'',''record_hash'']);\n perform public.controlled_stock_uuid(p_row->''id'');perform public.controlled_stock_uuid(p_row->''event_id'');\n if p_row->''reason''is distinct from ''\"rejected\"''::jsonb or jsonb_typeof(p_row->''first_detected_at'')is distinct from ''string''then raise exception ''review_rejection_record_invalid''using errcode=''23514'';end if;\n stamp:=(p_row->>''first_detected_at'')::timestamptz;perform controlled_review_v3.protocol_utc(stamp);\n evidence_value:=p_row->''evidence'';perform public.controlled_stock_keys(evidence_value,array[''version'',''reason'',''event_id'',''target_hash'',''decision_operation_id'',''receipt_hash'']);\n if evidence_value->''version''is distinct from ''1''::jsonb or evidence_value->''reason''is distinct from ''\"rejected\"''::jsonb\n  or evidence_value->''event_id''is distinct from p_row->''event_id''then raise exception ''review_rejection_record_invalid''using errcode=''23514'';end if;\n perform public.controlled_stock_uuid(evidence_value->''decision_operation_id'');\n foreach field in array array[''target_hash'',''receipt_hash'']loop\n  if jsonb_typeof(evidence_value->field)is distinct from ''string''or(evidence_value->>field)!~''^[0-9a-f]{64}$''then raise exception ''review_rejection_record_invalid''using errcode=''23514'';end if;\n end loop;\n perform controlled_review_v3.protocol_validate_rejection_routing(p_row->''routing_snapshot'',p_row#>''{routing_snapshot,historical}'',stamp);\n row_value:=jsonb_build_object(''id'',p_row->''id'',''event_id'',p_row->''event_id'',''reason'',''rejected'',''routing_snapshot'',p_row->''routing_snapshot'',\n  ''first_detected_at'',controlled_review_v3.protocol_utc(stamp),''evidence'',evidence_value);\n if jsonb_typeof(p_row->''record_hash'')is distinct from ''string''or p_row->>''record_hash''is distinct from public.controlled_stock_hash(row_value)then raise exception ''review_rejection_record_invalid''using errcode=''23514'';end if;\n return row_value||jsonb_build_object(''record_hash'',p_row->''record_hash'');\nexception when invalid_text_representation or datetime_field_overflow then raise exception ''review_rejection_record_invalid''using errcode=''23514'';\nend\n","sql_body":null,"strict":false,"support":"-","variadic":"-","volatility":"v"},"controlled_review_v3.protocol_rejection_routing(p_historical jsonb, p_not_before timestamp with time zone)":{"acl":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}],"all_argument_types":null,"argument_modes":null,"argument_names":["p_historical","p_not_before"],"configuration":["search_path=pg_catalog, public, pg_temp","TimeZone=UTC"],"cost":100,"default_count":0,"defaults":null,"kind":"f","language":"plpgsql","leakproof":false,"owner":"postgres","parallel":"u","return_type":"jsonb","returns_set":false,"rows":0,"security_definer":false,"source":"\ndeclare facts jsonb:=''[]'';snapshot_value jsonb;at_value timestamptz;status_value text;eligible boolean:=false;member jsonb;\nbegin\n perform controlled_review_v3.protocol_utc(p_not_before);\n if p_historical is not null and p_historical<>''null''::jsonb then\n  -- Validate structural inventory BEFORE querying named UUIDs. The final pure\n  -- validator below rechecks every exact roster/role/status/time binding.\n  perform public.controlled_stock_keys(p_historical,array[''version'',''id'',''record_hash'',''enabled'',''members'']);\n  if jsonb_typeof(p_historical->''members'')is distinct from ''array''or jsonb_array_length(p_historical->''members'')>100 then raise exception ''review_rejection_routing_invalid''using errcode=''23514'';end if;\n  for member in select value from jsonb_array_elements(p_historical->''members'')loop\n   perform public.controlled_stock_keys(member,array[''actor_id'',''roles'']);perform public.controlled_stock_uuid(member->''actor_id'');\n  end loop;\n  -- ONE bounded command observes every named member, including inactive ones.\n  -- No row lock, fresh session, wild-card user scan or impersonated JWT.\n  with named as(select value->>''actor_id''as actor_id,value->''roles''as roles from jsonb_array_elements(p_historical->''members'')),\n  observed as(select n.actor_id,n.roles,coalesce(p.id is not null and p.is_active,false)as profile_active,\n   coalesce((select jsonb_agg(role_name order by role_name collate \"C\")from(select distinct r.role::text as role_name from public.user_roles r\n    where p.id is not null and r.user_id=n.actor_id::uuid and r.role::text in(''ADMIN'',''DVM'',''STAFF'',''TECH''))roles),''[]''::jsonb)as live_roles\n   from named n left join public.profiles p on p.id=n.actor_id::uuid)\n  select coalesce(jsonb_agg(jsonb_build_object(''actor_id'',actor_id,''configured_roles'',roles,''profile_active'',profile_active,''live_roles'',live_roles)\n   order by actor_id collate \"C\"),''[]''::jsonb),coalesce(bool_or(profile_active and exists(select 1 from jsonb_array_elements(roles)c(value)\n    join jsonb_array_elements(live_roles)l(value)on c.value=l.value)),false)into facts,eligible from observed;\n  status_value:=case when p_historical->''enabled''=''false''::jsonb then ''disabled_route''when eligible then ''eligible_recipients''else ''no_eligible_recipient''end;\n else status_value:=''missing_route'';end if;\n at_value:=clock_timestamp();\n snapshot_value:=jsonb_build_object(''version'',1,''historical'',coalesce(p_historical,''null''::jsonb),''assessment'',jsonb_build_object(''version'',1,\n  ''recorded_at'',controlled_review_v3.protocol_utc(at_value),''status'',status_value,''member_facts'',facts));\n return controlled_review_v3.protocol_validate_rejection_routing(snapshot_value,p_historical,p_not_before);\nend\n","sql_body":null,"strict":false,"support":"-","variadic":"-","volatility":"v"},"controlled_review_v3.protocol_relation_plan(p_path text, p_rows jsonb)":{"acl":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}],"all_argument_types":null,"argument_modes":null,"argument_names":["p_path","p_rows"],"configuration":["search_path=pg_catalog, public, pg_temp","TimeZone=UTC"],"cost":100,"default_count":0,"defaults":null,"kind":"f","language":"plpgsql","leakproof":false,"owner":"postgres","parallel":"u","return_type":"jsonb","returns_set":false,"rows":0,"security_definer":false,"source":"\ndeclare base_value jsonb:=controlled_review_v3.protocol_path_tables(p_path);\n rows_value jsonb:=controlled_review_v3.protocol_row_targets(p_rows);item jsonb;result_value jsonb;\nbegin\n for item in select value from jsonb_array_elements(rows_value)loop\n  if not exists(select 1 from jsonb_array_elements(base_value)as b(value)where b.value->''relation''=item->''relation'')\n   or(item->''local''=''true''::jsonb and not exists(select 1 from jsonb_array_elements(base_value)as b(value)\n    where b.value->''relation''=item->''relation''and b.value->>''mode''=''ROW EXCLUSIVE''))then\n   raise exception ''review_lock_plan_invalid''using errcode=''23514'';end if;\n end loop;\n with modes as(select value->>''relation''as relation_name,case value->>''mode''when ''ROW EXCLUSIVE''then 3 else 1 end as strength\n  from jsonb_array_elements(base_value)\n union all select value->>''relation'',2 from jsonb_array_elements(rows_value)where value->''local''=''false''::jsonb),\n collapsed as(select relation_name,max(strength)as strength from modes group by relation_name)\n select jsonb_agg(jsonb_build_object(''relation'',relation_name,''mode'',case strength when 3 then ''ROW EXCLUSIVE''\n  when 2 then ''ROW SHARE''else ''ACCESS SHARE''end)order by relation_name collate \"C\")into result_value from collapsed;\n return result_value;\nend\n","sql_body":null,"strict":false,"support":"-","variadic":"-","volatility":"v"},"controlled_review_v3.protocol_request(p_request jsonb)":{"acl":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}],"all_argument_types":null,"argument_modes":null,"argument_names":["p_request"],"configuration":["search_path=pg_catalog, public, pg_temp","TimeZone=UTC"],"cost":100,"default_count":0,"defaults":null,"kind":"f","language":"plpgsql","leakproof":false,"owner":"postgres","parallel":"u","return_type":"jsonb","returns_set":false,"rows":0,"security_definer":false,"source":"\ndeclare field_name text;\nbegin\n if jsonb_typeof(p_request)is distinct from ''object''or octet_length(p_request::text)>131072 then\n  raise exception ''review_request_invalid''using errcode=''23514'';end if;\n perform public.controlled_stock_keys(p_request,array[''actor_id'',''operation_id'',''event_id'',''policy_id'',''read_eligibility_id'',''review_eligibility_id'',''decision'',''reason'']);\n foreach field_name in array array[''actor_id'',''operation_id'',''event_id'',''policy_id'',''read_eligibility_id'',''review_eligibility_id'']loop\n  perform public.controlled_stock_uuid(p_request->field_name);\n end loop;\n if jsonb_typeof(p_request->''decision'')is distinct from ''string''or p_request->>''decision''not in(''approve'',''reject'')then\n  raise exception ''review_request_invalid''using errcode=''23514'';end if;\n perform public.controlled_stock_text(p_request->''reason'',4000,true);\n return p_request;\nexception when check_violation or invalid_text_representation or numeric_value_out_of_range then\n raise exception ''review_request_invalid''using errcode=''23514'';\nend\n","sql_body":null,"strict":false,"support":"-","variadic":"-","volatility":"v"},"controlled_review_v3.protocol_retained_member(p_record jsonb, p_actor_id uuid, p_product_id uuid, p_site_id uuid, p_event_kind text, p_capability text)":{"acl":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}],"all_argument_types":null,"argument_modes":null,"argument_names":["p_record","p_actor_id","p_product_id","p_site_id","p_event_kind","p_capability"],"configuration":["search_path=pg_catalog, public, pg_temp","TimeZone=UTC"],"cost":100,"default_count":0,"defaults":null,"kind":"f","language":"plpgsql","leakproof":false,"owner":"postgres","parallel":"u","return_type":"jsonb","returns_set":false,"rows":0,"security_definer":false,"source":"\n declare record_value jsonb:=controlled_review_v3.validate_configuration_record(p_record);member_value jsonb;\n begin\n  perform public.controlled_stock_uuid(to_jsonb(p_actor_id));\n  if record_value->>''kind''<>''eligibility''or record_value->''enabled''is distinct from ''true''::jsonb\n   or record_value#>>''{scope,product_id}''is distinct from p_product_id::text or record_value#>>''{scope,site_id}''is distinct from p_site_id::text\n   or record_value#>>''{scope,event_kind}''is distinct from p_event_kind or record_value#>>''{scope,capability}''is distinct from p_capability\n   or p_capability not in(''read'',''review'')then raise exception ''review_history_integrity''using errcode=''23514'';end if;\n  select value into member_value from jsonb_array_elements(record_value#>''{body,members}'')where value->>''actor_id''=p_actor_id::text;\n  if member_value is null then raise exception ''review_history_integrity''using errcode=''23514'';end if;\n  return jsonb_build_object(''id'',record_value->''id'',''record_hash'',record_value->''record_hash'',''actor_id'',p_actor_id,''roles'',member_value->''roles'');\n end\n","sql_body":null,"strict":false,"support":"-","variadic":"-","volatility":"v"},"controlled_review_v3.protocol_retained_preparation(p_row jsonb)":{"acl":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}],"all_argument_types":null,"argument_modes":null,"argument_names":["p_row"],"configuration":["search_path=pg_catalog, public, pg_temp","TimeZone=UTC"],"cost":100,"default_count":0,"defaults":null,"kind":"f","language":"plpgsql","leakproof":false,"owner":"postgres","parallel":"u","return_type":"jsonb","returns_set":false,"rows":0,"security_definer":false,"source":"\n declare request_value jsonb;packet_value jsonb;created_value timestamptz;expires_value timestamptz;\n begin\n  perform public.controlled_stock_keys(p_row,array[''operation_id'',''event_id'',''actor_id'',''session_id'',''request'',''request_hash'',''transport_digest'',\n   ''target_hash'',''packet'',''packet_hash'',''policy_id'',''read_eligibility_id'',''review_eligibility_id'',''decision'',''reason'',''prepared_boot'',''prepared_xid'',''created_at'',''expires_at'']);\n  request_value:=controlled_review_v3.protocol_request(p_row->''request'');packet_value:=p_row->''packet'';\n  perform public.controlled_stock_uuid(p_row->''session_id'');\n  perform public.controlled_stock_keys(packet_value,array[''version'',''meaning'',''meaning_text'',''meaning_version'',''target'',''adapter'',''event'',\n   ''parent_preparation'',''original_result'',''clinical_snapshot'',''source_rows'',''event_lines'',''cells'',''transitions'',''containers'',''obligation'',''current_authorization'']);\n  if octet_length(packet_value::text)>1048576 or packet_value->''version''is distinct from ''3''::jsonb\n   or packet_value->''meaning''is distinct from ''\"independent_record_review_v1\"''::jsonb\n   or packet_value->''meaning_text''is distinct from ''\"Independent record review; no claim of personal physical observation.\"''::jsonb\n   or packet_value->''meaning_version''is distinct from ''1''::jsonb\n   or packet_value#>''{adapter,provenance_state}''is distinct from ''\"supported\"''::jsonb\n   or packet_value#>''{event,secondary_review_required}''is distinct from ''true''::jsonb\n   or packet_value#>''{target,event_id}''is distinct from request_value->''event_id''\n   or packet_value#>''{target,original_actor_id}''=request_value->''actor_id''\n   or packet_value#>''{current_authorization,policy,id}''is distinct from request_value->''policy_id''\n   or packet_value#>''{current_authorization,read,id}''is distinct from request_value->''read_eligibility_id''\n   or packet_value#>''{current_authorization,review,id}''is distinct from request_value->''review_eligibility_id''then\n   raise exception ''review_history_integrity''using errcode=''23514'';end if;\n  if exists(select 1 from unnest(array[''operation_id'',''event_id'',''actor_id'',''policy_id'',''read_eligibility_id'',''review_eligibility_id'',''decision'',''reason''])as field\n    where p_row->field is distinct from request_value->field)\n   or p_row->>''request_hash''is distinct from public.controlled_stock_hash(request_value)\n   or p_row->>''transport_digest''is distinct from controlled_review_v3.protocol_transport_digest(request_value)\n   or p_row->>''target_hash''is distinct from public.controlled_stock_hash(packet_value->''target'')\n   or p_row->>''packet_hash''is distinct from public.controlled_stock_hash(packet_value)then\n   raise exception ''review_history_integrity''using errcode=''23514'';end if;\n  -- Raw row timestamptz text is a PostgreSQL projection; derived response text\n  -- is normalized separately. Never treat source display spelling as a seal.\n  if jsonb_typeof(p_row->''created_at'')is distinct from ''string''or jsonb_typeof(p_row->''expires_at'')is distinct from ''string''\n   or jsonb_typeof(p_row->''prepared_boot'')is distinct from ''string''\n   or jsonb_typeof(p_row->''prepared_xid'')is distinct from ''string''or p_row->>''prepared_xid''!~''^[1-9][0-9]{0,19}$''then\n   raise exception ''review_history_integrity''using errcode=''23514'';end if;\n  created_value:=(p_row->>''created_at'')::timestamptz;expires_value:=(p_row->>''expires_at'')::timestamptz;\n  perform controlled_review_v3.protocol_utc(created_value);perform controlled_review_v3.protocol_utc(expires_value);\n  if not isfinite((p_row->>''prepared_boot'')::timestamptz)or(p_row->>''prepared_boot'')::timestamptz>created_value\n   or expires_value is distinct from created_value+interval ''15 minutes''\n   or(p_row->>''prepared_xid'')::numeric>18446744073709551615::numeric then\n   raise exception ''review_history_integrity''using errcode=''23514'';end if;\n  return p_row;\n exception when invalid_text_representation or datetime_field_overflow or numeric_value_out_of_range then\n  raise exception ''review_history_integrity''using errcode=''23514'';\n end\n","sql_body":null,"strict":false,"support":"-","variadic":"-","volatility":"v"},"controlled_review_v3.protocol_review_keys(p_request jsonb)":{"acl":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}],"all_argument_types":null,"argument_modes":null,"argument_names":["p_request"],"configuration":["search_path=pg_catalog, public, pg_temp","TimeZone=UTC"],"cost":100,"default_count":0,"defaults":null,"kind":"f","language":"plpgsql","leakproof":false,"owner":"postgres","parallel":"u","return_type":"jsonb","returns_set":false,"rows":0,"security_definer":false,"source":"\n declare path_value text;operation_value uuid;adapter_value jsonb;target_value jsonb;event_value uuid;family_value uuid;\n site_value uuid;product_value uuid;kind_value text;keys_value jsonb;stream_value jsonb;item jsonb;capability_value text;field text;\n begin\n  perform public.controlled_stock_keys(p_request,array[''path'',''operation_id'',''adapter'',''escalation_ids'']);\n  if jsonb_typeof(p_request->''path'')is distinct from ''string''or p_request->>''path''not in(''prepare'',''decision'',''prepared_cancel'')then\n   raise exception ''review_lock_plan_invalid''using errcode=''23514'';end if;\n  path_value:=p_request->>''path'';operation_value:=public.controlled_stock_uuid(p_request->''operation_id'');adapter_value:=p_request->''adapter'';\n  perform public.controlled_stock_keys(adapter_value,array[''version'',''event_kind'',''adapter_id'',''target'',''site_basis'',''site_id'',''source_refs'',''native_family_dispense_id'',''provenance_state'',''reason'']);\n  target_value:=adapter_value->''target'';perform public.controlled_stock_keys(target_value,array[''event_id'',''product_id'',''sequence'',''record_hash'',''original_actor_id'',''policy_version_id'',''opening_id'',''engine_revision'']);\n  event_value:=public.controlled_stock_uuid(target_value->''event_id'');product_value:=public.controlled_stock_uuid(target_value->''product_id'');\n  family_value:=case when adapter_value->''native_family_dispense_id''=''null''::jsonb then null else public.controlled_stock_uuid(adapter_value->''native_family_dispense_id'')end;\n  site_value:=case when adapter_value->''site_id''=''null''::jsonb then null else public.controlled_stock_uuid(adapter_value->''site_id'')end;\n  kind_value:=adapter_value->>''event_kind'';\n  if site_value is null or adapter_value->''provenance_state''is distinct from ''\"supported\"''::jsonb then\n   raise exception ''unsupported_provenance''using errcode=''23514'';end if;\n  keys_value:=jsonb_build_array(jsonb_build_object(''class_id'',90271101,''key'',''review-v3-operation:''||operation_value::text,''mode'',''exclusive''));\n  -- Family locking uses the original proven native family ID even if no managed\n  -- families row can be created (e.g. supported opening pickup). No second event.\n  if family_value is not null then keys_value:=keys_value||jsonb_build_array(jsonb_build_object(''class_id'',90271102,\n   ''key'',''review-v3-family:''||family_value::text,''mode'',''exclusive''));end if;\n  keys_value:=keys_value||jsonb_build_array(jsonb_build_object(''class_id'',90271103,''key'',''review-v3-event:''||event_value::text,''mode'',''exclusive''));\n  if path_value<>''prepared_cancel''then\n   stream_value:=controlled_review_v3.protocol_stream_key(jsonb_build_object(''kind'',''policy'',''product_id'',product_value,''site_id'',site_value,''event_kind'',null,''capability'',null));\n   keys_value:=keys_value||jsonb_build_array(jsonb_build_object(''class_id'',90271104,''key'',''review-v3-config:''||stream_value::text,''mode'',''shared''));\n   for capability_value in select unnest(array[''read'',''review''])loop\n    stream_value:=controlled_review_v3.protocol_stream_key(jsonb_build_object(''kind'',''eligibility'',''product_id'',product_value,\n     ''site_id'',site_value,''event_kind'',kind_value,''capability'',capability_value));\n    keys_value:=keys_value||jsonb_build_array(jsonb_build_object(''class_id'',90271104,''key'',''review-v3-config:''||stream_value::text,''mode'',''shared''));\n   end loop;\n  end if;\n  if path_value=''decision''then\n   perform public.controlled_stock_keys(p_request->''escalation_ids'',array[''rejected'',''overdue'']);\n   stream_value:=controlled_review_v3.protocol_stream_key(jsonb_build_object(''kind'',''routing'',''product_id'',product_value,''site_id'',site_value,''event_kind'',null,''capability'',null));\n   keys_value:=keys_value||jsonb_build_array(jsonb_build_object(''class_id'',90271104,''key'',''review-v3-config:''||stream_value::text,''mode'',''shared''));\n   if p_request#>''{escalation_ids,rejected}''=p_request#>''{escalation_ids,overdue}''then raise exception ''review_lock_plan_invalid''using errcode=''23514'';end if;\n   for field in select unnest(array[''rejected'',''overdue''])loop\n    perform public.controlled_stock_uuid(p_request#>array[''escalation_ids'',field]);\n    keys_value:=keys_value||jsonb_build_array(jsonb_build_object(''class_id'',90271105,''key'',''review-v3-unique:escalations:''||\n     (p_request#>>array[''escalation_ids'',field]),''mode'',''exclusive''));\n   end loop;\n  elsif p_request->''escalation_ids''is distinct from ''{}''::jsonb then raise exception ''review_lock_plan_invalid''using errcode=''23514'';end if;\n  -- Validate actual hash collisions/strongest mode/total signed ordering now.\n  perform controlled_review_v3.protocol_lock_keys(keys_value);\n  return keys_value;\n end\n","sql_body":null,"strict":false,"support":"-","variadic":"-","volatility":"v"},"controlled_review_v3.protocol_review_route_keys(p_request jsonb)":{"acl":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}],"all_argument_types":null,"argument_modes":null,"argument_names":["p_request"],"configuration":["search_path=pg_catalog, public, pg_temp","TimeZone=UTC"],"cost":100,"default_count":0,"defaults":null,"kind":"f","language":"plpgsql","leakproof":false,"owner":"postgres","parallel":"u","return_type":"jsonb","returns_set":false,"rows":0,"security_definer":false,"source":"\n declare path_value text;operation_value uuid;adapter_value jsonb;target_value jsonb;event_value uuid;family_value uuid;\n site_value uuid;product_value uuid;kind_value text;keys_value jsonb;stream_value jsonb;item jsonb;capability_value text;field text;\n begin\n  perform public.controlled_stock_keys(p_request,array[''path'',''operation_id'',''route'',''escalation_ids'']);\n  if jsonb_typeof(p_request->''path'')is distinct from ''string''or p_request->>''path''not in(''prepare'',''decision'',''prepared_cancel'')then\n   raise exception ''review_lock_plan_invalid''using errcode=''23514'';end if;\n  path_value:=p_request->>''path'';operation_value:=public.controlled_stock_uuid(p_request->''operation_id'');adapter_value:=p_request->''route'';\n  perform public.controlled_stock_keys(adapter_value,array[''target'',''event_kind'',''site_id'',''native_family_dispense_id'',''provenance_state'']);\n  target_value:=adapter_value->''target'';perform public.controlled_stock_keys(target_value,array[''event_id'',''product_id'',''sequence'',''record_hash'',''original_actor_id'',''policy_version_id'',''opening_id'',''engine_revision'']);\n  event_value:=public.controlled_stock_uuid(target_value->''event_id'');product_value:=public.controlled_stock_uuid(target_value->''product_id'');\n  family_value:=case when adapter_value->''native_family_dispense_id''=''null''::jsonb then null else public.controlled_stock_uuid(adapter_value->''native_family_dispense_id'')end;\n  site_value:=case when adapter_value->''site_id''=''null''::jsonb then null else public.controlled_stock_uuid(adapter_value->''site_id'')end;\n  kind_value:=adapter_value->>''event_kind'';\n  if site_value is null or adapter_value->''provenance_state''is distinct from ''\"supported\"''::jsonb then\n   raise exception ''unsupported_provenance''using errcode=''23514'';end if;\n  keys_value:=jsonb_build_array(jsonb_build_object(''class_id'',90271101,''key'',''review-v3-operation:''||operation_value::text,''mode'',''exclusive''));\n  -- Family locking uses the original proven native family ID even if no managed\n  -- families row can be created (e.g. supported opening pickup). No second event.\n  if family_value is not null then keys_value:=keys_value||jsonb_build_array(jsonb_build_object(''class_id'',90271102,\n   ''key'',''review-v3-family:''||family_value::text,''mode'',''exclusive''));end if;\n  keys_value:=keys_value||jsonb_build_array(jsonb_build_object(''class_id'',90271103,''key'',''review-v3-event:''||event_value::text,''mode'',''exclusive''));\n  if path_value<>''prepared_cancel''then\n   stream_value:=controlled_review_v3.protocol_stream_key(jsonb_build_object(''kind'',''policy'',''product_id'',product_value,''site_id'',site_value,''event_kind'',null,''capability'',null));\n   keys_value:=keys_value||jsonb_build_array(jsonb_build_object(''class_id'',90271104,''key'',''review-v3-config:''||stream_value::text,''mode'',''shared''));\n   for capability_value in select unnest(array[''read'',''review''])loop\n    stream_value:=controlled_review_v3.protocol_stream_key(jsonb_build_object(''kind'',''eligibility'',''product_id'',product_value,\n     ''site_id'',site_value,''event_kind'',kind_value,''capability'',capability_value));\n    keys_value:=keys_value||jsonb_build_array(jsonb_build_object(''class_id'',90271104,''key'',''review-v3-config:''||stream_value::text,''mode'',''shared''));\n   end loop;\n  end if;\n  if path_value=''decision''then\n   perform public.controlled_stock_keys(p_request->''escalation_ids'',array[''rejected'',''overdue'']);\n   stream_value:=controlled_review_v3.protocol_stream_key(jsonb_build_object(''kind'',''routing'',''product_id'',product_value,''site_id'',site_value,''event_kind'',null,''capability'',null));\n   keys_value:=keys_value||jsonb_build_array(jsonb_build_object(''class_id'',90271104,''key'',''review-v3-config:''||stream_value::text,''mode'',''shared''));\n   if p_request#>''{escalation_ids,rejected}''=p_request#>''{escalation_ids,overdue}''then raise exception ''review_lock_plan_invalid''using errcode=''23514'';end if;\n   for field in select unnest(array[''rejected'',''overdue''])loop\n    perform public.controlled_stock_uuid(p_request#>array[''escalation_ids'',field]);\n    keys_value:=keys_value||jsonb_build_array(jsonb_build_object(''class_id'',90271105,''key'',''review-v3-unique:escalations:''||\n     (p_request#>>array[''escalation_ids'',field]),''mode'',''exclusive''));\n   end loop;\n  elsif p_request->''escalation_ids''is distinct from ''{}''::jsonb then raise exception ''review_lock_plan_invalid''using errcode=''23514'';end if;\n  -- Validate actual hash collisions/strongest mode/total signed ordering now.\n  perform controlled_review_v3.protocol_lock_keys(keys_value);\n  return keys_value;\n end\n","sql_body":null,"strict":false,"support":"-","variadic":"-","volatility":"v"},"controlled_review_v3.protocol_review_rows(p_request jsonb)":{"acl":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}],"all_argument_types":null,"argument_modes":null,"argument_names":["p_request"],"configuration":["search_path=pg_catalog, public, pg_temp","TimeZone=UTC"],"cost":100,"default_count":0,"defaults":null,"kind":"f","language":"plpgsql","leakproof":false,"owner":"postgres","parallel":"u","return_type":"jsonb","returns_set":false,"rows":0,"security_definer":false,"source":"\n declare path_value text;event_kind_value text;operation_value uuid;event_value uuid;family_value uuid;obligation_value controlled_review_v3.obligations;\n rows_value jsonb:=''[]''::jsonb;field text;id_value uuid;claim_exists boolean;obligation_exists boolean;family_exists boolean;\n begin\n  perform public.controlled_stock_keys(p_request,array[''path'',''operation_id'',''event_id'',''configuration_ids'']);\n  if jsonb_typeof(p_request->''path'')is distinct from ''string''or p_request->>''path''not in(''prepare'',''decision'',''prepared_cancel'',''eventless_cancel'')then\n   raise exception ''review_lock_plan_invalid''using errcode=''23514'';end if;\n  path_value:=p_request->>''path'';operation_value:=public.controlled_stock_uuid(p_request->''operation_id'');\n  if path_value=''eventless_cancel''then\n   if p_request->''event_id''is distinct from ''null''::jsonb or p_request->''configuration_ids''is distinct from ''{}''::jsonb then\n    raise exception ''review_lock_plan_invalid''using errcode=''23514'';end if;\n   if exists(select 1 from controlled_review_v3.preparations where operation_id=operation_value)then\n    raise exception ''review_lock_plan_stale''using errcode=''PT409'';end if;\n   claim_exists:=exists(select 1 from controlled_review_v3.operation_claims where operation_id=operation_value);\n   return controlled_review_v3.protocol_row_targets(jsonb_build_array(jsonb_build_object(''relation'',''controlled_review_v3.operation_claims'',\n    ''key'',jsonb_build_object(''operation_id'',operation_value),''local'',not claim_exists)));\n  end if;\n  event_value:=public.controlled_stock_uuid(p_request->''event_id'');\n  if path_value=''decision''then\n   if p_request->''configuration_ids''is distinct from ''{}''::jsonb then raise exception ''review_lock_plan_invalid''using errcode=''23514'';end if;\n   return controlled_review_v3.protocol_row_targets(jsonb_build_array(\n    jsonb_build_object(''relation'',''controlled_review_v3.obligations'',''key'',jsonb_build_object(''event_id'',event_value),''local'',false),\n    jsonb_build_object(''relation'',''controlled_review_v3.preparations'',''key'',jsonb_build_object(''operation_id'',operation_value),''local'',false)));\n  end if;\n  claim_exists:=exists(select 1 from controlled_review_v3.operation_claims where operation_id=operation_value);\n  rows_value:=rows_value||jsonb_build_array(jsonb_build_object(''relation'',''controlled_review_v3.operation_claims'',''key'',jsonb_build_object(''operation_id'',operation_value),''local'',not claim_exists));\n  if path_value=''prepared_cancel''then\n   if not claim_exists or p_request->''configuration_ids''is distinct from ''{}''::jsonb then raise exception ''review_history_integrity''using errcode=''23514'';end if;\n   return controlled_review_v3.protocol_row_targets(rows_value);\n  end if;\n  perform public.controlled_stock_keys(p_request->''configuration_ids'',array[''policy'',''read'',''review'']);\n  for field in select unnest(array[''policy'',''read'',''review''])loop\n   id_value:=public.controlled_stock_uuid(p_request#>array[''configuration_ids'',field]);\n   rows_value:=rows_value||jsonb_build_array(jsonb_build_object(''relation'',''controlled_review_v3.configuration'',''key'',jsonb_build_object(''id'',id_value),''local'',false));\n  end loop;\n  select *into obligation_value from controlled_review_v3.obligations where event_id=event_value;\n  obligation_exists:=found;\n  rows_value:=rows_value||jsonb_build_array(jsonb_build_object(''relation'',''controlled_review_v3.obligations'',''key'',jsonb_build_object(''event_id'',event_value),''local'',not obligation_exists));\n  -- Full canonical key union is unconditional, including parent and managed\n  -- family even when an obligation already exists. Only initial presence flags\n  -- vary; no xmin/subtransaction/epoch ownership inference is used.\n   rows_value:=rows_value||jsonb_build_array(jsonb_build_object(''relation'',''public.controlled_stock_events'',''key'',jsonb_build_object(''id'',event_value),''local'',false));\n   -- Preview is recomputed only while earlier immutable/family/event gates are\n   -- held by the caller. It never assumes adapter family equals managed family.\n   select event_kind into strict event_kind_value from public.controlled_stock_events where id=event_value;\n   -- Source-exact family branch: obligation_preview only assigns family_id for\n   -- native dispense/pickup. Other20 kinds cannot yield a family; do not rebuild\n   -- their entire immutable adapter merely to rediscover SQL NULL here.\n   if event_kind_value in(''record_native_dispense'',''record_native_pickup'')then\n    family_value:=(controlled_review_v3.protocol_obligation_preview(event_value)->>''family_dispense_id'')::uuid;\n   else family_value:=null;end if;\n   if family_value is not null then\n    family_exists:=exists(select 1 from controlled_review_v3.families where dispense_id=family_value);\n    rows_value:=rows_value||jsonb_build_array(jsonb_build_object(''relation'',''controlled_review_v3.families'',''key'',jsonb_build_object(''dispense_id'',family_value),''local'',not family_exists));\n   end if;\n  return controlled_review_v3.protocol_row_targets(rows_value);\n end\n","sql_body":null,"strict":false,"support":"-","variadic":"-","volatility":"v"},"controlled_review_v3.protocol_review_states(p_request jsonb)":{"acl":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}],"all_argument_types":null,"argument_modes":null,"argument_names":["p_request"],"configuration":["search_path=pg_catalog, public, pg_temp","TimeZone=UTC"],"cost":100,"default_count":0,"defaults":null,"kind":"f","language":"plpgsql","leakproof":false,"owner":"postgres","parallel":"u","return_type":"jsonb","returns_set":false,"rows":0,"security_definer":false,"source":"\ndeclare required_value boolean;adapter_value jsonb;authorization_value jsonb;obligation_value jsonb;historical_value jsonb;\n terminal_value jsonb;as_of_value timestamptz;due_value timestamptz;terminal_time timestamptz;result_value jsonb;\n review_value text;deadline_value text;signing_value text;reason_value text;basis_value text;unavailable_value text;\nbegin\n if jsonb_typeof(p_request)is distinct from ''object''or octet_length(p_request::text)>1048576 then\n  raise exception ''review_history_integrity''using errcode=''23514'';end if;\n perform public.controlled_stock_keys(p_request,array[''secondary_review_required'',''actor_id'',''original_actor_id'',''adapter'',''current_authorization'',''current_policy_status'',''terminal_decision'',''as_of'',''obligation'']);\n perform public.controlled_stock_uuid(p_request->''actor_id'');perform public.controlled_stock_uuid(p_request->''original_actor_id'');\n if jsonb_typeof(p_request->''secondary_review_required'')is distinct from ''boolean''\n  or jsonb_typeof(p_request->''current_policy_status'')is distinct from ''string''\n  or p_request->>''current_policy_status''not in(''missing'',''disabled'',''enabled'')then\n  raise exception ''review_history_integrity''using errcode=''23514'';end if;\n required_value:=(p_request->>''secondary_review_required'')::boolean;adapter_value:=p_request->''adapter'';\n authorization_value:=p_request->''current_authorization'';terminal_value:=p_request->''terminal_decision'';\n obligation_value:=p_request->''obligation'';as_of_value:=controlled_review_v3.protocol_instant(p_request->''as_of'');\n perform public.controlled_stock_keys(authorization_value,array[''policy'',''read'',''review'']);\n if adapter_value#>''{target,original_actor_id}''is distinct from p_request->''original_actor_id''then\n  raise exception ''review_history_integrity''using errcode=''23514'';end if;\n if not required_value then\n  if obligation_value is distinct from ''null''::jsonb or terminal_value is distinct from ''null''::jsonb then\n   raise exception ''review_history_integrity''using errcode=''23514'';end if;\n  return jsonb_build_object(''review_state'',''not_required'',''deadline_state'',''not_required'',''deadline_basis'',''not_required'',\n   ''due_at'',null,''unavailable_reason'',null,''signing_state'',''blocked'',''signing_reason'',''not_required'');\n end if;\n if jsonb_typeof(obligation_value)is distinct from ''object''or obligation_value->''adapter''is distinct from adapter_value\n  or jsonb_typeof(obligation_value->''historical'')is distinct from ''object''then\n  raise exception ''review_history_integrity''using errcode=''23514'';end if;\n historical_value:=obligation_value->''historical'';basis_value:=historical_value->>''deadline_basis'';unavailable_value:=historical_value->>''unavailable_reason'';\n if basis_value is null or basis_value not in(''configured'',''not_configured'',''not_assigned'',''historical_policy_unavailable'',''calendar_unavailable'')\n  or obligation_value->''due_at''is distinct from historical_value->''due_at''then\n  raise exception ''review_history_integrity''using errcode=''23514'';end if;\n if historical_value->''due_at''is distinct from ''null''::jsonb then due_value:=controlled_review_v3.protocol_instant(historical_value->''due_at'');end if;\n if(basis_value=''configured'')is distinct from(due_value is not null)or(due_value is not null and unavailable_value is not null)then\n  raise exception ''review_history_integrity''using errcode=''23514'';end if;\n review_value:=''awaiting_review'';signing_value:=''blocked'';\n if terminal_value is distinct from ''null''::jsonb then\n  perform public.controlled_stock_keys(terminal_value,array[''decision'',''recorded_at'']);\n  if jsonb_typeof(terminal_value->''decision'')is distinct from ''string''or terminal_value->>''decision''not in(''approve'',''reject'')then\n   raise exception ''review_history_integrity''using errcode=''23514'';end if;\n  terminal_time:=controlled_review_v3.protocol_instant(terminal_value->''recorded_at'');\n  review_value:=case when terminal_value->>''decision''=''approve''then ''approved''else ''rejected''end;\n  deadline_value:=case when due_value is null then ''completed_time_unassessable''\n   when terminal_time<=due_value then ''completed_on_time''else ''completed_late''end;\n  signing_value:=''terminal'';reason_value:=''terminal_outcome'';\n else\n  deadline_value:=case when due_value is null then basis_value when as_of_value>due_value then ''overdue''else ''not_due''end;\n  if adapter_value->''provenance_state''is distinct from ''\"supported\"''::jsonb then reason_value:=''unsupported_provenance'';\n  elsif p_request->''actor_id''=p_request->''original_actor_id''then reason_value:=''own_record'';\n  elsif p_request->>''current_policy_status''=''missing''then reason_value:=''no_current_policy'';\n  elsif p_request->>''current_policy_status''=''disabled''or authorization_value->''policy''=''null''::jsonb then reason_value:=''disabled_current_policy'';\n  elsif authorization_value->''read''=''null''::jsonb then reason_value:=''no_read_eligibility'';\n  elsif authorization_value->''review''=''null''::jsonb then reason_value:=''no_review_eligibility'';\n  else signing_value:=''available'';reason_value:=''none'';end if;\n end if;\n return jsonb_build_object(''review_state'',review_value,''deadline_state'',deadline_value,''deadline_basis'',basis_value,\n  ''due_at'',historical_value->''due_at'',''unavailable_reason'',historical_value->''unavailable_reason'',''signing_state'',signing_value,''signing_reason'',reason_value);\nend\n","sql_body":null,"strict":false,"support":"-","variadic":"-","volatility":"v"},"controlled_review_v3.protocol_routing_snapshot(p_record jsonb)":{"acl":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}],"all_argument_types":null,"argument_modes":null,"argument_names":["p_record"],"configuration":["search_path=pg_catalog, public, pg_temp","TimeZone=UTC"],"cost":100,"default_count":0,"defaults":null,"kind":"f","language":"plpgsql","leakproof":false,"owner":"postgres","parallel":"u","return_type":"jsonb","returns_set":false,"rows":0,"security_definer":false,"source":"\ndeclare record_value jsonb;\nbegin\n if p_record is null or p_record=''null''::jsonb then return null;end if;\n record_value:=controlled_review_v3.validate_configuration_record(p_record);\n if record_value->''kind''is distinct from ''\"routing\"''::jsonb then\n  raise exception ''review_history_integrity''using errcode=''23514'';end if;\n return jsonb_build_object(''version'',1,''id'',record_value->''id'',''record_hash'',record_value->''record_hash'',\n  ''enabled'',record_value->''enabled'',''members'',record_value#>''{body,members}'');\nend\n","sql_body":null,"strict":false,"support":"-","variadic":"-","volatility":"v"},"controlled_review_v3.protocol_row_targets(p_rows jsonb)":{"acl":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}],"all_argument_types":null,"argument_modes":null,"argument_names":["p_rows"],"configuration":["search_path=pg_catalog, public, pg_temp","TimeZone=UTC"],"cost":100,"default_count":0,"defaults":null,"kind":"f","language":"plpgsql","leakproof":false,"owner":"postgres","parallel":"u","return_type":"jsonb","returns_set":false,"rows":0,"security_definer":false,"source":"\ndeclare item jsonb;result_value jsonb;\nbegin\n if jsonb_typeof(p_rows)is distinct from ''array''or jsonb_array_length(p_rows)>64\n  or octet_length(p_rows::text)>32768 then raise exception ''review_lock_plan_invalid''using errcode=''23514'';end if;\n for item in select value from jsonb_array_elements(p_rows)loop\n  perform public.controlled_stock_keys(item,array[''relation'',''key'',''local'']);\n  if jsonb_typeof(item->''relation'')is distinct from ''string''or jsonb_typeof(item->''local'')is distinct from ''boolean''then\n   raise exception ''review_lock_plan_invalid''using errcode=''23514'';end if;\n  case item->>''relation''\n  when ''controlled_review_v3.configuration''then perform public.controlled_stock_keys(item->''key'',array[''id'']);perform public.controlled_stock_uuid(item#>''{key,id}'');\n  when ''controlled_review_v3.publications''then perform public.controlled_stock_keys(item->''key'',array[''operation_id'']);perform public.controlled_stock_uuid(item#>''{key,operation_id}'');\n  when ''controlled_review_v3.operation_claims''then perform public.controlled_stock_keys(item->''key'',array[''operation_id'']);perform public.controlled_stock_uuid(item#>''{key,operation_id}'');\n  when ''controlled_review_v3.families''then perform public.controlled_stock_keys(item->''key'',array[''dispense_id'']);perform public.controlled_stock_uuid(item#>''{key,dispense_id}'');\n  when ''controlled_review_v3.obligations''then perform public.controlled_stock_keys(item->''key'',array[''event_id'']);perform public.controlled_stock_uuid(item#>''{key,event_id}'');\n  when ''controlled_review_v3.preparations''then perform public.controlled_stock_keys(item->''key'',array[''operation_id'']);perform public.controlled_stock_uuid(item#>''{key,operation_id}'');\n  when ''controlled_review_v3.escalations''then perform public.controlled_stock_keys(item->''key'',array[''id'']);perform public.controlled_stock_uuid(item#>''{key,id}'');\n  when ''public.controlled_stock_events''then perform public.controlled_stock_keys(item->''key'',array[''id'']);perform public.controlled_stock_uuid(item#>''{key,id}'');\n  else raise exception ''review_lock_plan_invalid''using errcode=''23514'';end case;\n end loop;\n if exists(select 1 from jsonb_array_elements(p_rows)as a(value)join jsonb_array_elements(p_rows)as b(value)\n  on a.value->''relation''=b.value->''relation''and a.value->''key''=b.value->''key''\n  where a.value->''local''is distinct from b.value->''local'')then\n  raise exception ''review_lock_plan_invalid''using errcode=''23514'';end if;\n select coalesce(jsonb_agg(value order by value->>''relation''collate \"C\",(value->''key'')::text collate \"C\"),''[]''::jsonb)\n into result_value from(select distinct value from jsonb_array_elements(p_rows))as deduplicated;\n return result_value;\nend\n","sql_body":null,"strict":false,"support":"-","variadic":"-","volatility":"v"},"controlled_review_v3.protocol_saved_commitment(p_receipt jsonb)":{"acl":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}],"all_argument_types":null,"argument_modes":null,"argument_names":["p_receipt"],"configuration":["search_path=pg_catalog, public, pg_temp","TimeZone=UTC"],"cost":100,"default_count":0,"defaults":null,"kind":"f","language":"plpgsql","leakproof":false,"owner":"postgres","parallel":"u","return_type":"jsonb","returns_set":false,"rows":0,"security_definer":false,"source":"\ndeclare field_name text;recorded_text text;recorded_value timestamp;\nbegin\n if jsonb_typeof(p_receipt)is distinct from ''object''or octet_length(p_receipt::text)>131072 then\n  raise exception ''review_receipt_invalid''using errcode=''23514'';end if;\n perform public.controlled_stock_keys(p_receipt,array[''version'',''operation_id'',''event_id'',''meaning'',''meaning_text'',''meaning_version'',''target'',''target_hash'',''adapter_id'',''site_basis'',''site_id'',''request_hash'',''transport_digest'',''packet_hash'',''obligation_binding_hash'',''historical'',''policy_id'',''policy_hash'',''read_eligibility_id'',''read_eligibility_hash'',''review_eligibility_id'',''review_eligibility_hash'',''actor_id'',''session_id'',''actor_name'',''decision'',''reason'',''recorded_at'',''review_state'',''deadline_state'']);\n if jsonb_typeof(p_receipt->''version'')is distinct from ''number''or p_receipt->>''version''<>''3''\n  or jsonb_typeof(p_receipt->''meaning_version'')is distinct from ''number''or p_receipt->>''meaning_version''<>''1''\n  or p_receipt->''meaning''is distinct from ''\"independent_record_review_v1\"''::jsonb\n  or p_receipt->''meaning_text''is distinct from ''\"Independent record review; no claim of personal physical observation.\"''::jsonb then\n  raise exception ''review_receipt_invalid''using errcode=''23514'';end if;\n foreach field_name in array array[''operation_id'',''event_id'',''site_id'',''policy_id'',''read_eligibility_id'',''review_eligibility_id'',''actor_id'',''session_id'']loop\n  perform public.controlled_stock_uuid(p_receipt->field_name);end loop;\n foreach field_name in array array[''target_hash'',''request_hash'',''transport_digest'',''packet_hash'',''obligation_binding_hash'',''policy_hash'',''read_eligibility_hash'',''review_eligibility_hash'']loop\n  if jsonb_typeof(p_receipt->field_name)is distinct from ''string''or(p_receipt->>field_name)!~''^[0-9a-f]{64}$''then\n   raise exception ''review_receipt_invalid''using errcode=''23514'';end if;end loop;\n perform public.controlled_stock_text(p_receipt->''actor_name'',200,false);\n perform public.controlled_stock_text(p_receipt->''reason'',4000,true);\n if jsonb_typeof(p_receipt->''decision'')is distinct from ''string''or p_receipt->>''decision''not in(''approve'',''reject'')\n  or jsonb_typeof(p_receipt->''review_state'')is distinct from ''string''\n  or p_receipt->>''review_state''is distinct from (case p_receipt->>''decision''when ''approve''then ''approved''else ''rejected''end)\n  or jsonb_typeof(p_receipt->''deadline_state'')is distinct from ''string''\n  or p_receipt->>''deadline_state''not in(''completed_on_time'',''completed_late'',''completed_time_unassessable'')\n  or jsonb_typeof(p_receipt->''adapter_id'')is distinct from ''string''\n  or p_receipt->>''adapter_id''not in(''movement_v1'',''treatment_v1'',''anesthesia_v1'',''dispense_v1'',''pickup_v1'',''return_v1'',''return_v2'',''retraction_v1'',''discrepancy_v1'',''annotation_v1'')\n  or jsonb_typeof(p_receipt->''site_basis'')is distinct from ''string''\n  or p_receipt->>''site_basis''not in(''event_transitions'',''managed_dispense'',''managed_pickup'',''managed_return'',''opening_custody_site'')\n  or jsonb_typeof(p_receipt->''target'')is distinct from ''object''or jsonb_typeof(p_receipt->''historical'')is distinct from ''object''\n  or jsonb_typeof(p_receipt->''recorded_at'')is distinct from ''string''then\n  raise exception ''review_receipt_invalid''using errcode=''23514'';end if;\n recorded_text:=p_receipt->>''recorded_at'';\n if recorded_text!~''^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\\.[0-9]{6}Z$''then\n  raise exception ''review_receipt_invalid''using errcode=''23514'';end if;\n recorded_value:=left(recorded_text,26)::timestamp;\n if not isfinite(recorded_value)or recorded_value<timestamp ''2026-01-01''or recorded_value>=timestamp ''2101-01-01''\n  or to_char(recorded_value,''YYYY-MM-DD\"T\"HH24:MI:SS.US\"Z\"'')<>recorded_text then\n  raise exception ''review_receipt_invalid''using errcode=''23514'';end if;\n -- Only a minimal projection. Caller''s reciprocal history validator must first\n -- prove this is the exact stored receipt for the owned accepted preparation.\n return jsonb_build_object(''version'',3,''actor_id'',p_receipt->''actor_id'',''operation_id'',p_receipt->''operation_id'',\n  ''transport_digest'',p_receipt->''transport_digest'',''decision'',p_receipt->''decision'',''recorded_at'',p_receipt->''recorded_at'',\n  ''receipt_hash'',public.controlled_stock_hash(p_receipt));\nexception when check_violation or invalid_text_representation or invalid_datetime_format or datetime_field_overflow then\n raise exception ''review_receipt_invalid''using errcode=''23514'';\nend\n","sql_body":null,"strict":false,"support":"-","variadic":"-","volatility":"v"},"controlled_review_v3.protocol_select_configuration(p_request jsonb)":{"acl":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}],"all_argument_types":null,"argument_modes":null,"argument_names":["p_request"],"configuration":["search_path=pg_catalog, public, pg_temp","TimeZone=UTC"],"cost":100,"default_count":0,"defaults":null,"kind":"f","language":"plpgsql","leakproof":false,"owner":"postgres","parallel":"u","return_type":"jsonb","returns_set":false,"rows":0,"security_definer":false,"source":"\ndeclare stream_value jsonb;at_value timestamptz;selected_id uuid;\nbegin\n if jsonb_typeof(p_request)is distinct from ''object''or octet_length(p_request::text)>8192 then\n  raise exception ''review_selection_invalid''using errcode=''23514'';end if;\n perform public.controlled_stock_keys(p_request,array[''stream_key'',''at'']);\n stream_value:=controlled_review_v3.protocol_stream_key(p_request->''stream_key'');\n at_value:=controlled_review_v3.protocol_instant(p_request->''at'');\n if stream_value->>''kind''=''policy''then\n  select id into selected_id from controlled_review_v3.configuration\n   where stream_key=stream_value and effective_from<=at_value and published_at<=at_value\n   order by effective_from desc,version desc limit 1;\n else\n  select id into selected_id from controlled_review_v3.configuration\n   where stream_key=stream_value and published_at<=at_value order by version desc limit 1;\n end if;\n if selected_id is null then return null;end if;\n -- No enabled filter: a disabled newest/selected record suppresses prior rows.\n return controlled_review_v3.protocol_configuration_record(selected_id);\nend\n","sql_body":null,"strict":false,"support":"-","variadic":"-","volatility":"v"},"controlled_review_v3.protocol_signing_packet(p_request jsonb, p_packet jsonb)":{"acl":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}],"all_argument_types":null,"argument_modes":null,"argument_names":["p_request","p_packet"],"configuration":["search_path=pg_catalog, public, pg_temp","TimeZone=UTC"],"cost":100,"default_count":0,"defaults":null,"kind":"f","language":"plpgsql","leakproof":false,"owner":"postgres","parallel":"u","return_type":"jsonb","returns_set":false,"rows":0,"security_definer":false,"source":"\n declare request_value jsonb:=controlled_review_v3.protocol_request(p_request);authorization_value jsonb;\n begin\n  authorization_value:=p_packet->''current_authorization'';\n  if p_packet#>''{adapter,provenance_state}''is distinct from ''\"supported\"''::jsonb then\n   raise exception ''unsuppo