lue bigint;through_value bigint;high_value bigint;\nbegin\n if jsonb_typeof(p_request)is distinct from ''object''or octet_length(p_request::text)>131072 then\n  raise exception ''review_request_invalid''using errcode=''23514'';end if;\n if p_kind=''prepare_controlled_record_review_v3''then return controlled_review_v3.protocol_request(p_request);\n elsif p_kind in(''read_controlled_record_review_v3'',''execute_controlled_record_review_v3'',''cancel_controlled_record_review_v3'',''read_controlled_review_publication_v3'')then\n  return controlled_review_v3.protocol_operation_request(p_request);\n elsif p_kind=''get_controlled_record_review_event_v3''then\n  perform public.controlled_stock_keys(p_request,array[''actor_id'',''event_id'']);\n  perform public.controlled_stock_uuid(p_request->''event_id'');\n elsif p_kind=''list_controlled_record_reviews_v3''then\n  perform public.controlled_stock_keys(p_request,array[''actor_id'',''product_id'',''site_id'',''event_kind'',''view'',''page_size'',''cursor'']);\n  perform public.controlled_stock_uuid(p_request->''product_id'');\n  perform controlled_review_v3.protocol_page_size(p_request->''page_size'');\n  if p_request->''view''=''\"site\"''::jsonb then\n   stream_value:=jsonb_build_object(''kind'',''eligibility'',''product_id'',p_request->''product_id'',''site_id'',p_request->''site_id'',''event_kind'',p_request->''event_kind'',''capability'',''read'');\n  elsif p_request->''view''=''\"exceptions\"''::jsonb then\n   stream_value:=jsonb_build_object(''kind'',''eligibility'',''product_id'',p_request->''product_id'',''site_id'',p_request->''site_id'',''event_kind'',p_request->''event_kind'',''capability'',''exception_read'');\n  else raise exception ''review_request_invalid''using errcode=''23514'';end if;\n  perform controlled_review_v3.protocol_stream_key(stream_value);\n  if p_request->''cursor''is distinct from ''null''::jsonb then perform controlled_review_v3.protocol_cursor(p_request->''cursor'',p_request);end if;\n elsif p_kind=''publish_controlled_review_configuration_v3''then\n  perform public.controlled_stock_keys(p_request,array[''actor_id'',''operation_id'',''record_id'',''document'']);\n  perform public.controlled_stock_uuid(p_request->''operation_id'');perform public.controlled_stock_uuid(p_request->''record_id'');\n  perform controlled_review_v3.validate_configuration(p_request->''document'');\n  if p_request#>''{document,kind}''=''\"administration\"''::jsonb then raise exception ''review_request_invalid''using errcode=''23514'';end if;\n elsif p_kind=''get_controlled_review_configuration_v3''then\n  perform public.controlled_stock_keys(p_request,array[''actor_id'',''product_id'',''kind'',''site_id'',''event_kind'',''capability'',''after_version'',''page_size'']);\n  stream_value:=p_request-array[''actor_id'',''after_version'',''page_size''];\n  perform controlled_review_v3.protocol_stream_key(stream_value);\n  perform controlled_review_v3.protocol_page_size(p_request->''page_size'');\n  if jsonb_typeof(p_request->''after_version'')is distinct from ''number''or(p_request->>''after_version'')!~''^(0|[1-9][0-9]{0,9})$''\n   or(p_request->>''after_version'')::numeric>2147483647 then raise exception ''review_request_invalid''using errcode=''23514'';end if;\n elsif p_kind=''record_controlled_review_escalation_action_v3''then\n  perform public.controlled_stock_keys(p_request,array[''actor_id'',''operation_id'',''escalation_id'',''kind'',''note'']);\n  perform public.controlled_stock_uuid(p_request->''operation_id'');perform public.controlled_stock_uuid(p_request->''escalation_id'');\n  if jsonb_typeof(p_request->''kind'')is distinct from ''string''or p_request->>''kind''not in(''acknowledge'',''resolution_note'')then\n   raise exception ''review_request_invalid''using errcode=''23514'';end if;\n  perform public.controlled_stock_text(p_request->''note'',4000,true);\n elsif p_kind=''get_controlled_review_backlog_v3''then\n  perform public.controlled_stock_keys(p_request,array[''act