ent public.inventory_movements;selected_movement record;link public.controlled_stock_source_links;parent public.controlled_stock_events;opening public.controlled_stock_openings;\n did uuid;managed_dispense jsonb;entry jsonb;n integer:=0;sourced integer:=0;root_count integer;expected_writer text;expected_kind text;\nbegin\n captured:=controlled_review_v3.read_return_capture(p_event_id,p_product_id);e:=jsonb_populate_record(null::public.native_return_events,captured->''event'');did:=e.dispense_id;\n expected_writer:=case e.document->>''version''when''1''then''record_native_dispense_return''when''2''then''record_native_dispense_return_v2''end;expected_kind:=case e.action when''retract_restock''then''native_return_compensation''else''native_return''end;\n managed_dispense:=controlled_review_v3.read_native_source_event(''dispense'',did,p_product_id);\n select *into native_provenance from public.stock_custody_sources where event_id=e.id;\n if native_provenance.event_id is not null and(native_provenance.actor_id is distinct from e.actor_id or native_provenance.writer<>expected_writer)then raise exception ''adapter_source_integrity''using errcode=''23514'';end if;\n for selected_movement in select l.movement_id,l.lot_id,l.quantity from public.native_return_stock_links l where e.action=''restock''and l.event_id=e.id union all select l.movement_id,l.lot_id,-l.quantity from public.native_return_compensation_links l where e.action=''retract_restock''and l.event_id=e.id order by movement_id limit 101 loop\n  n:=n+1;if n>100 then raise exception ''evidence_limit_exceeded''using errcode=''54000'';end if;\n  select *into movement from public.inventory_movements where id=selected_movement.movement_id;\n  if movement.id is null or movement.lot_id<>selected_movement.lot_id or movement.quantity<>selected_movement.quantity or movement.created_by is distinct from e.actor_id or movement.kind<>expected_kind then raise exception ''adapter_source_integrity''using errcode=''23514'';end if;\n  select *into provenance from public.stock_movement_sources where movement_id=movement.id;\n  if provenance.movement_id is not null then\n   sourced:=sourced+1;\n   if provenance.source_id<>e.id or provenance.writer<>expected_writer or provenance.actor_id is distinct from e.actor_id then raise exception ''adapter_source_integrity''using errcode=''23514'';end if;\n   perform controlled_review_v3.read_stock_source(provenance.movement_id);\n  end if;\n end loop;\n if(e.action in(''restock'',''retract_restock'')and(n=0 or n<>jsonb_array_length(e.document->''allocations'')))or sourced not in(0,n)then raise exception ''adapter_source_integrity''using errcode=''23514'';end if;\n select count(*)into root_count from(select movement_id from public.stock_movement_sources where writer=expected_writer and source_id=e.id limit 101)q;\n if root_count>100 then raise exception ''evidence_limit_exceeded''using errcode=''54000'';end if;\n if root_count<>sourced or exists(select 1 from public.stock_movement_sources s where s.writer=expected_writer and s.source_id=e.id and not exists(select 1 from public.native_return_stock_links l where e.action=''restock''and l.event_id=e.id and l.movement_id=s.movement_id)and not exists(select 1 from public.native_return_compensation_links l where e.action=''retract_restock''and l.event_id=e.id and l.movement_id=s.movement_id))then raise exception ''adapter_source_integrity''using errcode=''23514'';end if;\n select *into opening from public.controlled_stock_openings where product_id=p_product_id;\n select *into link from public.controlled_stock_source_links where return_event_id=e.id;\n if link.id is not null then\n  select *into parent from public.controlled_stock_events where id=link.event_id;\n  if native_provenance.event_id is null or sourced<>n or parent.id is distinct from e.id or parent.product_id is distinct from p_product_id or parent.writer<>expected_writer or parent.actor_id is distinct from e.actor_id\n   or parent.event_kind is distinct from expected_writer||'':''||e.action or(opening.id is not null and parent.opening_id is distinct from opening.id)\n   or parent.source_bundle#>>''{native,kind}''is distinct from''return''or parent.source_bundle#>>''{native,id}''is distinct from e.id::text then raise exception ''adapter_source_integrity''using errcode=''23514'';end if;\n  perform controlled_review_v3.read_validate_scalar(parent.id);\n  return jsonb_build_object(''event_id'',parent.id,''source_link_ids'',jsonb_build_array(link.id));\n end if;\n if exists(select 1 from public.controlled_stock_events where id=e.id)then raise exception ''adapter_source_integrity''using errcode=''23514'';end if;\n if opening.id is not null then\n  if managed_dispense is not null or jsonb_typeof(opening.native_custody_boundary)is distinct from''array''or jsonb_array_length(opening.native_custody_boundary)>200 then raise exception ''adapter_source_integrity''using errcode=''23514'';end if;\n  select value into entry from jsonb_array_elements(opening.native_custody_boundary)where value->>''dispense_id''=did::text;\n  if entry is null or e.sequence>public.controlled_stock_opening_selector(entry->''return_head'')then raise exception ''adapter_source_integrity''using errcode=''23514'';end if;\n end if;\n return null;\nend\n","sql_body":null,"strict":false,"support":"-","variadic":"-","volatility":"s"},"controlled_review_v3.read_return_v1_capture(p_event_id uuid, p_product_id uuid)":{"acl":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}],"all_argument_types":null,"argument_modes":null,"argument_names":["p_event_id","p_product_id"],"configuration":["search_path=pg_catalog, public, pg_temp","TimeZone=UTC"],"cost":100,"default_count":0,"defaults":null,"kind":"f","language":"plpgsql","leakproof":false,"owner":"postgres","parallel":"u","return_type":"jsonb","returns_set":false,"rows":0,"security_definer":false,"source":"\ndeclare projected jsonb;d jsonb;target jsonb;head jsonb;corrections jsonb:=''{\"events\":[]}''::jsonb;prior_state jsonb;\n e public.native_return_events;o public.native_return_operations;previous_row public.native_return_events;correction public.native_dispense_correction_events;\n authorization_value uuid;pet_value uuid;dispense_value uuid;v jsonb;c jsonb;intent jsonb;x jsonb;b jsonb;i jsonb;balances jsonb;prev timestamptz;\n orig public.native_dispense_allocations;m public.inventory_movements;link public.native_return_stock_links;expected jsonb;\nbegin\n projected:=controlled_review_v3.read_return_v1_context(p_event_id,p_product_id);\n select *into e from public.native_return_events where id=p_event_id;select *into o from public.native_return_operations where id=e.id;\n d:=projected#>''{dispense,dispense,document}'';prior_state:=projected->''prior_projection'';v:=e.document;c:=e.reviewed_context;intent:=o.request->''intent'';\n authorization_value:=(d->>''authorization_id'')::uuid;pet_value:=(d->>''pet_id'')::uuid;dispense_value:=(d->>''id'')::uuid;\n target:=jsonb_build_object(''authorization_id'',authorization_value,''pet_id'',pet_value,''dispense_id'',dispense_value);\n head:=jsonb_build_object(''event_id'',null,''version'',0,''record_hash'',null);\n if e.prior_event_id is not null then\n  select *into previous_row from public.native_return_events where id=e.prior_event_id;\n  if previous_row.id is null or previous_row.dispense_id is distinct from e.dispense_id or previous_row.authorization_id is distinct from e.authorization_id\n   or previous_row.pet_id is distinct from e.pet_id or previous_row.sequence<>e.sequence-1\n   or previous_row.record_hash is distinct from public.native_fulfillment_hash(previous_row.document-''record_hash'')\n   or previous_row.document->>''id''is distinct from previous_row.id::text or previous_row.document->''sequence''is distinct from to_jsonb(previous_row.sequence)\n   or previous_row.document->''target''is distinct from target then raise exception ''adapter_source_integrity''using errcode=''23514'';end if;\n  head:=jsonb_build_object(''event_id'',previous_row.id,''version'',previous_row.sequence,''record_hash'',previous_row.record_hash);prev:=previous_row.created_at;\n elsif e.sequence<>1 then raise exception ''adapter_source_integrity''using errcode=''23514'';end if;\n -- Full current correction replay is unnecessary for this one retained head.\n -- H0/W supplies prefix completeness; selected PK/domain/sequence/hash binding\n -- and every original native-return selected step predicate remain explicit.\n if c#>>''{correction_head,version}''<>''0''then\n  select *into correction from public.native_dispense_correction_events where id=(c#>>''{correction_head,event_id}'')::uuid;\n  if correction.id is null or correction.dispense_id is distinct from e.dispense_id or correction.authorization_id is distinct from e.authorization_id or correction.pet_id is distinct from e.pet_id\n   or correction.sequence is distinct from(c#>>''{correction_head,version}'')::integer or correction.record_hash is distinct from c#>>''{correction_head,record_hash}''\n   or correction.record_hash is distinct from public.native_fulfillment_hash(correction.document-''record_hash'')or correction.document->>''id''is distinct from correction.id::text\n   or correction.document->''target''is distinct from target then raise exception ''adapter_source_integrity''using errcode=''23514'';end if;\n  perform controlled_review_v3.read_correction_capture(correction.id,p_product_id);\n  corrections:=jsonb_build_object(''events'',jsonb_build_array(correction.document));\n end if;\n  perform public.native_return_validate_intent(intent);\n  perform public.native_rx_keys(v,array[''version'',''id'',''target'',''authorization_hash'',''dispense_document_hash'',''sequence'',''prior_event_id'',''prior_record_hash'',''actor'',''action'',''intake_id'',''allocations'',''custody'',''package_condition'',''storage_history'',''reason'',''note'',''policy'',''reviewed_context_hash'',''created_at'',''record_hash'']);\n  balances:=public.native_reconciliation_balances(prior_state);i:=public.native_reconciliation_intake(prior_state,e.intake_id);\n  if o.id is null or o.actor_id<>e.actor_id or o.result is distinct from v or o.created_at is distinct from e.created_at\n   or o.request_hash is distinct from public.native_fulfillment_hash(jsonb_build_object(''version'',1,''actor_id'',o.actor_id,''operation'',''record_native_dispense_return'',''request'',o.request))\n   or e.authorization_id<>authorization_value or e.pet_id<>pet_value or e.sequence<>(head->>''version'')::integer+1 or e.prior_event_id::text is distinct from head->>''event_id''\n   or v->''version'' is distinct from ''1''::jsonb or v->>''id'' is distinct from e.id::text or v->''target'' is distinct from target or v->>''sequence'' is distinct from e.sequence::text\n   or v->>''prior_event_id'' is distinct from head->>''event_id'' or v->>''prior_record_hash'' is distinct from head->>''record_hash'' or v#>>''{actor,id}'' is distinct from e.actor_id::text\n   or v->>''action'' is distinct from e.action or v->>''intake_id'' is distinct from e.intake_id::text or (v->>''created_at'')::timestamptz is distinct from e.created_at\n   or v->>''authorization_hash'' is distinct from d->>''authorization_hash'' or v->>''dispense_document_hash'' is distinct from public.native_fulfillment_hash(d)\n   or e.record_hash is distinct from v->>''record_hash'' or e.record_hash is distinct from public.native_fulfillment_hash(v-''record_hash'')\n   or v->>''reviewed_context_hash'' is distinct from public.native_fulfillment_hash(c) or o.request->>''expected_context_hash'' is distinct from v->>''reviewed_context_hash'' or o.request->''expected_head'' is distinct from head\n   or o.request->''attest_review'' is distinct from ''true''::jsonb or o.request->''attest_restock'' is distinct from to_jsonb(e.action=''restock'')\n   or c->''target'' is distinct from target or c->''head'' is distinct from head or c->''intent'' is distinct from intent or c->''allocations'' is distinct from balances or c->''intake'' is distinct from coalesce(i,''null''::jsonb)\n   or c->>''authorization_hash'' is distinct from d->>''authorization_hash'' or c->>''dispense_document_hash'' is distinct from public.native_fulfillment_hash(d) or c->''dispensed_at'' is distinct from d->''dispensed_at''\n   or intent->''target'' is distinct from target or intent->>''action'' is distinct from e.action or intent->>''intake_id'' is distinct from e.intake_id::text\n   or v->''reason'' is distinct from intent->''reason'' or v->''note'' is distinct from intent->''note'' or v->''custody'' is distinct from intent->''custody'' or v->''package_condition'' is distinct from intent->''package_condition'' or v->''storage_history'' is distinct from intent->''storage_history''\n   or e.created_at<(d->>''dispensed_at'')::timestamptz or (prev is not null and e.created_at<prev)\n  then raise exception ''Native return integrity mismatch'' using errcode=''23514'';end if;\n  perform public.native_rx_keys(c,array[''version'',''target'',''authorization_hash'',''dispense_document_hash'',''dispensed_at'',''head'',''original_pickup'',''correction_head'',''allocations'',''intake'',''stock_review'',''policy'',''intent'']);\n  perform public.native_rx_keys(v->''actor'',array[''id'',''name'',''authority'']);perform public.native_rx_text(v#>''{actor,name}'',200);\n  if v#>>''{actor,authority}'' is distinct from (case when e.action=''restock'' then ''active_dvm'' else ''active_staff'' end) or c->''version'' is distinct from ''1''::jsonb then raise exception ''Native return authority mismatch'' using errcode=''23514'';end if;\n  if c->''original_pickup'' is distinct from coalesce(public.native_correction_pickup(dispense_value),''null''::jsonb) then raise exception ''Native return pickup evidence mismatch'' using errcode=''23514'';end if;\n  if c#>>''{correction_head,version}''=''0'' then\n   if c->''correction_head'' is distinct from jsonb_build_object(''event_id'',null,''version'',0,''record_hash'',null) then raise exception ''Native return correction evidence mismatch'' using errcode=''23514'';end if;\n  elsif not exists(select 1 from jsonb_array_elements(corrections->''events'')ce where ce->>''id''=c#>>''{correction_head,event_id}'' and ce->''sequence''=c#>''{correction_head,version}'' and ce->>''record_hash''=c#>>''{correction_head,record_hash}'') then raise exception ''Native return correction evidence mismatch'' using errcode=''23514'';end if;\n  if e.action<>''intake'' and (i is null or not exists(select 1 from public.native_return_events src where src.id=e.intake_id and src.dispense_id=dispense_value and src.action=''intake'' and src.sequence<e.sequence and src.created_at<=e.created_at)) then raise exception ''Native return intake reference mismatch'' using errcode=''23514'';end if;\n  if jsonb_array_length(v->''allocations'')<>jsonb_array_length(intent->''allocations'') then raise exception ''Native return allocation mismatch'' using errcode=''23514'';end if;\n  for x in select value from jsonb_array_elements(v->''allocations'') loop\n   perform public.native_rx_keys(x,array[''allocation_id'',''lot_id'',''quantity'',''movement_id'']);select * into orig from public.native_dispense_allocations where id=(x->>''allocation_id'')::uuid and dispense_id=dispense_value;\n   select value into b from jsonb_array_elements(balances) where value->>''allocation_id''=x->>''allocation_id'';\n   if orig.id is null or x->>''lot_id''<>orig.lot_id::text or x->>''quantity'' is distinct from public.native_fulfillment_decimal(public.native_fulfillment_quantity(x->''quantity''))\n    or not exists(select 1 from jsonb_array_elements(intent->''allocations'') inp where inp->>''allocation_id''=orig.id::text and public.native_fulfillment_quantity(inp->''quantity'')=(x->>''quantity'')::numeric)\n    or (e.action=''intake'' and (x->>''quantity'')::numeric>(b->>''remaining_returnable_quantity'')::numeric)\n    or (e.action<>''intake'' and not exists(select 1 from jsonb_array_elements(i->''allocations'') ia where ia->>''allocation_id''=orig.id::text and (ia->>''held_quantity'')::numeric>=(x->>''quantity'')::numeric))\n   then raise exception ''Native return allocation cap mismatch'' using errcode=''23514'';end if;\n   if e.action=''restock'' then\n    select * into link from public.native_return_stock_links where event_id=e.id and allocation_id=orig.id;select * into m from public.inventory_movements where id=link.movement_id;\n    if link.id is null or m.id is null or link.lot_id<>orig.lot_id or link.quantity<>(x->>''quantity'')::numeric or x->>''movement_id'' is distinct from m.id::text or m.kind<>''native_return'' or m.lot_id<>orig.lot_id or m.quantity<>link.quantity or m.created_by<>e.actor_id or m.created_at is distinct from e.created_at then raise exception ''Native return stock linkage mismatch'' using errcode=''23514'';end if;\n   elsif x->''movement_id'' is distinct from ''null''::jsonb then raise exception ''Held or disposed return cannot move available stock'' using errcode=''23514'';end if;\n  end loop;\n  select coalesce(jsonb_agg(allocation_row.value order by allocation_row.value->>''allocation_id''),''[]'') into expected from jsonb_array_elements(v->''allocations'') as allocation_row(value);\n  if expected is distinct from v->''allocations'' or (select count(*)<>count(distinct allocation_row.value->>''allocation_id'') from jsonb_array_elements(v->''allocations'') as allocation_row(value)) or (select count(*) from public.native_return_stock_links where event_id=e.id)<>(case when e.action=''restock'' then jsonb_array_length(v->''allocations'') else 0 end) then raise exception ''Native return stock allocation ordering mismatch'' using errcode=''23514'';end if;\n  if e.action=''restock'' then\n   if v->''policy'' is distinct from c->''policy'' or v->''policy'' is distinct from public.native_return_policy_verified((v#>>''{policy,version}'')::integer) or v#>''{policy,enabled}'' is distinct from ''true''::jsonb\n    or (v#>>''{poli