controlled_review_v3.ops_backlog(p_reque.source:
declare request_value jsonb;actor_value uuid;product_value uuid;stream_value jsonb;keys_value jsonb;authority_value jsonb;final_authority jsonb;page_value jsonb;
begin
 if octet_length(p_request::text)>8192 then raise exception 'review_request_invalid'using errcode='23514';end if;
 request_value:=controlled_review_v3.protocol_validate_wire(p_request,'get_controlled_review_backlog_v3');actor_value:=(request_value->>'actor_id')::uuid;product_value:=(request_value->>'product_id')::uuid;
 perform controlled_review_v3.ops_admin_preflight();perform controlled_review_v3.read_prelude(actor_value);
 stream_value:=controlled_review_v3.protocol_stream_key(jsonb_build_object('kind','administration','product_id',product_value,'site_id',null,'event_kind',null,'capability',null));
 keys_value:=jsonb_build_array(jsonb_build_object('class_id',90271104,'key','review-v3-config:'||stream_value::text,'mode','shared'));
 perform controlled_review_v3.protocol_acquire_advisory(keys_value,actor_value);perform controlled_review_v3.ops_admin_read_tail(actor_value);
 authority_value:=controlled_review_v3.ops_admin_authority(actor_value,product_value,'audit');
 -- ONE STABLE page command observes the frozen endpoint/checkpoint, bounded
 -- parent rows and retained history together; authorization is fresh outside it.
 page_value:=controlled_review_v3.ops_backlog_page(request_value);perform controlled_review_v3.required();
 final_authority:=controlled_review_v3.ops_admin_authority(actor_value,product_value,'audit');
 if final_authority is distinct from authority_value then raise exception 'configuration_changed'using errcode='PT409';end if;
 return jsonb_build_object('version',3,'state','page','data',page_value);
end

controlled_review_v3.ops_backlog_page(p_.source:
declare product_value uuid:=(p_request->>'product_id')::uuid;after_value bigint:=(p_request->>'after_sequence')::bigint;size_value integer:=(p_request->>'page_size')::integer;
 high_value bigint;checkpoint bigint;e public.controlled_stock_events;o jsonb;m controlled_review_v3.materializations;d controlled_review_v3.decisions;p controlled_review_v3.preparations;
 items jsonb:='[]';escalations jsonb;s controlled_review_v3.escalations;review_value text;provenance_value text;basis_value text;reason_value text;n integer:=0;last_value bigint;receipt_value jsonb;
begin
 select sequence into high_value from public.controlled_stock_events where product_id=product_value order by sequence desc limit 1;
 select through_sequence into checkpoint from controlled_review_v3.scan_receipts where product_id=product_value order by through_sequence desc limit 1;
 for e in select *from public.controlled_stock_events where product_id=product_value and sequence>after_value and sequence<=coalesce(high_value,0)order by sequence limit size_value loop
  n:=n+1;last_value:=e.sequence;o:=controlled_review_v3.read_obligation_dto(e.id);provenance_value:=null;basis_value:=null;reason_value:='not_materialized';
  review_value:=case when e.secondary_review_required then 'awaiting_review'else 'not_required'end;
  if o is not null then
   if not e.secondary_review_required or o->'product_id'is distinct from to_jsonb(product_value)or o->>'event_sequence'is distinct from e.sequence::text then raise exception 'review_history_integrity'using errcode='23514';end if;
   provenance_value:=o#>>'{adapter,provenance_state}';basis_value:=o#>>'{historical,deadline_basis}';reason_value:=o#>>'{historical,unavailable_reason}';
  else
   select *into m from controlled_review_v3.materializations where product_id=product_value and event_id=e.id order by operation_id limit 1;
   if found then
    perform controlled_review_v3.ops_materialization_record(to_jsonb(m));
    if e.secondary_review_required or m.result->>'state'<>'not_required'then raise exception 'review_history_integrity'using errcode='23514';end if;
    provenance_value:=m.result#>>'{availability,provenance_state}';basis_value:=m.result#>>'{availability,deadline_basis}';reason_value:=m.result#>>'{availability,unavailable_reason}';
   end if;
  end if;
  select *into d from controlled_review_v3.decisions where event_id=e.id;
  if found then
   if o is null then raise exception 'review_history_integrity'using errcode='23514';end if;
   select *into strict p from controlled_review_v3.preparations where operation_id=d.operation_id;
   receipt_value:=controlled_review_v3.protocol_receipt_from_rows(to_jsonb(p),to_jsonb(d));
   if d.receipt is distinct from receipt_value then raise exception 'review_history_integrity'using errcode='23514';end if;
   review_value:=case when d.decision='approve'then 'approved'else 'rejected'end;
  end if;
  escalations:='[]';
  for s in select *from controlled_review_v3.escalations where event_id=e.id order by reason collate "C" limit 7 loop
   if o is null or jsonb_array_length(escalations)>=6 then raise exception 'review_history_integrity'using errcode='23514';end if;
   perform controlled_review_v3.ops_escalation_record(to_jsonb(s));
   escalations:=escalations||jsonb_build_array(jsonb_build_object('id',s.id,'reason',s.reason,'first_detected_at',controlled_review_v3.protocol_utc(s.first_detected_at)));
  end loop;
  items:=items||jsonb_build_array(jsonb_build_object('event_sequence',e.sequence::text,'event_kind',e.event_kind,'review_state',review_value,
   'provenance_state',provenance_value,'deadline_basis',basis_value,'unavailable_reason',reason_value,'escalations',escalations));
 end loop;
 return jsonb_build_object('items',items,'next_sequence',case when n=size_value and last_value<high_value then last_value::text else null end,
  'materialized_through',coalesce(checkpoint,0)::text,'high_water',coalesce(high_value,0)::text);
end

controlled_review_v3.ops_configuration_a.source:
declare request_value jsonb:=controlled_review_v3.protocol_validate_wire(p_request,'get_controlled_review_configuration_v3');
 actor_value uuid;product_value uuid;stream_value jsonb;admin_stream jsonb;keys_value jsonb;authority_value jsonb;final_authority jsonb;
 row_value record;record_value jsonb;records_value jsonb:='[]';size_value integer;after_value integer;count_value integer:=0;last_value integer;next_value integer;
begin
 actor_value:=(request_value->>'actor_id')::uuid;product_value:=(request_value->>'product_id')::uuid;
 stream_value:=controlled_review_v3.protocol_stream_key(request_value-array['actor_id','after_version','page_size']);
 admin_stream:=controlled_review_v3.protocol_stream_key(jsonb_build_object('kind','administration','product_id',product_value,'site_id',null,'event_kind',null,'capability',null));
 size_value:=controlled_review_v3.protocol_page_size(request_value->'page_size');after_value:=(request_value->>'after_version')::integer;
 perform controlled_review_v3.ops_admin_preflight();perform controlled_review_v3.read_prelude(actor_value);
 keys_value:=jsonb_build_array(jsonb_build_object('class_id',90271104,'key','review-v3-config:'||admin_stream::text,'mode','shared'),
  jsonb_build_object('class_id',90271104,'key','review-v3-config:'||stream_value::text,'mode','shared'));
 perform controlled_review_v3.protocol_acquire_advisory(keys_value,actor_value);
 perform controlled_review_v3.ops_admin_read_tail(actor_value);
 authority_value:=controlled_review_v3.ops_admin_authority(actor_value,product_value,'audit');
 -- Leading UNIQUE(stream_key,version), bounded cap+1. Disabled rows and future
 -- effective policy records remain visible; this is audit, not selection.
 for row_value in select id,version from controlled_review_v3.configuration
  where stream_key=stream_value and version>after_value order by version limit(size_value+1)loop
  count_value:=count_value+1;
  if count_value>size_value then next_value:=last_value;exit;end if;
  record_value:=controlled_review_v3.protocol_validate_publication_record(row_value.id);
  records_value:=records_value||jsonb_build_array(record_value);last_value:=row_value.version;
 end loop;
 perform controlled_review_v3.required();
 final_authority:=controlled_review_v3.ops_admin_authority(actor_value,product_value,'audit');
 if final_authority is distinct from authority_value then raise exception 'configuration_changed'using errcode='PT409';end if;
 return jsonb_build_object('version',3,'state','page','data',jsonb_build_object('records',records_value,'next_version',next_value));
end

controlled_review_v3.ops_construct_termi.source:
declare context_value jsonb;operation_value uuid;actor_value uuid;event_value uuid;id_value uuid;ids_value jsonb;keys_value jsonb;rows_value jsonb;
 decision_value controlled_review_v3.decisions;preparation_value controlled_review_v3.preparations;obligation_value controlled_review_v3.obligations;
 identity_value jsonb;row_value jsonb;evidence_value jsonb;routing_value jsonb;
begin
 if jsonb_typeof(p_new)is distinct from 'object'or octet_length(p_new::text)>8192 then raise exception 'review_overdue_context_invalid'using errcode='23514';end if;
 perform public.controlled_stock_keys(p_new,array['id','event_id','reason','routing_snapshot','first_detected_at','evidence','record_hash']);
 if p_new->'reason'is distinct from '"overdue"'::jsonb or p_new->'routing_snapshot'is distinct from 'null'::jsonb
  or p_new->'first_detected_at'is distinct from 'null'::jsonb or p_new->'evidence'is distinct from 'null'::jsonb or p_new->'record_hash'is distinct from 'null'::jsonb then raise exception 'review_server_field_supplied'using errcode='23514';end if;
 if pg_catalog.pg_my_temp_schema()<>0 then raise exception 'review_temp_namespace_forbidden'using errcode='42501';end if;
 id_value:=public.controlled_stock_uuid(p_new->'id');event_value:=public.controlled_stock_uuid(p_new->'event_id');
 context_value:=controlled_review_v3.protocol_rejection_context();operation_value:=(context_value->>'operation_id')::uuid;actor_value:=(context_value->>'actor_id')::uuid;
 if context_value->>'event_id'is distinct from event_value::text then raise exception 'review_overdue_context_invalid'using errcode='23514';end if;
 ids_value:=controlled_review_v3.protocol_escalation_ids(operation_value,event_value);
 if id_value::text is distinct from ids_value->>'overdue'then raise exception 'review_unique_uuid_collision'using errcode='23514';end if;
 keys_value:=jsonb_build_array(jsonb_build_object('class_id',90271101,'key','review-v3-operation:'||operation_value::text,'mode','exclusive'),
  jsonb_build_object('class_id',90271103,'key','review-v3-event:'||event_value::text,'mode','exclusive'),
  jsonb_build_object('class_id',90271105,'key','review-v3-unique:escalations:'||(ids_value->>'rejected'),'mode','exclusive'),
  jsonb_build_object('class_id',90271105,'key','review-v3-unique:escalations:'||(ids_value->>'overdue'),'mode','exclusive'));
 rows_value:=controlled_review_v3.protocol_review_rows(jsonb_build_object('path','decision','operation_id',operation_value,'event_id',event_value,'configuration_ids','{}'::jsonb));
 perform controlled_review_v3.protocol_assert_advisory(keys_value);perform controlled_review_v3.protocol_assert_relation_tail('decision',rows_value);
 select *into strict decision_value from controlled_review_v3.decisions where operation_id=operation_value;
 select *into strict preparation_value from controlled_review_v3.preparations where operation_id=operation_value;
 select *into strict obligation_value from controlled_review_v3.obligations where event_id=event_value;
 if decision_value.actor_id is distinct from actor_value or decision_value.event_id is distinct from event_value
  or decision_value.receipt->>'deadline_state'is distinct from 'completed_late'or obligation_value.due_at is null
  or decision_value.recorded_at<=obligation_value.due_at or exists(select 1 from controlled_review_v3.cancellations where operation_id=operation_value)then raise exception 'review_overdue_context_invalid'using errcode='23514';end if;
 keys_value:=controlled_review_v3.protocol_review_keys(jsonb_build_object('path','decision','operation_id',operation_value,'adapter',preparation_value.packet->'adapter','escalation_ids',ids_value));
 perform controlled_review_v3.protocol_assert_advisory(keys_value);perform controlled_review_v3.protocol_acquire_advisory(keys_value,actor_value);
 perform controlled_review_v3.protocol_acquire_fk_tail('decision',rows_value,actor_value);perform controlled_review_v3.required();
 identity_value:=controlled_review_v3.protocol_identity(actor_value);
 if identity_value->>'session_id'is distinct from decision_value.session_id::text then raise exception 'review_identity_invalid'using errcode='42501';end if;
 if exists(select 1 from controlled_review_v3.escalations where id=id_value or(event_id=event_value and reason='overdue'))then raise exception 'review_unique_uuid_collision'using errcode='23514';end if;
 evidence_value:=jsonb_build_object('version',1,'reason','overdue','event_id',event_value,'target_hash',obligation_value.target_hash,
  'due_at',controlled_review_v3.protocol_utc(obligation_value.due_at),'detected_at',controlled_review_v3.protocol_utc(decision_value.recorded_at),
  'terminal_operation_id',operation_value,'terminal_receipt_hash',public.controlled_stock_hash(decision_value.receipt),'maintenance_operation_id',null);
 routing_value:=controlled_review_v3.protocol_rejection_routing(obligation_value.historical->'routing_snapshot',decision_value.recorded_at);
 row_value:=jsonb_build_object('id',id_value,'event_id',event_value,'reason','overdue','routing_snapshot',routing_value,
  'first_detected_at',controlled_review_v3.protocol_utc(decision_value.recorded_at),'evidence',evidence_value);
 row_value:=row_value||jsonb_build_object('record_hash',public.controlled_stock_hash(row_value));
 perform controlled_review_v3.ops_validate_overdue(row_value);
 perform controlled_review_v3.protocol_identity(actor_value);
 if pg_catalog.pg_my_temp_schema()<>0 then raise exception 'review_temp_namespace_forbidden'using errcode='42501';end if;
 return row_value;
end

controlled_review_v3.ops_construct_worke.source:
declare context_value jsonb:=controlled_review_v3.ops_worker_context();base_value jsonb;assessment_value jsonb;request_value jsonb:=context_value->'request';
 ids_value jsonb;row_value jsonb;evidence_value jsonb;stamp timestamptz;reason_value text:=p_new->>'reason';
begin
 perform controlled_review_v3.protocol_principal(null);perform public.controlled_stock_keys(p_new,array['id','event_id','reason','routing_snapshot','first_detected_at','evidence','record_hash']);
 if p_new->'routing_snapshot'is distinct from 'null'::jsonb or p_new->'first_detected_at'is distinct from 'null'::jsonb
 or p_new->'evidence'is distinct from 'null'::jsonb or p_new->'record_hash'is distinct from 'null'::jsonb then raise exception 'review_server_field_supplied'using errcode='23514';end if;
 base_value:=controlled_review_v3.ops_worker_base(context_value);assessment_value:=controlled_review_v3.ops_worker_capture(base_value);
 ids_value:=controlled_review_v3.ops_worker_ids((request_value->>'operation_id')::uuid,(request_value->>'event_id')::uuid);
 if p_new->'event_id'is distinct from request_value->'event_id'or p_new->'id'is distinct from ids_value->reason_value
 or not(assessment_value->'reasons'?reason_value)then raise exception 'review_worker_escalation_not_due'using errcode='23514';end if;
 if exists(select 1 from controlled_review_v3.escalations where id=(p_new->>'id')::uuid or(event_id=(request_value->>'event_id')::uuid and reason=reason_value))then raise exception 'review_unique_uuid_collision'using errcode='23514';end if;
 stamp:=controlled_review_v3.protocol_instant(assessment_value->'assessed_at');
 if reason_value='overdue'then
  evidence_value:=jsonb_build_object('version',1,'reason','overdue','event_id',request_value->'event_id','target_hash',public.controlled_stock_hash(base_value->'target'),
   'due_at',base_value#>'{obligation,due_at}','detected_at',controlled_review_v3.protocol_utc(stamp),'terminal_operation_id',null,'terminal_receipt_hash',null,'maintenance_operation_id',request_value->'operation_id');
 else
  evidence_value:=jsonb_build_object('version',1,'reason',reason_value,'event_id',request_value->'event_id','target_hash',public.controlled_stock_hash(base_value->'target'),
   'maintenance_operation_id',request_value->'operation_id','assessment',assessment_value);
 end if;
 row_value:=jsonb_build_object('id',p_new->'id','event_id',request_value->'event_id','reason',reason_value,'first_detected_at',controlled_review_v3.protocol_utc(stamp),'routing_snapshot',assessment_value->'routing','evidence',evidence_value);
 row_value:=row_value||jsonb_build_object('record_hash',public.controlled_stock_hash(row_value));perform controlled_review_v3.ops_escalation_record(row_value);
 perform controlled_review_v3.protocol_principal(null);return row_value;
end

declare context_value jsonb:=controlled_review_v3.ops_worker_context();projection_value jsonb;family_value jsonb;
begin
 perform controlled_review_v3.protocol_principal(null);
 perform public.controlled_stock_keys(p_new,array['dispense_id','product_id','target','target_hash','site_id','selection','binding_hash','materialized_at']);
 if p_new-array['dispense_id','product_id']is distinct from jsonb_build_object('target',null,'target_hash',null,
  'site_id',null,'selection',null,'binding_hash',null,'materialized_at',null)then raise exception 'review_server_field_supplied'using errcode='23514';end if;
 projection_value:=controlled_review_v3.ops_worker_base(context_value);family_value:=projection_value->'family';
 if family_value is null or family_value='null'::jsonb or p_new->'dispense_id'is distinct from family_value->'dispense_id'
  or p_new->'product_id'is distinct from family_value->'product_id'then raise exception 'review_history_integrity'using errcode='23514';end if;
 return family_value||jsonb_build_object('materialized_at',clock_timestamp());
end

declare context_value jsonb:=controlled_review_v3.ops_worker_context();base_value jsonb;obligation_value jsonb;expected_value jsonb;
begin
 perform controlled_review_v3.protocol_principal(null);
 if p_new-array['event_id','product_id']is distinct from jsonb_build_object('event_sequence',null,'meaning',null,'target',null,'target_hash',null,'adapter',null,'historical',null,'binding_hash',null,'site_id',null,'due_at',null,'family_dispense_id',null,'materialized_at',null)
 or p_new->'event_id'is distinct from context_value#>'{request,event_id}'or p_new->'product_id'is distinct from context_value#>'{request,product_id}'then raise exception 'review_server_field_supplied'using errcode='23514';end if;
 base_value:=controlled_review_v3.ops_worker_base(context_value);obligation_value:=base_value->'obligation';
 if obligation_value is null or obligation_value='null'::jsonb then raise exception 'review_not_required'using errcode='23514';end if;
 expected_value:=obligation_value||jsonb_build_object('event_sequence',(obligation_value->>'event_sequence')::bigint,'due_at',(obligation_value->>'due_at')::timestamptz,'materialized_at',clock_timestamp());
