 if r.result->>'state'='not_required'and(r.result#>'{availability,deadline_basis}'is distinct from '"not_required"'::jsonb or r.result#>'{availability,unavailable_reason}'is distinct from 'null'::jsonb)then raise exception 'review_materialization_invalid'using errcode='23514';end if;
