 if session_user='postgres'and current_user='postgres'then
  NEW:=jsonb_populate_record(null::controlled_review_v3.escalations,controlled_review_v3.ops_construct_worker_escalation(to_jsonb(NEW)));return NEW;
 end if;
 if NEW.reason='overdue'then
  row_value:=controlled_review_v3.ops_construct_terminal_overdue(to_jsonb(NEW));
  NEW.first_detected_at:=controlled_review_v3.protocol_instant(row_value->'first_detected_at');NEW.evidence:=row_value->'evidence';
  NEW.routing_snapshot:=row_value->'routing_snapshot';NEW.record_hash:=row_value->>'record_hash';return NEW;
 end if;
 if NEW.reason is distinct from 'rejected'then raise exception 'review_escalation_reason_not_implemented'using errcode='0A000';end if;
