   or previous_row.document->'target'is distinct from target then raise exception 'adapter_source_integrity'using errcode='23514';end if;
  head:=jsonb_build_object('event_id',previous_row.id,'version',previous_row.sequence,'record_hash',previous_row.record_hash);previous_stamp:=previous_row.created_at;
