controlled_review_v3.read_named_facts(p_.source:
declare id_value jsonb;facts_value jsonb;
begin
 if jsonb_typeof(p_ids)is distinct from 'array'or jsonb_array_length(p_ids)>201 or octet_length(p_ids::text)>16384 then raise exception 'review_history_integrity'using errcode='23514';end if;
 for id_value in select value from jsonb_array_elements(p_ids)loop perform public.controlled_stock_uuid(id_value);end loop;
 select coalesce(jsonb_object_agg(p.id::text,jsonb_build_object('active',p.is_active,'roles',
  (select coalesce(jsonb_agg(role_value order by role_value collate "C"),'[]'::jsonb)from(select distinct r.role::text role_value from public.user_roles r where r.user_id=p.id and r.role::text in('ADMIN','DVM','STAFF','TECH'))roles_value))),'{}'::jsonb)
 into facts_value from public.profiles p where p.id in(select(value#>>'{}')::uuid from jsonb_array_elements(p_ids));
 return facts_value;
end

controlled_review_v3.read_native_family(.source:
declare managed_value jsonb;event_value public.controlled_stock_events;adapter_value jsonb;policy_value jsonb;references_value jsonb;
 selection_value jsonb;result_value jsonb;reason_value text;stored controlled_review_v3.families;stored_value jsonb;
begin
 managed_value:=controlled_review_v3.read_native_source_event('dispense',p_dispense_id,p_product_id);
 if managed_value is null then
  if exists(select 1 from controlled_review_v3.families where dispense_id=p_dispense_id)then raise exception 'review_history_integrity'using errcode='23514';end if;
  return null;end if;
 select *into strict event_value from public.controlled_stock_events where id=(managed_value->>'event_id')::uuid;
 if event_value.id<>p_dispense_id or event_value.product_id<>p_product_id or event_value.event_kind<>'record_native_dispense'
  or event_value.observed_at is null then raise exception 'review_history_integrity'using errcode='23514';end if;
 adapter_value:=controlled_review_v3.read_collect_scalar(event_value.id)->'adapter';
 policy_value:=controlled_review_v3.read_policy_at(p_product_id,(adapter_value->>'site_id')::uuid,event_value.observed_at);
 references_value:=case when policy_value is null then jsonb_build_object('calendar',null,'routing',null)
  else controlled_review_v3.read_policy_references(policy_value)end;
 reason_value:=case when adapter_value->>'site_id'is null then 'family_site_unproven'
  when policy_value is null then 'no_policy_at_anchor'
  when policy_value->'enabled'is distinct from 'true'::jsonb then 'policy_disabled_at_anchor'else null end;
 selection_value:=jsonb_build_object('version',1,'original_dispense_target',adapter_value->'target',
  'original_dispense_target_hash',public.controlled_stock_hash(adapter_value->'target'),
  'selection_anchor',to_char(event_value.observed_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
  'policy_id',policy_value->'id','policy_hash',policy_value->'record_hash',
  'native_deadline_kind',policy_value#>'{body,native_deadline_kind}',
  'calendar_id',references_value#>'{calendar,id}','calendar_hash',references_value#>'{calendar,record_hash}',
  'routing_id',references_value#>'{routing,id}','routing_hash',references_value#>'{routing,record_hash}','unavailable_reason',reason_value);
 result_value:=jsonb_build_object('dispense_id',p_dispense_id,'target',adapter_value->'target',
  'target_hash',public.controlled_stock_hash(adapter_value->'target'),'product_id',p_product_id,
  'site_id',adapter_value->'site_id','selection',selection_value);
 select *into stored from controlled_review_v3.families where dispense_id=p_dispense_id;
 if found then
  stored_value:=jsonb_build_object('dispense_id',stored.dispense_id,'target',stored.target,'target_hash',stored.target_hash,'product_id',stored.product_id,'site_id',stored.site_id,'selection',stored.selection);
  if stored.binding_hash is distinct from public.controlled_stock_hash(stored_value)or stored_value is distinct from result_value then raise exception 'review_history_integrity'using errcode='23514';end if;
 end if;
 return result_value||jsonb_build_object('binding_hash',public.controlled_stock_hash(result_value));
end

controlled_review_v3.read_native_family_.source:
declare managed_value jsonb;event_value public.controlled_stock_events;adapter_value jsonb;policy_value jsonb;references_value jsonb;
 selection_value jsonb;result_value jsonb;reason_value text;stored controlled_review_v3.families;stored_value jsonb;row_value jsonb;ref_value jsonb;ref_count integer;event_row jsonb;refs_index jsonb;
begin
 perform public.controlled_stock_keys(p_collected,array['adapter','source_rows']);
 if jsonb_typeof(p_collected->'source_rows')is distinct from 'array'or jsonb_array_length(p_collected->'source_rows')>512
  or octet_length(p_collected::text)>1048576 then raise exception 'review_history_integrity'using errcode='23514';end if;
 if p_collected#>>'{adapter,native_family_dispense_id}'is distinct from p_dispense_id::text
  or p_collected#>>'{adapter,target,product_id}'is distinct from p_product_id::text then raise exception 'review_history_integrity'using errcode='23514';end if;
 if jsonb_typeof(p_collected#>'{adapter,source_refs}')is distinct from 'array'or jsonb_array_length(p_collected#>'{adapter,source_refs}')not between 1 and 512
  or not exists(select 1 from jsonb_array_elements(p_collected->'source_rows')x where x->>'relation'='public.controlled_stock_events'and x#>'{key,id}'=p_collected#>'{adapter,target,event_id}')
  or not exists(select 1 from jsonb_array_elements(p_collected->'source_rows')x where x->>'relation'='public.native_dispenses'and x#>>'{key,id}'=p_dispense_id::text)then raise exception 'review_history_integrity'using errcode='23514';end if;
 if exists(select 1 from jsonb_array_elements(p_collected#>'{adapter,source_refs}')x group by x->'relation',x->'key'having count(*)<>1)then raise exception 'review_history_integrity'using errcode='23514';end if;
 select jsonb_object_agg(jsonb_build_array(value->'relation',value->'key')::text,value)into refs_index from jsonb_array_elements(p_collected#>'{adapter,source_refs}');
 -- These are raw immutable rows from the SERVER LOCAL full collector, not a
 -- caller packet or a Boolean. Recompute every captured row/reference hash.
 for row_value in select value from jsonb_array_elements(p_collected->'source_rows')loop
  perform public.controlled_stock_keys(row_value,array['relation','key','row']);
  ref_value:=refs_index->jsonb_build_array(row_value->'relation',row_value->'key')::text;
  if ref_value is null or ref_value->>'row_hash'is distinct from public.controlled_stock_hash(row_value->'row')then raise exception 'review_history_integrity'using errcode='23514';end if;
 end loop;
 if jsonb_array_length(p_collected#>'{adapter,source_refs}')<>jsonb_array_length(p_collected->'source_rows')
  or exists(select 1 from jsonb_array_elements(p_collected->'source_rows')x group by x->'relation',x->'key'having count(*)<>1)then raise exception 'review_history_integrity'using errcode='23514';end if;
 select count(*),min((value->'row')::text)::jsonb into ref_count,event_row from jsonb_array_elements(p_collected->'source_rows')
  where value->>'relation'='public.controlled_stock_events'and value#>>'{key,id}'=p_dispense_id::text;
 if ref_count=0 then
  if p_collected#>>'{adapter,event_kind}'is distinct from 'record_native_pickup'
   or exists(select 1 from controlled_review_v3.families where dispense_id=p_dispense_id)then raise exception 'review_history_integrity'using errcode='23514';end if;
  return null;
 elsif ref_count<>1 then raise exception 'review_history_integrity'using errcode='23514';end if;
 event_value:=jsonb_populate_record(null::public.controlled_stock_events,event_row);
 if event_value.id is distinct from p_dispense_id or event_value.product_id is distinct from p_product_id or event_value.event_kind is distinct from 'record_native_dispense'
  or event_value.observed_at is null then raise exception 'review_history_integrity'using errcode='23514';end if;
 -- Full canonical validation of this immutable parent already ran during
 -- collection. The selected site helper reads only its own immutable transitions
 -- and containers, with no source/global/native re-verification.
 adapter_value:=jsonb_build_object('target',jsonb_build_object('event_id',event_value.id,'product_id',event_value.product_id,
  'sequence',event_value.sequence,'record_hash',event_value.record_hash,'original_actor_id',event_value.actor_id,'policy_version_id',event_value.policy_version_id,
  'opening_id',event_value.opening_id,'engine_revision',event_value.engine_revision),'site_id',controlled_review_v3.read_adapter_site(event_value.id)->'site_id');
 policy_value:=controlled_review_v3.read_policy_at(p_product_id,(adapter_value->>'site_id')::uuid,event_value.observed_at);
 references_value:=case when policy_value is null then jsonb_build_object('calendar',null,'routing',null)
  else controlled_review_v3.read_policy_references(policy_value)end;
 reason_value:=case when adapter_value->>'site_id'is null then 'family_site_unproven'
  when policy_value is null then 'no_policy_at_anchor'
  when policy_value->'enabled'is distinct from 'true'::jsonb then 'policy_disabled_at_anchor'else null end;
 selection_value:=jsonb_build_object('version',1,'original_dispense_target',adapter_value->'target',
  'original_dispense_target_hash',public.controlled_stock_hash(adapter_value->'target'),
  'selection_anchor',to_char(event_value.observed_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
  'policy_id',policy_value->'id','policy_hash',policy_value->'record_hash',
  'native_deadline_kind',policy_value#>'{body,native_deadline_kind}',
  'calendar_id',references_value#>'{calendar,id}','calendar_hash',references_value#>'{calendar,record_hash}',
  'routing_id',references_value#>'{routing,id}','routing_hash',references_value#>'{routing,record_hash}','unavailable_reason',reason_value);
 result_value:=jsonb_build_object('dispense_id',p_dispense_id,'target',adapter_value->'target',
  'target_hash',public.controlled_stock_hash(adapter_value->'target'),'product_id',p_product_id,
  'site_id',adapter_value->'site_id','selection',selection_value);
 select *into stored from controlled_review_v3.families where dispense_id=p_dispense_id;
 if found then
  stored_value:=jsonb_build_object('dispense_id',stored.dispense_id,'target',stored.target,'target_hash',stored.target_hash,'product_id',stored.product_id,'site_id',stored.site_id,'selection',stored.selection);
  if stored.binding_hash is distinct from public.controlled_stock_hash(stored_value)or stored_value is distinct from result_value then raise exception 'review_history_integrity'using errcode='23514';end if;
 end if;
 return result_value||jsonb_build_object('binding_hash',public.controlled_stock_hash(result_value));
end

controlled_review_v3.read_native_source_.source:
declare opening public.controlled_stock_openings;e public.controlled_stock_events;link public.controlled_stock_source_links;
 d public.native_dispenses;p public.native_pickups;s public.stock_movement_sources;
 a record;did uuid;native_row jsonb;native_provenance jsonb;entry jsonb;ids jsonb:='[]'::jsonb;
 n integer:=0;linked integer:=0;opened integer:=0;sourced integer:=0;root_count integer;parent_id uuid;
begin
 perform public.controlled_stock_uuid(to_jsonb(p_source_id));perform public.controlled_stock_uuid(to_jsonb(p_product_id));
 if p_source_kind is null or p_source_kind not in('dispense','pickup')then raise exception 'invalid_adapter_argument'using errcode='22023';end if;
 select *into opening from public.controlled_stock_openings where product_id=p_product_id;
 if p_source_kind='dispense'then
  perform controlled_review_v3.read_dispense_capture(p_source_id,p_product_id);
  select *into strict d from public.native_dispenses where id=p_source_id;did:=d.id;native_row:=to_jsonb(d);
 else
  perform controlled_review_v3.read_pickup_capture(p_source_id,p_product_id);
  select *into strict p from public.native_pickups where id=p_source_id;did:=p.dispense_id;native_row:=to_jsonb(p);
  select to_jsonb(x)into native_provenance from public.stock_pickup_sources x where event_id=p_source_id;
  if native_provenance is not null and native_provenance->>'actor_id'is distinct from native_row->>'actor_id'then raise exception 'adapter_source_integrity'using errcode='23514';end if;
 end if;
 -- read_dispense_capture has already observed101 before any verifier aggregate.
 for a in select *from public.native_dispense_allocations where dispense_id=did order by lot_id loop
  n:=n+1;select *into s from public.stock_movement_sources where movement_id=a.movement_id;
  if s.movement_id is not null then
   sourced:=sourced+1;
   if s.writer<>'record_native_dispense'or s.source_id<>did or s.actor_id is distinct from(select actor_id from public.native_dispenses where id=did)then raise exception 'adapter_source_integrity'using errcode='23514';end if;
   perform controlled_review_v3.read_stock_source(s.movement_id);
  end if;
  if exists(select 1 from public.controlled_stock_opening_movements where movement_id=a.movement_id and opening_id=opening.id)then opened:=opened+1;end if;
  if p_source_kind='dispense'then
   select *into link from public.controlled_stock_source_links where movement_id=a.movement_id;
   if link.id is not null then
    linked:=linked+1;
    if parent_id is not null and parent_id<>link.event_id then raise exception 'adapter_source_integrity'using errcode='23514';end if;
    parent_id:=link.event_id;ids:=ids||jsonb_build_array(link.id);
   end if;
  end if;
 end loop;
 if n=0 or n>100 or sourced not in(0,n)or opened not in(0,n)then raise exception 'adapter_source_integrity'using errcode='23514';end if;
 select count(*)into root_count from(select 1 from public.stock_movement_sources where writer='record_native_dispense'and source_id=did limit 101)q;
 if root_count>100 then raise exception 'adapter_source_integrity'using errcode='23514';end if;
 if root_count<>sourced or exists(select 1 from public.stock_movement_sources x where writer='record_native_dispense'and source_id=did and not exists(select 1 from public.native_dispense_allocations allocation_row where allocation_row.dispense_id=did and allocation_row.movement_id=x.movement_id))then raise exception 'adapter_source_integrity'using errcode='23514';end if;
 if p_source_kind='dispense'then
  if linked not in(0,n)or(linked>0 and(opened>0 or sourced<>n))then raise exception 'adapter_source_integrity'using errcode='23514';end if;
 else
  select *into link from public.controlled_stock_source_links where pickup_id=p_source_id;
  if link.id is not null then parent_id:=link.event_id;ids:=jsonb_build_array(link.id);end if;
 end if;
 if parent_id is not null then
  if p_source_kind='pickup'and native_provenance is null then raise exception 'adapter_source_integrity'using errcode='23514';end if;
  select *into e from public.controlled_stock_events where id=parent_id;
  if e.id is null or e.product_id<>p_product_id or(opening.id is not null and e.opening_id<>opening.id)
   or e.id<>p_source_id or e.actor_id::text is distinct from native_row->>'actor_id'
   or e.writer is distinct from(case p_source_kind when 'dispense'then 'record_native_dispense'else 'record_native_pickup'end)
   or(p_source_kind='pickup'and(e.source_bundle#>>'{native,kind}'is distinct from 'pickup'or e.source_bundle#>>'{native,id}'is distinct from p_source_id::text))then raise exception 'adapter_source_integrity'using errcode='23514';end if;
  perform controlled_review_v3.read_validate_scalar(e.id);
  select jsonb_agg(x order by(x#>>'{}')collate "C")into ids from jsonb_array_elements(ids)x;
  return jsonb_build_object('event_id',e.id,'source_link_ids',ids);
 end if;
 if exists(select 1 from public.controlled_stock_events where id=p_source_id)then raise exception 'adapter_source_integrity'using errcode='23514';end if;
 if opening.id is not null then
  -- This immutable opening document is source-admitted under H0, not a new
  -- cap on growing later product/native histories. No later history is read.
  if jsonb_typeof(opening.native_custody_boundary)is distinct from 'array'or jsonb_array_length(opening.native_custody_boundary)>200 then raise exception 'adapter_source_integrity'using errcode='23514';end if;
  select x into entry from jsonb_array_elements(opening.native_custody_boundary)x where x->>'dispense_id'=did::text;
  if entry is null or opened<>n or(p_source_kind='pickup'and entry#>>'{pickup,id}'is distinct from p_source_id::text)then raise exception 'adapter_source_integrity'using errcode='23514';end if;
 end if;
 return null;
end

controlled_review_v3.read_obligation_cap.source:
declare event_value public.controlled_stock_events:=jsonb_populate_record(null::public.controlled_stock_events,p_event);adapter_value jsonb;anchor_value timestamptz;anchor_basis text;
 family_value jsonb;policy_value jsonb;references_value jsonb;historical_value jsonb;rule_value jsonb;
 deadline_value jsonb;reason_value text;choice_value text;family_id uuid;result_value jsonb;
begin
 adapter_value:=p_adapter;
 if p_family is not null and p_family<>'null'::jsonb then
  perform public.controlled_stock_keys(p_family,array['dispense_id','target','target_hash','product_id','site_id','selection','binding_hash']);
  if p_family->'dispense_id'is distinct from adapter_value->'native_family_dispense_id'or p_family->>'product_id'is distinct from event_value.product_id::text
   or p_family->>'target_hash'is distinct from public.controlled_stock_hash(p_family->'target')
   or p_family->>'binding_hash'is distinct from public.controlled_stock_hash(p_family-'binding_hash')then raise exception 'review_history_integrity'using errcode='23514';end if;
 end if;
 if event_value.id is null or event_value.event_kind not in('receive_inventory','adjust_inventory','record_patient_treatment','record_anesthesia_drug_administration','record_native_dispense','record_native_pickup','append_native_dispense_correction:clinical_annotation','append_native_dispense_correction:operational_annotation','append_native_dispense_correction:pickup_amendment','record_native_dispense_return:intake','record_native_dispense_return:dispose','record_native_dispense_return:restock','record_native_dispense_return_v2:intake','record_native_dispense_return_v2:dispose','record_native_dispense_return_v2:restock','record_native_dispense_return_v2:retract_intake','record_native_dispense_return_v2:retract_disposal','record_native_dispense_return_v2:retract_restock','record_native_return_discrepancy:report','record_native_return_discrepancy:note','record_native_return_discrepancy:resolve_corrected','record_native_return_discrepancy:resolve_confirmed_original')then raise exception 'read_denied'using errcode='42501';end if;
 if not event_value.secondary_review_required then return null;end if;
 anchor_basis:=case when event_value.basis='physical_record'then 'observed_at'else 'recorded_at'end;
 anchor_value:=case when anchor_basis='observed_at'then event_value.observed_at else event_value.recorded_at end;
 if anchor_value is null or not isfinite(anchor_value)then raise exception 'review_history_integrity'using errcode='23514';end if;
 historical_value:=jsonb_build_object('version',1,'selection_anchor',to_char(anchor_value at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
  'anchor_basis',anchor_basis,'policy_id',null,'policy_hash',null,'rule',null,'family_binding_hash',null,
  'calendar_id',null,'calendar_hash',null,'anchor_local_date',null,'selected_staffed_date',null,'due_at',null,
  'deadline_basis','historical_policy_unavailable','unavailable_reason',null,'routing_id',null,'routing_hash',null,'routing_snapshot',null);
 if adapter_value->>'site_id'is null then reason_value:='site_unproven';
 elsif event_value.event_kind in('record_native_dispense','record_native_pickup')then
  family_value:=p_family;
  if family_value is null then reason_value:='missing_managed_dispense_family';
  else
   family_id:=(family_value->>'dispense_id')::uuid;
   historical_value:=historical_value||jsonb_build_object('family_binding_hash',family_value->'binding_hash');
   reason_value:=family_value#>>'{selection,unavailable_reason}';
   if family_value->'site_id'is distinct from adapter_value->'site_id'then
    raise exception 'review_history_integrity'using errcode='23514';end if;
   if family_value#>>'{selection,policy_id}'is not null then
    policy_value:=controlled_review_v3.read_configuration_record((family_value#>>'{selection,policy_id}')::uuid);
    if policy_value->'record_hash'is distinct from family_value#>'{selection,policy_hash}'then
     raise exception 'review_history_integrity'using errcode='23514';end if;
   end if;
   choice_value:=family_value#>>'{selection,native_deadline_kind}';
  end if;
 else policy_value:=controlled_review_v3.read_policy_at(event_value.product_id,(adapter_value->>'site_id')::uuid,anchor_value);
 end if;
 if policy_value is not null then
  rule_value:=policy_value#>array['body','rules',event_value.event_kind];
  if rule_value is null then raise exception 'review_history_integrity'using errcode='23514';end if;
  references_value:=controlled_review_v3.read_policy_references(policy_value);
  historical_value:=historical_value||jsonb_build_object('policy_id',policy_value->'id','policy_hash',policy_value->'record_hash','rule',rule_value,
   'calendar_id',references_value#>'{calendar,id}','calendar_hash',references_value#>'{calendar,record_hash}',
   'routing_id',references_value#>'{routing,id}','routing_hash',references_value#>'{routing,record_hash}',
   'routing_snapshot',controlled_review_v3.protocol_routing_snapshot(references_value->'routing'));
  if reason_value is null and policy_value->'enabled'is distinct from 'true'::jsonb then reason_value:='policy_disabled_at_anchor';end if;
 elsif reason_value is null then reason_value:='no_policy_at_anchor';end if;
 if reason_value is null then
  if event_value.event_kind in('record_native_dispense','record_native_pickup')and choice_value is not null and choice_value<>event_value.event_kind then
   historical_value:=historical_value||jsonb_build_object('deadline_basis','not_assigned','unavailable_reason','other_native_kind_selected');
  elsif rule_value->'enabled'is distinct from 'true'::jsonb or rule_value->>'deadline_mode'='not_configured'then
   historical_value:=historical_value||jsonb_build_object('deadline_basis','not_configured','unavailable_reason','kind_not_configured');
  else
   if rule_value->>'deadline_mode'<>'next_staffed_day_close'or references_value#>>'{calendar,id}'is null then
    raise exception 'review_history_integrity'using errcode='23514';end if;
   deadline_value:=controlled_review_v3.protocol_deadline(references_value->'calendar',anchor_value);
   historical_value:=historical_value||deadline_value;
  end if;
 else historical_value:=historical_value||jsonb_build_object('unavailable_reason',reason_value);end if;
 result_value:=jsonb_build_object('event_id',event_value.id,'product_id',event_value.product_id,'event_sequence',event_value.sequence::text,
  'meaning','independent_record_review_v1','target',adapter_value->'target','target_hash',public.controlled_stock_hash(adapter_value->'target'),
  'adapter',adapter_value,'historical',historical_value,'site_id',adapter_value->'site_id','due_at',historical_value->'due_at','family_dispense_id',family_id);
 return result_value||jsonb_build_object('binding_hash',public.controlled_stock_hash(result_value));
end

controlled_review_v3.read_obligation_dto.source:
