controlled_review_v3.read_return_discrep.source:
declare correction_quantities jsonb;parent public.native_return_events;documents jsonb:='[]';snapshot_case jsonb;snapshot_document jsonb;snapshot_result jsonb;wanted_head jsonb;declared_documents jsonb:='{}';document_count integer:=0;item jsonb;input_item jsonb;prior_allocation text; e public.native_return_discrepancy_events;o public.native_return_discrepancy_operations;d jsonb;c jsonb;cases jsonb:='{}';ordered text[]:='{}';case_row jsonb;rows jsonb:='[]';lots jsonb;open_count integer:=0;head jsonb:=jsonb_build_object('event_id',null,'version',0,'record_hash',null);previous timestamptz;key text;s public.native_return_events;
begin
 select *into parent from public.native_return_events where id=(p_parent->>'id')::uuid;
 if parent.id is null or to_jsonb(parent)is distinct from p_parent then raise exception 'adapter_source_integrity'using errcode='23514';end if;
 if octet_length(p_snapshot::text)>1048576 then raise exception 'evidence_limit_exceeded'using errcode='54000';end if;
 perform public.native_rx_keys(p_snapshot,array['version','head','open_case_count','held_lot_ids','cases']);
 perform public.native_rx_keys(p_snapshot->'head',array['event_id','version','record_hash']);
 if p_snapshot->'version'is distinct from'1'::jsonb or jsonb_typeof(p_snapshot->'cases')is distinct from'array'or jsonb_typeof(p_snapshot->'head'->'version')is distinct from'number'or(p_snapshot#>>'{head,version}')!~'^(0|[1-9][0-9]{0,9})$'or(p_snapshot#>>'{head,version}')::numeric>2147483647 then raise exception 'adapter_source_integrity'using errcode='23514';end if;
 wanted_head:=p_snapshot->'head';
 for snapshot_case in select value from jsonb_array_elements(p_snapshot->'cases')loop
  perform public.native_rx_keys(snapshot_case,array['id','source','allocations','status','report','decisions']);
  if snapshot_case->>'id'is distinct from snapshot_case#>>'{report,id}'or snapshot_case#>>'{report,action}'is distinct from'report'or jsonb_typeof(snapshot_case->'decisions')is distinct from'array'then raise exception 'adapter_source_integrity'using errcode='23514';end if;
  for snapshot_document in select snapshot_case->'report' union all select value from jsonb_array_elements(snapshot_case->'decisions')loop
   key:=public.native_correction_uuid(snapshot_document->'id')::text;
   if declared_documents?key then raise exception 'adapter_source_integrity'using errcode='23514';end if;
   declared_documents:=declared_documents||jsonb_build_object(key,snapshot_document);documents:=documents||jsonb_build_array(snapshot_document);document_count:=document_count+1;
  end loop;
 end loop;
 -- The retained representation includes every report/note/resolution document
 -- once. Byte cap is immutable per selected event, not a lifetime-history cap.
 if document_count<>(wanted_head->>'version')::integer then raise exception 'adapter_source_integrity'using errcode='23514';end if;
 for e in select actual.*from jsonb_array_elements(documents)declared join public.native_return_discrepancy_events actual on actual.id=(declared->>'id')::uuid order by actual.sequence loop
  -- Untrusted retained documents become source evidence only after exact
  -- actual-row equality. This bounds actual correction arrays by sharedB
  -- before hashes, array walks or reconstruction (not only at final equality).
  if e.document is distinct from declared_documents->e.id::text then raise exception 'adapter_source_integrity'using errcode='23514';end if;
  if e.dispense_id is distinct from parent.dispense_id or e.authorization_id is distinct from parent.authorization_id or e.pet_id is distinct from parent.pet_id or e.created_at>parent.created_at then raise exception 'adapter_source_integrity'using errcode='23514';end if;
  d:=e.document;c:=e.reviewed_context;
  if jsonb_typeof(d->'allocations')is distinct from'array'or jsonb_array_length(d->'allocations')not between 1 and 100 or jsonb_typeof(d->'correction_ids')is distinct from'array'or jsonb_array_length(d->'correction_ids')>100 then raise exception 'adapter_source_integrity'using errcode='23514';end if;
  if octet_length(d::text)>1048576 or octet_length(c::text)>1048576 then raise exception 'evidence_limit_exceeded'using errcode='54000';end if;select * into o from public.native_return_discrepancy_operations where id=e.id;select * into s from public.native_return_events where id=(d#>>'{source,event_id}')::uuid;
  if octet_length(s.document::text)>1048576 then raise exception 'evidence_limit_exceeded'using errcode='54000';end if;
  if s.id is null or c->'source'is distinct from s.document then raise exception 'adapter_source_integrity'using errcode='23514';end if;
  perform public.native_rx_keys(d,array['version','id','target','sequence','prior_event_id','prior_record_hash','actor','action','case_id','source','allocations','observation','correction_ids','return_head','reviewed_context_hash','created_at','record_hash']);
  perform public.native_rx_keys(c,array['version','target','return_head','discrepancy_head','source','replay','discrepancies','intent']);
  perform public.native_rx_keys(o.request,array['intent','expected_context_hash','expected_return_head','expected_discrepancy_head','attest_physical_review','attest_original_quantities_custody_and_stock_accurate']);
  perform public.native_rx_keys(d->'actor',array['id','name','authority']);perform public.native_rx_text(d#>'{actor,name}',200);
  if d->'source' is distinct from o.request#>'{intent,source}' or d->'observation' is distinct from o.request#>'{intent,observation}' or d->'action' is distinct from o.request#>'{intent,action}' or d->'correction_ids' is distinct from o.request#>'{intent,correction_ids}' or d->'target' is distinct from o.request#>'{intent,target}'
   or c->'version' is distinct from '1'::jsonb or c->'target' is distinct from d->'target' or c->'source' is distinct from s.document
   or o.request->'attest_original_quantities_custody_and_stock_accurate' is distinct from to_jsonb(e.action='resolve_confirmed_original')
   or jsonb_array_length(d->'allocations')<>jsonb_array_length(o.request#>'{intent,allocations}') then raise exception 'Discrepancy request evidence mismatch' using errcode='23514';end if;
  prior_allocation:='';
  for item in select value from jsonb_array_elements(d->'allocations') loop
   perform public.native_rx_keys(item,array['allocation_id','lot_id','quantity']);
   if (item->>'allocation_id') collate "C"<=prior_allocation collate "C" or not exists(select 1 from jsonb_array_elements(s.document->'allocations')src where src->'allocation_id'=item->'allocation_id' and src->'lot_id'=item->'lot_id' and (src->>'quantity')::numeric>=public.native_fulfillment_quantity(item->'quantity')) or not exists(select 1 from jsonb_array_elements(o.request#>'{intent,allocations}')inp where inp->'allocation_id'=item->'allocation_id' and public.native_fulfillment_quantity(inp->'quantity')=(item->>'quantity')::numeric) then raise exception 'Discrepancy allocation evidence mismatch' using errcode='23514';end if;
   prior_allocation:=item->>'allocation_id';
  end loop;
  if d->'version' is distinct from '1'::jsonb or d->>'id' is distinct from e.id::text or d->>'action' is distinct from e.action or d->>'case_id' is distinct from e.case_id::text
   or d->'target' is distinct from jsonb_build_object('authorization_id',e.authorization_id,'pet_id',e.pet_id,'dispense_id',e.dispense_id)
   or e.sequence<>(head->>'version')::integer+1 or d->'sequence' is distinct from to_jsonb(e.sequence) or d->'prior_event_id' is distinct from head->'event_id' or d->'prior_record_hash' is distinct from head->'record_hash' or e.prior_event_id::text is distinct from head->>'event_id'
   or d#>>'{actor,id}' is distinct from e.actor_id::text or d->>'record_hash' is distinct from e.record_hash or public.native_fulfillment_hash(d-'record_hash') is distinct from e.record_hash or d->>'reviewed_context_hash' is distinct from public.native_fulfillment_hash(c)
   or (d->>'created_at')::timestamptz is distinct from e.created_at or e.created_at<previous or o.id is null or o.result is distinct from d or o.actor_id<>e.actor_id or o.created_at is distinct from e.created_at
   or o.request_hash is distinct from public.native_fulfillment_hash(jsonb_build_object('version',1,'actor_id',o.actor_id,'operation','record_native_return_discrepancy','request',o.request))
   or o.request->>'expected_context_hash' is distinct from d->>'reviewed_context_hash' or o.request->'expected_discrepancy_head' is distinct from head or o.request->'expected_return_head' is distinct from d->'return_head'
   or c->'discrepancy_head' is distinct from head or c->'return_head' is distinct from d->'return_head' or c->'intent' is distinct from o.request->'intent'
   or s.id is null or s.record_hash is distinct from public.native_fulfillment_hash(s.document-'record_hash')or s.document->>'id'is distinct from s.id::text or s.document->'target'is distinct from d->'target'or s.dispense_id<>parent.dispense_id or s.authorization_id<>e.authorization_id or s.pet_id<>e.pet_id or s.record_hash is distinct from d#>>'{source,record_hash}' or s.action not in('intake','dispose','restock') or s.created_at>e.created_at
   or o.request->'attest_physical_review' is distinct from 'true'::jsonb
  then raise exception 'Return discrepancy evidence mismatch' using errcode='23514';end if;
  if not exists(select 1 from public.native_return_events r where r.dispense_id=parent.dispense_id and r.id::text=d#>>'{return_head,event_id}' and r.sequence=(d#>>'{return_head,version}')::integer and r.record_hash=d#>>'{return_head,record_hash}' and r.created_at<=e.created_at) then raise exception 'Discrepancy return head mismatch' using errcode='23514';end if;
  if e.action='report' then
   if cases ? e.case_id::text or d#>>'{actor,authority}' not in('active_staff','active_dvm') then raise exception 'Discrepancy report identity mismatch' using errcode='23514';end if;
   case_row:=jsonb_build_object('id',e.id,'source',d->'source','allocations',d->'allocations','status','open','report',d,'decisions','[]'::jsonb);ordered:=array_append(ordered,e.id::text);
  else
   case_row:=cases->e.case_id::text;
   if case_row is null or case_row->>'status'<>'open' or case_row->'source' is distinct from d->'source' or case_row->'allocations' is distinct from d->'allocations' then raise exception 'Discrepancy case mismatch' using errcode='23514';end if;
   if e.action like 'resolve_%' then
    if d#>>'{actor,authority}'<>'active_dvm' then raise exception 'DVM discrepancy resolution required' using errcode='23514';end if;
    -- H0/W: canonical confirmed-original writer forbids a compensated case.
    -- Its committed prefix absence is not re-scanned through later history.
    if e.action='resolve_confirmed_original' and o.request->'attest_original_quantities_custody_and_stock_accurate' is distinct from 'true'::jsonb then raise exception 'Original facts require explicit confirmation' using errcode='23514';end if;
    if e.action='resolve_corrected' then
