 allocations jsonb:='[]';intake_result jsonb:='[]';correction_result jsonb:='[]';history_result jsonb:='[]';rows jsonb;
 slot jsonb;row_value jsonb;maximum numeric;current_quantity numeric;received numeric;held numeric;disposed numeric;restocked numeric;
 history_seen jsonb:='{}';last_allocation uuid;candidate_id uuid;
begin
 perform public.native_return_quantity_allocations(p_originals);
 perform public.native_rx_keys(p_event,array['action','allocations','correction_target_id','id','intake_id','sequence']);
 if jsonb_typeof(p_event->'sequence')is distinct from'number'or(p_event->>'sequence')!~'^[1-9][0-9]{0,9}$'or(p_event->>'sequence')::numeric>2147483647 then raise exception 'adapter_source_integrity'using errcode='23514';end if;
 seq:=(p_event->>'sequence')::integer-1;
 if octet_length(p_prior::text)>1048576 then raise exception 'evidence_limit_exceeded'using errcode='54000';end if;
 perform public.native_rx_keys(p_prior,array['allocations','intakes','correction_remaining','historical']);
