 or jsonb_typeof(p_prior->'historical')is distinct from'array'or jsonb_array_length(p_prior->'historical')<>jsonb_array_length(p_originals)
 or jsonb_typeof(p_prior->'intakes')is distinct from'array'or jsonb_array_length(p_prior->'intakes')>seq
 or jsonb_typeof(p_prior->'correction_remaining')is distinct from'array'or jsonb_array_length(p_prior->'correction_remaining')>seq then raise exception 'adapter_source_integrity'using errcode='23514';end if;
 for a in select value from jsonb_array_elements(p_originals)loop
  aid:=a->>'allocation_id';sources:=sources||jsonb_build_object(aid,a);
  sums:=sums||jsonb_build_object(aid,jsonb_build_object('received',0.000,'held',0.000,'disposed',0.000,'restocked',0.000));
 end loop;
 last_allocation:=null;
 for slot in select value from jsonb_array_elements(p_prior->'allocations')loop
  perform public.native_rx_keys(slot,array['allocation_id','lot_id','dispensed_quantity','returned_quantity','remaining_returnable_quantity','held_quantity','disposed_quantity','restocked_quantity']);
  candidate_id:=public.native_correction_uuid(slot->'allocation_id');aid:=candidate_id::text;s:=sources->aid;
  if s is null or(last_allocation is not null and candidate_id<=last_allocation)or slot->'lot_id'is distinct from s->'lot_id'then raise exception 'adapter_source_integrity'using errcode='23514';end if;last_allocation:=candidate_id;
