  current_quantity:=controlled_review_v3.read_return_quantity_number(slot->'dispensed_quantity',maximum);
  received:=controlled_review_v3.read_return_quantity_number(slot->'returned_quantity',maximum);
  held:=controlled_review_v3.read_return_quantity_number(slot->'held_quantity',maximum);
  disposed:=controlled_review_v3.read_return_quantity_number(slot->'disposed_quantity',maximum);
  restocked:=controlled_review_v3.read_return_quantity_number(slot->'restocked_quantity',maximum);
  remaining:=controlled_review_v3.read_return_quantity_number(slot->'remaining_returnable_quantity',maximum);
  if current_quantity<>maximum or received<>held+disposed+restocked or remaining<>maximum-received then raise exception 'adapter_source_integrity'using errcode='23514';end if;
  totals:=totals||jsonb_build_object(aid,jsonb_build_object('received',received,'held',held,'disposed',disposed,'restocked',restocked));
 end loop;
 last_allocation:=null;
 for slot in select value from jsonb_array_elements(p_prior->'historical')loop
  perform public.native_rx_keys(slot,array['allocation_id','lot_id','gross_intake_quantity','gross_disposed_quantity','gross_restocked_quantity','retracted_intake_quantity','retracted_disposed_quantity','retracted_restocked_quantity']);
  candidate_id:=public.native_correction_uuid(slot->'allocation_id');aid:=candidate_id::text;s:=sources->aid;t:=totals->aid;
  if s is null or(last_allocation is not null and candidate_id<=last_allocation)or slot->'lot_id'is distinct from s->'lot_id'then raise exception 'adapter_source_integrity'using errcode='23514';end if;last_allocation:=candidate_id;
  maximum:=(s->>'quantity')::numeric*seq;
  h:=jsonb_build_object('intake',controlled_review_v3.read_return_quantity_number(slot->'gross_intake_quantity',maximum),'disposed',controlled_review_v3.read_return_quantity_number(slot->'gross_disposed_quantity',maximum),'restocked',controlled_review_v3.read_return_quantity_number(slot->'gross_restocked_quantity',maximum),
